# "¿COMO ESTAS CONFIGURADA?": lo esencial en una tarjeta, para no tener que
# abrir config.json a mano. Solo lo que cambia algo para ti.
function Get-Configuracion {
    $p = @()
    $motorO = [string](Get-Cfg 'input' 'motorOrdenes' 'auto')
    $conFino = if ($WhisperPreciso) { " y repaso lo dudoso con $WhisperPreciso" } else { '' }
    $oidoT = switch ($motorO) {
        'worker' { "te oigo con Whisper $WhisperModelo$conFino" }
        'auto' { "te oigo con el dictado de Windows fuera del juego y con Whisper $WhisperModelo jugando" }
        default { 'te oigo con el dictado de Windows' }
    }
    if ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) {
        $oidoT += ', aunque ahora estoy en sordina ' + [int][Math]::Ceiling(($script:sordinaHasta - $sw.ElapsedMilliseconds) / 60000) + ' minutos'
    }
    $p += "Me llamo $EscuchaNombre y $oidoT"
    $p += if (-not $VozOn) { 'tengo la voz apagada' }
          elseif ($VozMotor -eq 'online') { "hablo con la voz en linea $VozOnlineNombre" }
          else { "hablo con $VozMotor" }
    if ($CerebroMotor -eq 'claude-code') {
        $p += "lo que no se hacer lo piensa Claude: $CcModeloTraducir para entenderte, $CcModeloPregunta para preguntas y $CcModeloAccion para tareas"
    } elseif ($CerebroMotor) {
        $p += "mi cerebro es $CerebroMotor"
    }
    $esq = $script:esquina -split '-'
    $colN = ''
    foreach ($k in $ColoresUI.Keys) { if ($ColoresUI[$k] -eq $script:uiColor) { $colN = $k; break } }
    $p += "vivo $($esq[0]) a la $($esq[1]), al $([int]($script:uiEscala * 100)) por ciento" + $(if ($colN) { " y de color $colN" } else { '' })
    $nMod = 0
    try { $nMod = @($cmds.perfiles.PSObject.Properties.Name).Count } catch {}
    $nReg = (Get-Reglas).Count
    $nRec = (Get-Recetas).Count
    $nDat = @(Get-DatosPerfil).Count
    $p += "tengo $nMod modos, $nReg reglas, $nRec tareas aprendidas y $nDat cosas sabidas de ti"
    # cada frase empieza en mayuscula: en la tarjeta se lee, no solo se oye
    return (@($p | ForEach-Object { $_.Substring(0, 1).ToUpper() + $_.Substring(1) }) -join '. ') + '.'
}

# PLAZO POR MODO (auditoria del 13/09): con un solo plazo de 240 s, si Haiku se
# colgaba traduciendo (tarda ~5 s) Nova se quedaba 4 min "Entendiendo".
function Get-PlazoJob {
    switch ([string]$script:jobModo) {
        'traducir' { return 25000 }
        'plan' { return 25000 }
        'pregunta' { return 90000 }
        'charla' { return 90000 }
        default { return $CliTimeoutMs }
    }
}

# SE APUNTA EL USO AQUI, que es el unico sitio por el que se usa una traduccion (D6,
# 21/09). En memoria y sin tocar el disco: guardar en cada acierto seria escribir un
# fichero en mitad de una orden, y eso es justo lo que no se hace.
function Add-UsoTraduccion([string]$clave) {
    if (-not $clave) { return }
    # CONTAR NO PUEDE TUMBAR UNA ORDEN (21/09). Esto corre DENTRO de Find-Traduccion, o
    # sea en mitad de resolver lo que acabas de decir: si la tabla no estuviera creada,
    # el indexador revienta con NullArray y se lleva la orden por delante. Lo canto un
    # banco que no la declaraba, y ahi se ve el riesgo de verdad: un contador que no le
    # importa a nadie no puede ser la razon de que Nova no te abra el Steam.
    if ($null -eq $script:traduccionesUsos) { $script:traduccionesUsos = @{} }
    try {
        $script:traduccionesUsos[$clave] = 1 + [int]$script:traduccionesUsos[$clave]
        $script:traduccionesUsoSucio = $true
    } catch { }
}

function Find-Traduccion([string]$text) {
    $t = Get-Traducciones
    if ($t.Count -eq 0) { return $null }
    $clave = ConvertTo-Plain $text
    if ($t.ContainsKey($clave)) { Add-UsoTraduccion $clave; return $t[$clave] }
    # tolerancia a variaciones del dictado sobre algo ya aprendido.
    # LA MAS PARECIDA, NO LA PRIMERA (17/09). Devolvia la primera clave que entrara en el
    # tope, asi que con dos parecidas el resultado dependia del ORDEN DEL HASHTABLE: un
    # fallo que puede cambiar de una ejecucion a otra y que por eso no se reproduce.
    # Hoy no puede pasar -hay 2 traducciones y no se parecen en nada (distancia ~25 sobre
    # un tope de 5)-, asi que esto no rescata nada: cuesta tres lineas y hace que la
    # respuesta sea siempre la misma. El empate se rompe por orden alfabetico, no por
    # como esten guardadas.
    $mejorK = ''
    $mejorD = 999
    foreach ($k in $t.Keys) {
        if ([Math]::Abs($k.Length - $clave.Length) -gt 6) { continue }
        $tope = [Math]::Max(2, [int][Math]::Floor($k.Length * 0.2))
        $dK = Get-Distancia $clave $k
        if ($dK -gt $tope) { continue }
        if ($dK -lt $mejorD -or ($dK -eq $mejorD -and $k -lt $mejorK)) { $mejorD = $dK; $mejorK = $k }
    }
    if ($mejorK) { return $t[$mejorK] }
    return $null
}

# ¿Reconoceria la capa local esta frase? SOLO resuelve, no ejecuta nada. Se
# usa sobre la transcripcion EN VIVO para que la capsula asienta ("lo tengo")
# antes de que termines de hablar.
function Test-FastCommand([string]$text) {
    if (-not $cmds -or -not $text) { return $false }
    # el MISMO patron completo que usa el ejecutor: con solo "aprende que"
    # decia si, y luego no habia nada que aprender (y de paso Repair-Verb
    # convertia "aprende" en "prende" y la frase se perdia)
    if ($text -match '(?i)^\s*aprende\s+que\s+(?:a\s+)?(.+?)\s+(?:le\s+(?:digo|llamo|dicen)|es|se\s+llama)\s+(.+)$') { return $true }
    # OLVIDAR UN DATO, los MISMOS patrones que el ejecutor (18/09). No tenian espejo aqui, ni el
    # viejo "olvida que X": el banco decia "IA" para todos aunque en produccion si se ejecutaban.
    if ($text -match '(?i)^\s*(?:olvida|olv[ií]date de|borra)\s+(?:que|lo de)\s+(.+)$') { return $true }
    if ($text -match '(?i)^\s*(?:eso\s+(?:es\s+)?(?:un\s+dato\s+)?(?:falso|mentira|incorrecto|no\s+es\s+(?:verdad|cierto|asi))\s*[,.]?\s*)?(?:elim[ií]nalo|b[oó]rralo|qu[ií]talo|olv[ií]dalo|olvida\s+eso|borra\s+eso|elimina\s+eso)\s*[.!]?$') { return $true }
    # el MISMO patron que el ejecutor del deshacer (23/09): sin espejo aqui, el banco diria
    # "IA" para "vuelve a ponerlo" cuando en produccion se resuelve en local.
    if ($text -match '(?i)^\s*(?:no\s*[,.]?\s*)?(?:vuelve\s+a\s+ponerlo|ponlo\s+(?:otra\s+vez|de\s+nuevo)|devu[eé]lvelo|deshaz\s+eso|no\s+lo\s+borres|era\s+verdad)\s*[.!]?$') { return $true }
    if ($text -match '(?i)^\s*(?:(?:el|lo|la|los|las)\s+(?:de|del|de la|de los)\s+)?(.+?)\s*[,.]?\s*(?:elim[ií]nalo|b[oó]rralo|qu[ií]talo|olv[ií]dalo)\s*[.!]?$' -or
        $text -match '(?i)^\s*(?:elimina|quita|borra|olvida)\s+(?:el\s+dato\s+(?:de|del|sobre)|lo\s+(?:de|del)|(?:el|la|los|las)\s+(?:de|del))\s+(.+)$') { return $true }
    # el MISMO patron que el ejecutor, o el banco no ve que crear un modo es local
    # NOMBRES DE DOS PALABRAS (23/09, verificando la idea 17): ver Invoke-FastCommand
    if ($text -match '(?i)^\s*(?:crea|crear|haz|hazme|define|guardame)\s+(?:el\s+|un\s+)?modo\s+([^:,]{2,20})\s*[:,]\s*(.+)$' -or
        $text -match '(?i)^\s*(?:crea|crear|haz|hazme|define|guardame)\s+(?:el\s+|un\s+)?modo\s+([^\s:,]{2,20})\s*(?::|,|\s+que\s+|\s+con\s+|\s+)\s*(.+)$') { return $true }
    $pl = ConvertTo-Plain $text
    if ($pl -match '^(?:recuerdame|avisame|recordatorio)\s+(?!que\b)(?:hoy|manana|pasado manana|el (?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)|el \d{1,2} de |a las? )') { return $true }   # recordatorio con fecha
    # ojo: los mismos lookaheads que el ejecutor. Con el patron corto, este
    # atajo devolvia $true y se saltaba Resolve-Fragment, de modo que el
    # banco no podia ver que "guarda el archivo" acababa en el diario.
    if ($text -match '(?i)^\s*(?:recu[eé]rdame|recuerda|acu[eé]rdate|anota|apunta|guarda(?=\s+(?:que|de\s+que)\b)|memoriza)\s+(?!.*\s(?:en|a)\s+(?:la\s+|mi\s+)?lista(?:\s+de\s+.+)?$)(?!(?:en|dentro de)\s+(?:\d+|un|una|uno|medi[ao]|(?:un\s+)?cuarto\s+de|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|diecis\S+|veinte|veinti\S+|treinta|cuarenta|cincuenta|sesenta|noventa)(?:\s+y\s+\S+)?\s+(?:segundos?|minutos?|horas?)\b)(?!(?:\d+|un|una|medi[ao]|(?:un\s+)?cuarto\s+de|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|diecis\S+|veinte|veinti\S+|treinta|cuarenta|cincuenta|sesenta|noventa)(?:\s+y\s+\S+)?\s+(?:minutos?|horas?)(?:\s+y\s+media)?\s+antes\b)(?!(?:esto|eso|esta pantalla|lo de la pantalla|lo que dice la pantalla|lo que pone|este codigo|el codigo|la clave|la combinacion|esta clave|este numero)$)(?!(?:hoy|ma[nñ]ana|pasado\s+ma[nñ]ana|el\s+(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo)|el\s+\d{1,2}\s+de\s|a\s+las?\s)\b)(?!(?:cual|cuales|que es|que fue|si|donde|cuando|quien|como|cuanto)\b)(?:que\s+|de\s+que\s+)?(.+)$' -and $text -notmatch '\?\s*$') { return $true }
    # Reglas y recordatorios con hora: los decide Invoke-ReglaVoz, que SI crea
    # cosas, asi que aqui no se puede llamar. Se responde $true solo si la
    # frase tiene la forma de una regla; el banco las prueba aparte llamando
    # al de verdad. Antes era un $false seco y la capsula nunca asentia a una
    # regla, aunque fuera perfecta.
    # OJO: solo las formas que DE VERDAD son una regla. Con un '^cuando\s' a
    # secas se colaban preguntas sobre el pasado -"cuando jugue a outlast"- que
    # no son reglas y acababan en el modelo por nada.
    # Y 'A LAS?' PIDE UNA HORA DETRAS (21/09). Estaba puesto como 'a las?\s' a secas,
    # o sea que CUALQUIER frase que empiece por 'a la ' o 'a las ' entraba aqui como si
    # fuera una regla horaria, y salia por el return de abajo: falso, salvo que llevara
    # un verbo de accion. Sin pasar por Resolve-Fragment, o sea sin que nadie mirara si
    # era una orden. Se iban al modelo, calladas:
    #     'a la derecha' y 'a la izquierda'  -> media pantalla; el switch existe y no
    #                                           lo alcanzaba nadie
    #     'a la mitad'                       -> el volumen a la mitad
    # Con la hora detras, 'a las tres apaga el wifi' sigue entrando -que para eso esta-
    # y 'a la una' tambien, que es la unica hora que va en singular.
    # LAS PALABRAS TAMBIEN CUENTAN, Y EN LAS DOS PUERTAS (23/09, idea 4). Invoke-ReglaVoz pasa
    # ahora la frase por ConvertTo-Digitos, asi que "cada DOS horas di que estire la espalda"
    # SI crea la regla. Si esta puerta no hiciera lo mismo, la regla se crearia y la capsula
    # no asentiria, y el banco -Probar la daria por no reconocida: verde en un sitio, rojo en
    # la realidad. Es la misma leccion del commit e1ab4dc, dos listas que se separan.
    $plD4 = ConvertTo-Digitos $pl
    if ($plD4 -match '^(?:cuando\s+(?:se\s+)?(?:abra|abras|inicie|inicies|arranque|empiece|entre|cierre|cierres|termine|acabe|complete|salga|la bateria|la pila|quite|quites|enchufe|enchufes|ponga|pongas|conecte|desconecte)|(?:recuerdame|avisame|recuerda|dime)\s+cada\s+(?:\d+|media|un|una)\s*(?:minuto|hora)|cada\s+(?:\d+|media|un|una)\s*(?:minuto|hora)|todos los dias|a las?\s+(?:\d{1,2}\b|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|medianoche|mediodia))') {
        return [bool]($pl -match ('(?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame|abrelo|abrela|ejecutalo|lanzalo|inicialo|arrancalo|juegalo)\b'))
    }
    # el mismo corte que en Invoke-FastCommand: este es el camino que usan la
    # capsula y el banco de pruebas, y tiene que decir lo mismo que el ejecutor
    if (Test-CatalogoRecitado $text) { return $false }
    $frags = $null
    try { $frags = Split-Ordenes $text } catch { return $false }
    if (-not $frags -or $frags.Count -eq 0) { return $false }
    $dudosaAntes = $script:dudosa
    try {
        foreach ($f in $frags) {
            $a = $null
            try { $a = Resolve-Fragment $f } catch { $a = $null }
            if (-not $a) { return $false }
        }
        return $true
    } finally { $script:dudosa = $dudosaAntes }
}

# LA RED DE ATRAS DEL DEICTICO (23/09, idea 2). El verbo de cabeza decide A PRIORI, pero el
# oido va al 70,4 % y una frase puede acabar en una accion sin empezar por un verbo claro.
# Esto mira la frase YA REESCRITA: si al resolverla sale un kind de $AccionesQueTocan, no es
# una pregunta y no se ejecuta sola, se pregunta. Dos cierres para lo mismo, a proposito.
# Guarda y restaura $script:dudosa igual que hace Test-FastCommand, o resolver aqui dejaria
# una duda encendida que luego pagaria la frase de verdad.
function Test-SoloPregunta([string]$frase) {
    if (-not $frase) { return $true }
    $fragsP = $null
    try { $fragsP = Split-Ordenes $frase } catch { return $true }
    if (-not $fragsP -or $fragsP.Count -eq 0) { return $true }
    $dudosaAntesP = $script:dudosa
    try {
        foreach ($fP in $fragsP) {
            $aP = $null
            try { $aP = Resolve-Fragment $fP } catch { $aP = $null }
            if (-not $aP) { continue }          # no lo resuelve nadie: acaba en la charla
            foreach ($xP in @($aP)) {
                if ($AccionesQueTocan -contains [string]$xP.kind) { return $false }
            }
        }
        return $true
    } finally { $script:dudosa = $dudosaAntesP }
}

# Las acciones que TOCAN el sistema, por oposicion a las que solo miran o
# cuentan. Sirven para dos cosas distintas y las dos quieren la misma lista: dar
# un respiro entre ellas, y decidir si una orden merece que se pregunte antes
# (una voz que no es la tuya puede preguntar la hora; no puede cerrar el juego).
$AccionesQueTocan = @('app', 'url', 'key', 'atajo', 'escribir', 'winkey', 'altf4', 'alttab', 'otroMonitor', 'crearAlgo',
                      'enfocar', 'enfocarJuego', 'buscarEquipo', 'winprt', 'winaltg',
                      'volumenPct', 'brillo', 'lock', 'cerrarApp', 'cerrarJuego', 'cerrarTodo')

# PONER EL VIDEO, NO SOLO BUSCARLO (15/09). "Reproduce la cancion de Pitbull Give Me
# Everything en YouTube" abria la busqueda; braya se quejo y el agente tardo 83 s en
# ponerla. La pagina de resultados de YouTube ya trae los videoId: se abre el primero,
# sin clave ni agente. Probado: "pitbull give me everything" -> "Pitbull - Give Me
# Everything ft. Ne-Yo, Afrojack, Nayer". Si falla o tarda, la busqueda como antes.
# ABRIR UNA CARPETA POR SU NOMBRE (15/09): "abre la carpeta Games" (la del escritorio) no se
# entendia; la API lo tradujo a "abre explorador" y ademas se aprendio. Primero los nombres
# de siempre (descargas, documentos...); si no, una carpeta con ese nombre en el escritorio,
# documentos, descargas, la carpeta personal, imagenes, videos o musica.
# LAS SIETE DE SIEMPRE, escritas una vez y usadas en los dos sitios: aqui y en los patrones
# de contar y medir, donde hacen de lista cerrada para cuando braya no dice "carpeta".
$CARPETAS_FIJAS = 'descargas|documentos|escritorio|imagenes|fotos|musica|videos'
function Find-CarpetaPorNombre([string]$nombre) {
    $pl = ConvertTo-Plain $nombre
    if (-not $pl) { return '' }
    $especiales = @{
        'descargas' = (Join-Path $env:USERPROFILE 'Downloads'); 'documentos' = [Environment]::GetFolderPath('MyDocuments')
        'escritorio' = [Environment]::GetFolderPath('Desktop'); 'imagenes' = [Environment]::GetFolderPath('MyPictures')
        'fotos' = [Environment]::GetFolderPath('MyPictures'); 'musica' = [Environment]::GetFolderPath('MyMusic')
        'videos' = [Environment]::GetFolderPath('MyVideos')
    }
    if ($especiales.ContainsKey($pl) -and $especiales[$pl] -and (Test-Path -LiteralPath $especiales[$pl])) { return $especiales[$pl] }
    $raices = @([Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('MyDocuments'), (Join-Path $env:USERPROFILE 'Downloads'),
                $env:USERPROFILE, [Environment]::GetFolderPath('MyPictures'), [Environment]::GetFolderPath('MyVideos'), [Environment]::GetFolderPath('MyMusic'))
    $parecida = ''
    foreach ($r in $raices) {
        if (-not $r -or -not (Test-Path -LiteralPath $r)) { continue }
        foreach ($d in @(Get-ChildItem -LiteralPath $r -Directory -ErrorAction SilentlyContinue)) {
            $pd = ConvertTo-Plain $d.Name
            if ($pd -eq $pl) { return $d.FullName }
            if (-not $parecida -and $pd -and [Math]::Min($pd.Length, $pl.Length) -ge 4 -and ($pd.StartsWith($pl) -or $pl.StartsWith($pd))) { $parecida = $d.FullName }
        }
    }
    return $parecida
}

# LO QUE HAY DENTRO DE UNA CARPETA (23/09, idea 9). Va pegada a Find-CarpetaPorNombre porque
# son pareja: una resuelve el nombre y la otra mira dentro, y asi un banco puede sacar las dos
# con el mismo parser.
# CON TOPE DE TIEMPO Y DE FICHEROS, y eso es lo que la hace distinta de Get-TamanoMB, que no
# tiene ninguno: un Get-ChildItem -Recurse sobre Descargas dentro del bucle deja el juego
# tirando, y aqui braya esta jugando casi siempre. Al pasarse, se corta y se DICE que el
# numero va por lo menos: media respuesta dicha como media respuesta, no como entera.
# DE DONDE SALEN 1200 Y 20000 (24/09, repaso: el comentario explicaba por que hay tope, no de
# donde salia el numero). 1.200 ms es el hueco que ya se considera aceptable en esta casa para
# una orden hablada: es el mismo orden que el arranque de powershell.exe que paga la guia
# (~2 s) y menos de la mitad del tope de red de 6 s que llevan las llamadas sincronas. Y 20.000
# ficheros es cuatro veces lo que tiene su carpeta mas gorda; se cuentan para no depender solo
# del reloj, que en una lectura de microSD puede irse de golpe.
# LOS DOS SE PUEDEN AJUSTAR CON DATOS: cada corte queda apuntado como 'parcial' en la respuesta.
function Get-ResumenCarpeta([string]$ruta, [bool]$conTamano = $false, [int]$topeMs = 1200, [int]$topeFich = 20000) {
    if (-not $ruta -or -not (Test-Path -LiteralPath $ruta)) { return @{ ok = $false } }
    $r = @{ ok = $true; ficheros = 0; carpetas = 0; nombres = @(); bytes = 0; parcial = $false }
    try {
        $hijos = @(Get-ChildItem -LiteralPath $ruta -Force -ErrorAction SilentlyContinue)
        # 'desktop.ini' lo pone Windows y no es de braya: el mismo filtro que ya usa la frase
        # del escritorio
        $hijos = @($hijos | Where-Object { $_.Name -ne 'desktop.ini' })
        $r.ficheros = @($hijos | Where-Object { -not $_.PSIsContainer }).Count
        $r.carpetas = @($hijos | Where-Object { $_.PSIsContainer }).Count
        $r.nombres = @($hijos | Sort-Object Name | Select-Object -First 12 | ForEach-Object {
            if ($_.PSIsContainer) { $_.Name } else { ($_.Name -replace '\.(lnk|url)$', '') } })
    } catch { return @{ ok = $false } }
    if ($conTamano) {
        $cron = [System.Diagnostics.Stopwatch]::StartNew()
        $n = 0
        try {
            foreach ($f in [System.IO.Directory]::EnumerateFiles($ruta, '*', [System.IO.SearchOption]::AllDirectories)) {
                try { $r.bytes += (New-Object System.IO.FileInfo($f)).Length } catch {}
                $n++
                # EL RELOJ se mira cada 200, no en cada fichero: preguntar la hora 20.000 veces
                # cuesta mas que sumar 20.000 tamanos. El CONTADOR, en cambio, se mira
                # siempre: comparar dos enteros es gratis, y mirandolo cada 200 una carpeta
                # de diez ficheros no podia cortarse nunca, o sea que ese tope no existia.
                if ($n -gt $topeFich -or (($n % 200) -eq 0 -and $cron.ElapsedMilliseconds -gt $topeMs)) { $r.parcial = $true; break }
            }
        } catch { $r.parcial = $true }
    }
    return $r
}

# EL VIDEO NUMERO N (16/09). El 15/09, "reproduce el segundo video de YouTube" y
# "reproduce la segunda cancion de el" se fueron al agente cuatro veces (hasta 88 s) y
# ni asi. Es la misma pagina de resultados: basta con coger la coincidencia numero N,
# quitando repetidos (YouTube repite el mismo videoId varias veces en el HTML).
# LO QUE NO LE GUSTA (23/09, idea 1-B). Fichero propio, no el perfil: el perfil esta a 59 de
# 60, tiro un dato cuatro veces el 22/09 y su filtro ya rechazo diez preferencias suyas. Un
# gusto musical ahi entra directo en la cola de expulsion.
# El tope de 60 es el MISMO del perfil, no un numero nuevo.
function Get-MusicaNoPath { return (Join-Path $MemoriaDir 'musica-no.json') }
$MusicaNoMax = 60
$script:musicaNo = $null
function Get-MusicaNo {
    # LA COMA, TAMBIEN AQUI: esta es la salida que se usa el 99 % de las veces -la de abajo
    # solo la primera- y sin ella la lista vacia volvia a llegar como $null.
    if ($null -ne $script:musicaNo) { return ,$script:musicaNo }
    $script:musicaNo = New-Object System.Collections.ArrayList
    try {
        if (Test-Path -LiteralPath (Get-MusicaNoPath)) {
            $j = Get-Content -LiteralPath (Get-MusicaNoPath) -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($x in $j) {
                if ($null -eq $x) { continue }
                [void]$script:musicaNo.Add(@{ q = [string]$x.q; t = [string]$x.t; id = [string]$x.id; f = [string]$x.f })
            }
        }
    } catch { Save-Corrupto (Get-MusicaNoPath) 'musica-no' }
    # LA COMA NO ES UN ADORNO: sin ella, PowerShell desenrolla la lista y una lista VACIA se
    # convierte en $null, asi que el primer "no me gusta" reventaba al anadir. Es el mismo
    # bicho que ya documentan Get-Recordatorios y Get-Reglas.
    return ,$script:musicaNo
}
function Save-MusicaNo {
    try {
        $lista = @()
        foreach ($x in $script:musicaNo) {
            $o = New-Object PSObject
            foreach ($k in 'q', 't', 'id', 'f') { $o | Add-Member -NotePropertyName $k -NotePropertyValue $x[$k] }
            $lista += $o
        }
        $json = if ($lista.Count -eq 0) { '[]' } else { ConvertTo-Json -InputObject @($lista) -Depth 3 }
        Write-Atomico (Get-MusicaNoPath) $json
    } catch {}
}
# DEVUELVE LO QUE TUVO QUE SOLTAR, para poder decirlo en voz alta: una lista que se poda en
# silencio es una lista en la que dejas de confiar.
function Add-MusicaNo([string]$que, [string]$titulo, [string]$id) {
    if ($script:invitado) { return '' }
    $q = (ConvertTo-Plain $que).Trim()
    if (-not $q -and -not $id) { return '' }
    $l = Get-MusicaNo
    foreach ($x in @($l)) {
        if ((ConvertTo-Plain ([string]$x.q)) -eq $q -and $q) { return '' }   # ya estaba
    }
    [void]$l.Add(@{ q = $que; t = $titulo; id = $id; f = (Get-Date).ToString('s') })
    $soltado = ''
    while ($l.Count -gt $MusicaNoMax) { $soltado = [string]$l[0].q; $l.RemoveAt(0) }
    Save-MusicaNo
    Log "MUSICA NO: '$que'$(if ($titulo) { " ($titulo)" } else { '' })"
    return $soltado
}
function Remove-MusicaNo([string]$que) {
    # MODO INVITADO: lo que diga otro no se queda (24/09, repaso). Add-MusicaNo ya lo miraba
    # y esta no: quitar un veto tambien cambia la lista de braya para siempre, asi que la
    # pareja no puede deshacer un "esa no me gusta" suyo diciendo "vuelve a ponerla".
    if ($script:invitado) { return $false }
    $q = (ConvertTo-Plain $que).Trim()
    if (-not $q) { return $false }
    $l = Get-MusicaNo
    $fuera = @($l | Where-Object { (ConvertTo-Plain ([string]$_.q)).Contains($q) })
    if ($fuera.Count -eq 0) { return $false }
    foreach ($x in $fuera) { [void]$l.Remove($x) }
    Save-MusicaNo
    Log "MUSICA NO: quitado '$que'"
    return $true
}
# EL MINIMO DE CUATRO LETRAS no es de adorno: es el mismo criterio que ya usan las demas
# comparaciones por palabra. Con menos, un veto de dos letras tacharia media lista.
# LO QUE DE VERDAD VETA UNA FRASE (24/09, repaso). De "pon algo de musica rock" lo que veta
# es "rock", no "musica" ni "algo": las palabras de relleno estan aqui a proposito, porque son
# las que hacen que un veto tache media biblioteca. Y se piden al menos cuatro letras a la que
# quede, que es lo que separa un genero de un "de" mal oido.
$MusicaNoRelleno = @('musica', 'cancion', 'canciones', 'tema', 'temas', 'video', 'videos',
                     'pon', 'ponme', 'algo', 'de', 'del', 'la', 'el', 'los', 'las', 'un',
                     'una', 'y', 'en', 'tipo', 'tipos', 'esa', 'ese', 'esta', 'este', 'eso')
function Get-MusicaNoClaves([string]$q) {
    $out = @()
    foreach ($w in @((ConvertTo-Plain ([string]$q)) -split '[^a-z0-9]+')) {
        if (-not $w) { continue }
        if ($MusicaNoRelleno -contains $w) { continue }
        if ($w.Length -lt 4) { continue }
        $out += $w
    }
    return @($out)
}

# POR PALABRAS ENTERAS, NO POR TROZOS (24/09, repaso). Antes era Contains() a pelo con cuatro
# letras: "no me gusta nada" dejaba q = "nada" y tachaba "enamorada" para siempre, y el video
# desaparecia en silencio. Ahora hacen falta TODAS las palabras con contenido del veto, y cada
# una como palabra entera.
function Test-MusicaVetada([string]$titulo, [string]$id) {
    $l = Get-MusicaNo
    if ($l.Count -eq 0) { return $false }
    $t = ConvertTo-Plain ([string]$titulo)
    foreach ($x in @($l)) {
        # EL ID ES EXACTO Y NO FALLA NUNCA: esa cancion concreta no vuelve a salir.
        if ($id -and [string]$x.id -eq $id) { return $true }
        if (-not $t) { continue }
        $claves = @(Get-MusicaNoClaves ([string]$x.q))
        if ($claves.Count -eq 0) { continue }
        $todas = $true
        foreach ($k in $claves) {
            if ($t -notmatch ('(?<![a-z0-9])' + [regex]::Escape($k) + '(?![a-z0-9])')) { $todas = $false; break }
        }
        if ($todas) { return $true }
    }
    return $false
}

# LOS RESULTADOS DE VERDAD, CON SU TITULO (23/09, idea 1-A). PURA: se le da el HTML y
# devuelve la lista, asi que un banco puede probarla sin tocar la red.
# EL REGEX ESTA VALIDADO HOY contra las cuatro paginas reales de sus busquedas: da 19, 16, 19
# y 28 bloques, el 100 % con titulo. El de antes -'"videoId":"..."' a secas- daba 45, 71, 45
# y 28, o sea que mezclaba los videos de verdad con los de las estanterias y las playlists, y
# por eso "el tercero" nunca era el tercero.
# El {0,4000} acota al perezoso para que no salte al bloque siguiente.
# LA GUIA DEL JUEGO, FUERA DEL BUCLE (23/09, idea 6). Se lanza tools\guia-web.ps1 en otro
# proceso y se recoge cuando llegue, igual que ya se hace con el ayudante de la API. El bucle
# no espera a nadie: braya juega mientras habla.
$script:guiaProc = $null
$script:guiaOut = ''
$script:guiaDesde = 0
$script:guiaJuego = ''
function Get-GuiaTiemposPath { return (Join-Path $MemoriaDir 'guia-tiempos.json') }
function Get-GuiaTiempos {
    $out = @()
    try {
        if (-not (Test-Path -LiteralPath (Get-GuiaTiemposPath))) { return $out }
        $j = Get-Content -LiteralPath (Get-GuiaTiemposPath) -Raw -Encoding UTF8 | ConvertFrom-Json
        foreach ($x in $j) { $out += [int]$x }
    } catch { return @() }
    return $out
}
function Add-GuiaTiempo([int]$ms) {
    if ($ms -le 0) { return }
    $l = @(Get-GuiaTiempos) + $ms
    if ($l.Count -gt 200) { $l = @($l | Select-Object -Last 200) }
    try { Write-Atomico (Get-GuiaTiemposPath) (ConvertTo-Json -InputObject @($l) -Depth 2) } catch {}
}
# EL PLAZO SE PONE CON DATOS O NO SE PONE. Con pocas medidas, 8 s: los 6 s que ya lleva de
# tope la busqueda de YouTube mas 2 s de arrancar powershell.exe. A partir de ahi, el p90 de
# lo medido por vez y media, entre 4 y 15 s.
function Get-GuiaPlazoMs {
    $l = @(Get-GuiaTiempos)
    if ($l.Count -lt $DecisionMinIntentos) { return 8000 }
    $orden = @($l | Sort-Object)
    $p90 = [int]$orden[[int][Math]::Floor(($orden.Count - 1) * 0.9)]
    return [Math]::Max(4000, [Math]::Min(15000, [int]($p90 * 1.5)))
}

function Stop-Guia {
    if (-not $script:guiaProc) { return }
    # SIN ESPERAR (24/09, repaso): esto se llama desde el bucle, y arrancar taskkill.exe con
    # -Wait son 100-400 ms parado en el mismo tick en el que se lee el mando. Kill() no
    # arranca ningun proceso y vuelve al momento; el /T de taskkill no hacia falta porque el
    # script de la guia no lanza hijos.
    try { if (-not $script:guiaProc.HasExited) { $script:guiaProc.Kill() } } catch {}
    try { $script:guiaProc.Dispose() } catch {}
    try { if ($script:guiaOut) { Remove-Item -LiteralPath $script:guiaOut -Force -ErrorAction SilentlyContinue } } catch {}
    $script:guiaProc = $null
    $script:guiaOut = ''
}

function Start-GuiaJuego([string]$juego) {
    Stop-Guia   # una guia a la vez: la anterior se cancela
    try {
        $script:guiaOut = Join-Path $TmpDir ('guia-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.json')
        $script:guiaProc = Start-Process -FilePath 'powershell.exe' -WindowStyle Hidden -PassThru `
            -ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $GuiaScript,
                            '-Juego', ('"' + $juego + '"'), '-SalidaArchivo', ('"' + $script:guiaOut + '"'))
        $null = $script:guiaProc.Handle
        $script:guiaDesde = $sw.ElapsedMilliseconds
        return $true
    } catch { Log ("guia: no pude lanzarla: " + $_.Exception.Message); $script:guiaProc = $null; return $false }
}

# LO QUE SE DICE EN VOZ ALTA: una frase si esta jugando, dos si no. Es el mismo criterio que
# ya se impone en la charla -jugando, corto- y no un numero nuevo.
function Get-GuiaFrases([string]$texto, [int]$n) {
    if (-not $texto) { return '' }
    $t = ($texto -replace '\s+', ' ').Trim()
    $frases = @([regex]::Split($t, '(?<=[.!?])\s+') | Where-Object { $_.Trim() })
    if ($frases.Count -eq 0) { return $t }
    return (($frases | Select-Object -First $n) -join ' ').Trim()
}

# UNA VUELTA DEL BUCLE = UN HasExited. Cero red aqui.
function Receive-Guia {
    if (-not $script:guiaProc) { return }
    $vivo = $true
    try { $vivo = -not $script:guiaProc.HasExited } catch { $vivo = $false }
    $plazo = Get-GuiaPlazoMs
    if ($vivo) {
        if (($sw.ElapsedMilliseconds - $script:guiaDesde) -lt $plazo) { return }
        Log "GUIA: $($script:guiaJuego) tardo mas de $plazo ms; la corto"
        Stop-Guia
        Say 'No he podido mirarlo.'
        return
    }
    $txt = ''
    try { if ($script:guiaOut -and (Test-Path -LiteralPath $script:guiaOut)) { $txt = Get-Content -LiteralPath $script:guiaOut -Raw -Encoding UTF8 } } catch {}
    $salida = $script:guiaOut
    $script:guiaProc = $null
    $script:guiaOut = ''
    try { if ($salida) { Remove-Item -LiteralPath $salida -Force -ErrorAction SilentlyContinue } } catch {}
    if (-not $txt) { Say ('No he podido mirar lo de ' + $script:guiaJuego + '.'); return }
    $j = $null
    try { $j = $txt | ConvertFrom-Json } catch { $j = $null }
    if (-not $j) { Say ('No he podido mirar lo de ' + $script:guiaJuego + '.'); return }
    # SE MIDE LO QUE SE COMPARA (24/09, repaso). Antes se guardaba el $res.ms del script, cuyo
    # cronometro arranca DENTRO, con powershell.exe ya levantado; y el plazo se compara contra
    # el tiempo desde que se LANZO, que incluye ese arranque de ~2 s. Eran dos cosas distintas
    # con el mismo nombre.
    try { Add-GuiaTiempo ([int]($sw.ElapsedMilliseconds - $script:guiaDesde)) } catch {}
    if (-not $j.ok) {
        Log "GUIA: $($script:guiaJuego) sin articulo ($($j.motivo))"
        Say ('No he encontrado nada de ' + $script:guiaJuego + ' en la Wikipedia.')
        return
    }
    $nFr = if ($script:juegoActivo) { 1 } else { 2 }
    $frase = Get-GuiaFrases ([string]$j.texto) $nFr
    $deDonde = if ([string]$j.fuente -eq 'en.wikipedia') { ' Lo he sacado de la Wikipedia en ingles.' } else { ' Es de la Wikipedia.' }
    Log "GUIA: $($script:guiaJuego) -> $($j.titulo) ($($j.fuente), $($j.ms) ms)"
    Add-Estadistica 'guia-juego' ([string]$script:guiaJuego)
    # SE DICE CON Say, NO CON Send-Aviso: un aviso con el juego delante se queda MUDO, y aqui
    # el juego delante es justo el caso. Esto es la respuesta a una orden suya, no un aviso.
    $script:ultimaRespuesta = $frase + $deDonde
    Show-Popup ($frase + $deDonde)
    Say ($frase + $deDonde)
}

function Get-VideosDeHtml([string]$html) {
    $out = @()
    if (-not $html) { return $out }
    $vistos = @{}
    foreach ($m in [regex]::Matches($html, '"videoRenderer":\{"videoId":"([A-Za-z0-9_-]{11})"[\s\S]{0,4000}?"title":\{"runs":\[\{"text":"(.*?)"\}\]')) {
        $id = $m.Groups[1].Value
        if ($vistos.ContainsKey($id)) { continue }
        $vistos[$id] = $true
        $t = $m.Groups[2].Value
        # el titulo viene escapado como en JSON
        $t = [regex]::Replace($t, '\\u([0-9a-fA-F]{4})', { param($x) [string][char][Convert]::ToInt32($x.Groups[1].Value, 16) })
        $t = $t -replace '\\"', '"' -replace '\\/', '/' -replace '\\\\', '\'
        $out += @{ id = $id; titulo = $t.Trim() }
        # los ordinales llegan al decimo; doce sobra
        if ($out.Count -ge 12) { break }
    }
    return $out
}

# LA PETICION, que es lo unico que toca la red. Si la pagina no trae ni un bloque, se cae al
# regex viejo para no quedar PEOR que hoy: sin titulo, pero con algo.
$script:ytLista = @()
$script:ytN = 0
# LO QUE SE CONTESTA ES DE ALGUIEN: no va entero al registro (24/09, repaso)
$script:respuestaPrivada = $false
$script:ytVetados = 0          # cuantos tacho el veto en la ultima busqueda
$script:ytPuesto = $null
$script:ytHasta = 0
# CUANTO SIGUE VALIENDO "la siguiente" (24/09, repaso: este numero estaba suelto, sin una
# sola linea que dijera de donde salia).
# NO HAY MEDICION Y SE DICE: los 52 intentos de musica del registro acabaron todos mal -"el
# segundo video" se pidio cuatro veces el 15/09 y las cuatro se fueron al agente-, asi que no
# hay ni un hueco medible entre poner una cancion y pedir la siguiente. Se copian los cinco
# minutos de la sordina, que es el otro plazo de la casa pensado para "lo que dura una cosa
# que acabas de pedir". En cuanto haya diez casos de verdad en el registro, se ajusta.
$YtSiguienteMs = 300000
function Get-VideosYouTube([string]$q) {
    if (-not $q) { return @() }
    $lista = @()
    try {
        $r = Invoke-WebRequest -UseBasicParsing -TimeoutSec 6 -Headers @{ 'Accept-Language' = 'es-ES,es;q=0.9' } `
            -Uri ('https://www.youtube.com/results?search_query=' + [Uri]::EscapeDataString($q))
        $lista = @(Get-VideosDeHtml ([string]$r.Content))
        if ($lista.Count -eq 0) {
            $ids = @([regex]::Matches([string]$r.Content, '"videoId":"([A-Za-z0-9_-]{11})"') |
                     ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
            foreach ($id in @($ids | Select-Object -First 12)) { $lista += @{ id = $id; titulo = '' } }
            if ($lista.Count -gt 0) { Log "YOUTUBE: la pagina no trae bloques de resultado; tiro del metodo viejo" }
        }
    } catch { Log ("YOUTUBE: no pude sacar los videos (" + $_.Exception.Message + "); abro la busqueda") }
    $script:ytLista = @($lista)
    $script:ytUltimaBusqueda = $q
    return $script:ytLista
}

# Y EL NUMERO N, SIN VOLVER A LA RED si es la misma busqueda: "no, la siguiente" cuesta una
# frase y cero red, que es el remedio de verdad a que el primero no sea el bueno.
function Select-VideoYouTube([string]$q, [int]$n = 1) {
    if ($n -lt 1) { $n = 1 }
    $lista = @($script:ytLista)
    if ($q -ne [string]$script:ytUltimaBusqueda -or $lista.Count -eq 0) { $lista = @(Get-VideosYouTube $q) }
    if ($lista.Count -eq 0) { return $null }
    # los vetados se saltan (idea 1-B): lo que dijo que no le gusta no vuelve a salir
    $buenos = @()
    foreach ($v in $lista) {
        if (Test-MusicaVetada ([string]$v.titulo) ([string]$v.id)) { continue }
        $buenos += $v
    }
    # SI LOS TACHA TODOS, SE DICE. Antes se ponia el primero igualmente y braya no se enteraba
    # de que su veto habia tachado la busqueda entera; ahora queda en el registro y quien
    # llama puede contarlo.
    $script:ytVetados = $lista.Count - $buenos.Count
    if ($buenos.Count -eq 0) {
        Log "MUSICA: lo que no te gusta tacha los $($lista.Count) resultados de '$q'; pongo el primero igual"
        $buenos = $lista
    } elseif ($script:ytVetados -gt 0) {
        Log "MUSICA: $($script:ytVetados) de $($lista.Count) tachados por lo que no te gusta"
    }
    if ($n -gt $buenos.Count) { $n = $buenos.Count }
    $v = $buenos[$n - 1]
    return @{ id = [string]$v.id; titulo = [string]$v.titulo
              url = ('https://www.youtube.com/watch?v=' + [string]$v.id); n = $n; total = $buenos.Count }
}

function Get-PrimerVideoYouTube([string]$q, [int]$n = 1) {
    if (-not $q) { return '' }
    if ($n -lt 1) { $n = 1 }
    # POR DENTRO YA ES Select-VideoYouTube (23/09, idea 1-A): la firma y lo que devuelve no
    # cambian, asi que los cuatro patrones de ordinal y su banco siguen igual.
    $v = Select-VideoYouTube $q $n
    if (-not $v) { Log "YOUTUBE: '$q' sin videos en la pagina; abro la busqueda"; return '' }
    Log "YOUTUBE: '$q' -> $($v.id)$(if ($v.n -gt 1) { " (el numero $($v.n) de $($v.total))" })$(if ($v.titulo) { ' | ' + $v.titulo } else { '' })"
    return $v.url
}

# LO ULTIMO QUE SE PUSO EN YOUTUBE, para poder decir "pon el segundo" despues
$script:ytUltimaBusqueda = ''
# "el segundo", "la tercera cancion", "el video numero 4"
$ORDINALES_YT = @{ 'primer' = 1; 'primero' = 1; 'primera' = 1; 'segundo' = 2; 'segunda' = 2; 'tercer' = 3
                   'tercero' = 3; 'tercera' = 3; 'cuarto' = 4; 'cuarta' = 4; 'quinto' = 5; 'quinta' = 5
                   # hasta el decimo (18/09): "con la novena cancion" se descarto
                   'sexto' = 6; 'sexta' = 6; 'septimo' = 7; 'septima' = 7; 'octavo' = 8; 'octava' = 8
                   'noveno' = 9; 'novena' = 9; 'decimo' = 10; 'decima' = 10 }
# "el dos", "el tres": cuando Nova pide UN NUMERO, lo que contesta la gente es un cardinal.
$CARDINALES = @{ 'uno' = 1; 'una' = 1; 'dos' = 2; 'tres' = 3; 'cuatro' = 4; 'cinco' = 5
                 'seis' = 6; 'siete' = 7; 'ocho' = 8; 'nueve' = 9; 'diez' = 10 }
# EL SITIO DE LA MUSICA, UNA PREFERENCIA DE VERDAD (18/09). braya pidio "siempre en YouTube",
# la charla dijo "anotado" y no anoto nada. Ahora vive en config.json (musica.sitio) y se
# cambia hablando (ver "cuando te diga que pongas una cancion").
$MusicaSitio = [string](Get-Cfg 'musica' 'sitio' 'youtube')

function Invoke-FastCommand([string]$text) {
    if (-not $cmds) { return $null }
    # EL JUEGO QUE TIENES DELANTE (15/09): jugando a It Takes Two, "busca informacion sobre el
    # juego que esta en pantalla" buscaba esa frase tal cual en Google.
    $reJuegoDelante = '(?i)\b(?:el juego (?:al )?que estoy jugando|el juego que (?:est[aá]|tengo) en (?:la )?pantalla|este juego)\b'
    if ($script:juegoActivo -and $text -match $reJuegoDelante) {
        $text = $text -replace $reJuegoDelante, [string]$script:juegoActivo
    }
    # EL JUEGO QUE SALE EN PANTALLA, SIN ESTAR JUGANDO (15/09): con la ficha de It Takes Two
    # abierta en Steam, "abre el juego que tengo en pantalla" acabo preguntando por Hollow
    # Knight. Se lee la pantalla (OCR) y se busca un juego de la biblioteca que salga ahi.
    if (-not $script:juegoActivo -and $text -match '(?i)\b(?:abre|abras|abrir|inicia|inicies|arranca|lanza|juega|pon)\b' -and
        $text -match '(?i)\b(?:(?:el )?juego que (?:tengo|est[aá]|sale|aparece|hay) en (?:la |mi )?pantalla|ese juego|el juego de la pantalla)\b') {
        $ocrJ = ''
        try { $ocrJ = Invoke-OCR (Save-Captura (Join-Path $TmpDir 'pantalla.png')) } catch { Log ("juego en pantalla: " + $_.Exception.Message) }
        $plOcr = ' ' + (ConvertTo-Plain $ocrJ) + ' '
        $jEnc = @(@($script:Juegos) | Where-Object { $_.nombre -and $plOcr.Contains(' ' + (ConvertTo-Plain ([string]$_.nombre)) + ' ') } |
                  Sort-Object { - ([string]$_.nombre).Length } | Select-Object -First 1)
        if ($jEnc.Count -gt 0) {
            Log "JUEGO EN PANTALLA: '$($jEnc[0].nombre)'"
            $text = "abre $($jEnc[0].nombre) en steam"
        } else {
            Log "JUEGO EN PANTALLA: no veo el nombre de ningun juego de la biblioteca"
        }
    }
    # ENSEÑARLE UNA SECUENCIA (ver New-RecetaEnsenada): "aprende que cuando diga
    # prepara la partida, abre discord y pon modo juego". Va antes que el dato
    # sobre ti y que el alias, que tambien empiezan por "aprende que".
    if ($text -match '(?i)^\s*(?:aprende|apr[eé]ndete|aprendete|recuerda)\s+que\s+(?:cuando|si)\s+(?:te\s+)?(?:diga|digo)\s+(.+)$') {
        $restoE = $Matches[1].Trim()
        $dispE = $null; $cuerpoE = $null
        # lo mas fiable: una coma o dos puntos entre la frase y lo que hay que hacer
        if ($restoE -match '^(.+?)\s*[,:]\s*(?:(?:tienes que|debes|hay que|quiero que|entonces)\s+)?(.+)$') {
            $dispE = $Matches[1]; $cuerpoE = $Matches[2]
        } elseif ($restoE -match ('(?i)^(.+?)\s+(?:(?:tienes que|debes|hay que|quiero que|entonces)\s+)?((?:' + $VERBOS + '|modo|activa|desactiva)\b.+)$')) {
            # sin coma: la frase acaba donde empieza la primera orden
            $dispE = $Matches[1]; $cuerpoE = $Matches[2]
        }
        if ($dispE -and $cuerpoE) { return (New-RecetaEnsenada $dispE $cuerpoE).texto }
        return "Dime la frase y lo que tengo que hacer, por ejemplo: aprende que cuando diga prepara la partida, abre discord y pon modo juego."
    }
    # CONTESTAR UN MENSAJE POR VOZ (13/09): "contestale que ya voy". Se escribe en
    # la app del ultimo mensaje que llego (Discord, WhatsApp...), SIN ENVIAR: Nova
    # no sabe si la conversacion abierta es la de quien te escribio, asi que lo
    # deja escrito y te pide que lo revises. Se lee del texto ORIGINAL (tildes).
    # SIN EL PRONOMBRE PEGADO TAMBIEN (23/09, idea 16): "contesta que ahora voy" es como lo
    # dice el, y hasta hoy no casaba y se iba al modelo. El (?!a\s) NO sobra: sin el, "dile a
    # maria que la llamo" caeria aqui y escribiria en la ventana de quien te escribio el
    # ultimo mensaje, que puede no ser maria.
    if ($text -match '(?i)^\s*(?:cont[eé]stale|cont[eé]sta|resp[oó]ndele|resp[oó]nde|escr[ií]bele|dile)\s+(?!a\s)(?:que\s+)?(.{2,300}?)[\s.]*$') {
        $respM = $Matches[1].Trim()
        $nM = $script:ultimaNotif
        if (-not $nM) { return "No tengo ningun mensaje reciente al que contestar." }
        # Y LA MISMA VENTANA DE DIEZ MINUTOS que para "¿que dice?": contestar a un mensaje de
        # ayer es escribirle a quien no toca.
        if (($sw.ElapsedMilliseconds - $script:ultimaNotifEn) -ge $NotifVentanaMs) { return "El ultimo mensaje que tengo ya es viejo; abre la conversacion tu." }
        $procM = Resolve-Proceso ([string]$nM.app)
        $ventM = if ($procM) { Get-Process -Name $procM.proceso -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1 } else { $null }
        if (-not $ventM) { return "No encuentro $($nM.app) abierto para escribirle." }
        [AX]::ShowWindow($ventM.MainWindowHandle, 9) | Out-Null
        [void][AX]::ForceForeground($ventM.MainWindowHandle)
        Start-Sleep -Milliseconds 400
        if ([AX]::GetForegroundWindow() -ne $ventM.MainWindowHandle) { return "No pude poner $($nM.app) delante para escribir." }
        [System.Windows.Forms.SendKeys]::SendWait(([regex]::Replace($respM, '[+^%~(){}\[\]]', { param($mm) '{' + $mm.Value + '}' })))
        Log "CONTESTAR: escrito en $($nM.app), sin enviar"
        return "Lo he escrito en $($nM.app) sin enviar. Mira que sea la conversacion de $($nM.titulo) y dale a enviar."
    }
    # DONDE TE QUEDASTE (ver JUEGOS): "me quede en el jefe del castillo", "lo
    # dejo en el capitulo 3". Se lee del texto ORIGINAL, con sus mayusculas.
    # Sin un juego delante ni uno cerrado hace poco no hay de que juego
    # hablar: la frase sigue su camino.
    if ($text -match '(?i)^\s*(?:me\s+(?:he\s+)?qued[eé]|me\s+quedo|lo\s+dej[oeé])\s+(?:en|por)\s+(.{3,120}?)[\s.]*$') {
        $notaJ = $Matches[1].Trim()
        # mas estricto que "donde me quede": con el juego delante o cerrado hace
        # menos de 30 min, y sin lo que claramente no es una partida ("me quede
        # en casa"; revision del 13/09)
        $jr = if ($script:juegoActivo) { $script:juegoActivo }
              elseif ($script:ultimoJuego -and ($sw.ElapsedMilliseconds - $script:ultimoJuegoEn) -lt 1800000) { $script:ultimoJuego }
              else { $null }
        if ((ConvertTo-Plain $notaJ) -match '^(?:hoy|aqui|ahora|ya)$|^(?:(?:la |mi |el )?(?:casa|trabajo|escuela|colegio|clase|oficina|cama|calle|coche|carro)|dormid[oa]|sin (?:bateria|luz|internet))\b') { $jr = $null }
        if ($jr) {
            Set-NotaJuego $jr $notaJ
            Log "JUEGOS: nota para $jr -> $notaJ"
            return "Apuntado. En $jr te quedaste en $notaJ."
        }
    }
    # APRENDER UN DATO SOBRE TI (ver PERFIL): "aprende que mi carpeta de capturas
    # es D:\Capturas". Va ANTES que el alias de abajo, que tambien empieza por
    # "aprende que" y contestaria "no supe a que te refieres".
    if ($text -match '(?i)^\s*(?:aprende|apr[eé]ndete|aprendete|ten en cuenta|recuerda siempre|quiero que sepas)\s+que\s+((?:mi|mis|yo|me|a mi)\b.+)$') {
        $datoDicho = $Matches[1].Trim().TrimEnd('.')
        $guardado = Add-DatoPerfil ("Dicho por braya: " + $datoDicho) 'lo dijiste'
        if ($guardado) { return "Aprendido sobre ti: $datoDicho." }
        return "Eso ya lo sabia, o no es algo que guarde."
    }
    # OLVIDAR UN DATO: "olvida que mi juego favorito es..." (si no se parece a
    # ninguno, la frase sigue su camino: puede ser otra cosa)
    if ($text -match '(?i)^\s*(?:olvida|olv[ií]date de|borra)\s+(?:que|lo de)\s+(.+)$') {
        $quitado = Remove-DatoPerfil $Matches[1]
        if ($quitado) { return "Olvidado: " + ($quitado -replace '^Dicho por braya:\s*', '') + "." }
    }
    # "ESO ES UN DATO FALSO, ELIMINALO" (18/09): lo ULTIMO que aprendio de ti, fuera. braya lo
    # dijo asi dos veces y Nova contesto "?de donde sacas que lo tengo?"; podia aprender datos
    # falsos y no habia forma de borrarlos hablando.
    if ($text -match '(?i)^\s*(?:eso\s+(?:es\s+)?(?:un\s+dato\s+)?(?:falso|mentira|incorrecto|no\s+es\s+(?:verdad|cierto|asi))\s*[,.]?\s*)?(?:elim[ií]nalo|b[oó]rralo|qu[ií]talo|olv[ií]dalo|olvida\s+eso|borra\s+eso|elimina\s+eso)\s*[.!]?$' -and (Get-UltimoDatoPerfil)) {
        # POR DISCO SI LA SESION ES NUEVA (23/09): ver Get-UltimoDatoPerfil. Nova arranca 16,3
        # veces al dia, y antes esta frase no apuntaba a nada despues de cada arranque.
        $quitado = Remove-DatoPerfil (Get-UltimoDatoPerfil)
        $script:ultimoDatoPerfil = ''
        if ($quitado) { return "Vale, lo quito: " + ($quitado -replace '^Dicho por braya:\s*', '') + "." }
        return "Eso ya no lo tenia apuntado."
    }
    # DESHACER UN BORRADO (23/09, idea 7). Es la otra mitad de la regla 1: si Nova se lleva un
    # dato que braya no queria perder, tiene que poder devolverlo hablando, sin abrir el
    # fichero. VA DELANTE del cajon de sastre de abajo, que se come cualquier frase acabada
    # en "ponlo" solo si lleva "eliminalo" -no es el caso-, pero tambien delante del cerebro.
    # Cinco minutos: el hueco entre lo que dice Nova y la correccion de braya en el registro
    # esta siempre por debajo de dos segundos.
    if ($text -match '(?i)^\s*(?:no\s*[,.]?\s*)?(?:vuelve\s+a\s+ponerlo|ponlo\s+(?:otra\s+vez|de\s+nuevo)|devu[eé]lvelo|deshaz\s+eso|no\s+lo\s+borres|era\s+verdad)\s*[.!]?$') {
        # ESTA RAMA LLAMA A Save-DatosPerfil A PELO (24/09, repaso), saltandose la guarda que
        # si lleva Add-DatoPerfil: sin esto, un invitado deshace un borrado del perfil de braya.
        if ($script:invitado) { return 'ahora mismo no toco tu perfil' }
        if ($script:perfilQuitado -and $sw.ElapsedMilliseconds -lt [long]$script:perfilQuitado.hasta) {
            $vuelve = [string]$script:perfilQuitado.dato
            $script:perfilQuitado = $null
            $dts = @(Get-DatosPerfil)
            if ($dts -notcontains $vuelve) { Save-DatosPerfil @($dts + $vuelve) }
            $script:ultimoDatoPerfil = $vuelve
            # el dato NO va entero al registro: es lo mismo que Add-DatoPerfil ya decidio no
            # loguear, y aqui se habia colado por la puerta de atras
            Log ("PERFIL: devuelto un dato de " + $vuelve.Length + " caracteres")
            return "Lo dejo como estaba: " + ($vuelve -replace '^Dicho por braya:\s*', '') + "."
        }
        return "No he borrado nada hace poco."
    }
    # "EL DEL OSO POLAR, ELIMINALO" / "elimina lo del oso polar" (18/09): el tema delante o
    # detras, y con elimina/quita/borra ademas de olvida
    if ($text -match '(?i)^\s*(?:(?:el|lo|la|los|las)\s+(?:de|del|de la|de los)\s+)?(.+?)\s*[,.]?\s*(?:elim[ií]nalo|b[oó]rralo|qu[ií]talo|olv[ií]dalo)\s*[.!]?$' -or
        $text -match '(?i)^\s*(?:elimina|quita|borra|olvida)\s+(?:el\s+dato\s+(?:de|del|sobre)|lo\s+(?:de|del)|(?:el|la|los|las)\s+(?:de|del))\s+(.+)$') {
        $temaB = $Matches[1].Trim()
        $quitado = Remove-DatoPerfil $temaB
        if ($quitado) { return "Vale, lo quito: " + ($quitado -replace '^Dicho por braya:\s*', '') + "." }
    }
    # aprender vocabulario hablando (se lee del texto ORIGINAL, sin normalizar)
    if ($text -match '(?i)^\s*aprende\s+que\s+(?:a\s+)?(.+?)\s+(?:le\s+(?:digo|llamo|dicen)|es|se\s+llama)\s+(.+)$') {
        $a = $Matches[1].Trim(); $b = $Matches[2].Trim()
        # "aprende que a spotify le digo musica" -> alias=musica, objetivo=spotify
        $r = Add-Alias-Comando $b $a
        if (-not $r) { $r = Add-Alias-Comando $a $b }   # o al reves
        if ($r) { return $r }
        return "No supe a que te refieres con eso"
    }
    # CREAR UN MODO HABLANDO. Tiene que ser aqui arriba, sobre la frase ENTERA:
    # "crea el modo streaming: cierra discord Y pon el volumen al 30" se parte
    # por esa "y" unas lineas mas abajo, y entonces ningun patron volveria a ver
    # el nombre del modo junto a sus ordenes.
    # UN MODO DE DOS PALABRAS SE PODIA PONER PERO NO CREAR (23/09, verificando la idea 17).
    # El patron de ponerlo -"modo X"- termina en (.+)$ y se traga "modo estamos dos" sin
    # pestanear, y la propuesta de secuencia YA crea modos de dos palabras ("rutina 2"). Este
    # cogia el nombre con [^\s:,], sin espacios: "crea el modo estamos dos: abre it takes two"
    # guardaba un modo llamado "estamos" con la orden "dos: abre it takes two". La alternativa
    # de delante solo entra cuando hay dos puntos o coma, que es donde el nombre acaba sin
    # ninguna duda; sin separador explicito manda el de siempre, porque ahi adivinar donde
    # acaba el nombre seria inventarselo.
    if ($text -match '(?i)^\s*(?:crea|crear|haz|hazme|define|guardame)\s+(?:el\s+|un\s+)?modo\s+([^:,]{2,20})\s*[:,]\s*(.+)$' -or
        $text -match '(?i)^\s*(?:crea|crear|haz|hazme|define|guardame)\s+(?:el\s+|un\s+)?modo\s+([^\s:,]{2,20})\s*(?::|,|\s+que\s+|\s+con\s+|\s+)\s*(.+)$') {
        $nom = $Matches[1].Trim(); $cuerpo = $Matches[2].Trim()
        # Se COMPRUEBA que cada trozo se entienda ANTES de guardar nada: un modo
        # con una linea que no se reconoce es un modo que un dia hace la mitad de
        # lo que le pides y no dice por que.
        $lineas = @(); $malas = @()
        foreach ($fr in @(Split-Ordenes $cuerpo)) {
            if (-not $fr) { continue }
            if (Resolve-Fragment $fr) { $lineas += $fr } else { $malas += $fr }
        }
        if ($lineas.Count -eq 0) { return "No entendi ninguna de esas ordenes, asi que no he creado nada." }
        # el porque, no un "no pude": Add-Perfil ya se niega en modo invitado, pero devolver
        # $false a secas deja a quien habla sin saber que paso ni como arreglarlo
        if ($script:invitado) { return "Estoy en modo invitado y no guardo nada. Di: sal del modo invitado, y te lo creo." }
        if (-not (Add-Perfil $nom $lineas)) { return "No pude guardar el modo." }
        $r = "Modo $nom creado, con $($lineas.Count) " + $(if ($lineas.Count -eq 1) { 'orden' } else { 'ordenes' }) + '.'
        if ($malas.Count -gt 0) { $r += " Esto no lo entendi y lo he dejado fuera: " + ($malas -join '; ') + '.' }
        return $r
    }
    # La memoria guarda el texto TAL CUAL se dijo, con mayusculas y acentos.
    # Si se dejara pasar por la normalizacion se archivaria en minusculas y sin
    # tildes, que es justo lo que no quieres leer meses despues en Obsidian.
    # mismo lookahead que en Resolve-Fragment: "en 20 minutos" es temporizador,
    # no una nota para el diario
    if ($text -match '(?i)^\s*(?:recu[eé]rdame|recuerda|acu[eé]rdate|anota|apunta|guarda(?=\s+(?:que|de\s+que)\b)|memoriza)\s+(?!.*\s(?:en|a)\s+(?:la\s+|mi\s+)?lista(?:\s+de\s+.+)?$)(?!(?:en|dentro de)\s+(?:\d+|un|una|uno|medi[ao]|(?:un\s+)?cuarto\s+de|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|diecis\S+|veinte|veinti\S+|treinta|cuarenta|cincuenta|sesenta|noventa)(?:\s+y\s+\S+)?\s+(?:segundos?|minutos?|horas?)\b)(?!(?:\d+|un|una|medi[ao]|(?:un\s+)?cuarto\s+de|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|trece|catorce|quince|diecis\S+|veinte|veinti\S+|treinta|cuarenta|cincuenta|sesenta|noventa)(?:\s+y\s+\S+)?\s+(?:minutos?|horas?)(?:\s+y\s+media)?\s+antes\b)(?!(?:esto|eso|esta pantalla|lo de la pantalla|lo que dice la pantalla|lo que pone|este codigo|el codigo|la clave|la combinacion|esta clave|este numero)$)(?!(?:hoy|ma[nñ]ana|pasado\s+ma[nñ]ana|el\s+(?:lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo)|el\s+\d{1,2}\s+de\s|a\s+las?\s)\b)(?!(?:cual|cuales|que es|que fue|si|donde|cuando|quien|como|cuanto)\b)(?:que\s+|de\s+que\s+)?(.+)$' -and $text -notmatch '\?\s*$') {
        $frase = $Matches[1].Trim()
        if ($frase.Length -gt 0) {
            $null = Add-Memoria $frase
            Log "MEMORIA: $frase"
            # si lleva una fecha ("el 3 de octubre"), ese dia lo celebro
            $md = $null
            try { $md = Add-Fecha $frase } catch { $md = $null }
            if ($md) { return "Anotado. Y ese dia te lo recuerdo." }
            return "Anotado."
        }
    }
    # recordatorios con fecha y hora reales ("recuerdame manana a las 10 que...")
    $rec = $null
    try { $rec = Invoke-RecordatorioVoz $text } catch { Log ("recordatorio: " + $_.Exception.Message); $rec = $null }
    if ($rec) { return $rec }
    # fechas guardadas: "que fechas tengo"
    if ($text -match '(?i)^\s*(?:que fechas (?:tengo|hay|guardaste)|mis fechas|que cumples hay|que cumpleanos hay)\b') {
        $fs = @(Get-Fechas | Sort-Object md)
        if ($fs.Count -eq 0) { return "No tienes fechas guardadas. Di, por ejemplo: recuerda que el 3 de octubre es el cumple de Ana." }
        return ("Tienes " + $fs.Count + ": " + (($fs | ForEach-Object { $_.texto }) -join '; '))
    }
    # reglas por voz: se interpretan sobre la frase ENTERA (no se parte por "y")
    #
    # LA VOZ DE UN VIDEO NO DEJA REGLAS PUESTAS (17/09). Invoke-ReglaVoz CREA cosas
    # -reglas, modos, recordatorios- y devuelve en el acto, asi que nunca llegaba a las
    # guardas de mas abajo (Test-Rechazada y Test-VozExtrana, unas 60 lineas despues):
    # una frase del audio de fondo podia dejar una regla DIARIA puesta sin que nadie
    # preguntara. Aqui no valen esas guardas tal cual, porque miran $acciones y una regla
    # no genera ninguna.
    #
    # El patron es corto y conservador a proposito: solo decide SI PREGUNTAR. Duplicar
    # aqui el regex largo de Test-FastCommand seria peor, porque los dos se separarian
    # con el tiempo. Y Test-VozExtrana ya se calla sola con el boton y en seguimiento
    # (ahi quien habla es braya), asi que esto solo muerde con la voz tras el nombre.
    # 'recuerdame cada' y 'avisame cada' TAMBIEN (23/09, idea 4): son la forma en que braya lo
    # dice de verdad, y dejan puesta una regla que habla sola cada dos horas. Sin esto, la voz
    # de un video de fondo podia crearla sin que nadie confirmara nada.
    if (-not $script:confirmado -and (ConvertTo-Plain $text) -match '^(?:cuando\s|cada\s|(?:recuerdame|avisame|recuerda|dime)\s+cada\s|todos los dias|cada dia|diariamente|a las?\s)' -and (Test-VozExtrana)) {
        $script:pendiente = @{ texto = $text; vence = 0; tipo = 'peligrosa' }
        Log ("VOZ EXTRANA: no creo nada con '$text' sin confirmar ($([int]$script:ultimaF0) Hz frente a $([int](Get-VozDuena)) Hz)")
        Add-Estadistica 'voz-extrana' $text
        return "No me suena tu voz. ¿$($text)?"
    }
    # SI EL MOTOR DE REGLAS REVIENTA, SE DICE (24/09, idea 14 de la tanda nueva).
    #
    # El 13/09 a las 16:22:01 braya dijo "cada 2 horas di que estire la espalda" -una regla
    # valida- y esto reviento. La frase siguio su camino como si no fuera una regla, y dos
    # segundos despues el pregunto "que reglas hay" y Nova le contesto "no tienes reglas".
    # Creia haberla creado. Paso tres veces: 11/09 01:13:25, 11/09 01:16:31 y 13/09 16:22:01.
    #
    # EL NULL DE ENTONCES YA NO ESTA -probado hoy con las 528 funciones del archivo cargadas y
    # las siete frases de regla del registro: ninguna lanza, y no vuelve a salir en el log
    # desde el 13/09-. Lo que se arregla aqui es lo otro, que es peor: que el catch se trague
    # cualquier fallo FUTURO y la frase se pierda callando.
    #
    # LA CONDICION ES LA MISMA QUE YA USA LA GUARDA DE VOZ EXTRANA, doce lineas mas arriba, y
    # a proposito: si esa forma basta para no crear nada sin confirmar, basta para saber que
    # braya estaba intentando crear algo. Lo que NO se hace es adivinar la regla ni crearla a
    # medias: se dice que no se pudo, que es la regla 1 -fallar en entender se puede; hacer
    # algo que no se pidio, no-.
    $regla = $null
    $eraRegla = $false
    try {
        $eraRegla = [bool]((ConvertTo-Plain $text) -match '^(?:cuando\s|cada\s|(?:recuerdame|avisame|recuerda|dime)\s+cada\s|todos los dias|cada dia|diariamente)')
        $regla = Invoke-ReglaVoz $text
    } catch {
        Log ("regla: " + $_.Exception.Message)
        $regla = $null
        if ($eraRegla) {
            Add-Estadistica 'regla-rota' $text
            return 'Iba a guardar eso como una regla y algo ha fallado por dentro. No he guardado nada; dimelo otra vez, por favor.'
        }
    }
    if ($regla) { return $regla }
    if (Test-CatalogoRecitado $text) {
        Log "LOCAL descarta: '$text' es el catalogo recitado, no una orden"
        # se cuenta para poder vigilarlo: es la defensa principal contra abrir
        # cosas solo, y conviene ver tanto si deja de saltar como si se pasa
        Add-Estadistica 'recitado' $text
        return $null
    }
    # CHARLA AL FINAL UNIDA CON "Y" (ver LAS DOS COSAS A LA VEZ): "que hora es y
    # cuentame algo curioso" no se partia y la cola se perdia (probado en vivo el
    # 13/09). Si la cola no es a su vez una orden conocida ("y dime la bateria"),
    # se aparta para la conversacion y se resuelve solo lo de delante.
    $colaCharla = ''
    if ($ConversacionOn -and $text -match '(?i)^(.+?)[\s,]+y\s+((?:cu[eé]ntame|dime|expl[ií]came|h[aá]blame|qu[eé] opinas|crees|sabes|recomi[eé]ndame|dame una idea)\b.+)$') {
        $delanteC = $Matches[1].Trim(); $colaC = $Matches[2].Trim()
        if (-not (Resolve-Fragment (ConvertTo-Plain $colaC))) { $colaCharla = $colaC; $text = $delanteC }
    }
    $frags = Split-Ordenes $text
    if (-not $frags -or $frags.Count -eq 0) { return $null }

    $script:dudosa = $null
    $script:charlaResto = ''
    $acciones = @()
    $restoCharla = @()
    foreach ($f in $frags) {
        $a = Resolve-Fragment $f
        if (-not $a) {
            # LAS DOS COSAS A LA VEZ (13/09): "abre spotify y cuentame algo de
            # musica". El trozo que no es orden pero parece charla o pregunta no
            # tumba lo demas: las ordenes se hacen y ese trozo va a la
            # conversacion (ver CONVERSACION DE VERDAD)
            if ($ConversacionOn -and ((Test-Charla $f) -or ((ConvertTo-Plain $f) -match $RE_PREGUNTA))) {
                $restoCharla += $f
                continue
            }
            # SI LA TOMA VENIA SATURADA, MEJOR PEDIR QUE LO REPITA (24/09, idea 12).
            #
            # Medido sobre 886 dictados: los 83 que traian un recorte en los 20 s previos
            # fallaron el 42,2 %, frente al 25,7 % de los otros 803 -1,64 veces peor, z~3,3,
            # p<0,001-. Y 32 de esos 35 fallos acabaron aqui mismo, escalando a un agente con
            # manos a ver si adivinaba lo que Nova ya sabia que habia oido mal.
            #
            # No es que el recorte estropee la orden: 30 de los 83 salieron bien. Es que
            # cuando ADEMAS no se entiende, la explicacion mas probable ya no es que falte
            # vocabulario, es que la toma era mala. Y ahi repetir sale mucho mas barato que
            # mandarselo a un agente que puede hacer cualquier cosa.
            #
            # Cuesta unas 83 peticiones de repetir en quince dias, y solo en las que ADEMAS no
            # se entendieron: 35. Dos al dia.
            $segRec = Get-SegDesdeRecorte
            if (Test-TomaSaturada $segRec $RecorteVentanaSeg) {
                Log "LOCAL descarta: no reconozco '$f', y la toma venia saturada (recorte hace $segRec s); pido que lo repita en vez de escalarlo"
                Add-Estadistica 'toma-saturada' $f
                $script:ultimoDescarte = ''
                return 'Te he oido con la voz saturada y no me ha quedado claro. ¿Me lo repites, o lo dices con el boton?'
            }
            # dejar constancia del trozo exacto: es lo que dice que anadir a
            # commands.json en vez de tener que adivinarlo despues
            Log "LOCAL descarta: no reconozco '$f' -> la orden entera va a opencode"
            # se anota en las estadisticas SOLO si la frase acaba yendo al
            # modelo como orden (las preguntas siempre se descartan aqui y no
            # son vocabulario que falte): lo decide Process-Texto
            $script:ultimoDescarte = $f
            return $null   # todo o nada
        }
        $acciones += $a
    }
    # solo charla, sin ninguna orden: no es cosa de este atajo (Process-Texto la lleva)
    if ($acciones.Count -eq 0) { return $null }
    if ($colaCharla) { $restoCharla += $colaCharla }
    if ($restoCharla.Count -gt 0) {
        $script:charlaResto = ($restoCharla -join ', ')
        Log "LOCAL: hago las ordenes y '$($script:charlaResto)' va a la conversacion"
    }

    # --- CONFIRMACION DE COINCIDENCIAS DUDOSAS ---
    # Si algo se resolvio por parecido lejano, no se ejecuta: se devuelve la
    # pregunta y se deja la orden pendiente. El bucle principal la ejecuta si
    # dices "si" o si pasan unos segundos sin respuesta; "no" la cancela. Sin
    # estado pegajoso: el plazo la limpia sola.
    # YA ME DIJISTE QUE ESTO NO. La misma frase, otra vez: se pregunta en vez
    # de hacerla. Es la unica defensa contra lo que de verdad pasa -una frase
    # del video de fondo que la capa local entiende perfectamente-, porque ahi
    # no hay ninguna traduccion aprendida que borrar.
    if (-not $script:confirmado -and (Test-Rechazada $text)) {
        $script:pendiente = @{ texto = $text; vence = 0; tipo = 'rechazada' }
        $qr = @($acciones | ForEach-Object { $_.desc }) -join ' y '
        if (-not $qr) { $qr = $text }
        # $($var)? y no $var?: en PowerShell 5.1 la ? se come como parte del nombre
        # de la variable y la pregunta salia vacia (auditoria del 13/09)
        return "La ultima vez me dijiste que no era eso. ¿$($qr)?"
    }
    # ESTA VOZ NO ES LA TUYA. Solo para las ordenes que TOCAN algo: si el audio
    # de un video pregunta la hora, que la pregunte. Y solo se pregunta -nunca
    # se descarta-, porque el que habla raro puedes ser tu con la voz tomada, y
    # porque decir "si" o mantener el boton cuesta menos que quedarse sin
    # asistente. Si la frase ya venia confirmada, no se vuelve a preguntar.
    if (-not $script:confirmado -and (Test-VozExtrana) -and
        @($acciones | Where-Object { $AccionesQueTocan -contains $_.kind }).Count -gt 0) {
        $script:pendiente = @{ texto = $text; vence = 0; tipo = 'peligrosa' }
        $qv = @($acciones | ForEach-Object { $_.desc }) -join ' y '
        if (-not $qv) { $qv = $text }
        Log ("VOZ EXTRANA: $([int]$script:ultimaF0) Hz frente a $([int](Get-VozDuena)) Hz; se pregunta antes de: " + $qv)
        Add-Estadistica 'voz-extrana' $text
        return "No me suena tu voz. ¿$($qv)?"
    }
    # TRADUCCION DE ALGO MAL OIDO (15/09): "Ensectiva el modo noche" (dijo "desactiva") se
    # tradujo a "modo noche" y se hizo lo contrario de lo pedido. Si lo que se tradujo ya
    # necesito un repaso (ver NO APRENDER DE LO MAL OIDO), no se hace a la primera: se
    # pregunta, y como una peligrosa, solo vale un si hablado (ni el plazo ni el boton).
    if (-not $script:confirmado -and $script:preguntarTraduccion -and @($acciones).Count -gt 0) {
        $script:pendiente = @{ texto = $text; vence = 0; tipo = 'peligrosa' }
        $qd = @($acciones | ForEach-Object { $_.desc }) -join ' y '
        if (-not $qd) { $qd = $text }
        Log "OIDO DUDOSO: la traduccion sale de algo mal oido; se pregunta antes de: $qd"
        Add-Estadistica 'traduccion-preguntada' $text
        return "No estoy segura de haberte oido bien. ¿$($qd)?"
    }
    if ($ConfirmacionOn -and $script:dudosa -and -not $script:confirmado -and -not $script:sinDudosa) {
        $script:pendiente = @{ texto = $text; vence = 0 }
        $q = [string]$script:dudosa
        $script:dudosa = $null
        return ("¿" + $q + "?")
    }

    # se recuerda el ultimo objetivo nombrado, para que "abrelo" funcione luego
    foreach ($a in $acciones) {
        if ($a.desc -match '^abrir (.+?)( en Steam)?$') { $script:ultimoObjetivo = $Matches[1]; break }
        if ($a.desc -match "^buscar '(.+?)' en ") { $script:ultimoObjetivo = $Matches[1]; break }
    }

    # QUE FRASE FUE. Para que "no era eso" sepa a que se refiere. No se apunta
    # la propia "no era eso", claro, ni "deshaz": eso dejaria sin referencia a
    # la siguiente queja.
    if (-not ($acciones | Where-Object { $_.kind -in @('noEraEso', 'deshacer', 'deshacerDesde', 'deshacerAuto') })) {
        $script:ultimoEjecutado = $text
    }

    # se guarda el estado ANTES de tocar nada, para poder deshacer
    $tocaEstado = @($acciones | Where-Object { $_.kind -in @('brillo', 'volumenPct', 'key', 'app') }).Count -gt 0
    if ($tocaEstado -and -not ($acciones | Where-Object { $_.kind -in @('deshacer', 'deshacerDesde') })) { Save-EstadoParaDeshacer }

    $hechas = @()
    $navegador = $null
    # Tras estas acciones hay que dar un respiro: son las que mandan teclas o
    # abren cosas, y si se encadenan sin pausa se pisan entre si (dos SendKeys
    # seguidos, o lanzar la URL antes de que el navegador exista). Las demas
    # -decir, anotar, consultar- no tocan nada de fuera y no necesitan nada.
    $RESPIRO = $AccionesQueTocan
    $acciones = @($acciones)
    for ($iAcc = 0; $iAcc -lt $acciones.Count; $iAcc++) {
        $a = $acciones[$iAcc]
        # ANTES de tocar nada: que se vea lo que viene, y por cual va
        Set-UIHaciendo $a.kind
        Set-UICola $acciones.Count ($iAcc + 1)
        try {
            switch ($a.kind) {
                # se sustituye la descripcion por el resultado real
                'deshacer' {
                    $a.desc = (Invoke-Deshacer)
                    # DESHACER ALGO QUE ACABA DE PASAR ES DECIR QUE ESTUVO MAL (17/09), sin
                    # tener que explicarlo. Pero solo cuenta si fue AHORA MISMO y si la orden
                    # venia de algo dudoso (una traduccion o una receta): deshacer una orden
                    # limpia por cambiar de idea no es un error suyo.
                    if ($script:ultimaOrden -and ($sw.ElapsedMilliseconds - [double]$script:ultimaOrden.cuando) -lt $DeshazEnsenaMs) {
                        $apD = Invoke-AprenderDelError $true
                        if ($apD) {
                            if ($apD.recetaOlvidada) { $a.desc = "$($a.desc). Y olvido esa receta." }
                            elseif ($apD.olvidada) { $a.desc = "$($a.desc). Y olvido que '$($apD.olvidada)' significaba eso." }
                            elseif ($apD.apuntada) { $a.desc = "$($a.desc). Si lo vuelvo a oir, te pregunto antes." }
                        }
                    }
                }
                'deshacerAuto' { $a.desc = (Undo-DecisionPropia) }
                'nubeOir' {
                    if ([bool]$a.encendida) {
                        if ($script:NubeOir) { $a.desc = 'Ya la tengo encendida' }
                        elseif (-not (Set-Cfg 'escucha' 'nubeOir' 'gemini')) { $a.desc = 'No he podido guardarlo; lo dejo como estaba' }
                        else {
                            $script:NubeOir = 'gemini'
                            # la misma marca que deja el "deshaz": si braya la enciende a
                            # mano, Nova no se la puede volver a apagar esta tarde.
                            Set-DecisionDevuelta 'escucha' 'nubeOir'
                            Add-Estadistica 'auto-ajuste' 'nube on: a mano'
                            $a.desc = 'Vale, vuelvo a preguntarle a la nube. No la toco en dos semanas.'
                        }
                    } else {
                        if (-not $script:NubeOir) { $a.desc = 'Ya la tengo apagada' }
                        else {
                            $antesNU = [string]$script:NubeOir
                            if (-not (Set-Cfg 'escucha' 'nubeOir' '')) { $a.desc = 'No he podido guardarlo; lo dejo como estaba' }
                            else {
                                $script:NubeOir = ''
                                # se apunta como decision para que "deshaz lo que has
                                # cambiado" tambien valga aqui: dos salidas, no una.
                                [void](Save-DecisionPropia 'escucha' 'nubeOir' $antesNU 'la segunda opinion de la nube')
                                Add-Estadistica 'auto-ajuste' 'nube off: a mano'
                                $a.desc = 'Hecho, se acabo la nube. Si la quieres de vuelta, dime: vuelve a usar la nube.'
                            }
                        }
                    }
                }
                'deshacerDesde' { $a.desc = (Invoke-DeshacerDesde ([int]$a.minutos)) }
                'app' {
                    # ABRIR UN JUEGO MIENTRAS JUEGAS A OTRA COSA casi nunca es lo
                    # que pediste: es la firma de una orden mal oida. El 11/09 un
                    # ruido acabo abriendo SILENT BREATH en mitad de una partida.
                    # Se pregunta antes, igual que con 'cierra todos los programas'.
                    # el -match solo valia para Steam: los de Game Pass se abren por su
                    # lanzador y sin este campo se quedaban sin pregunta y sin deshacer
                    $esJuego = ([bool]$a.esJuego -or ($a.target -match 'steam://rungameid'))
                    $comoSeLlama = ($a.desc -replace '^abrir\s+', '' -replace '\s+en Steam$', '')
                    if ($esJuego -and -not $script:confirmado -and ($script:juegoActivo -or $a.sinVerbo)) {
                        $script:pendiente = @{ texto = "abre $comoSeLlama en steam"; vence = 0; tipo = 'peligrosa' }
                        $a.desc = if ($script:juegoActivo) { "estas jugando a $($script:juegoActivo). ¿Abro $($comoSeLlama)?" }
                                  else { "¿Abro $($comoSeLlama)?" }
                    } else {
                        # con -PassThru para poder cerrarlo si pides deshacer; las
                        # URI (steam://, shell:appsFolder) no devuelven proceso propio
                        # LAS URI DE WINDOWS NO DEVUELVEN PROCESO (18/09): Start-Process
                        # 'ms-settings:' -PassThru falla con "no encuentra toda la informacion
                        # necesaria" (probado); por explorer.exe abre bien. Los ajustes llevaban
                        # fallando desde que existen.
                        $pr = $null
                        if ($a.target -match '^ms-[a-z-]+:') { Start-Process 'explorer.exe' $a.target -ErrorAction Stop }
                        else { $pr = Start-Process $a.target -PassThru -ErrorAction Stop }
                        # ¿se abrira de verdad? se apunta y se mira luego, sin bloquear
                        if (-not $esJuego) { [void](Add-AperturaPendiente $comoSeLlama) }
                        # AVISO DE ACTUALIZACION (13/09): si Steam marca el juego con
                        # una actualizacion pendiente (StateFlags bit 2), se dice ya,
                        # antes de encontrarse la descarga al arrancar
                        if ($esJuego -and $a.target -match 'rungameid/(\d+)') {
                            $idAct = $Matches[1]
                            $jAct = @($script:Juegos | Where-Object { [string]$_.id -eq $idAct }) | Select-Object -First 1
                            if ($jAct -and ([int]$jAct.estado -band 2) -and -not $jAct.bajando) { $a.desc = "$($a.desc); ojo, tiene una actualizacion pendiente" }
                        }
                        if ($pr -and $script:deshacer) { [void]$script:deshacer.procesos.Add($pr.Id) }
                        # Un juego de Steam no deja proceso al que agarrarse, asi
                        # que se apunta QUE y CUANDO: al deshacer se busca el que
                        # haya aparecido despues. Antes, 'deshaz' no podia con
                        # ellos, que es justo lo que hace falta tras un falso
                        # positivo.
                        if ($esJuego -and $script:deshacer) {
                            $script:deshacer.juego = @{ nombre = $comoSeLlama; desde = (Get-Date) }
                        }
                        if ($a.target -match 'msedge|chrome|firefox') { $navegador = $a.target }
                    }
                }
                'url' {
                    $urlA = $a.url
                    if ($a.youtube) {
                        $nV = if ($a.videoN) { [int]$a.videoN } else { 1 }
                        $vY = Select-VideoYouTube ([string]$a.youtube) $nV
                        if ($vY) {
                            $urlA = [string]$vY.url
                            # EL TITULO, ANTES DE ABRIR NADA (23/09, idea 1-A). La capsula se
                            # pinta aqui, antes del Start-Process; la voz sale unas decimas
                            # despues, porque este ejecutor no habla (no hay ni un Say en sus
                            # 2.200 lineas) y meter voz aqui bloquearia el bucle.
                            if ($vY.titulo) {
                                $tiY = [string]$vY.titulo
                                if ($tiY.Length -gt 45) { $tiY = $tiY.Substring(0, 44) + [string][char]0x2026 }
                                Set-UI 'hablando' ([string][char]0x266A + ' ' + $tiY) 4000
                                $a.desc = 'pongo ' + $vY.titulo
                            }
                            $script:ytPuesto = @{ id = [string]$vY.id; titulo = [string]$vY.titulo; q = [string]$a.youtube }
                            $script:ytN = [int]$vY.n
                            # la ventana de "la siguiente": cinco minutos y se cierra sola
                            $script:ytHasta = $sw.ElapsedMilliseconds + $YtSiguienteMs
                        }
                        $script:ytUltimaBusqueda = [string]$a.youtube   # para "pon el segundo"
                    }
                    if ($a.carpeta) { Start-Process -FilePath 'explorer.exe' -ArgumentList ('"' + $urlA + '"') -ErrorAction Stop }
                    elseif ($navegador) { Start-Process $navegador $urlA -ErrorAction Stop }
                    else { Start-Process $urlA -ErrorAction Stop }
                }
                'key' { for ($i = 0; $i -lt $a.repeat; $i++) { Send-Key $a.vk } }
                'brillo' { Set-Brillo $a.nivel }
                'modoEntra' {
                    # como estaba ANTES de aplicar el modo, para poder volver
                    $brAntes = -1; $volAntes = -1
                    try { $brAntes = Get-BrilloActual } catch {}
                    try { $volAntes = [AX]::LeerVolumen() } catch {}
                    $script:antesDeModo = @{ modo = [string]$a.modo; brillo = $brAntes
                                             volumen = $volAntes; cuando = (Get-Date) }
                    Log "MODO $($a.modo): antes estaba brillo=$brAntes volumen=$volAntes"
                }
                'modoFuera' {
                    # SOLO SE DESHACE LO QUE SE PUEDE DESHACER, Y SE DICE CUAL (21/09).
                    # Un modo puede abrir Discord, y cerrarlo al salir seria pasarse: no
                    # se pidio eso. Lo que se devuelve es el brillo y el volumen, que es
                    # lo que de verdad molesta cuando se queda puesto -la pantalla al 15
                    # por ciento a media tarde- y es lo que el nombra al quejarse.
                    # Y Nova dice EXACTAMENTE lo que hizo, ni mas ni menos: prometer que
                    # ha 'salido del modo' cuando solo ha tocado dos cosas seria mentir.
                    $aM = $script:antesDeModo
                    $queriaM = [string]$a.modo
                    if (-not $aM) {
                        $a.desc = 'No tengo apuntado como estaba antes. Dime a que brillo y volumen lo dejo.'
                    } elseif ($queriaM -and (ConvertTo-Plain $queriaM) -ne (ConvertTo-Plain ([string]$aM.modo))) {
                        # pidio salir de OTRO modo distinto del que esta puesto
                        $a.desc = "El ultimo modo que puse fue $($aM.modo), no $queriaM. Si quieres, dime: modo normal."
                    } else {
                        $hechoM = @()
                        if ([int]$aM.brillo -ge 0) {
                            try { $null = Set-Brillo ([int]$aM.brillo); $hechoM += "el brillo al $($aM.brillo)" } catch {}
                        }
                        if ([int]$aM.volumen -ge 0) {
                            try { $null = [AX]::PonerVolumen([int]$aM.volumen); $hechoM += "el volumen al $($aM.volumen)" } catch {}
                        }
                        $script:antesDeModo = $null
                        if ($hechoM.Count -gt 0) {
                            $a.desc = "Vale, te dejo $($hechoM -join ' y '), como antes del modo $($aM.modo)."
                            Log "MODO FUERA: $($aM.modo) -> $($hechoM -join ', ')"
                        } else {
                            $a.desc = 'No pude devolver el brillo ni el volumen.'
                        }
                    }
                }
                'memoria' { $null = Add-Memoria $a.texto }
                'modoEditar' { $a.desc = Invoke-ModoEditar $a.datos }
                'correo' { $a.desc = Invoke-Correo $a }
                'papelera' { $a.desc = Get-PapeleraResumen }
                'musicaSitio' {
                    # la preferencia se guarda AQUI, no al resolver: -Probar solo resuelve
                    [void](Set-Cfg 'musica' 'sitio' $a.sitio)
                    $script:MusicaSitio = [string]$a.sitio
                }
                'avisosEntorno' { $a.desc = Set-AvisosEntorno ([bool]$a.encendido) }
                'crearAlgo' {
                    # D7 (21/09). Donde se crea sale de Find-CarpetaPorNombre, que solo
                    # conoce las seis carpetas de siempre: no hay forma de que esto escriba
                    # en otro sitio del disco. El nombre ya viene limpio de Resolve-Fragment
                    # (sin barras, sin dos puntos, sin '..' y de 60 como mucho).
                    $dirC = Find-CarpetaPorNombre ([string]$a.donde)
                    if (-not $dirC -or -not (Test-Path -LiteralPath $dirC)) {
                        $a.desc = "no encuentro tu $($a.donde)"
                        break
                    }
                    # un archivo sin extension no lo abre nadie: .txt, que es lo que pide
                    # cuando dice 'un archivo' o 'una nota'
                    $nomC = [string]$a.nombre
                    if (-not $a.carpeta -and $nomC -notmatch '\.[A-Za-z0-9]{1,5}$') { $nomC += '.txt' }
                    $rutaC = Join-Path $dirC $nomC
                    if (Test-Path -LiteralPath $rutaC) {
                        # YA ESTABA: no se toca ni se pisa. Crear encima de un archivo suyo
                        # seria borrarlo, y eso no se hace sin preguntar.
                        $a.desc = "ya tienes $(if ($a.carpeta) { 'esa carpeta' } else { 'ese archivo' }) en el $($a.donde)"
                        break
                    }
                    try {
                        if ($a.carpeta) { [void](New-Item -ItemType Directory -Path $rutaC -ErrorAction Stop) }
                        else { [void](New-Item -ItemType File -Path $rutaC -ErrorAction Stop) }
                    } catch {
                        Log ("CREAR: no pude crear '$rutaC': " + $_.Exception.Message)
                        $a.desc = 'no he podido crearlo'
                        break
                    }
                    # Y SE COMPRUEBA QUE ESTA (B9, 21/09). Es la meta declarada de NOVA-LLM.md
                    # -que compruebe que lo que hizo salio bien- y hasta hoy solo lo hacian las
                    # recetas. New-Item puede no lanzar y aun asi no dejar nada (permisos, un
                    # antivirus, un disco lleno): decir 'hecho' sin mirar es la misma mentira
                    # que la de las carpetas del 20/09.
                    if (-not (Test-Path -LiteralPath $rutaC)) {
                        Log "CREAR: dije que cree '$rutaC' y no esta"
                        Add-Estadistica 'no-surtio-efecto' "crearAlgo: $rutaC no aparecio"
                        $a.desc = 'crei que lo habia creado, pero no esta'
                        break
                    }
                    Log "CREADO: $rutaC"
                    # "carpeta fotos CREADO" lo canto el banco: la concordancia tambien
                    # se oye, y esto se dice en voz alta.
                    $a.desc = $(if ($a.carpeta) { "carpeta $nomC creada" } else { "archivo $nomC creado" }) + " en tu $($a.donde)"
                }
                'decir' {
                    # la respuesta ES la descripcion; se dice y ya. Si es un
                    # perfil, la capsula lo sabe ("noche" = paleta calida)
                    if ($a.desc -match '^modo (\w+)$') { $script:uiPerfil = $Matches[1] }
                }
                'temporizador' {
                    $vence = $sw.ElapsedMilliseconds + $a.ms
                    $txt = if ($a.texto) { $a.texto } else { "se acabo el tiempo" }
                    [void]$script:temporizadores.Add(@{ vence = $vence; texto = $txt; total = $a.ms })
                    $a.desc = "listo, te aviso en $($a.n) $($a.unidad)"
                }
                # LO DE HOY, NO EL TRAMO (23/09). Antes contestaba ($sw - $juegoDesde)/60000,
                # que es el tiempo desde el ultimo alt-tab o desde el ultimo arranque de
                # Nova; con 244 arranques en 15 dias ese numero no dice nada.
                'tiempoJuego' {
                    if ($script:juegoActivo) { $a.desc = Get-FraseTiempoHoy $script:juegoActivo }
                    else {
                        $todoH = Get-MinutosJuegoHoy
                        $a.desc = if ($todoH -ge 1) { Get-FraseTiempoHoy '' } else { 'hoy no te he visto jugar a nada' }
                    }
                }
                'tiempoHoy' { $a.desc = Get-FraseTiempoHoy $script:juegoActivo }
                'avisoJuegoCada' {
                    # EL SUELO DE QUINCE MINUTOS no es un numero nuevo: es el cadaMin que ya
                    # se le pasa a Test-PuedoAvisar en el aviso de juego. Por debajo de ahi
                    # deja de ser un aviso y es ruido.
                    $minA = [int]$a.minutos
                    if ($minA -gt 0 -and $minA -lt 15) { $a.desc = 'cada cuanto? Menos de quince minutos es mucho ruido' }
                    else { Log "AVISO DE JUEGO: cada $minA min"; $a.desc = (Set-AvisoJuego $minA) }
                }
                'avisosEspera' {
                    # los vivos vuelven a pasar por Send-AvisoEntorno, que los junta en UNA
                    # frase con Send-AvisoCola: por eso aqui no se habla dos veces encima.
                    $nEsp = 0
                    try { $nEsp = [int](Send-AvisoEsperaSuelta) } catch { $nEsp = 0 }
                    if ($nEsp -eq 0) { $a.desc = 'Nada, no tenia nada guardado.' } else { $a.desc = '' }
                }
                'avisoJuegoHoy' {
                    Log ("AVISO DE JUEGO: " + $(if ($a.avisar) { 'vuelve' } else { 'callado por hoy' }))
                    $a.desc = (Set-AvisoJuegoHoy ([bool]$a.avisar))
                }
                'balanceAprendizaje' { $a.desc = (Get-BalanceAprendizaje) }
                'configuracion' { $a.desc = (Get-Configuracion) }
                'nivelNova' { $a.desc = Get-FraseNivel }
                'energia' {
                    if ($a.modo -eq 'consulta') {
                        $actualE = Get-ModoEnergia
                        $a.desc = if ($actualE) { "estoy en modo $actualE" } else { 'no pude leer el modo de energia' }
                    } else {
                        $okE = $false
                        try { $okE = Set-ModoEnergia $a.modo } catch { Log ("energia: " + $_.Exception.Message) }
                        $a.desc = if ($okE) { "modo $($a.modo) puesto" } else { 'Windows no me dejo cambiar el modo de energia' }
                    }
                }
                'radio' {
                    try { $a.desc = Set-Radio $a.tipo $a.encender } catch { $a.desc = "no pude cambiar el $($a.tipo)"; Log ("radio: " + $_.Exception.Message) }
                }
                'tiempoSemana' {
                    $listaJ = @(Get-TiempoJugado $a.dias)
                    $a.desc = if ($listaJ.Count -eq 0) { "$($a.periodo) no has jugado nada, o no te he visto" }
                              else {
                                  $trozosJ = @($listaJ | Select-Object -First 4 | ForEach-Object { "$($_.juego), $(Format-Minutos $_.minutos)" })
                                  $totalJ = 0; foreach ($x in $listaJ) { $totalJ += $x.minutos }
                                  "$($a.periodo) has jugado $(Format-Minutos $totalJ): " + ($trozosJ -join '; ')
                              }
                    $script:sinTarjeta = $true
                    $script:sinTarjetaEn = $sw.ElapsedMilliseconds
                }
                'salidaAudio' {
                    try {
                        if ($a.quiere) { $a.desc = Set-SalidaAudio $a.quiere }
                        else {
                            $actA = @(Get-SalidasAudio | Where-Object { $_.actual }) | Select-Object -First 1
                            $a.desc = if ($actA) { "suena por $($actA.nombre)" } else { 'no se por donde suena' }
                        }
                    } catch { $a.desc = 'no pude cambiar la salida de sonido'; Log ("salida de audio: " + $_.Exception.Message) }
                }
                'ultimaCaptura' {
                    $capU = Get-UltimaCaptura
                    if (-not $capU) {
                        $a.desc = 'no encuentro ninguna captura'
                    } elseif ($a.accion -eq 'abrir') {
                        try { Start-Process -FilePath $capU.FullName; $a.desc = 'ahi la tienes' } catch { $a.desc = 'no pude abrirla' }
                    } else {
                        try {
                            # desde memoria: con FromFile el archivo se queda bloqueado
                            $bytesU = [System.IO.File]::ReadAllBytes($capU.FullName)
                            $imgU = [System.Drawing.Image]::FromStream((New-Object System.IO.MemoryStream(, $bytesU)))
                            [System.Windows.Forms.Clipboard]::SetImage($imgU)
                            $hace = [int]((Get-Date) - $capU.LastWriteTime).TotalMinutes
                            $a.desc = 'copiada, lista para pegar' + $(if ($hace -ge 60) { " (es de hace $(Format-Minutos $hace))" } else { '' })
                        } catch { $a.desc = 'no pude copiarla'; Log ("ultima captura: " + $_.Exception.Message) }
                    }
                }
                'esconderTiempo' {
                    $script:uiRetirada = 'tiempo'
                    $script:retiradaHasta = $sw.ElapsedMilliseconds + [int]$a.minutos * 60000
                    Set-UI 'retirada'
                    # nunca vacia: una respuesta vacia se toma por "no lo entendi" y va a la IA
                    $a.desc = "vale, vuelvo en $(Format-Minutos ([int]$a.minutos))"
                }
                'vozVelocidad' {
                    $nuevaV = if ($a.paso -eq 0) { 0 } else { $script:vozVelocidad + [int]$a.paso }
                    Set-VozVelocidad $nuevaV
                    # solo si cambia: Set-Cfg reescribe config.json entero
                    if ([int](Get-Cfg 'voz' 'velocidad' 0) -ne $script:vozVelocidad) { [void](Set-Cfg 'voz' 'velocidad' $script:vozVelocidad) }
                    $a.desc = if ($script:vozVelocidad -eq 0) { 'vuelvo a mi velocidad normal' }
                              elseif ($a.paso -gt 0 -and $script:vozVelocidad -ge 45) { 'ya hablo lo mas rapido que se' }
                              elseif ($a.paso -lt 0 -and $script:vozVelocidad -le -30) { 'ya hablo lo mas despacio que se' }
                              elseif ($a.paso -gt 0) { 'hablo mas rapido' } else { 'hablo mas despacio' }
                }
                'foco' {
                    # MODO FOCO (13/09): un temporizador de tipo "foco" (el anillo de
                    # la capsula lo cuenta). Al vencer pregunta por el descanso.
                    for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) { if ($script:temporizadores[$i].tipo -in 'foco', 'descanso') { $script:temporizadores.RemoveAt($i) } }
                    $msF = [int]$a.minutos * 60000
                    [void]$script:temporizadores.Add(@{ vence = $sw.ElapsedMilliseconds + $msF; texto = 'fin del foco'; total = $msF; tipo = 'foco' })
                    $a.desc = "foco de " + $(if ($a.minutos -eq 1) { 'un minuto' } else { "$($a.minutos) minutos" }) + "; te aviso al terminar"
                }
                'focoFin' {
                    $habia = 0
                    for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) { if ($script:temporizadores[$i].tipo -in 'foco', 'descanso') { $script:temporizadores.RemoveAt($i); $habia++ } }
                    $a.desc = if ($habia -gt 0) { 'foco terminado' } else { 'no habia ningun foco en marcha' }
                }
                { $_ -in 'discordMicro', 'discordSordo' } {
                    if (-not (Get-Process Discord -ErrorAction SilentlyContinue)) {
                        $a.desc = 'Discord no esta abierto'
                    } else {
                        $comboD = if ($a.kind -eq 'discordMicro') { $DiscordTeclaMicro } else { $DiscordTeclaSordo }
                        try {
                            Send-Combinacion $comboD
                            $a.desc = if ($a.kind -eq 'discordMicro') { 'cambiado tu micro de Discord' } else { 'cambiado el ensordecer de Discord' }
                        } catch { $a.desc = "no pude pulsar el atajo de Discord: $($_.Exception.Message)" }
                    }
                }
                'portaAnterior' {
                    $a.desc = if ($script:portaHist.Count -ge 2) { 'antes copiaste: ' + (Get-Ojeada $script:portaHist[1]) }
                              else { 'no recuerdo nada copiado antes de lo ultimo' }
                }
                'pegarAnterior' {
                    if ($script:portaHist.Count -ge 2) {
                        $anterior = [string]$script:portaHist[1]
                        $puesto = $false
                        try { Set-Clipboard -Value $anterior; $puesto = $true } catch {}
                        if ($puesto) {
                            Watch-Portapapeles $anterior
                            Start-Sleep -Milliseconds 120
                            [System.Windows.Forms.SendKeys]::SendWait('^v')
                            $a.desc = 'pegado lo de antes'
                        } else { $a.desc = 'no pude tocar el portapapeles' }
                    } else { $a.desc = 'no recuerdo nada copiado antes de lo ultimo' }
                }
                'portaHistorial' {
                    $nH = $script:portaHist.Count
                    $a.desc = if ($nH -eq 0) { 'desde que estoy encendida no has copiado nada' }
                              else { "recuerdo ${nH}: " + ((@($script:portaHist | Select-Object -First 3) | ForEach-Object { Get-Ojeada $_ }) -join '; ') }
                    $script:sinTarjeta = $true
                    $script:sinTarjetaEn = $sw.ElapsedMilliseconds
                }
                'musicaPlay' {
                    $muP = Get-MusicaActual
                    if ($muP -and $muP.sonando -eq $a.sonar) {
                        $a.desc = if ($a.sonar) { 'ya esta sonando' } else { 'ya esta en pausa' }
                    } else {
                        Send-Key 0xB3
                        $a.desc = if ($a.sonar) { 'la pongo' } else { 'pausada' }
                    }
                }
                'ytSiguiente' {
                    # SIN VOLVER A LA RED: la lista ya esta en memoria, asi que pasar de
                    # cancion cuesta una frase y cero espera. Ese es el remedio de verdad a
                    # que el primero no sea el bueno.
                    $qS = [string]$script:ytUltimaBusqueda
                    $nS = [int]$script:ytN + [int]$a.paso
                    if ($nS -lt 1) { $a.desc = 'esa ya era la primera'; break }
                    $vS = Select-VideoYouTube $qS $nS
                    if (-not $vS) { $a.desc = 'no me queda ninguna mas'; break }
                    if ([int]$vS.n -eq [int]$script:ytN) { $a.desc = 'esa ya era la ultima'; break }
                    $script:ytN = [int]$vS.n
                    $script:ytPuesto = @{ id = [string]$vS.id; titulo = [string]$vS.titulo; q = $qS }
                    $script:ytHasta = $sw.ElapsedMilliseconds + $YtSiguienteMs
                    try { Start-Process ([string]$vS.url) -ErrorAction Stop } catch { $a.desc = 'no pude abrirlo'; break }
                    $a.desc = if ($vS.titulo) { 'pongo ' + $vS.titulo } else { "pongo el numero $($vS.n)" }
                }
                'musicaNo' {
                    # SIN NOMBRAR NADA: se veta lo que acaba de sonar, que es como lo dice el
                    $queN = [string]$a.que
                    $tituloN = ''
                    $idN = ''
                    if (-not $queN) {
                        if (-not $script:ytPuesto) { $a.desc = 'no se que estaba sonando'; break }
                        $queN = [string]$script:ytPuesto.q
                        $tituloN = [string]$script:ytPuesto.titulo
                        $idN = [string]$script:ytPuesto.id
                    }
                    $soltado = Add-MusicaNo $queN $tituloN $idN
                    # SE DICE LO QUE DE VERDAD SE HACE (24/09, repaso). Antes contestaba
                    # "no te pongo mas musica rock" vetando la BUSQUEDA entera, que no aparece
                    # en ningun titulo: prometia un genero y cumplia una cadena literal.
                    # Ahora se dicen las palabras que van a tachar de verdad, y si no queda
                    # ninguna se dice eso, que es lo honesto.
                    $clavesN = @(Get-MusicaNoClaves $queN)
                    if ($idN) {
                        $a.desc = if ($clavesN.Count -gt 0) { "apuntado: esa no te la vuelvo a poner, y evito lo que suene a " + ($clavesN -join ' ') }
                                  else { 'apuntado: esa cancion no te la vuelvo a poner' }
                    } else {
                        $a.desc = if ($clavesN.Count -gt 0) { "apuntado: no te pongo mas " + ($clavesN -join ' ') }
                                  else { "apuntado, pero de '$queN' no saco ninguna palabra con la que filtrar; dime el estilo" }
                    }
                    if ($soltado) { $a.desc += ". Como ya eran $MusicaNoMax, he soltado lo de $soltado" }
                }
                'musicaSi' {
                    if (Remove-MusicaNo ([string]$a.que)) { $a.desc = "vale, vuelvo a ponerte $($a.que)" }
                    else { $a.desc = "no tenia $($a.que) en esa lista" }
                }
                'musicaNoLista' {
                    $lN = @(Get-MusicaNo)
                    if ($lN.Count -eq 0) { $a.desc = 'no tengo nada apuntado que no te guste'; break }
                    $ultN = @($lN | Select-Object -Last 5 | ForEach-Object { [string]$_.q })
                    $a.desc = "tengo $($lN.Count): " + ($ultN -join ', ')
                    if ($lN.Count -gt $ultN.Count) { $a.desc += ' y mas' }
                }
                'guiaJuego' {
                    $jg = if ([string]$a.juego -eq '*juego*') { Get-JuegoDeReferencia } else { [string]$a.juego }
                    if (-not $jg) { $a.desc = 'no se a que juego te refieres'; break }
                    if ([bool]$a.parte) {
                        # LO QUE HACER AQUI NO ESTA EN LA WIKIPEDIA: va por el camino que ya
                        # existe -captura, OCR y cerebro-, que es el unico que puede mirar la
                        # escena. Leerle el resumen del juego seria contestar a otra cosa.
                        $capG = ''
                        try { $capG = Save-Captura (Join-Path $TmpDir 'pantalla.png') } catch {}
                        $pregG = "Estoy jugando a $jg. Dime en UNA frase que hacer en esta parte. Si no reconoces la escena, dilo; no te lo inventes."
                        if ($capG) {
                            try {
                                $oG = Invoke-OCR $capG
                                if ($oG) { $pregG += ' [Texto visible: ' + $oG.Substring(0, [Math]::Min(1500, $oG.Length)) + ']' }
                            } catch {}
                        }
                        Submit-Command $pregG 'charla' $capG
                        $a.desc = ''   # contesta el cerebro por su camino
                        break
                    }
                    $script:guiaJuego = $jg
                    if (-not (Start-GuiaJuego $jg)) { $a.desc = 'ahora mismo no puedo mirarlo'; break }
                    Set-UI 'pensando' 'mirando la Wikipedia'
                    $a.desc = ''   # se habla cuando llegue, en Receive-Guia
                }
                'musicaQue' {
                    $mu = Get-MusicaActual
                    $a.desc = if (-not $mu -or -not $mu.titulo) { 'ahora mismo no suena nada' }
                              elseif (-not $mu.sonando) { "esta en pausa: $($mu.titulo)" + $(if ($mu.artista) { ", de $($mu.artista)" } else { '' }) }
                              else { "suena $($mu.titulo)" + $(if ($mu.artista) { ", de $($mu.artista)" } else { '' }) }
                }
                'contactoImp' {
                    $lcI = Get-Contactos
                    switch ($a.accion) {
                        'poner' {
                            if ($lcI -notcontains $a.nombre) { [void]$lcI.Add($a.nombre); Save-Contactos }
                            $a.desc = "vale: si te escribe $($a.nombre) te aviso aunque estes jugando; los demas mensajes esperan"
                        }
                        'quitar' {
                            $fuera = @($lcI | Where-Object { $_ -eq $a.nombre })
                            foreach ($y in $fuera) { [void]$lcI.Remove($y) }
                            Save-Contactos
                            $a.desc = if ($fuera.Count -gt 0) { "quitado $($a.nombre)" } else { "$($a.nombre) no estaba entre los importantes" }
                        }
                        'ver' { $a.desc = if ($lcI.Count -gt 0) { 'tus contactos importantes: ' + ($lcI -join ', ') } else { 'no tienes contactos importantes; todos los mensajes avisan igual' } }
                    }
                }
                'brilloAuto' {
                    $hbB = Get-Habitos
                    $hbB.brilloAuto = [bool]$a.activar
                    Save-Habitos
                    $script:brilloAutoPuesto = -1
                    if ($a.activar) { Update-BrilloAuto; $a.desc = "brillo automatico activado: ahora al $(Get-BrilloPorHora (Get-Date).Hour) por ciento" }
                    else { $a.desc = 'brillo automatico desactivado' }
                }
                'notifResumen' {
                    if ($script:invitado) { $a.desc = 'en modo invitado no miro los mensajes'; break }
                    try { [void](Watch-Notificaciones @(Get-Notificaciones)) } catch {}
                    $a.desc = Get-ResumenNotificaciones
                }
                'notifQueDice' {
                    $script:respuestaPrivada = $true   # el remitente y el texto de un mensaje privado
                    if ($script:invitado) { $a.desc = 'en modo invitado no leo los mensajes'; break }
                    try { [void](Watch-Notificaciones @(Get-Notificaciones)) } catch {}
                    # $false: NO se consume. Preguntar "que dice" no puede borrar lo que
                    # "leemelos" iba a leer despues.
                    $a.desc = Get-UltimaNotificacion $false
                    $script:sinTarjeta = $true   # para oirlo, no para una tarjeta
                    $script:sinTarjetaEn = $sw.ElapsedMilliseconds
                }
                'notifLeer' {
                    if ($script:invitado) { $a.desc = 'en modo invitado no leo los mensajes'; break }
                    # MUCHOS MENSAJES (M9): el modelo LOCAL (nunca la API: son tus
                    # mensajes) los resume agrupados por persona o conversacion
                    $nPendL = @($script:notifPendientes).Count
                    if ($nPendL -ge 4 -and $ConversacionOn) {
                        $todosL = Get-LecturaNotificaciones 15
                        # lo que pone en una notificacion tampoco lo dijo el (ver Send-Charla)
                        if (Send-Charla $todosL $false 'resumir' $null $true) { $a.desc = "tienes $nPendL; te los resumo"; break }
                        $a.desc = $todosL
                    } else {
                        $a.desc = Get-LecturaNotificaciones
                    }
                    $script:sinTarjeta = $true   # para oirlo, no para una tarjeta
                    $script:sinTarjetaEn = $sw.ElapsedMilliseconds
                }
                'bateriaHasta' {
                    # BATERIA CON CONSEJO (13/09): cuanto falta hasta esa hora frente a
                    # lo que te dura (lo aprendido de ESTE juego, o lo que calcula
                    # Windows). Si no llega, pregunta si pone el modo ahorro.
                    $ahoraH = Get-Date
                    $objH = Get-Date -Hour ([Math]::Min(23, [int]$a.hora)) -Minute ([Math]::Min(59, [int]$a.minuto)) -Second 0
                    if ($objH -le $ahoraH -and [int]$a.hora -lt 12) { $objH = $objH.AddHours(12) }
                    if ($objH -le $ahoraH) { $objH = $objH.AddDays(1) }
                    $faltanH = [int][Math]::Ceiling(($objH - $ahoraH).TotalMinutes)
                    $dispH = if ($script:juegoActivo) { Get-DuracionBateriaJuego $script:juegoActivo } else { $null }
                    if (-not $dispH -and $script:bateriaMin -gt 0) { $dispH = [int]$script:bateriaMin }
                    $a.desc = if ($script:uiCargando -eq 1) { 'con el cargador puesto, sin problema' }
                              elseif (-not $dispH) { "todavia no se cuanto te dura; vas por el $($script:uiBateria) por ciento" }
                              elseif ($dispH -ge $faltanH) { "si: te quedan unas $(Format-Minutos $dispH) y necesitas $(Format-Minutos $faltanH)" }
                              else {
                                  $script:pendiente = @{ texto = ''; vence = 0; tipo = 'ahorroEnergia' }
                                  "no llegas: te quedan unas $(Format-Minutos $dispH) y necesitas $(Format-Minutos $faltanH). ¿Pongo el modo ahorro?"
                              }
                }
                'duracionBateria' {
                    $jB = $script:juegoActivo
                    $minJ = if ($jB) { Get-DuracionBateriaJuego $jB } else { $null }
                    $a.desc = if ($script:uiCargando -eq 1) { "el cargador esta puesto, asi que sin prisa ($($script:uiBateria) por ciento)" }
                              elseif ($minJ) { "con $jB, unas $(Format-Minutos $minJ) mas; vas por el $($script:uiBateria) por ciento" }
                              elseif ($jB -and $script:bateriaMin -gt 0) { "Windows calcula $(Format-Minutos $script:bateriaMin); lo que gasta $jB lo aprendo en cuanto juegues un rato sin cargador" }
                              elseif ($script:bateriaMin -gt 0) { "a este ritmo, unas $(Format-Minutos $script:bateriaMin); vas por el $($script:uiBateria) por ciento" }
                              else { Get-FraseBateria }
                }
                'dondeMeQuede' {
                    $mJ = Get-JuegosMem
                    $jr = $null
                    if ($a.juego) {
                        foreach ($k in $mJ.Keys) {
                            $pk = ConvertTo-Plain $k
                            if ($pk.Contains($a.juego) -or $a.juego.Contains($pk)) { $jr = $k; break }
                        }
                    }
                    if (-not $jr) { $jr = Get-JuegoDeReferencia }
                    if (-not $jr) {
                        # sin juego delante: la nota mas reciente, sea del juego que sea
                        $masReciente = ''
                        foreach ($k in $mJ.Keys) {
                            if ($mJ[$k]['nota'] -and [string]$mJ[$k]['notaFecha'] -gt $masReciente) { $masReciente = [string]$mJ[$k]['notaFecha']; $jr = $k }
                        }
                    }
                    $a.desc = if ($jr -and $mJ.ContainsKey($jr) -and $mJ[$jr]['nota']) {
                        "En $jr te quedaste en $($mJ[$jr]['nota']), $(Get-HaceCuanto ([string]$mJ[$jr]['notaFecha']))"
                    } elseif ($jr) { "no tengo apuntado donde te quedaste en $jr; dime: me quede en..." }
                    else { 'no tengo nada apuntado; mientras juegas, dime: me quede en...' }
                }
                'fijarTarjeta' {
                    if ($script:popupForm) {
                        $script:popupFijada = $true
                        $script:popupUntil = $sw.ElapsedMilliseconds + $PopupFijadaMs
                        $a.desc = 'la dejo ahi; di quitala cuando acabes'
                    } else {
                        $a.desc = 'no hay ninguna tarjeta abierta'
                    }
                }
                'quitarTarjeta' {
                    # "quitala" tambien se lleva la lupa: si no, braya la quita y le sigue
                    # tapando media pantalla mientras Nova dice que no habia ninguna tarjeta.
                    $habia = ($script:popupForm -or $script:lupaForm)
                    $a.desc = if ($habia) { 'quitada' } else { 'no habia ninguna tarjeta' }
                    Close-Popup
                    Close-Lupa
                }
                'verPerfil' {
                    $dp = @(Get-DatosPerfil)
                    $a.desc = if ($dp.Count -eq 0) { 'todavia no se nada de ti; se ira llenando solo, o dime: aprende que mi...' }
                              else { "se $($dp.Count) cosas de ti: " + ((@($dp | Select-Object -Last 6) | ForEach-Object { $_ -replace '^Dicho por braya:\s*', '' }) -join '; ') }
                }
                'perfilCaidos' {
                    # LA LAPIDA (24/09, idea 12). Sin esto seria un fichero que nadie lee, y
                    # el punto de la idea es justo que braya pueda enterarse de lo que se cayo.
                    $script:respuestaPrivada = $true   # son datos suyos: no al registro
                    $pcV = @(Get-PerfilCaidos 5)
                    $a.desc = if ($pcV.Count -eq 0) { 'no se me ha caido nada todavia' }
                              else { "se me han caido $(@(Get-PerfilCaidos $PerfilMax).Count); las ultimas: " + ($pcV -join '; ') }
                }
                'verRecetas' {
                    $rsV = Get-Recetas
                    $a.desc = if ($rsV.Count -eq 0) { 'todavia no he aprendido ninguna tarea; cuando la IA haga algo por ti, la aprendere' }
                              else { "he aprendido $($rsV.Count): " + ((@($rsV) | Select-Object -Last 8 | ForEach-Object { ([string]$_.frase) -replace '\{[a-z_]+\}', 'algo' }) -join '; ') }
                    # y lo aprendido HABLANDO (el cerebro propio, M1)
                    $cerebroV = ''
                    try { $cerebroV = Get-BalanceCerebro } catch {}
                    if ($cerebroV) { $a.desc = if ($rsV.Count -eq 0) { $cerebroV } else { "$($a.desc). Y $cerebroV" } }
                }
                'olvidoRato' {
                    $rO = $null
                    try { $rO = Invoke-Olvido ([int]$a.minutos) } catch { Log ('OLVIDO: fallo: ' + $_.Exception.Message) }
                    if ($rO) {
                        $totO = 0
                        foreach ($kO in $rO.Keys) { if ($kO -ne 'minutos') { $totO += [int]$rO[$kO] } }
                        $cuantoO = if ([int]$a.minutos -ge 60) { $m = [int]$a.minutos / 60; "$([Math]::Round($m,1)) horas" } else { "$($a.minutos) minutos" }
                        # se dice CUANTO se borro y de cuantos sitios, nunca QUE se borro
                        $a.desc = if ($totO -gt 0) {
                            "Olvidado. He borrado $totO rastros de los ultimos $cuantoO en $($rO.Count - 1) sitios"
                        } else {
                            "No habia nada guardado de los ultimos $cuantoO"
                        }
                    } else {
                        $a.desc = 'No he podido olvidarlo del todo, mirate el log'
                    }
                }
                'aPapelera' {
                    # SOLO SE MIRA DONDE BRAYA GUARDA SUS COSAS. Nada de rutas del sistema
                    # ni de recorrer el disco entero: si no esta en uno de estos cuatro
                    # sitios, se dice y no se busca mas.
                    $dondeP = @(
                        [Environment]::GetFolderPath('Desktop'),
                        (Join-Path $env:USERPROFILE 'Downloads'),
                        [Environment]::GetFolderPath('MyDocuments'),
                        [Environment]::GetFolderPath('MyPictures')
                    ) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
                    $buscaP = [string]$a.que
                    # "PRUEBA DOS" LLEGA AQUI COMO "PRUEBA 2" (20/09). La capa de texto
                    # normaliza los numeros hablados, y la carpeta del disco se llama
                    # "Prueba dos". Buscar solo una de las dos formas es no encontrarla la
                    # mitad de las veces. Se prueban las dos, del 1 al 10, que es hasta
                    # donde llega un nombre de carpeta dicho en voz alta.
                    $numsP = @{ '1' = 'uno'; '2' = 'dos'; '3' = 'tres'; '4' = 'cuatro'; '5' = 'cinco'
                                '6' = 'seis'; '7' = 'siete'; '8' = 'ocho'; '9' = 'nueve'; '10' = 'diez' }
                    $variantesP = New-Object System.Collections.Generic.List[string]
                    $variantesP.Add($buscaP)
                    foreach ($kN in $numsP.Keys) {
                        $vN = $buscaP -replace ('\b' + [regex]::Escape($kN) + '\b'), $numsP[$kN]
                        if ($vN -ne $buscaP) { $variantesP.Add($vN) }
                        $vP = $buscaP -replace ('\b' + [regex]::Escape($numsP[$kN]) + '\b'), $kN
                        if ($vP -ne $buscaP) { $variantesP.Add($vP) }
                    }
                    $variantesP = @($variantesP | Select-Object -Unique)
                    $hallP = @()
                    foreach ($dP in $dondeP) {
                        try {
                            $hallP += @(Get-ChildItem -LiteralPath $dP -Force -ErrorAction SilentlyContinue |
                                        Where-Object { $variantesP -contains $_.Name })
                        } catch {}
                    }
                    if ($hallP.Count -eq 0) {
                        # y se dice DONDE se ha mirado: "no existe" a secas fue justo la
                        # mentira del 20/09
                        foreach ($dP in $dondeP) {
                            try {
                                $hallP += @(Get-ChildItem -LiteralPath $dP -Force -ErrorAction SilentlyContinue |
                                            Where-Object { $n2P = $_.Name; @($variantesP | Where-Object { $n2P -like ("*" + $_ + "*") }).Count -gt 0 })
                            } catch {}
                        }
                    }
                    if ($hallP.Count -eq 0) {
                        $a.desc = "No encuentro nada que se llame $buscaP. He mirado en el escritorio, descargas, documentos e imagenes"
                    } elseif ($hallP.Count -gt 1 -and -not $script:confirmado) {
                        $nomsP = @($hallP | Select-Object -First 4 | ForEach-Object { $_.Name })
                        $a.desc = "Hay varios: " + ($nomsP -join ', ') + ". Dime cual exactamente"
                    } elseif (-not $script:confirmado) {
                        # NUNCA A LA PRIMERA, aunque lo pida claro: lo que se borra por un
                        # malentendido no vuelve solo. Mismo mecanismo que el correo.
                        $itP = $hallP[0]
                        $queEsP = if ($itP.PSIsContainer) { 'la carpeta' } else { 'el archivo' }
                        $script:pendiente = @{ texto = "borra la carpeta $buscaP"; vence = 0; tipo = 'peligrosa' }
                        $dondeEstaP = Split-Path -Leaf (Split-Path -Parent $itP.FullName)
                        $a.desc = "Encontre $queEsP $($itP.Name) en $dondeEstaP. La mando a la papelera?"
                    } else {
                        $itP = $hallP[0]
                        $okP = $false
                        try {
                            Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop
                            if ($itP.PSIsContainer) {
                                [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory(
                                    $itP.FullName, 'OnlyErrorDialogs', 'SendToRecycleBin')
                            } else {
                                [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile(
                                    $itP.FullName, 'OnlyErrorDialogs', 'SendToRecycleBin')
                            }
                            $okP = -not (Test-Path -LiteralPath $itP.FullName)
                        } catch {
                            Log ('PAPELERA: no pude mandar ' + $itP.FullName + ': ' + $_.Exception.Message)
                        }
                        # SE COMPRUEBA QUE DE VERDAD SE FUE, y se dice lo que paso: decir
                        # "hecho" sin mirar es como nacio la mentira del 20/09
                        $a.desc = if ($okP) { "$($itP.Name) esta en la papelera; si me equivoque, sacala de ahi" }
                                  else { "No pude mandar $($itP.Name) a la papelera" }
                    }
                }
                'olvidarReceta' {
                    $rsO = Get-Recetas
                    $objO = $null
                    if ($script:ultimaReceta) { $objO = @($rsO | Where-Object { $_.id -eq $script:ultimaReceta }) | Select-Object -First 1 }
                    if (-not $objO -and $rsO.Count -gt 0) { $objO = $rsO[$rsO.Count - 1] }
                    if ($objO) {
                        [void]$rsO.Remove($objO)
                        Save-Recetas
                        $script:ultimaReceta = $null
                        $a.desc = 'olvidada: ' + (([string]$objO.frase) -replace '\{[a-z_]+\}', 'algo')
                    } else {
                        $a.desc = 'no tengo ninguna receta que olvidar'
                    }
                }
                'juegoSeLlama' {
                    $dSL = $script:ultimoSonidoDudoso
                    if (-not $dSL) { $a.desc = 'ya no me acuerdo de que estabamos hablando'; break }
                    if (Save-JuegoOido ([string]$dSL.oido) ([string]$a.nombre)) {
                        $script:ultimoSonidoDudoso = $null
                        $script:dudosa = $null
                        $a.desc = "apuntado: cuando digas $($dSL.oido) me refiero a $($a.nombre)"
                    } else { $a.desc = "no he podido apuntarlo" }
                }
                'juegoOlvidaSonido' {
                    if (Remove-JuegoOido ([string]$a.oido)) { $a.desc = "olvidado: $($a.oido) vuelve a ser lo que suene" }
                    else { $a.desc = "no tenia nada aprendido de $($a.oido)" }
                }
                'noEraEso' {
                    # 1) deshacer lo que se hiciera
                    $r = Invoke-Deshacer
                    # 2) y aprender: apuntar la frase, marcarla como fallo y olvidar la
                    #    traduccion o la receta de la que salio (ver Invoke-AprenderDelError).
                    #    Aqui SIEMPRE, porque lo has dicho tu: "no era eso" no deja dudas.
                    $ap = Invoke-AprenderDelError $false
                    $a.desc = if ($ap.recetaOlvidada) { "$r. Y olvido esa receta." }
                              elseif ($ap.olvidada) { "$r. Y olvido que '$($ap.olvidada)' significaba eso." }
                              elseif ($ap.apuntada) { "$r. Si lo vuelvo a oir, te pregunto antes." }
                              else { $r }
                }
                'verModos' {
                    $nn = @()
                    try { $nn = @($cmds.perfiles.PSObject.Properties.Name) } catch {}
                    $a.desc = if ($nn.Count -eq 0) { 'no tienes ningun modo' }
                              else { 'tienes ' + ($nn -join ', ') }
                }
                'verModo' {
                    $nom = ConvertTo-Plain $a.nombre
                    if (-not (Test-Prop $cmds.perfiles $nom)) {
                        $a.desc = "no tengo ningun modo que se llame $nom"
                    } else {
                        $a.desc = "el modo $nom hace: " + (@($cmds.perfiles.$nom) -join '; ')
                    }
                }
                'borrarModo' {
                    $nom = ConvertTo-Plain $a.nombre
                    if (-not (Test-Prop $cmds.perfiles $nom)) {
                        $a.desc = "no tengo ningun modo que se llame $nom"
                    } elseif (Remove-Perfil $nom) {
                        $a.desc = "modo $nom borrado"
                    } else {
                        $a.desc = 'no pude borrarlo'
                    }
                }
                'otroMonitor' {
                    # si solo hay una pantalla, mandar Win+Shift+Derecha es tirar
                    # la combinacion al vacio y quedarse callado como si valiera
                    $pantallas = 1
                    try { $pantallas = @([System.Windows.Forms.Screen]::AllScreens).Count } catch {}
                    if ($pantallas -lt 2) {
                        $a.desc = 'solo tienes una pantalla'
                    } else {
                        Send-WinShiftKey 0x27
                        $a.desc = 'al otro monitor'
                    }
                }
                'siempreEncima' {
                    $ya = $false
                    try { $ya = [AX]::EstaEncima() } catch {}
                    if ($ya -eq $a.encima) {
                        $a.desc = if ($a.encima) { 'ya estaba siempre encima' } else { 'no estaba siempre encima' }
                    } else {
                        $ok = $false
                        try { $ok = [AX]::SiempreEncima([bool]$a.encima) } catch {}
                        $a.desc = if (-not $ok) { 'no pude con esa ventana' }
                                  elseif ($a.encima) { 'siempre encima' }
                                  else { 'ya no esta siempre encima' }
                    }
                }
                'esquina' {
                    if ($script:esquina -eq $a.valor) {
                        $a.desc = 'ya estaba ahi'
                    } else {
                        $script:esquina = $a.valor
                        if (Set-Cfg 'ui' 'esquina' $a.valor) {
                            $a.desc = 'listo, y me acuerdo'
                        } else {
                            # se mueve igual: no poder guardarlo no es razon para
                            # no obedecer, pero se dice, que si no parece que si
                            $a.desc = 'me muevo, pero no he podido guardarlo para la proxima'
                        }
                        Refresh-UI
                    }
                }
                'colorUI' {
                    if ($script:uiColor -eq $a.valor) {
                        $a.desc = if ($a.valor) { "ya soy $($a.nombre)" } else { 'ya tengo mi color de siempre' }
                    } else {
                        $script:uiColor = $a.valor
                        $guardadoC = Set-Cfg 'ui' 'color' $a.valor
                        $a.desc = if ($a.valor) { "listo, ahora soy $($a.nombre)" } else { 'vuelvo a mi color de siempre' }
                        if (-not $guardadoC) { $a.desc += ', pero no he podido guardarlo para la proxima' }
                        Refresh-UI
                    }
                }
                'dondeEstas' {
                    $p = $script:esquina -split '-'
                    $a.desc = "estoy $($p[0]) a la $($p[1])"
                }
                'copiarRespuesta' {
                    $t = [string]$script:ultimaRespuesta
                    if (-not $t.Trim()) {
                        $a.desc = 'todavia no te he dicho nada'
                    } else {
                        $puesto = $false
                        try { Set-Clipboard -Value $t; $puesto = $true } catch {}
                        $a.desc = if ($puesto) { "copiado, $($t.Length) caracteres" }
                                  else { 'no pude tocar el portapapeles' }
                    }
                }
                'copiar' {
                    [System.Windows.Forms.SendKeys]::SendWait('^c')
                    # se espera a que la ventana de verdad copie: sin esta pausa
                    # se lee el portapapeles ANTERIOR y te dice una cosa por otra
                    Start-Sleep -Milliseconds 250
                    $t = Get-Portapapeles
                    $a.desc = if ($t) { 'copiado: ' + (Get-Ojeada $t) } else { 'copiado' }
                }
                'pegar' {
                    [System.Windows.Forms.SendKeys]::SendWait('^v')
                    $a.desc = 'pegado'
                }
                'queCopiado' {
                    $t = Get-Portapapeles
                    $a.desc = if ($t) { 'tienes copiado: ' + (Get-Ojeada $t) }
                              else { 'no tienes nada copiado' }
                }
                'apuntarCopiado' {
                    $t = Get-Portapapeles
                    if (-not $t) {
                        $a.desc = 'no tienes nada copiado'
                    } else {
                        $limpio = (($t -replace '[\r\n]+', ' / ') -replace '\s{2,}', ' ').Trim()
                        if ($limpio.Length -gt 600) { $limpio = $limpio.Substring(0, 600) + ' [...]' }
                        $null = Add-Memoria ("(copiado) " + $limpio)
                        # se lee el principio: asi sabes QUE guardo al momento
                        $a.desc = 'apuntado: ' + (Get-Ojeada $t)
                    }
                }
                'queFallo' {
                    $at = @(Get-Atragantos | Where-Object { $_.veces -ge 2 } | Select-Object -First 4)
                    if ($at.Count -eq 0) {
                        $a.desc = 'de lo que llevo apuntado, nada se me ha atragantado mas de una vez'
                    } else {
                        $partes = foreach ($x in $at) { "$($x.frase), $($x.veces) veces ($($x.rutas -join ' y '))" }
                        $a.desc = 'lo que mas se me atraganta: ' + ($partes -join '; ') +
                                  '. Si me dices "aprende que" y luego la frase y la orden buena, no vuelve a pasar.'
                    }
                }
                'tempoUno' {
                    $tpsU = @($script:temporizadores | Where-Object { $_.tipo -ne 'sordina' })
                    $queU = ((ConvertTo-Plain ([string]$a.que)) -replace '^(?:la|el|los|las)\s+', '').Trim()
                    $elegidos = if ($queU) { @($tpsU | Where-Object { (ConvertTo-Plain ([string]$_.texto)) -match [regex]::Escape($queU) }) } else { $tpsU }
                    if ($elegidos.Count -eq 0) {
                        $a.desc = if ($queU) { "no tengo ningun temporizador de $queU" } else { 'no tienes ningun temporizador' }
                    } elseif ($elegidos.Count -gt 1 -and -not $queU -and $a.accion -ne 'ver') {
                        $a.desc = "tienes $($elegidos.Count); dime cual, por ejemplo: pausa el temporizador de la pizza"
                    } else {
                        $tU = $elegidos[0]
                        switch ($a.accion) {
                            'ver' {
                                $restU = if ($tU.pausado) { [long]$tU.pausado } else { $tU.vence - $sw.ElapsedMilliseconds }
                                $minU = [int][Math]::Ceiling($restU / 60000.0)
                                $a.desc = $(if ($minU -le 1) { 'queda menos de un minuto' } else { "quedan $minU minutos" }) + $(if ($tU.pausado) { ', y esta en pausa' } else { '' })
                            }
                            'pausar' {
                                if ($tU.pausado) { $a.desc = 'ya estaba en pausa' }
                                else { $tU.pausado = [long]($tU.vence - $sw.ElapsedMilliseconds); $tU.vence = [long]::MaxValue; $a.desc = 'temporizador en pausa' }
                            }
                            'reanudar' {
                                if (-not $tU.pausado) { $a.desc = 'no estaba en pausa' }
                                else { $tU.vence = $sw.ElapsedMilliseconds + [long]$tU.pausado; $tU.Remove('pausado'); $a.desc = 'sigue contando' }
                            }
                            'cancelar' { [void]$script:temporizadores.Remove($tU); $a.desc = 'temporizador cancelado' }
                        }
                    }
                }
                'verTempo' {
                    # la sordina vive en esta misma lista y no es un aviso tuyo
                    $tps = @($script:temporizadores | Where-Object { $_.tipo -ne 'sordina' })
                    if ($tps.Count -eq 0) {
                        $a.desc = 'no tienes ningun temporizador'
                    } else {
                        $partes = @()
                        foreach ($tp in ($tps | Sort-Object { $_.vence })) {
                            $restoT = if ($tp.pausado) { [long]$tp.pausado } else { $tp.vence - $sw.ElapsedMilliseconds }
                            $queda = [int][Math]::Ceiling($restoT / 60000.0)
                            $cuanto = if ($queda -le 1) { 'menos de un minuto' } else { "$queda minutos" }
                            # sin el texto por defecto: "quedan 2 minutos para se acabo el tiempo"
                            $partes += if ($tp.texto -and $tp.texto -notin 'se acabo el tiempo', 'fin del foco', 'se acabo el descanso') { "$cuanto para $($tp.texto)" } else { "$cuanto" }
                        }
                        $a.desc = 'quedan ' + ($partes -join '; ')
                    }
                }
                'quitarTempo' {
                    $antes = 0
                    for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) {
                        if ($script:temporizadores[$i].tipo -ne 'sordina') { $script:temporizadores.RemoveAt($i); $antes++ }
                    }
                    $a.desc = if ($antes -eq 0) { 'no tenias ninguno' }
                              elseif ($antes -eq 1) { 'temporizador cancelado' }
                              else { "$antes temporizadores cancelados" }
                }
                'descargas' {
                    $bajando = @($script:Juegos | Where-Object { $_.bajando })
                    if ($bajando.Count -eq 0) {
                        $a.desc = 'no hay ninguna descarga en marcha'
                    } else {
                        $partes = @()
                        foreach ($j in $bajando) {
                            $pct = [int](100.0 * $j.descargado / [Math]::Max(1, $j.total))
                            $falta = Format-Gigas ($j.total - $j.descargado)
                            $partes += "$($j.nombre), $pct por ciento, faltan $falta"
                        }
                        $a.desc = ($partes -join '; ')
                    }
                }
                'parte' { $a.desc = (Get-ParteGeneral) }
                'copiaSeguridad' {
                    $c = New-CopiaSeguridad 'lo pediste'
                    $a.desc = if ($c) { "hecha la copia: $($c.archivos) archivos guardados" } else { 'no pude hacer la copia, esta en el log' }
                }
                'queHeHecho' { $a.desc = (Get-QueHeHecho) }
                'comoTeEntendi' { $a.desc = (Get-ComoTeEntendi) }
                'listaAdd' {
                    $listas = Get-Listas
                    $cual = Resolve-Lista ([string]$a.lista) $listas
                    $items = @()
                    if ($listas.ContainsKey($cual)) { $items = @($listas[$cual]) }
                    $yaEsta = $false
                    foreach ($it in $items) { if ((ConvertTo-Plain $it) -eq (ConvertTo-Plain $a.cosa)) { $yaEsta = $true } }
                    if ($yaEsta) {
                        $a.desc = "$($a.cosa) ya estaba en la lista de $cual"
                    } else {
                        $items += [string]$a.cosa
                        $listas[$cual] = $items
                        if (Save-Listas $listas) {
                            $a.desc = "apuntado, en la lista de $cual llevas $(@($items).Count)"
                        } else {
                            $a.desc = "no pude guardar la lista"
                        }
                    }
                }
                'clipJuego' { $a.desc = Invoke-ClipJuego }
                'paraDos' { $a.desc = (Get-ParaDos ([string]$a.cual)) }
                'apuntaDos' {
                    $jA = Find-Juego ([string]$a.cual)
                    if ($jA) {
                        Set-JuegoDos ([string]$jA.nombre) ([bool]$a.si)
                        $a.desc = if ($a.si) { "apuntado: " + $jA.nombre + " es de dos" }
                                  else { "apuntado: " + $jA.nombre + " no es de dos" }
                    } else { $a.desc = 'no tengo ningun juego que se llame asi' }
                }
                'descargaJuego' { $a.desc = [string]$a.texto }
                'descargasAbrir' {
                    try {
                        Start-Process 'steam://open/downloads'
                        $a.desc = if ($a.pausar) { 'te abro las descargas de Steam; desde ahi se pausan' } else { 'abriendo las descargas de Steam' }
                    } catch { $a.desc = 'no pude abrir Steam' }
                }
                'amigosSteam' {
                    $script:respuestaPrivada = $true   # los nicks de sus amigos y a que juegan
                    # TAMBIEN ASINCRONO (24/09, repaso): eran dos Invoke-RestMethod con
                    # -TimeoutSec 6 dentro del bucle, hasta 12 s de consola congelada.
                    $eA = Start-AmigoPregunta 'decir'
                    $a.desc = if ($eA) { $eA } else { 'un momento, que le pregunto a Steam' }
                }
                'amigoVigila' { $script:respuestaPrivada = $true; $a.desc = Start-AmigoVigila }
                'amigoElige' {
                    $rE = Complete-AmigoElige ([int]$a.n)
                    # sin lista viva no se contesta nada: el numero no era para esto
                    if ($rE) { try { Close-Eleccion } catch {}; $a.desc = $rE } else { $a.desc = '' }
                }
                'amigoOlvida' {
                    $gE = Get-Reglas
                    $fueraE = @()
                    foreach ($xE in @($gE)) {
                        if ([string]$xE.tipo -eq 'amigoConecta') { $fueraE += ([string]$xE.valor).Split('|')[1]; [void]$gE.Remove($xE) }
                    }
                    $script:amigoEligiendo = $null
                    if ($fueraE.Count -eq 0) { $a.desc = 'no estaba vigilando a nadie' }
                    else {
                        Save-Reglas
                        $script:amigoOnline = @{}
                        Log ("VIGILANCIA quitada: " + ($fueraE -join ', '))
                        $a.desc = 'vale, ya no te aviso de ' + ($fueraE -join ' ni de ')
                    }
                }
                'amigosDiscord' { $a.desc = 'en Discord no puedo verlo: no deja mirarlo sin un bot' }
                'musicaAnterior' {
                    $cA = Get-CancionAnterior
                    $a.desc = if ($cA) { "era $($cA.t)" + $(if ($cA.a) { " de $($cA.a)" } else { '' }) } else { 'no tengo apuntada ninguna cancion todavia' }
                }
                'musicaDe' {
                    $cD = Find-CancionDe ([string]$a.cuando)
                    if (-not $cD) { $a.desc = "no tengo apuntado nada de $($a.cuando)" }
                    else {
                        try { Start-Process ('spotify:search:' + [Uri]::EscapeDataString(("$($cD.t) $($cD.a)").Trim())) } catch {}
                        $a.desc = "te busco en Spotify $($cD.t)" + $(if ($cD.a) { " de $($cD.a)" } else { '' })
                    }
                }
                'listaCopiar' {
                    $listasC = Get-Listas
                    $cualC = Resolve-Lista ([string]$a.lista) $listasC
                    if (-not $listasC.ContainsKey($cualC) -or @($listasC[$cualC]).Count -eq 0) { $a.desc = "no tienes nada en la lista de $cualC" }
                    else {
                        $textoC = "Lista de $($cualC):`r`n" + ((@($listasC[$cualC]) | ForEach-Object { "- $_" }) -join "`r`n")
                        $okC = $false
                        try { Set-Clipboard -Value $textoC; $okC = $true } catch {}
                        $a.desc = if ($okC) { "copiada la lista de $cualC, " + $(if (@($listasC[$cualC]).Count -eq 1) { 'una cosa' } else { "$(@($listasC[$cualC]).Count) cosas" }) + '; ya puedes pegarla' } else { 'no pude tocar el portapapeles' }
                    }
                }
                'listaVer' {
                    $listas = Get-Listas
                    $cual = Resolve-Lista ([string]$a.lista) $listas
                    if (-not $listas.ContainsKey($cual)) { $a.desc = "no tienes lista de $cual" }
                    else { $a.desc = Format-Lista $cual $listas[$cual] }
                }
                'listaCuales' {
                    $listas = Get-Listas
                    if ($listas.Keys.Count -eq 0) {
                        $a.desc = 'no tienes ninguna lista todavia'
                    } else {
                        $partes = @()
                        foreach ($k in $listas.Keys) { $partes += "$k (" + @($listas[$k]).Count + ")" }
                        $a.desc = 'tienes ' + ($partes -join ', ')
                    }
                }
                'listaQuitar' {
                    $listas = Get-Listas
                    $cual = Resolve-Lista ([string]$a.lista) $listas
                    if (-not $listas.ContainsKey($cual)) {
                        $a.desc = "no tienes lista de $cual"
                    } else {
                        $items = @($listas[$cual])
                        # sin articulo: se dice "quita los huevos" y en la lista
                        # pone "huevos". Comparar en crudo fallaba justo en lo
                        # mas normal que se puede decir.
                        $plano = (ConvertTo-Plain $a.cosa) -replace '^(?:el|la|los|las|un|una|unos|unas|mi|mis)\s+', ''
                        # "el primero" y "el ultimo" son lo que de verdad se dice
                        # cuando ya has leido la lista en voz alta
                        $quitar = -1
                        if ($plano -match '^(?:primero|primera|primer|uno|el uno)$') { $quitar = 0 }
                        elseif ($plano -match '^(?:ultimo|ultima|el ultimo)$') { $quitar = $items.Count - 1 }
                        else {
                            for ($k = 0; $k -lt $items.Count; $k++) {
                                $it = (ConvertTo-Plain $items[$k]) -replace '^(?:el|la|los|las|un|una|unos|unas|mi|mis)\s+', ''
                                if ($it -eq $plano) { $quitar = $k; break }
                            }
                            # y si no es exacto, que contenga: "quita el pan de molde"
                            if ($quitar -lt 0) {
                                for ($k = 0; $k -lt $items.Count; $k++) {
                                    if ((ConvertTo-Plain $items[$k]) -like "*$plano*") { $quitar = $k; break }
                                }
                            }
                        }
                        if ($quitar -lt 0 -or $quitar -ge $items.Count) {
                            $a.desc = "no encuentro $($a.cosa) en la lista de $cual"
                        } else {
                            $quitado = $items[$quitar]
                            $nuevos = @()
                            for ($k = 0; $k -lt $items.Count; $k++) { if ($k -ne $quitar) { $nuevos += $items[$k] } }
                            $listas[$cual] = $nuevos
                            $null = Save-Listas $listas
                            $a.desc = if (@($nuevos).Count -eq 0) { "tachado $quitado, y con eso se acaba la lista" }
                                      else { "tachado $quitado, quedan " + @($nuevos).Count }
                        }
                    }
                }
                'listaVaciar' {
                    $listas = Get-Listas
                    $cual = Resolve-Lista ([string]$a.lista) $listas
                    if (-not $listas.ContainsKey($cual) -or @($listas[$cual]).Count -eq 0) {
                        $a.desc = "la lista de $cual ya estaba vacia"
                    } elseif (-not $script:confirmado) {
                        # vaciar una lista de la compra a medio hacer es tan
                        # irreversible como cerrar un juego: se pregunta
                        $cuantos = @($listas[$cual]).Count
                        $script:pendiente = @{ texto = "borra la lista de $cual"; vence = 0; tipo = 'peligrosa' }
                        $a.desc = "en la lista de $cual hay $cuantos cosas. ¿La vacio?"
                    } else {
                        $listas.Remove($cual)
                        $null = Save-Listas $listas
                        $a.desc = "lista de $cual vaciada"
                    }
                }
                'dictadoLargo' {
                    # la que tenias TU delante al empezar a hablar, no la que
                    # tiene el foco ahora (que ya es la del asistente)
                    $script:dictadoVentana = $script:ventanaUsuario
                    # ...salvo que hayas dicho a cual: entonces se pone delante
                    if ($a.proceso) {
                        $pd = Get-Process -Name $a.proceso -ErrorAction SilentlyContinue |
                              Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
                        if (-not $pd -and $a.abrir) {
                            # no esta abierta: se abre. Decir "dicta en el bloc
                            # de notas" y que conteste "no esta abierta" es
                            # mandar al usuario a hacer a mano justo lo que
                            # acaba de pedir.
                            Log "DICTADO LARGO: $($a.proceso) no estaba abierta; la abro"
                            try { Start-Process $a.abrir -ErrorAction Stop } catch {
                                $a.desc = "$($a.desc): no pude abrirla"
                                break
                            }
                            # esperar a que aparezca la ventana, hasta 6 s: una
                            # app fria tarda, y sin ventana no hay donde dictar
                            for ($esp = 0; $esp -lt 30; $esp++) {
                                Start-Sleep -Milliseconds 200
                                $pd = Get-Process -Name $a.proceso -ErrorAction SilentlyContinue |
                                      Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
                                if ($pd) { break }
                            }
                        }
                        if (-not $pd) {
                            $a.desc = "$($a.desc): no esta abierta"
                            break
                        }
                        [void][AX]::ShowWindow($pd.MainWindowHandle, 9)   # por si estaba minimizada
                        [void][AX]::ForceForeground($pd.MainWindowHandle)
                        Start-Sleep -Milliseconds 200
                        $script:dictadoVentana = $pd.MainWindowHandle
                    }
                    # QUE VENTANA es, en el log: si algun dia el texto aparece
                    # donde no debe, este numero es lo unico que lo explica
                    Log ("DICTADO LARGO: escribire en la ventana " + $script:dictadoVentana)
                    $script:dictandoLargo = $true
                    $script:dictadoLargoHasta = $sw.ElapsedMilliseconds + $DictadoLargoMs
                    $script:dictadoUltimo = ''
                    $script:dictadoLineas = 0
                    $script:dictadoWinH = ($DictadoLargoMotor -eq 'windows')
                    Log "DICTADO LARGO: empieza (motor $DictadoLargoMotor, plazo $([int]($DictadoLargoMs / 60000)) min)"
                    if ($script:dictadoWinH) {
                        # NO se abre aqui: el asistente esta a punto de contestar
                        # en voz alta, y Win+H transcribiria su propia voz. Se
                        # deja pedido y lo abre el bucle en cuanto se calle.
                        $script:dictadoWinHPendiente = $true
                        $a.desc = 'voy, abro el dictado de Windows. Cuando acabes, manten el boton'
                    } else {
                        $a.desc = 'te escribo lo que digas en la ventana de delante. Para salir, di ya esta o manten el boton'
                    }
                }
                'escalaUI' {
                    $antes = [double]$script:uiEscala
                    if ([int]$a.paso -eq 0) {
                        $script:uiEscala = 1.0
                    } else {
                        # al escalon de al lado, no a un numero cualquiera: se
                        # busca el actual en la lista y se avanza uno
                        $i = 0
                        for ($k = 0; $k -lt $EscalasUI.Count; $k++) {
                            if ([Math]::Abs($EscalasUI[$k] - $antes) -lt 0.01) { $i = $k }
                        }
                        $i = [Math]::Max(0, [Math]::Min($EscalasUI.Count - 1, $i + [int]$a.paso))
                        $script:uiEscala = [double]$EscalasUI[$i]
                    }
                    if ([Math]::Abs($script:uiEscala - $antes) -lt 0.01) {
                        $a.desc = if ([int]$a.paso -gt 0) { 'ya estoy todo lo grande que puedo' }
                                  elseif ([int]$a.paso -lt 0) { 'ya estoy todo lo pequena que puedo' }
                                  else { 'ya estaba en el tamano de siempre' }
                    } else {
                        $pct = [int]($script:uiEscala * 100)
                        $guardado = Set-Cfg 'ui' 'escala' $script:uiEscala
                        $a.desc = if ($guardado) { "listo, al $pct por ciento, y me acuerdo" }
                                  else { "listo, al $pct por ciento, pero no he podido guardarlo para la proxima" }
                        Refresh-UI
                    }
                }
                'soloYo' {
                    $script:SoloYoOn = [bool]$a.valor
                    $guardado = Set-Cfg 'escucha' 'soloYo' ([bool]$a.valor)
                    $que = if ($a.valor) { 'a partir de ahora, si la voz no se parece a la tuya, pregunto antes de hacer nada' }
                           else { 'vale, hago caso a cualquiera' }
                    $a.desc = if ($guardado) { $que } else { "$que, pero no he podido guardarlo para la proxima" }
                }
                'quienSoy' {
                    $duena = Get-VozDuena
                    if (-not $SoloYoOn) {
                        $a.desc = 'ahora mismo hago caso a cualquiera; dime hazme caso solo a mi para cambiarlo'
                    } elseif ($duena -le 0) {
                        $a.desc = 'todavia no. Necesito oirte unas cuantas veces mas para saber cual es tu voz'
                    } else {
                        $t = "tu voz esta sobre los $([int]$duena) hercios"
                        if ($script:ultimaF0 -gt 0) {
                            $dif = [int][Math]::Abs($script:ultimaF0 - $duena)
                            $t += if ($dif -gt $SoloYoMargen) { ", y esto ultimo lo he oido a $([int]$script:ultimaF0): no me suena a ti" }
                                  else { ", y lo que acabas de decir encaja" }
                        }
                        $a.desc = $t
                    }
                }
                'ram' {
                    # se lee AL EJECUTAR, no al reconocer: un banco que solo resuelve
                    # no tiene por que ir a mirar los procesos (igual que 'disco')
                    $a.desc = Get-RamResumen ([string]$a.que)
                }
                'carpetaInfo' {
                    $script:respuestaPrivada = $true   # los nombres de sus ficheros
                    # SOLO LECTURA: cuenta, mide y lista. Aqui no se borra ni se mueve nada.
                    $nomC = [string]$a.nombre
                    $rutaC = ''
                    try { $rutaC = Find-CarpetaPorNombre $nomC } catch { $rutaC = '' }
                    if (-not $rutaC) { $a.desc = "No encuentro ninguna carpeta que se llame $nomC"; break }
                    $comoC = Split-Path -Leaf $rutaC
                    $rC = Get-ResumenCarpeta $rutaC ([bool]($a.que -eq 'mide'))
                    if (-not $rC.ok) { $a.desc = "No pude mirar dentro de $comoC"; break }
                    switch ([string]$a.que) {
                        'cuenta' {
                            $pC = @()
                            $pC += "$($rC.ficheros) $(if ($rC.ficheros -eq 1) { 'archivo' } else { 'archivos' })"
                            if ($rC.carpetas -gt 0) { $pC += "$($rC.carpetas) $(if ($rC.carpetas -eq 1) { 'carpeta' } else { 'carpetas' })" }
                            $a.desc = "En $comoC tienes " + ($pC -join ' y ')
                        }
                        'mide' {
                            # SI SE CORTO, SE DICE: media respuesta dicha como media respuesta.
                            $a.desc = "$comoC ocupa $(if ($rC.parcial) { 'por lo menos ' } else { '' })$(Format-Gigas $rC.bytes)"
                        }
                        default {
                            $totC = $rC.ficheros + $rC.carpetas
                            if ($totC -eq 0) { $a.desc = "No hay nada en $comoC"; break }
                            # dicho en voz alta, "tienes 3:" suena a medias (probado el 16/09)
                            $tC = "En $comoC tienes $totC $(if ($totC -eq 1) { 'cosa' } else { 'cosas' }): " + (@($rC.nombres) -join ', ')
                            if ($totC -gt @($rC.nombres).Count) { $tC += " y $($totC - @($rC.nombres).Count) mas" }
                            $a.desc = $tC
                        }
                    }
                }
                'disco' {
                    # la unidad donde estan los juegos, no siempre C:
                    $unidades = @('C')
                    try {
                        $sp = (Get-ItemProperty 'HKCU:\Software\Valve\Steam' -ErrorAction SilentlyContinue).SteamPath
                        if ($sp) { $u = ($sp -replace '/', '\').Substring(0, 1).ToUpper(); if ($unidades -notcontains $u) { $unidades += $u } }
                    } catch {}
                    $partes = @()
                    foreach ($u in $unidades) {
                        try {
                            $di = New-Object System.IO.DriveInfo($u)
                            if (-not $di.IsReady) { continue }
                            $libre = Format-Gigas $di.AvailableFreeSpace
                            $partes += "en $($u): $libre"
                        } catch {}
                    }
                    if ($partes.Count -eq 0) { $a.desc = 'no pude leer el disco' }
                    else { $a.desc = 'te quedan ' + ($partes -join ', ') }
                }
                'ultimaPartida' {
                    $j = $null
                    if ($a.que) { $j = Find-Juego $a.que }
                    if (-not $j) {
                        $a.desc = "no tengo ese juego en la biblioteca"
                    } else {
                        # el indice se lee al arrancar; para una fecha conviene
                        # refrescar, que es justo el dato que cambia al jugar
                        $null = Update-Juegos
                        $act = @($script:Juegos | Where-Object { $_.id -eq $j.id })
                        $lp = if ($act.Count -gt 0) { [long]$act[0].ultimo } else { [long]$j.ultimo }
                        $cuando = Format-Desde $lp
                        $a.desc = if ($cuando) { "jugaste a $($j.nombre) $cuando" } else { "no has jugado a $($j.nombre) todavia" }
                    }
                }
                'jugadoReciente' {
                    $null = Update-Juegos
                    $limite = [DateTimeOffset]::Now.AddDays(-8).ToUnixTimeSeconds()
                    $recientes = @($script:Juegos | Where-Object { [long]$_.ultimo -gt $limite } | Sort-Object { -[long]$_.ultimo })
                    if ($recientes.Count -eq 0) {
                        $a.desc = 'no has jugado a nada esta semana'
                    } else {
                        $partes = @()
                        foreach ($j in ($recientes | Select-Object -First 5)) {
                            $partes += "$($j.nombre) ($(Format-Desde ([long]$j.ultimo)))"
                        }
                        $a.desc = 'esta semana: ' + ($partes -join ', ')
                    }
                }
                'ocupa' {
                    $j = if ($a.que) { Find-Juego $a.que } else { $null }
                    if (-not $j) { $a.desc = "no tengo ese juego en la biblioteca" }
                    else {
                        $act = @($script:Juegos | Where-Object { $_.id -eq $j.id })
                        $tam = if ($act.Count -gt 0) { [double]$act[0].tamano } else { 0 }
                        $a.desc = if ($tam -gt 0) { "$($j.nombre) ocupa $(Format-Gigas $tam)" } else { "no se cuanto ocupa $($j.nombre)" }
                    }
                }
                'volumenApp' {
                    # el juego activo no tiene nombre de proceso fijo: se resuelve
                    # al vuelo desde el ejecutable que la capsula ya conoce
                    $pids = @()
                    if ($a.proceso -eq '*juego*') {
                        if (-not $script:juegoExe) {
                            $a.desc = 'no hay ningun juego abierto'
                            break
                        }
                        $pids = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { try { $_.Path -eq $script:juegoExe } catch { $false } } | ForEach-Object { $_.Id })
                    } else {
                        $pids = @(Get-Process -Name $a.proceso -ErrorAction SilentlyContinue | ForEach-Object { $_.Id })
                    }
                    if ($pids.Count -eq 0) {
                        $a.desc = "$($a.nombre) no esta abierto"
                    } else {
                        $hizo = $false
                        foreach ($pd in $pids) {
                            if ($a.silenciar) {
                                if ([AX]::SilenciarApp($pd, $true)) { $hizo = $true }
                            } elseif ($null -ne $a.pct) {
                                if ([AX]::PonerVolumenApp($pd, [int]$a.pct)) { $hizo = $true }
                            } else {
                                $v = [AX]::LeerVolumenApp($pd)
                                if ($v -ge 0) {
                                    $destino = [Math]::Max(0, [Math]::Min(100, $v + $(if ($a.sube) { 20 } else { -20 })))
                                    if ([AX]::PonerVolumenApp($pd, $destino)) { $hizo = $true; $a.desc = "$($a.nombre) al $destino por ciento" }
                                }
                            }
                        }
                        if (-not $hizo) { $a.desc = "$($a.nombre) no esta reproduciendo nada ahora mismo" }
                    }
                }
                'queSuena' {
                    $pids = @()
                    try { $pids = @([AX]::PidsConSonido()) } catch {}
                    $nombres = @()
                    foreach ($pd in $pids) {
                        try {
                            $pr = Get-Process -Id $pd -ErrorAction Stop
                            $n = $pr.ProcessName
                            # si es un juego de Steam, mejor su nombre de verdad
                            try {
                                if ($pr.Path -match '(?i)steamapps\\common\\([^\\]+)') {
                                    $j = Find-Juego $Matches[1]
                                    if ($j) { $n = $j.nombre }
                                }
                            } catch {}
                            if ($nombres -notcontains $n) { $nombres += $n }
                        } catch {}
                    }
                    $a.desc = if ($nombres.Count -eq 0) { 'ahora mismo no suena nada' }
                              else { 'suena ' + ($nombres -join ', ') }
                }
                'queJuego' {
                    $a.desc = if ($script:juegoActivo) { "estas jugando a $($script:juegoActivo)" } else { "no detecto ningun juego en primer plano" }
                }
                'winprt' { Send-WinKey 0x2C }        # Win+ImprPant: guarda en Imagenes\Capturas
                'winaltg' { Send-WinAlt 0x47 }       # Win+Alt+G: graba lo ultimo
                'volumenPct' {
                    # UNA llamada. Antes esto eran 50 pulsaciones de bajar y N de
                    # subir, con 30 ms entre cada una: ~2,5 s de tics de volumen
                    # sonando encima del juego para poner un simple 70 %.
                    # Si la API falla (dispositivo raro), se vuelve al metodo
                    # viejo: mas vale lento que no hacer nada.
                    $script:uiVolumen = [int]$a.pct
                    if (-not [AX]::PonerVolumen($a.pct)) {
                        Log "volumen: la API fallo, voy con las teclas"
                        for ($i = 0; $i -lt 50; $i++) { Send-Key 0xAE }
                        $pasos = [int][Math]::Round($a.pct / 2)
                        for ($i = 0; $i -lt $pasos; $i++) { Send-Key 0xAF }
                    }
                }
                'volumenRel' {
                    # subir o bajar un paso, pero con numero exacto y sin tics
                    $ahora = [AX]::LeerVolumen()
                    if ($ahora -lt 0) {
                        Send-Key $(if ($a.sube) { 0xAF } else { 0xAE })
                    } else {
                        $destino = [Math]::Max(0, [Math]::Min(100, $ahora + $a.paso))
                        [void][AX]::PonerVolumen($destino)
                        $script:uiVolumen = [int]$destino
                        $a.desc = "volumen al $destino por ciento"
                    }
                }
                'silencio' {
                    $m = [AX]::LeerSilencio()
                    $quiere = if ($null -ne $a.silencio) { [bool]$a.silencio } else { ($m -ne 1) }
                    if (-not [AX]::PonerSilencio($quiere)) { Send-Key 0xAD }
                    $a.desc = if ($quiere) { 'silencio' } else { 'sonido otra vez' }
                }
                'winkey' { Send-WinKey $a.vk }
                'dividir' {
                    # PANTALLA DIVIDIDA (18/09): abrir, esperar a que tenga ventana delante,
                    # Win+Izquierda; y lo mismo con la otra a la derecha. La espera mira si
                    # cambia la ventana en primer plano, hasta 4 s: lanzar la tecla antes de
                    # que exista la ventana la colocaria en la que hubiera debajo.
                    $antesH = [AX]::GetForegroundWindow()
                    $colocadas = 0
                    foreach ($parte in @(@{ que = $a.izq; vk = 0x25 }, @{ que = $a.der; vk = 0x27 })) {
                        $q = $parte.que
                        if ($q.kind -eq 'url') { Start-Process $q.url -ErrorAction Stop }
                        else { $null = Start-Process $q.target -PassThru -ErrorAction Stop }
                        $t0 = $sw.ElapsedMilliseconds
                        $aparecio = $false
                        while (($sw.ElapsedMilliseconds - $t0) -lt 4000) {
                            Start-Sleep -Milliseconds 200
                            $hAhora = [AX]::GetForegroundWindow()
                            if ($hAhora -ne [IntPtr]::Zero -and $hAhora -ne $antesH) { $aparecio = $true; break }
                        }
                        if ($aparecio) {
                            Start-Sleep -Milliseconds 350        # que termine de pintarse antes de moverla
                            Send-WinKey $parte.vk
                            $colocadas++
                            Start-Sleep -Milliseconds 400
                            $antesH = [AX]::GetForegroundWindow()
                        }
                    }
                    if ($colocadas -lt 2) { $a.desc = "$($a.desc); una de las dos no llego a colocarse" }
                    else {
                        # y se recuerda, por si braya dice luego "guarda esto como el tablero"
                        # (ver MONTAJES CON NOMBRE). Se guarda lo RESUELTO, no lo que se oyo.
                        $script:ultimoDividir = @{
                            izq = [string]$(if ($a.izq.kind -eq 'url') { $a.izq.url } else { $a.izq.target })
                            der = [string]$(if ($a.der.kind -eq 'url') { $a.der.url } else { $a.der.target })
                            izqTipo = [string]$a.izq.kind; derTipo = [string]$a.der.kind
                        }
                    }
                }
                'dividirUna' {
                    # PANTALLA DIVIDIDA CON UNA SOLA APP (19/09). Igual que 'dividir', pero
                    # el otro lado NO se abre: se reusa $script:ventanaUsuario, que es la
                    # ventana que tenias delante al empezar a hablar y que ya deja fuera a
                    # Nova y a su capsula (se apunta antes de mostrar nada del asistente).
                    # Si no hay ninguna, se coloca solo la nueva y se dice: mover una ventana
                    # que no era es peor que dejar media pantalla sola.
                    $otraH = $script:ventanaUsuario
                    $antesH = [AX]::GetForegroundWindow()
                    $q = $a.que
                    if ($q.kind -eq 'url') { Start-Process $q.url -ErrorAction Stop }
                    else { $null = Start-Process $q.target -PassThru -ErrorAction Stop }
                    $t0 = $sw.ElapsedMilliseconds
                    $aparecio = $false
                    while (($sw.ElapsedMilliseconds - $t0) -lt 4000) {
                        Start-Sleep -Milliseconds 200
                        $hAhora = [AX]::GetForegroundWindow()
                        if ($hAhora -ne [IntPtr]::Zero -and $hAhora -ne $antesH) { $aparecio = $true; break }
                    }
                    if (-not $aparecio) {
                        $a.desc = "$($a.desc); no llego a abrirse a tiempo"
                    } else {
                        Start-Sleep -Milliseconds 350        # que termine de pintarse antes de moverla
                        Send-WinKey 0x27                     # Win+Derecha: la nueva, a la derecha
                        Start-Sleep -Milliseconds 400
                        $nuevaH = [AX]::GetForegroundWindow()
                        # Win+Derecha deja a Windows ofreciendo el otro lado (Snap Assist) por
                        # ENCIMA de todo. Poner la otra ventana delante lo quita y la coloca de
                        # una vez; si no hay otra, Escape, que ese panel no se queda puesto.
                        $ok2 = $false
                        if ($otraH -ne [IntPtr]::Zero -and $otraH -ne $nuevaH) {
                            try { $ok2 = [bool][AX]::ForceForeground($otraH) } catch { $ok2 = $false }
                        }
                        if ($ok2) {
                            Start-Sleep -Milliseconds 250
                            Send-WinKey 0x25                 # Win+Izquierda: la de antes, a la izquierda
                            Start-Sleep -Milliseconds 300
                        } else {
                            Send-Key 0x1B                    # VK_ESCAPE: fuera el Snap Assist
                            $a.desc = "$($q.desc -replace '^abrir ', '') a la derecha; no habia nada delante que poner al otro lado"
                        }
                    }
                }
                'anclar' {
                    # De donde sale el .exe: si se dijo un nombre, del PROCESO abierto (asi
                    # valen Steam, Discord y Spotify, cuyo target en commands.json es un URI
                    # y no un fichero); si no se dijo ninguno, de la ventana que tenias
                    # delante al hablar. Sin ruta no se inventa nada: se dice y se acaba.
                    $rutaAn = ''
                    $nombreAn = ''
                    if ($a.que) {
                        $prAn = Resolve-Proceso $a.que
                        if ($prAn -and $prAn.proceso -ne '*juego*') {
                            $nombreAn = [string]$prAn.nombre
                            $pAn = @(Get-Process -Name $prAn.proceso -ErrorAction SilentlyContinue)[0]
                            if ($pAn) { try { $rutaAn = [string]$pAn.MainModule.FileName } catch { $rutaAn = '' } }
                            if (-not $rutaAn) {
                                $tgAn = [string]$cmds.apps.$nombreAn
                                if ($tgAn -match '\.exe$') {
                                    try { $rutaAn = [string](Get-Command $tgAn -ErrorAction SilentlyContinue).Source } catch { $rutaAn = '' }
                                }
                            }
                        }
                    } else {
                        $hAn = $script:ventanaUsuario
                        if ($hAn -ne [IntPtr]::Zero) {
                            $pidAn = Get-PidDeVentana $hAn
                            if ($pidAn -gt 0) {
                                $pAn = Get-Process -Id $pidAn -ErrorAction SilentlyContinue
                                if ($pAn -and ($PROCESOS_INTOCABLES -notcontains $pAn.ProcessName)) {
                                    try { $rutaAn = [string]$pAn.MainModule.FileName } catch { $rutaAn = '' }
                                    $nombreAn = [string]$pAn.ProcessName
                                }
                            }
                        }
                    }
                    if (-not $rutaAn -or -not (Test-Path -LiteralPath $rutaAn)) {
                        $a.desc = if ($a.que) { "no tengo abierto '$($a.que)', y sin eso no se de que hacer el acceso directo" }
                                  else { 'no se de que programa lo quieres: dimelo por su nombre' }
                    } else {
                        $etiqAn = if ($nombreAn) { $nombreAn } else { [System.IO.Path]::GetFileNameWithoutExtension($rutaAn) }
                        if ($a.donde -eq 'inicio') {
                            # el verbo, tal cual lo da Windows y sin el '&' del acelerador
                            $shAn = New-Object -ComObject Shell.Application
                            $itAn = $shAn.Namespace((Split-Path $rutaAn)).ParseName((Split-Path $rutaAn -Leaf))
                            $vbAn = @($itAn.Verbs() | Where-Object { ($_.Name -replace '&', '') -match '^(?:Anclar a Inicio|Pin to Start)$' })[0]
                            if ($vbAn) { $vbAn.DoIt(); $a.desc = "$etiqAn anclado a Inicio" }
                            else { $a.desc = "Windows ya no me deja anclar $etiqAn a Inicio desde aqui" }
                        } else {
                            $lnkAn = Join-Path ([Environment]::GetFolderPath('Desktop')) ($etiqAn + '.lnk')
                            $wsAn = New-Object -ComObject WScript.Shell
                            $acAn = $wsAn.CreateShortcut($lnkAn)
                            $acAn.TargetPath = $rutaAn
                            $acAn.WorkingDirectory = (Split-Path $rutaAn)
                            $acAn.Save()
                            # LA BARRA, CON LA VERDAD POR DELANTE: el verbo de anclar a la barra
                            # ya no existe en Windows 11 (comprobado el 19/09 sobre notepad.exe),
                            # pero arrastrar el acceso directo a la barra si la ancla.
                            $a.desc = if ($a.donde -eq 'barra') { "$etiqAn en el escritorio; la barra de tareas de Windows 11 ya no deja anclar desde un script, arrastralo ahi y se queda" }
                                      else { "acceso directo de $etiqAn en el escritorio" }
                        }
                    }
                }
                'lock' { Start-Process 'rundll32.exe' 'user32.dll,LockWorkStation' -ErrorAction Stop }
                'altf4' { [AX]::keybd_event([byte]$VK_MENU, 0, 0, [UIntPtr]::Zero); Start-Sleep -Milliseconds 40; Send-Key 0x73; [AX]::keybd_event([byte]$VK_MENU, 0, $KEYUP, [UIntPtr]::Zero) }
                'alttab' { [AX]::keybd_event([byte]$VK_MENU, 0, 0, [UIntPtr]::Zero); Start-Sleep -Milliseconds 40; Send-Key 0x09; Start-Sleep -Milliseconds 40; [AX]::keybd_event([byte]$VK_MENU, 0, $KEYUP, [UIntPtr]::Zero) }
                'atajo' { [System.Windows.Forms.SendKeys]::SendWait($a.teclas) }
                'escribir' {
                    # SendKeys interpreta + ^ % ~ ( ) { }: se escapan entre llaves
                    $txt = [regex]::Replace($a.texto, '[+^%~(){}\[\]]', { param($m) '{' + $m.Value + '}' })
                    [System.Windows.Forms.SendKeys]::SendWait($txt)
                }
                'esconder' { $script:uiRetirada = 'nombre'; Set-UI 'retirada' }
                'sordina' {
                    # EL ORDEN IMPORTA (22/09): sordinaHasta se sella ANTES de pausar, porque
                    # Pausar-Escucha mira esa variable para decidir que marca escribe. Al
                    # reves, la primera marca salia 'x' -sorda del todo- y el nombre no la
                    # despertaba hasta la siguiente pausa.
                    $script:sordinaHasta = $sw.ElapsedMilliseconds + $a.ms
                    Pausar-Escucha $a.ms
                    # el aviso de vuelta va por la via de los temporizadores, que
                    # ya sabe hablar sola cuando vence
                    [void]$script:temporizadores.Add(@{ vence = ($sw.ElapsedMilliseconds + $a.ms + 1500)
                                                        texto = 'Ya vuelvo a escucharte.'; total = $a.ms
                                                        tipo = 'sordina' })
                    Log "SORDINA: escucha apagada $([int]($a.ms / 60000)) min"
                }
                'cerrarTodo' {
                    $abiertas = @(Get-AppsAbiertas)
                    # EXCEPCIONES: "menos steam y discord". Cada una se resuelve a su
                    # proceso; si alguna no se sabe que es, NO se sigue: cerrar
                    # justo lo que querias conservar es el peor fallo de todos.
                    $excepto = if ((Test-Prop $a 'excepto') -or $a.ContainsKey('excepto')) { [string]$a.excepto } else { '' }
                    $noTocar = @()
                    $desconocida = ''
                    if ($excepto) {
                        foreach ($x in @($excepto -split '\s*(?:,|\by\b|\be\b)\s*' | Where-Object { $_ })) {
                            $px = Resolve-Proceso $x
                            if ($px -and $px.proceso -eq '*juego*' -and $script:juegoExe) { $noTocar += [System.IO.Path]::GetFileNameWithoutExtension($script:juegoExe) }
                            elseif ($px) { $noTocar += $px.proceso }
                            else { $desconocida = $x; break }
                        }
                    }
                    if ($desconocida) {
                        $a.desc = "no se que es '$desconocida', asi que no cierro nada"
                    } else {
                    if ($noTocar.Count -gt 0) { $abiertas = @($abiertas | Where-Object { $noTocar -notcontains $_.ProcessName }) }
                    # al confirmar se cierra LO QUE SE ANUNCIO, no lo que haya abierto
                    # en ese momento: lo que abras mientras contestas no entra
                    if ($script:confirmado -and $script:cerrarTodoPids) {
                        $abiertas = @($abiertas | Where-Object { $script:cerrarTodoPids -contains $_.Id })
                    }
                    if ($abiertas.Count -eq 0) {
                        $a.desc = 'no hay ningun programa abierto que cerrar'
                    } elseif (-not $script:confirmado) {
                        # Cerrar programas no se deshace, asi que NUNCA se hace a la
                        # primera: se dice en voz alta que se va a cerrar y se espera
                        # un si. El tipo 'peligrosa' hace ademas que callarse cancele,
                        # al reves que en el resto de confirmaciones.
                        $nombres = @($abiertas | ForEach-Object { if ($_.MainWindowTitle.Length -gt 40) { $_.ProcessName } else { $_.MainWindowTitle } } | Select-Object -Unique)
                        $script:cerrarTodoPids = @($abiertas | ForEach-Object { $_.Id })
                        $textoCT = if ($excepto) { "cierra todos los programas menos $excepto" } else { 'cierra todos los programas' }
                        $script:pendiente = @{ texto = $textoCT; vence = 0; tipo = 'peligrosa' }
                        $a.desc = 'voy a cerrar ' + $nombres.Count + ': ' + ($nombres -join ', ') + '. ¿Cierro?'
                    } else {
                        $script:cerrarTodoPids = $null
                        $cerradas = 0
                        foreach ($pr in $abiertas) {
                            # CloseMainWindow es la X de la ventana: si el programa
                            # tiene algo sin guardar, lo preguntara el. Nunca se mata
                            # a la fuerza aqui: perder trabajo por una orden mal oida
                            # seria el peor fallo posible de todo esto.
                            try { if ($pr.CloseMainWindow()) { $cerradas++ } } catch {}
                        }
                        $a.desc = "cerrados $cerradas de $($abiertas.Count)"
                    }
                    }
                }
                'estadoEscucha' {
                    if (-not $script:wakeProc -or $script:wakeProc.HasExited) {
                        $a.desc = 'la escucha por voz no esta funcionando ahora mismo; el boton si'
                    } else {
                        $g = 0.0; $alt = 0.0
                        # "como me oyes" tiene que contestar con lo de ahora, no con la
                        # medicion del worker anterior (ver Test-EstadoFresco). Con el
                        # estado rancio los dos quedan en 0, que es como decir "aun no lo
                        # se", y las frases de abajo se saltan solas.
                        if (Test-EstadoFresco) {
                            try {
                                $cul = [System.Globalization.CultureInfo]::InvariantCulture
                                $st = ([System.IO.File]::ReadAllText($RutaEstado).Trim()) -split '\|'
                                $g = [double]::Parse($st[0], $cul)
                                $alt = [double]::Parse($st[2], $cul)
                            } catch {}
                        }
                        $partes = @()
                        # lo primero, si hay ruido: es lo que mas explica que no le oiga
                        if (Get-OidoConRuido) {
                            $partes += 'ahora mismo entra un ruido de fondo constante y me esta tapando tu voz'
                        }
                        if ($script:pausaHasta -gt 0) {
                            $partes += 'ahora mismo no estoy escuchando, me pediste silencio; di escuchame para volver'
                        } elseif ($g -ge 6) {
                            $partes += "entras muy bajito: estoy amplificando el microfono $([int]$g) veces"
                        } elseif ($g -ge 2.5) {
                            $partes += "te oigo algo bajo, amplifico $([int]$g) veces"
                        } else {
                            $partes += 'el microfono entra bien'
                        }
                        if ($alt -gt 0.02) { $partes += 'y ahora suenan los altavoces, asi que desconfio de lo que oigo' }
                        try {
                            # LAS DOS CIFRAS DE LA MISMA FRASE, DE LA MISMA POBLACION (20/09):
                            # "despertado" salia de las activaciones por nombre y "no eran para
                            # mi" del ruido del dia entero, asi que el 18/09 habria dicho 27 y
                            # 31. Ver Get-FalsasAlarmas.
                            $faE = Get-FalsasAlarmas
                            $diaE = Get-Date -Format 'yyyy-MM-dd'
                            if ($faE.ContainsKey($diaE)) {
                                $actE = [int]$faE[$diaE].act; $nadaE = [int]$faE[$diaE].nada
                                if ($actE -gt 0) { $partes += "hoy me has despertado $actE veces y $nadaE no eran para mi" }
                            }
                        } catch {}
                        $a.desc = ($partes -join ', ')
                    }
                }
                'discoFactura' {
                    $fac = @(Get-FacturaDisco)
                    $libreF = 0.0
                    try { $libreF = [Math]::Round((New-Object System.IO.DriveInfo('C')).AvailableFreeSpace / 1GB, 1) } catch {}
                    if ($fac.Count -eq 0) {
                        $a.desc = "te quedan $libreF gigas y no veo caches que soltar"
                    } else {
                        $trozos = @($fac | Select-Object -First 3 | ForEach-Object { "$($_.nombre), $($_.mb) megas" })
                        $totalF = [Math]::Round((@($fac | ForEach-Object { $_.mb }) | Measure-Object -Sum).Sum, 0)
                        $a.desc = "te quedan $libreF gigas. Lo que puedo soltar: " + ($trozos -join '; ') +
                                  ". En total unos $totalF megas. Di: limpia el disco"
                    }
                }
                'discoLimpia' {
                    # SE PREGUNTA ANTES, como todo lo que borra (ver $AccionesQueTocan): esto
                    # no deshace nada. Y lo que se borra es solo lo que el sistema regenera.
                    if (-not $script:confirmado) {
                        $facC = @(Get-FacturaDisco)
                        $totC = [Math]::Round((@($facC | ForEach-Object { $_.mb }) | Measure-Object -Sum).Sum, 0)
                        if ($facC.Count -eq 0) { $a.desc = 'no hay caches que soltar'; break }
                        $script:pendiente = @{ texto = 'limpia el disco'; vence = 0; tipo = 'peligrosa' }
                        $a.desc = "voy a borrar " + ($facC.nombre -join ', ') + ", unos $totC megas. ¿Lo hago?"
                    } else {
                        $res = Clear-CachesDisco
                        Log "DISCO: limpiado; $($res.antes) -> $($res.despues) GB ($($res.tocadas) elementos)"
                        Add-Estadistica 'disco-limpia' ([string]$res.soltado)
                        $a.desc = if ($res.soltado -ge 0.1) {
                            "te he soltado " + $res.soltado + " gigas; ahora tienes " + $res.despues
                        } else {
                            "no he podido soltar casi nada; sigues con " + $res.despues + " gigas"
                        }
                    }
                }
                'perfilLimpia' {
                    $par = Get-ParParecidoPerfil
                    if (-not $par) {
                        $a.desc = 'no veo nada repetido en lo que se de ti'
                    } else {
                        # SE PREGUNTA, NO SE DECIDE: lo que hay en su perfil es suyo.
                        # Y NO POR EL CANAL DE SI/NO (revision del 23/09): ese canal solo
                        # transporta si o no -confirmacion.txt esta filtrado a ^(si|no)$, el
                        # oido entra en gramatica cerrada de si/no, y el mando manda si/no-,
                        # asi que "la primera" no llegaba NUNCA y toda respuesta acababa en
                        # "no te he entendido, las dejo las dos". La funcion no se podia
                        # completar. Esto es una lista cerrada de dos: va por donde van las
                        # listas cerradas.
                        $script:perfilPar = @{ a = $par.a; b = $par.b
                                               hasta = $sw.ElapsedMilliseconds + 60000 }
                        [void](Open-Eleccion @($par.a, $par.b) 'perfil')
                        $a.desc = 'tengo dos cosas parecidas: ' + $par.a + '; y ' + $par.b +
                                  '. ¿Me quedo con la primera o con la segunda?'
                    }
                }
                'perfilElige' { $a.desc = (Resolve-PerfilPar ([int]$a.cual)) }
                'recordar' {
                    # va al worker de la charla, que es quien tiene los vectores. Si no
                    # contesta o no encuentra nada, se dice y punto: nada de inventar.
                    if (-not $ConversacionOn) { $a.desc = 'no tengo la memoria encendida' }
                    else {
                        $script:recuerdoPide = $a.tema
                        $okR = $false
                        try { $okR = [bool](Send-CharlaPedido @{ op = 'recordar'; id = 0; texto = $a.tema } $false) } catch {}
                        if ($okR) {
                            $a.desc = ''      # contesta el evento 'recuerdo' cuando llegue
                            $script:respuestaSinTarjeta = $true
                        } else { $a.desc = 'ahora mismo no puedo mirar mi memoria' }
                    }
                }
                'montajeGuarda' {
                    if (-not $script:ultimoDividir) {
                        $a.desc = 'primero divide la pantalla y luego te lo guardo'
                    } else {
                        $mm = Get-Montajes
                        $mm[$a.nombre] = @{
                            izq = $script:ultimoDividir.izq; der = $script:ultimoDividir.der
                            izqTipo = $script:ultimoDividir.izqTipo; derTipo = $script:ultimoDividir.derTipo
                            cuando = (Get-Date).ToString('s')
                        }
                        Save-Montajes
                        Log "MONTAJE guardado: '$($a.nombre)' = $($mm[$a.nombre].izq) | $($mm[$a.nombre].der)"
                        Add-Estadistica 'montaje-guarda' $a.nombre
                        Set-AcabaDeAprender
                        $a.desc = 'guardado. Dime "pon ' + $a.nombre + '" cuando lo quieras'
                    }
                }
                'montajePon' {
                    $mo = (Get-Montajes)[$a.nombre]
                    if (-not $mo) {
                        $a.desc = 'no tengo ningun montaje con ese nombre'
                    } else {
                        $antesM = [AX]::GetForegroundWindow()
                        $puestas = 0
                        foreach ($lado in @(@{ q = $mo.izq; t = $mo.izqTipo; vk = 0x25 },
                                            @{ q = $mo.der; t = $mo.derTipo; vk = 0x27 })) {
                            if (-not (Show-OAbrir $lado.t $lado.q)) { continue }
                            $t0M = $sw.ElapsedMilliseconds
                            $vino = $false
                            while (($sw.ElapsedMilliseconds - $t0M) -lt 4000) {
                                Start-Sleep -Milliseconds 200
                                $hM = [AX]::GetForegroundWindow()
                                if ($hM -ne [IntPtr]::Zero -and $hM -ne $antesM) { $vino = $true; break }
                            }
                            if ($vino) {
                                Start-Sleep -Milliseconds 350
                                Send-WinKey $lado.vk
                                $puestas++
                                Start-Sleep -Milliseconds 400
                                $antesM = [AX]::GetForegroundWindow()
                            }
                        }
                        Log "MONTAJE puesto: '$($a.nombre)' ($puestas de 2)"
                        Add-Estadistica 'montaje-pon' $a.nombre
                        $a.desc = if ($puestas -eq 2) { 'montado' } else { "monte $puestas de las dos; la otra no llego" }
                    }
                }
                'montajesLista' {
                    $lm = @((Get-Montajes).Keys)
                    $a.desc = if ($lm.Count -eq 0) { 'no tienes ningun montaje guardado' }
                              elseif ($lm.Count -eq 1) { 'solo uno: ' + $lm[0] }
                              else { 'tienes ' + $lm.Count + ': ' + ($lm -join ', ') }
                }
                'montajeBorra' {
                    $mb = Get-Montajes
                    if ($mb.ContainsKey($a.nombre)) {
                        $mb.Remove($a.nombre); Save-Montajes
                        Log "MONTAJE borrado: '$($a.nombre)'"
                        $a.desc = 'borrado'
                    } else { $a.desc = 'no tengo ningun montaje con ese nombre' }
                }
                'palabraNo' {
                    # LA LISTA ES CORTA A PROPOSITO (23/09, funcion 2). Con el oido al 70,4 %,
                    # un "no digas X" mal entendido podria vetar una palabra corriente y dejar
                    # a Nova muda a medias. Tope de cinco, y solo palabras que ELLA haya dicho
                    # alguna vez: si no la ha dicho nunca, lo mas probable es que el oido se
                    # haya inventado el nombre.
                    $listaPN = @(Get-PalabrasNo)
                    if ($listaPN -contains $a.palabra) {
                        $a.desc = 'esa ya no la digo'
                    } elseif ($listaPN.Count -ge 5) {
                        $a.desc = 'ya tengo cinco palabras prohibidas; quitame alguna antes'
                    } else {
                        Save-PalabrasNo (@($listaPN) + @($a.palabra))
                        Log "PALABRA PROHIBIDA: '$($a.palabra)' (van $(@(Get-PalabrasNo).Count))"
                        Add-Estadistica 'palabra-no' $a.palabra
                        Set-AcabaDeAprender
                        $a.desc = 'vale, no te lo digo mas'
                    }
                }
                'palabraSi' {
                    Save-PalabrasNo (@(Get-PalabrasNo) | Where-Object { $_ -ne $a.palabra })
                    Log "PALABRA DEVUELTA: '$($a.palabra)'"
                    $a.desc = 'te la devuelvo'
                }
                'palabrasLista' {
                    $lp = @(Get-PalabrasNo)
                    $a.desc = if ($lp.Count -eq 0) { 'no tengo ninguna palabra prohibida' }
                              elseif ($lp.Count -eq 1) { 'solo una: ' + $lp[0] }
                              else { 'no digo ' + $lp.Count + ': ' + ($lp -join ', ') }
                }
                'despertarEscucha' {
                    Reanudar-Escucha
                    $script:sordinaHasta = 0
                    # y se retira el aviso de vuelta: ya no hace falta
                    for ($i = $script:temporizadores.Count - 1; $i -ge 0; $i--) {
                        if ($script:temporizadores[$i].tipo -eq 'sordina') { $script:temporizadores.RemoveAt($i) }
                    }
                    Log 'SORDINA: cancelada a mano'
                }
                'zombis' {
                    $z = @(Get-JuegosZombis)
                    if ($z.Count -eq 0) {
                        $a.desc = 'no hay ningun juego colgado'
                    } elseif (-not $script:confirmado) {
                        # cerrar un juego pierde lo no guardado: nunca a la primera
                        $lista = @($z | ForEach-Object {
                            $h = [int]($_.minutos / 60); $m = $_.minutos % 60
                            $cuanto = if ($h -gt 0) { "$h horas" } else { "$m minutos" }
                            "$($_.nombre), abierto desde hace $cuanto"
                        })
                        $script:pendiente = @{ texto = 'cierra los juegos colgados'; vence = 0; tipo = 'peligrosa' }
                        $a.desc = 'sin ventana pero gastando procesador: ' + ($lista -join '; ') + '. ¿Lo cierro?'
                    } else {
                        $n = 0
                        foreach ($x in $z) {
                            # colgado quiere decir que no responde: CloseMainWindow no
                            # sirve (no hay ventana) y el cierre suave se ignora, asi
                            # que aqui si hay que forzarlo. Por eso se pregunta antes.
                            try { $x.proc.Kill(); $n++ } catch {}
                            $script:zombisAvisados.Remove($x.proc.Id)
                        }
                        $a.desc = if ($n -eq 1) { "cerrado $($z[0].nombre)" } else { "cerrados $n juegos colgados" }
                    }
                }
                'cerrarApp' {
                    $ps = @(Get-Process -Name $a.proceso -ErrorAction SilentlyContinue)
                    if ($ps.Count -eq 0) { $a.desc = "$($a.desc): no estaba abierta" }
                    else {
                        # Se le da el momento de cerrarse bien, igual que a los
                        # juegos. Matar de golpe una app que tiene algo sin
                        # guardar es el peor final posible para una orden mal
                        # oida, y aqui se hacia sin esperar nada.
                        # UNA SOLA ESPERA PARA TODOS (15/09): "cierra el navegador" tardo 20 s. El
                        # navegador tiene muchos procesos sin ventana, CloseMainWindow da $false en
                        # cada uno y se esperaban 1,5 s por CADA uno. Ahora se pide cerrar a los que
                        # tienen ventana, se espera una vez (hasta 1,5 s) y se mata lo que siga. Si
                        # ninguno tiene ventana (en la bandeja), se mata como antes, sin esperar.
                        $conVentana = @($ps | Where-Object { try { $_.MainWindowHandle -ne [IntPtr]::Zero } catch { $false } })
                        if ($conVentana.Count -eq 0) {
                            foreach ($pr in $ps) { try { if (-not $pr.HasExited) { $pr.Kill() } } catch {} }
                        } else {
                            foreach ($pr in $conVentana) { try { [void]$pr.CloseMainWindow() } catch {} }
                            $hastaC = [DateTime]::Now.AddMilliseconds(1500)
                            while ([DateTime]::Now -lt $hastaC -and @($conVentana | Where-Object { try { -not $_.HasExited } catch { $false } }).Count -gt 0) {
                                Start-Sleep -Milliseconds 100
                            }
                            foreach ($pr in $conVentana) { try { if (-not $pr.HasExited) { $pr.Kill() } } catch {} }
                        }
                    }
                }
                'cerrarJuego' {
                    # CON NOMBRE: "cierra elden ring". Si el que esta abierto es otro, se
                    # dice y no se toca nada: cerrar el juego equivocado es de los errores
                    # que no se perdonan. Sin nombre ("cierra el juego") sigue igual que antes.
                    if ($a.juego -and (-not $script:juegoActivo -or (ConvertTo-Plain $a.juego) -ne (ConvertTo-Plain $script:juegoActivo))) {
                        $a.desc = if ($script:juegoActivo) { "$($a.juego) no esta abierto; el que esta es $($script:juegoActivo)" } else { "$($a.juego) no esta abierto" }
                    } elseif ($script:juegoActivo -and $script:juegoExe) {
                        $ps = @(Get-Process | Where-Object { try { $_.Path -eq $script:juegoExe } catch { $false } })
                        foreach ($pr in $ps) { try { if (-not $pr.CloseMainWindow()) { Start-Sleep -Milliseconds 1500; if (-not $pr.HasExited) { $pr.Kill() } } } catch {} }
                        $a.desc = "cerrando $($script:juegoActivo)"
                    } else { $a.desc = 'no hay ningun juego abierto' }
                }
                'ventanaApp' {
                    # NO se toca el foco en ningun caso: ShowWindow con
                    # SW_MINIMIZE / SW_MAXIMIZE / SW_RESTORE no activa la
                    # ventana, y para mover se usa SetWindowPos con NOACTIVATE.
                    # Todo el sentido de esto es no salir del juego.
                    $pv = Get-Process -Name $a.proceso -ErrorAction SilentlyContinue |
                          Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
                    if (-not $pv) {
                        $a.desc = "$($a.desc): no esta abierta"
                    } else {
                        $hw = $pv.MainWindowHandle
                        switch ($a.accion) {
                            'minimizar' { [void][AX]::ShowWindow($hw, 6) }    # SW_MINIMIZE
                            'maximizar' { [void][AX]::ShowWindow($hw, 3) }    # SW_MAXIMIZE
                            'restaurar' { [void][AX]::ShowWindow($hw, 9) }    # SW_RESTORE
                            'otroMonitor' {
                                $pantallas = @([System.Windows.Forms.Screen]::AllScreens)
                                if ($pantallas.Count -lt 2) {
                                    # decirlo, en vez de mover la ventana al vacio:
                                    # es el mismo criterio que "mandala al otro
                                    # monitor" sobre la ventana con foco
                                    $a.desc = 'solo tienes una pantalla'
                                } else {
                                    $r = New-Object AX+RECT
                                    if (-not [AX]::GetWindowRect($hw, [ref]$r)) {
                                        $a.desc = "$($a.desc): no pude leer donde esta"
                                    } else {
                                        # una ventana maximizada no se puede mover:
                                        # hay que restaurarla antes y volver a
                                        # maximizarla en la pantalla nueva
                                        $estabaMax = ($pv.MainWindowHandle -ne 0) -and ([AX]::GetWindowLong($hw, -16) -band 0x01000000)
                                        if ($estabaMax) { [void][AX]::ShowWindow($hw, 9); Start-Sleep -Milliseconds 120; [void][AX]::GetWindowRect($hw, [ref]$r) }
                                        $cx = ($r.Left + $r.Right) / 2; $cy = ($r.Top + $r.Bottom) / 2
                                        $actual = $pantallas | Where-Object { $_.Bounds.Contains([int]$cx, [int]$cy) } | Select-Object -First 1
                                        if (-not $actual) { $actual = $pantallas[0] }
                                        $i = [Array]::IndexOf($pantallas, $actual)
                                        $destino = $pantallas[($i + 1) % $pantallas.Count]
                                        # se conserva el tamano y la posicion RELATIVA
                                        # dentro de la pantalla: una ventana que
                                        # estaba arriba a la izquierda sigue estando
                                        # arriba a la izquierda en la otra
                                        $nx = $destino.WorkingArea.X + ($r.Left - $actual.WorkingArea.X)
                                        $ny = $destino.WorkingArea.Y + ($r.Top - $actual.WorkingArea.Y)
                                        $anchoV = $r.Right - $r.Left; $altoV = $r.Bottom - $r.Top
                                        # y que no se salga de la pantalla de destino
                                        $nx = [Math]::Max($destino.WorkingArea.X, [Math]::Min($nx, $destino.WorkingArea.Right - $anchoV))
                                        $ny = [Math]::Max($destino.WorkingArea.Y, [Math]::Min($ny, $destino.WorkingArea.Bottom - $altoV))
                                        $SWP_NOACTIVATE = 0x0010; $SWP_NOZORDER = 0x0004
                                        [void][AX]::SetWindowPos($hw, [IntPtr]::Zero, [int]$nx, [int]$ny, $anchoV, $altoV, ($SWP_NOACTIVATE -bor $SWP_NOZORDER))
                                        if ($estabaMax) { Start-Sleep -Milliseconds 120; [void][AX]::ShowWindow($hw, 3) }
                                    }
                                }
                            }
                        }
                    }
                }
                'enfocar' {
                    $pr = Get-Process -Name $a.proceso -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | Select-Object -First 1
                    if ($pr) {
                        [AX]::ShowWindow($pr.MainWindowHandle, 9) | Out-Null   # SW_RESTORE por si esta minimizada
                        [void][AX]::ForceForeground($pr.MainWindowHandle)
                    } else { $a.desc = "$($a.desc): no esta abierta" }
                }
                'enfocarJuego' {
                    $pr = Get-Process | Where-Object { try { $_.Path -eq $script:juegoExe -and $_.MainWindowHandle -ne 0 } catch { $false } } | Select-Object -First 1
                    if ($pr) { [AX]::ShowWindow($pr.MainWindowHandle, 9) | Out-Null; [void][AX]::ForceForeground($pr.MainWindowHandle) }
                }
                'lupa' {
                    # ENSEÑAR EN VEZ DE RECITAR (23/09, funcion 8). Mismo recorte que 'ocr',
                    # pero sin pasar por el OCR: el texto lo lee braya. Nova no dice ni una
                    # palabra de lo que pone, asi que no puede equivocarse al decirlo.
                    $dondeL = if ($a.zonaTxt) { [string]$a.zonaTxt } else { 'la pantalla' }
                    Set-UI 'pensando' "ampliando $dondeL"
                    $pngL = Join-Path $TmpDir 'lupa.png'
                    Close-Lupa      # si no, la segunda lupa saldria con la primera dentro
                    Save-Captura $pngL ([string]$a.zona) | Out-Null
                    if (Show-Lupa $pngL) {
                        Log "LUPA: $dondeL"
                        Add-Estadistica 'lupa' ([string]$a.zona)
                        $a.desc = "ahi lo tienes, di quita la lupa cuando acabes"
                    } else {
                        $a.desc = 'no he podido hacer la captura'
                    }
                }
                'lupaQuita' {
                    $a.desc = if ($script:lupaForm) { 'quitada' } else { 'no habia ninguna lupa' }
                    Close-Lupa
                }
                'ocr' {
                    # Sin zona, la pantalla entera de siempre. Con zona (C15, 20/09) se
                    # captura SOLO ese trozo, que es menos trabajo que antes: leer una
                    # esquina nunca puede tardar más que leerlo todo.
                    $zonaOcr = [string]$a.zona
                    $texto0Ocr = [string]$script:jobTextoOriginal
                    $dondeOcr = if ($a.zonaTxt) { [string]$a.zonaTxt } else { 'la pantalla' }
                    Set-UI 'pensando' "leyendo $dondeOcr"
                    $png = Join-Path $TmpDir 'pantalla.png'
                    Save-Captura $png $zonaOcr | Out-Null
                    $texto = Invoke-OCR $png
                    if (-not $texto) { $a.desc = "No veo texto en $dondeOcr" }
                    else {
                        try { [System.IO.File]::WriteAllText((Join-Path $TmpDir 'ocr.txt'), $texto, (New-Object System.Text.UTF8Encoding($false))) } catch {}
                        $script:ultimaLectura = $texto
                        # Y LA POSICION VUELVE A CERO CON EL TEXTO (21/09). Texto nuevo, lectura
                        # nueva. Esto faltaba y el agujero estaba justo debajo: cuando la frase
                        # pide que te lo CUENTE, se le pasa al modelo y se sale con un 'break'
                        # sin llegar a la linea que pone lecturaPos. O sea que ultimaLectura ya
                        # era el texto nuevo y lecturaPos seguia siendo la de la pantalla
                        # anterior: 'sigue leyendo' se saltaba un trozo del tamano de la lectura
                        # de antes, o contestaba 'ya no queda mas' con la pantalla sin leer.
                        $script:lecturaPos = 0
                        # SI PEDISTE QUE TE LO CUENTE, NO SE RECITA (21/09). El texto de un
                        # HUD de juego leido letra a letra no le dice nada a nadie: la
                        # noche del 20/09, a "cuentame que ves", Nova solto "O Codigo de
                        # union. la ultima parada. Inspeccionar. Soltar objeto. Kit". Se le
                        # pasa al modelo lo leido para que lo cuente en una frase.
                        # Si la charla esta apagada se recita, que es mejor que callarse.
                        if ($a.interpretar -and $ConversacionOn) {
                            $pregOcr = "Esto es lo que se lee ahora mismo en la pantalla de braya, sacado con OCR: <<$texto>>. " +
                                       "Cuentale en UNA frase que esta pasando, con sus palabras, sin leerle el texto tal cual " +
                                       "y sin inventarte nada que no este ahi. El te dijo: '" + $texto0Ocr + "'."
                            # lo que se lee en la pantalla es de quien la escribio (ver Send-Charla)
                            if (Send-Charla $pregOcr $false 'hablar' $null $true) {
                                $a.desc = ''
                                Set-UI 'pensando' 'mirando la pantalla'
                                break
                            }
                        }
                        $trozo = Get-Trozo $texto 0
                        $script:lecturaPos = $trozo.fin
                        $a.desc = $trozo.texto + $(if ($trozo.fin -lt $texto.Length) { ' ... Di "sigue leyendo" para el resto.' } else { '' })
                    }
                }
                'seguirLeyendo' {
                    if (-not $script:ultimaLectura) {
                        $a.desc = 'no he leido nada todavia'
                    } elseif ($script:lecturaPos -ge $script:ultimaLectura.Length) {
                        $a.desc = 'ya no queda mas'
                    } else {
                        $trozo = Get-Trozo $script:ultimaLectura $script:lecturaPos
                        $script:lecturaPos = $trozo.fin
                        $a.desc = $trozo.texto + $(if ($trozo.fin -lt $script:ultimaLectura.Length) { ' ... y sigue.' } else { '' })
                    }
                }
                'ocrMemoria' {
                    Set-UI 'pensando' 'leyendo la pantalla'
                    $png = Join-Path $TmpDir 'pantalla.png'
                    Save-Captura $png | Out-Null
                    $texto = Invoke-OCR $png
                    if (-not $texto) {
                        # ver EL OCR VACIO NO ES "NO VEO NADA": aqui tambien, con la captura
                        # ya hecha, se manda la imagen antes de decir que no se ve nada.
                        $script:respuestaSinTarjeta = $true
                        Submit-Command ("Mira esta captura de lo que tengo delante y contesta a lo que te pido en una o dos frases cortas y naturales, porque se leera en voz alta. Lo que te pido: " + $text) 'pregunta' $png
                        return $null
                    } else {
                        $script:ultimaLectura = $texto
                        $script:lecturaPos = 0        # texto nuevo, lectura nueva (21/09)
                        # una pantalla viene en muchas lineas y en una nota de diario
                        # eso queda ilegible: se junta todo en una sola
                        $limpio = (($texto -replace '[\r\n]+', ' / ') -replace '\s{2,}', ' ').Trim()
                        if ($limpio.Length -gt 600) { $limpio = $limpio.Substring(0, 600) + ' [...]' }
                        # de donde salio: sin esto, meses despues es un texto
                        # huerfano en el diario y no hay forma de situarlo
                        $donde = if ($script:juegoActivo) { $script:juegoActivo } else { 'la pantalla' }
                        $null = Add-Memoria ("(de $donde) " + $limpio)
                        Log "OCR A MEMORIA ($donde): $limpio"
                        # se lee el principio: asi sabes QUE guardo, y si el OCR ha
                        # leido mal te enteras al momento y no meses despues
                        $ojo = if ($limpio.Length -gt 90) { $limpio.Substring(0, 90) + "..." } else { $limpio }
                        $a.desc = "Apuntado: $ojo"
                    }
                }
                'buscarEquipo' {
                    Send-WinKey 0x53   # Win+S
                    Start-Sleep -Milliseconds 700
                    [System.Windows.Forms.SendKeys]::SendWait(([regex]::Replace($a.texto, '[+^%~(){}\[\]]', { param($m) '{' + $m.Value + '}' })))
                }
            }
            # ¿DE VERDAD SE HIZO? (18/09). Aqui la accion ya se ejecuto y $a.desc es lo que
            # Nova va a decir en voz alta. Si el efecto no cuadra, lo peor seria presumir:
            # se reintenta una vez, y si sigue sin cuadrar se dice la verdad y se apunta.
            $efecto = Test-EfectoAccion $a
            if ($null -ne $efecto -and -not $efecto.ok) {
                Log ("EFECTO: $($a.kind) pedia $($efecto.esperado) y quedo en $($efecto.real); lo intento otra vez")
                if (Invoke-AccionOtraVez $a) {
                    Start-Sleep -Milliseconds 120
                    $efecto = Test-EfectoAccion $a
                }
            }
            if ($null -ne $efecto -and -not $efecto.ok) {
                Log ("NO SURTIO EFECTO: $($a.kind) pedia $($efecto.esperado) y se quedo en $($efecto.real)")
                Add-Estadistica 'no-surtio-efecto' "$($a.kind): pedi $($efecto.esperado) y quedo en $($efecto.real)"
                $a.desc = "lo intente dos veces y no se puso: se quedo en $($efecto.real)"
                Set-UICola $acciones.Count ($iAcc + 1) $true
            }
            $hechas += $a.desc
        } catch {
            $hechas += ($a.desc + " [FALLO: " + $_.Exception.Message + "]")
            # que se vea CUAL fallo, no solo que algo fallo
            Set-UICola $acciones.Count ($iAcc + 1) $true
            Start-Sleep -Milliseconds 400
        }
        # solo si esta accion toco el sistema Y queda alguna por hacer
        if ($iAcc -lt ($acciones.Count - 1) -and $RESPIRO -contains $a.kind) {
            Start-Sleep -Milliseconds 250
        }
    }
    Set-UIHaciendo ''
    Set-UICola 0 0
    return ($hechas -join '; ')
}

# =====================================================================
# VOZ (TTS). Se usa el motor MODERNO de Windows (WinRT), no System.Speech:
# System.Speech solo ve las voces SAPI5 viejas ("Helena Desktop"), mientras
# que WinRT ve las OneCore y, si se instalan, las "Natural" (neuronales),
# que son las unicas que suenan humanas. La preferencia esta ordenada para
# coger automaticamente la mejor disponible sin tocar codigo.
# =====================================================================
$VozOn = [bool](Get-Cfg 'voz' 'activada' $true)
$VozPref = @(Get-Cfg 'voz' 'preferencia' @('Natural', 'es-MX', 'es-'))
$script:vozSyn = $null
$script:vozAwait = $null
$script:vozPlayer = $null

# --- Voz EN LINEA (edge-tts): la de mejor calidad ---
# El worker de Python se mantiene VIVO: arrancarlo por frase costaba 2,5-4,4 s.
# Ademas cachea por hash, asi que una frase repetida ("Anotado.") sale en 2 ms.
$VozMotor = [string](Get-Cfg 'voz' 'motor' 'online')
$VozOnlineNombre = [string](Get-Cfg 'voz' 'vozOnline' 'es-MX-DaliaNeural')
$PyExe = [string](Get-Cfg 'paths' 'python' "$env:LOCALAPPDATA\Programs\Python\Python312\python.exe")
# LOS WORKERS, CON pythonw (14/09): con python.exe cada uno abria su conhost.exe (una
# consola oculta, 3-5 procesos y ~40 MB medidos en vivo). pythonw no abre consola y
# las tuberias funcionan igual. Si no esta, se sigue con python.exe.
$PyWorker = $PyExe
try {
    $pyw = Join-Path (Split-Path -Parent $PyExe) 'pythonw.exe'
    if (Test-Path -LiteralPath $pyw) { $PyWorker = $pyw }
} catch {}
$TtsWorker = Join-Path $LogDir "tts_worker.py"
# LO QUE NO ARRANCO (17/09). Nova ya comprueba sus piezas al arrancar -si falta wake_vosk.py,
# nova_ui.exe, commands.json o el CLI del agente- pero todas esas comprobaciones mueren en el
# log, donde nadie las ve: arrancaba a medias, saludaba igual y ya te enterarias cuando algo
# no funcionase.
#
# Esto NO anade comprobaciones nuevas: recoge las que ya hay y las cuenta en el saludo, que
# existe justo para eso (linea ~97: "saludo hablado al arrancar: confirma que la voz
# funciona"). Si todo esta bien, el saludo es el de siempre.
$script:fallosArranque = New-Object System.Collections.ArrayList
function Add-FalloArranque([string]$que) {
    if (-not $que) { return }
    if ($script:fallosArranque -contains $que) { return }
    [void]$script:fallosArranque.Add($que)
}

$VozCache = Join-Path $TmpDir "voz"
$script:ttsProc = $null
# la lectura pendiente sobre la tuberia del worker de voz, y si la que llega es de la
# frase anterior (ver UNA SOLA LECTURA VIVA SOBRE LA TUBERIA, en Say-Online)
$script:ttsLectura = $null
$script:ttsTardia = $false

# --- REPRODUCCION DE AUDIO ---
# Se usa MediaPlayer de WPF, NO MCI. MCI informaba 'playing' y la posicion
# avanzaba, pero en esta maquina no llegaba a los altavoces: el asistente
# "hablaba" en silencio. MediaPlayer es el metodo con el que el usuario SI
# escucho las pruebas de voz, asi que esta comprobado que suena aqui.
$script:reproductor = $null
# EL MP3 ABIERTO ANTES DE HABLAR (22/09). El reproductor de repuesto: aqui se deja
# cargado el audio de la frase QUE VIENE, para que Play() no pague el medio segundo de
# Open(). El porque, con los numeros, esta en Open-VozAdelantada (mas abajo).
$script:reproductorPrevio = $null
$script:preVozRuta = ''      # el mp3 que ESTA abierto en el de repuesto ('' = ninguno)
$script:preVozDesde = 0      # cuando se abrio, para poder medir el adelanto en el log
$script:preVozTexto = ''     # la frase de la cabeza de la cola, para no rehacer el md5 cada vuelta
$script:preVozCalc = ''      # su ruta calculada
$script:preVozMd5 = $null

function Play-Audio([string]$ruta) {
    if (-not (Test-Path -LiteralPath $ruta)) { return $false }
    # AQUI y no en Say (ver HACERSE SITIO PARA HABLAR): Say tiene cinco salidas antes de que
    # suene nada -la llamada entrante, la voz en linea, la tardia, Piper y el "no hay voz
    # disponible"-, y bajando arriba del todo una llamada dejaria el juego bajado entera.
    Push-VolumenJuego
    try {
        if (-not $script:reproductor) {
            Add-Type -AssemblyName PresentationCore -ErrorAction Stop
            $script:reproductor = New-Object System.Windows.Media.MediaPlayer
            # (ver EL CUARTO DE SEGUNDO QUE SE PAGABA EN CADA FRASE, mas abajo)
        }
        # EL MP3 ABIERTO ANTES DE HABLAR (22/09). Si Open-VozAdelantada ya cargo ESTE
        # mismo mp3 en el reproductor de repuesto, aqui no hay nada que abrir: se cambian
        # los dos de sitio y Play() suena en 31 ms en vez de 464 (medido, 120 medidas).
        # Se compara con la ruta que DEVOLVIO el worker, no con la calculada: si el md5 de
        # aqui y el de tts_worker.py se separasen algun dia, esto simplemente no acierta y
        # se abre como siempre. Lo peor que puede pasar es no ganar los 433 ms; nunca
        # puede sonar otra frase.
        # El cambio de sitio importa: $script:reproductor tiene que seguir siendo SIEMPRE
        # el que suena, porque es al que paran "callate", el dictado y el cierre limpio.
        if ($ruta -eq $script:preVozRuta -and $script:reproductorPrevio) {
            $otroRep = $script:reproductor
            $script:reproductor = $script:reproductorPrevio
            $script:reproductorPrevio = $otroRep
            # y el que sale se calla A MANO: con un solo reproductor, Open() cortaba el
            # solo la frase anterior; con dos, si no se para, se oirian las dos a la vez.
            # Close() ademas suelta el mp3, para que la poda de la cache pueda borrarlo.
            if ($script:reproductorPrevio) {
                try { $script:reproductorPrevio.Stop() } catch {}
                try { $script:reproductorPrevio.Close() } catch {}
            }
            Log ("voz: el mp3 ya estaba abierto, " + ($sw.ElapsedMilliseconds - $script:preVozDesde) + " ms antes de decirla")
            $script:preVozRuta = ''
        } else {
            $script:reproductor.Open([Uri]$ruta)
        }
        # DE NOCHE, MAS BAJITO (13/09): de 22:00 a 7:00 la voz suena al 55 %. Solo
        # la voz en linea: Piper (el respaldo sin internet) va por SoundPlayer,
        # que no tiene volumen.
        $horaV = (Get-Date).Hour
        $script:reproductor.Volume = if ($horaV -ge 22 -or $horaV -lt 7) { 0.55 } else { 1.0 }
        # EL CUARTO DE SEGUNDO QUE SE PAGABA EN CADA FRASE (17/09). Aqui habia un
        # Start-Sleep de 250 ms fijo, EN EL HILO DEL BUCLE, con el motivo "Open es
        # asincrono: sin esta pausa Play() no encuentra nada cargado". En el log de braya
        # son 202 frases = 50,5 s de bucle congelado, y la mitad eran frases ya
        # preparadas que llegaban en milisegundos y pagaban el cuarto de segundo igual.
        #
        # Medido en esta maquina, y por eso se quita del todo:
        #   - Open() tarda 453-547 ms en estar listo, SIEMPRE. O sea que los 250 ms no
        #     llegaban ni al peor caso: Play() ya se llamaba sobre un audio a medio cargar.
        #   - Y aun asi sonaba, porque Play() sobre un MediaPlayer que sigue cargando NO
        #     se pierde: queda encolado y arranca solo al terminar. Comprobado llamandolo
        #     inmediatamente: la posicion empezo a avanzar a los 513 ms, igual que con
        #     pausa. La pausa solo servia para congelar el bucle.
        #   - MediaOpened NO sirve aqui (era la mejora propuesta): en un script de
        #     PowerShell no hay bucle de mensajes WPF y el evento no llega NUNCA (probado,
        #     ni en 2 s). Sondear NaturalDuration tampoco: tarda 543 ms.
        $script:reproductor.Play()
        return $true
    } catch {
        Log ("reproduccion fallida, probando MCI: " + $_.Exception.Message)
        try { [AX]::PlayMp3($ruta); return $true } catch { return $false }
    }
}

function Initialize-Online {
    if (-not (Test-Path -LiteralPath $PyExe) -or -not (Test-Path -LiteralPath $TtsWorker)) { return $false }
    try {
        if (-not (Test-Path -LiteralPath $VozCache)) { New-Item -ItemType Directory -Force -Path $VozCache | Out-Null }
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $PyWorker
        $psi.Arguments = "-u `"$TtsWorker`" $VozOnlineNombre `"$VozCache`""
        $psi.UseShellExecute = $false
        $psi.RedirectStandardInput = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = $LogDir
        $script:ttsProc = [System.Diagnostics.Process]::Start($psi)
        Log "voz: $VozOnlineNombre (neuronal en linea) PID=$($script:ttsProc.Id)"
        return $true
    } catch {
        Log ("WARN: voz en linea no arranco: " + $_.Exception.Message)
        $script:ttsProc = $null
        return $false
    }
}

function Say-Online([string]$texto, [string]$emo = '') {
    if (-not $script:ttsProc -or $script:ttsProc.HasExited) {
        # si murio, que el log diga POR QUE: su stderr se guardaba y nadie lo leia
        if ($script:ttsProc) {
            try {
                $err = $script:ttsProc.StandardError.ReadToEnd()
                if ($err) { Log ("voz online: el worker murio con: " + (($err -replace '\s+', ' ').Trim())) }
                $script:ttsProc.Dispose()
            } catch {}
            $script:ttsProc = $null
            # el worker nuevo trae una tuberia nueva: la lectura pendiente del anterior
            # ya no sirve y dejarla apuntada la colgaria de un flujo muerto
            $script:ttsLectura = $null
        }
        # sin Start-Sleep (14/09): congelaba el bucle 2 s. El worker lee la frase de
        # la tuberia en cuanto arranca, y la espera de abajo ya tiene su plazo de 8 s
        if (-not (Initialize-Online)) { return $false }
    }
    try {
        # Bytes UTF-8 directos al flujo. .NET Framework no deja fijar la
        # codificacion de StandardInput y en la consola oculta usaba IBM850:
        # cada tilde o "¿" mataba al worker (surrogate en el md5). Verificado.
        # VOZ CON EMOCION (M6): "{emo:alegre} ..." o "{emo:suave} ...", lo entiende el worker
        $envioT = if ($emo) { "{emo:$emo} $texto" } else { $texto }
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($envioT + "`n")
        $flujo = $script:ttsProc.StandardInput.BaseStream
        $t0Voz = $sw.ElapsedMilliseconds
        $flujo.Write($bytes, 0, $bytes.Length)
        $flujo.Flush()
        # UNA SOLA LECTURA VIVA SOBRE LA TUBERIA (17/09). Esto creaba una ReadLineAsync
        # nueva en cada frase y, al vencer el plazo, hacia return dejando la anterior
        # VIVA sobre el mismo StreamReader. Entonces pasaba una de dos: .NET lanzaba
        # InvalidOperationException ("el flujo esta en uso") y la voz en linea se daba
        # por muerta el RESTO DE LA SESION, o la lectura vieja se quedaba con la ruta y
        # la frase nueva recibia la del audio anterior: Nova diciendo una cosa y la
        # capsula moviendo la boca con la envolvente de otra.
        #
        # Es el mismo patron que Receive-Charla ya resolvia bien: la tarea se guarda y se
        # reutiliza en vez de crear otra. Al vencer el plazo se deja APUNTADA para que la
        # recoja la llamada siguiente, y esa linea tardia se DESCARTA, porque es la ruta
        # de la frase anterior y usarla seria justo el descuadre que se quiere evitar.
        if (-not $script:ttsLectura) {
            $script:ttsLectura = $script:ttsProc.StandardOutput.ReadLineAsync()
        } else {
            $script:ttsTardia = $true
        }
        $tarea = $script:ttsLectura
        # una respuesta larga tarda mas en sintetizarse: plazo segun lo largo (ver RESPUESTAS LARGAS ENTERAS)
        # Y DESDE EL 24/09 EL PLAZO SALE DE LO QUE TARDA DE VERDAD (idea 8): ver
        # Get-VozPlazoMs. Con menos de $DecisionMinIntentos muestras devuelve este mismo
        # 8000 + letras * 15, que es lo que habia; con datos, el p99 real por tres.
        $plazoVoz = Get-VozPlazoMs $texto.Length (Get-VozTiempos) $DecisionMinIntentos $VozPlazoSueloMs 30000
        # AL VENCER EL PLAZO, LA TUBERIA YA NO ES DE FIAR (21/09). Antes se hacia return
        # dejando la lectura APUNTADA, y el arreglo del 17/09 -descartar la linea tardia-
        # solo cubre UNA frase, no el atasco. El worker contesta SIEMPRE una linea por cada
        # una que entra, asi que la de la frase que vencio se queda en la tuberia sin dueno:
        #   frase A vence      -> lectura apuntada, una linea debiendose
        #   frase B            -> recoge la de A, la tira (bien), pero la de B queda sin leer
        #   frase C            -> lectura nueva que recoge AL INSTANTE la linea de B, y
        #                         ttsTardia ya vale false, asi que se la cree
        # A partir de ahi Nova dice una frase y suena la ANTERIOR, con la envolvente de la
        # anterior moviendo la boca y fijando la pausa del microfono. Y no se cierra solo:
        # D coge la de C, E la de D... el resto de la sesion.
        # EN EL LOG ESTA: 3 "sin respuesta en 8 s" (13/09, 15/09 y 19/09) y UN solo
        # descarte (19/09 09:25:08). Las otras dos veces el desfase no se cerro nunca.
        # Matar el worker es lo unico que deja la tuberia limpia de verdad; Say-Online lo
        # relanza solo en la frase siguiente (mira HasExited mas arriba). Son 3 reinicios en
        # once dias de log: no cuesta nada.
        if (-not $tarea.Wait($plazoVoz)) {
            Log "voz online: sin respuesta en $([int]($plazoVoz / 1000)) s; reinicio el worker para no descuadrar las siguientes"
            try { $script:ttsProc.Kill() } catch {}
            $script:ttsLectura = $null
            $script:ttsTardia = $false
            return $false
        }
        $script:ttsLectura = $null
        if ($script:ttsTardia) {
            # llego la de la frase ANTERIOR: se tira y esta frase se queda sin voz en
            # linea (cae a Piper). Mejor muda un momento que hablar descuadrada.
            $script:ttsTardia = $false
            Log "voz online: la respuesta que llego era de la frase anterior; la descarto"
            return $false
        }
        # Y AHORA SE MIDEN TODAS (24/09, idea 8). La linea de abajo solo sale con charla
        # -si no, el registro se llenaria-, y por eso de la mitad de las frases de Nova no
        # habia ni un dato. Esto no escribe ninguna linea: son dos numeros en un json de 200.
        [void](Add-VozTiempo ($sw.ElapsedMilliseconds - $t0Voz) $texto.Length)
        # lo que ESPERO el bucle a la voz (ver VOZ PREPARADA): una frase ya hecha tarda
        # ms; una nueva, ~1 s. Solo se apunta en charla, o el log se llenaria de esto
        if ($script:charlaEsperando -or $script:charlaFrases.Count -gt 0 -or $script:prepVozProc) {
            Log ("voz: frase " + $(if (($sw.ElapsedMilliseconds - $t0Voz) -lt 250) { 'ya preparada' } else { 'sintetizada al momento' }) + " ($($sw.ElapsedMilliseconds - $t0Voz) ms)")
        }
        $ruta = $tarea.Result
        if (-not $ruta -or $ruta.StartsWith('ERR')) { Log "voz online: $ruta"; return $false }
        # la capsula mueve la boca con la envolvente de ESTE audio (<mp3>.env);
        # se avisa justo antes de reproducir para que vayan sincronizados.
        # La envolvente da ademas la DURACION real: con ella la pausa de la
        # escucha (y el seguimiento) acaban cuando acaba la voz, no cuando lo
        # estimaba la cuenta de letras
        $script:uiAudio = $ruta
        try {
            $env = $ruta + '.env'
            if (Test-Path -LiteralPath $env) {
                $n = ([System.IO.File]::ReadAllText($env).Trim() -split '\s+').Count
                $dur = $n * 50 + 450
                $fin = $sw.ElapsedMilliseconds + $dur
                $script:vozFinReal = $fin    # la charla encadena frases con esto
                # Max: una pausa mas larga ya puesta (la sordina) no se acorta (auditoria 13/09)
                # LA PAUSA REAL (14/09): pero la que puso Say con la cuenta de letras
                # (70 ms por letra + 1,2 s) si, o la escucha seguia sorda ~0,7 s de mas
                # en cada frase. Solo si nadie la ha tocado desde entonces.
                if ($script:pausaEstimadaVoz -gt 0 -and $script:pausaHasta -eq $script:pausaEstimadaVoz -and $script:sordinaHasta -le $sw.ElapsedMilliseconds) {
                    $script:pausaHasta = $fin
                } else {
                    $script:pausaHasta = [Math]::Max($script:pausaHasta, $fin)
                }
                $script:pausaEstimadaVoz = -1
                $script:uiHasta = [Math]::Max($script:uiHasta, $fin)
            }
        } catch {}
        Refresh-UI
        return (Play-Audio $ruta)
    } catch {
        Log ("voz online error: " + $_.Exception.Message)
        return $false
    }
}

# --- Piper: TTS neuronal OFFLINE, la voz que suena humana de verdad ---
# Windows instala las voces "Natural" (Dalia) como paquete de aplicacion pero
# NO las registra donde las apps pueden verlas: son exclusivas del Narrador.
# Verificado en esta maquina. Por eso se usa Piper.
# CLAVE: el proceso se mantiene VIVO. Arrancarlo por frase costaba 1.311 ms
# (recarga del modelo); persistente baja a ~250 ms.
$PiperDir = Join-Path $LogDir "piper"
$PiperExe = Join-Path $PiperDir "piper.exe"
$PiperModelo = Join-Path $PiperDir "es_MX-claude-high.onnx"
$PiperSalida = Join-Path $PiperDir "salida"
$script:piperProc = $null

function Initialize-Piper {
    if (-not (Test-Path -LiteralPath $PiperExe) -or -not (Test-Path -LiteralPath $PiperModelo)) { return $false }
    try {
        if (-not (Test-Path -LiteralPath $PiperSalida)) { New-Item -ItemType Directory -Force -Path $PiperSalida | Out-Null }
        Get-ChildItem -LiteralPath $PiperSalida -Filter *.wav -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $PiperExe
        $psi.Arguments = "--model `"$PiperModelo`" --output_dir `"$PiperSalida`""
        $psi.UseShellExecute = $false
        $psi.RedirectStandardInput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = $PiperDir
        $script:piperProc = [System.Diagnostics.Process]::Start($psi)
        Log "voz: Piper es-MX (neuronal, offline) PID=$($script:piperProc.Id)"
        return $true
    } catch {
        Log ("WARN: Piper no arranco: " + $_.Exception.Message)
        $script:piperProc = $null
        return $false
    }
}

function Say-Piper([string]$texto) {
    if (-not $script:piperProc -or $script:piperProc.HasExited) {
        # sin Start-Sleep (14/09): la carga del modelo la cubre la espera del .wav (8 s)
        if (-not (Initialize-Piper)) { return $false }
    }
    try {
        $antes = @(Get-ChildItem -LiteralPath $PiperSalida -Filter *.wav -ErrorAction SilentlyContinue).Count
        # BYTES UTF-8 (14/09), como con la voz en linea: WriteLine usa la codificacion
        # de la consola y Piper recibia "bater?a est?". Medido con --debug: con UTF-8
        # sale "bateria" con el acento en la i y "esta" en la a; asi, "batera est".
        $bytesP = [System.Text.Encoding]::UTF8.GetBytes($texto + "`n")
        $script:piperProc.StandardInput.BaseStream.Write($bytesP, 0, $bytesP.Length)
        $script:piperProc.StandardInput.BaseStream.Flush()
        $w = $null
        $t0 = [DateTime]::UtcNow
        while (([DateTime]::UtcNow - $t0).TotalSeconds -lt 8) {
            Start-Sleep -Milliseconds 25
            $fs = @(Get-ChildItem -LiteralPath $PiperSalida -Filter *.wav -ErrorAction SilentlyContinue)
            if ($fs.Count -gt $antes) { $w = ($fs | Sort-Object LastWriteTime | Select-Object -Last 1); break }
        }
        if (-not $w) { return $false }
        # esperar a que termine de escribirse: reproducirlo a medias da error
        $tam = -1
        for ($i = 0; $i -lt 40; $i++) {
            Start-Sleep -Milliseconds 25
            $n = (Get-Item -LiteralPath $w.FullName).Length
            if ($n -eq $tam -and $n -gt 0) { break }
            $tam = $n
        }
        $script:vozPlayer.SoundLocation = $w.FullName
        $script:vozPlayer.Load()
        $script:vozPlayer.Play()
        # LA PAUSA REAL, TAMBIEN CON PIPER (17/09). Say puso el plazo contando letras
        # (70 ms cada una, hasta 90 s) y solo Say-Online lo corregia: por aqui la escucha
        # se quedaba sorda de mas en CADA frase. El .wav ya esta entero y se conoce su
        # tamano, asi que la duracion sale del archivo y no de una estimacion: Piper
        # escribe PCM de 16 bits a 22.050 Hz en mono, con 44 bytes de cabecera.
        try {
            if ($tam -gt 44) {
                # LA TASA SE LEE DEL PROPIO .WAV, no se da por sabida. Aqui puse primero
                # 44100 B/s a mano (22.050 Hz, 16 bits, mono), que es justo lo que declara
                # es_MX-claude-high.onnx.json... hoy. El dia que se cambie de voz o de
                # calidad, una constante copiada desajusta el plazo en silencio: corto,
                # Nova se oye a si misma; largo, se queda sorda de mas. La cabecera del
                # archivo que Piper acaba de escribir siempre dice la verdad (bytes por
                # segundo en el byte 28), y si no se pudiera leer, se usa 44100.
                $bytesSegP = 44100
                try {
                    $cabP = New-Object byte[] 44
                    $fsP = [System.IO.File]::OpenRead($w.FullName)
                    [void]$fsP.Read($cabP, 0, 44)
                    $fsP.Close()
                    $leidoP = [BitConverter]::ToUInt32($cabP, 28)
                    if ($leidoP -gt 8000 -and $leidoP -lt 400000) { $bytesSegP = $leidoP }
                } catch {}
                $segundosP = ($tam - 44) / [double]$bytesSegP
                $finP = $sw.ElapsedMilliseconds + [int]($segundosP * 1000) + 250
                # solo si nadie ha tocado la pausa desde que Say la puso, igual que arriba
                if ($script:pausaEstimadaVoz -gt 0 -and $script:pausaHasta -eq $script:pausaEstimadaVoz -and $script:sordinaHasta -le $sw.ElapsedMilliseconds) {
                    $script:pausaHasta = $finP
                } else {
                    $script:pausaHasta = [Math]::Max($script:pausaHasta, $finP)
                }
                $script:pausaEstimadaVoz = -1
                $script:uiHasta = [Math]::Max($script:uiHasta, $finP)
            }
        } catch {}
        # dejar solo los ultimos wav para no llenar el disco
        Get-ChildItem -LiteralPath $PiperSalida -Filter *.wav | Sort-Object LastWriteTime -Descending |
            Select-Object -Skip 3 | Remove-Item -Force -ErrorAction SilentlyContinue
        return $true
    } catch {
        Log ("Piper error: " + $_.Exception.Message)
        return $false
    }
}

function Initialize-Voz {
    if (-not $VozOn) { Log "voz desactivada por configuracion"; return }
    $script:vozPlayer = New-Object System.Media.SoundPlayer
    # orden de preferencia: en linea (mejor voz) -> Piper (offline) -> Windows
    if ($VozMotor -eq 'online' -and (Initialize-Online)) { return }
    if ($VozMotor -ne 'windows' -and (Initialize-Piper)) { return }
    Log "sin motor neuronal; se usara la voz de Windows"
    try {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime
        # PS 5.1 no sabe "await": hay que llegar a AsTask por reflexion
        $script:vozAwait = ([System.WindowsRuntimeSystemExtensions].GetMethods() |
            Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and
                           $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]
        $null = [Windows.Media.SpeechSynthesis.SpeechSynthesizer, Windows.Media, ContentType = WindowsRuntime]
        $null = [Windows.Storage.Streams.DataReader, Windows.Storage.Streams, ContentType = WindowsRuntime]
        # OJO: la propiedad de instancia AllVoices se proyecta mal en PS 5.1
        # (devuelve 0); hay que usar la ESTATICA.
        $todas = [Windows.Media.SpeechSynthesis.SpeechSynthesizer]::AllVoices
        $elegida = $null
        foreach ($p in $VozPref) {
            $elegida = $todas | Where-Object { $_.DisplayName -like "*$p*" -or $_.Language -like "$p*" } | Select-Object -First 1
            if ($elegida) { break }
        }
        if (-not $elegida) { $elegida = $todas | Select-Object -First 1 }
        $script:vozSyn = New-Object Windows.Media.SpeechSynthesis.SpeechSynthesizer
        if ($elegida) {
            $script:vozSyn.Voice = $elegida
            Log "voz: $($elegida.DisplayName) [$($elegida.Language)]"
        }
        $script:vozPlayer = New-Object System.Media.SoundPlayer
    } catch {
        Log ("WARN: voz no disponible, se sigue sin ella: " + $_.Exception.Message)
        Add-FalloArranque 'me he quedado sin voz'
        $script:vozSyn = $null
    }
}

function Await-Voz($op, $tipo) {
    $m = $script:vozAwait.MakeGenericMethod($tipo)
    $t = $m.Invoke($null, @($op))
    # NUNCA Wait(-1): esto se ejecuta dentro del bucle principal, y una espera
    # infinita congelaria el asistente entero si el sintetizador se cuelga.
    if (-not $t.Wait(5000)) {
        Log "voz: la sintesis no respondio en 5 s"
        return $null
    }
    return $t.Result
}

# TILDES PARA LA VOZ (14/09). El codigo escribe sin tildes ("No te entendi",
# "bateria", "cancion") y la voz neuronal lee lo que ve: sin tilde, el acento
# puede caer donde no es. Solo palabras SIN otra lectura posible sin tilde ("esta",
# "mas", "si", "que" se quedan como estan: ahi la tilde cambia el significado).
# Las tildes se ponen con codigos de caracter: este archivo no lleva BOM y PS 5.1
# leeria mal una tilde escrita tal cual.
$script:TildesVoz = $null
# HACERSE SITIO PARA HABLAR (23/09, funcion 7 de la tanda de funciones nuevas).
# braya le habla mientras juega -toda la tanda del 22/09 de 21:43 a 21:48 es con una partida
# delante- y Nova habla ENCIMA del audio del juego, a volumen fijo. En catorce dias habla 41
# veces con un juego en primer plano, con los altavoces medidos entre 0,10 y 1,000. Que se
# oiga a la primera ahorra la repeticion entera, que son dos intervenciones habladas menos.
# No cambia lo que dice: cambia que llegue.
#
# NO SE PONE 50: SE MULTIPLICA. PonerVolumenApp es absoluto de 0 a 100, asi que si braya tiene
# el juego al 30 %, poner 50 se lo SUBE. Se lee antes con LeerVolumenApp -devuelve -1 si no
# hay sesion de audio- y se baja en proporcion; y si ya esta por debajo de 20, no se toca:
# bajarlo mas no ayuda a oir y se nota al devolverlo.
# RELOJ PROPIO, nunca pausaHasta: esa se alarga con la sordina y con el dictado, y el juego se
# quedaria bajado. Techo duro de 20 s, y el bucle lo devuelve SIEMPRE, aunque no haya sonado.
$JuegoBajarAlHablar = [bool](Get-Cfg 'juego' 'bajarAlHablar' $true)
$JuegoBajarPct = [int](Get-Cfg 'juego' 'bajarAlHablarPct' 35)   # a que % del suyo se baja
$script:juegoVolAntes = -1
$script:juegoVolPid = 0
$script:juegoBajadoHasta = 0
function Push-VolumenJuego {
    if (-not $JuegoBajarAlHablar -or $script:juegoVolAntes -ge 0) { return }
    $pidJ = [int]$script:juegoPid
    if ($pidJ -le 0 -or -not $script:juegoActivo) { return }
    $v = -1
    try { $v = [int][AX]::LeerVolumenApp($pidJ) } catch { return }
    if ($v -lt 20) { return }            # ya lo tiene bajo: no se toca
    $destino = [int][Math]::Max(5, [Math]::Round($v * ($JuegoBajarPct / 100.0)))
    try {
        if ([AX]::PonerVolumenApp($pidJ, $destino)) {
            $script:juegoVolAntes = $v
            $script:juegoVolPid = $pidJ
            $script:juegoBajadoHasta = $sw.ElapsedMilliseconds + 20000
        }
    } catch {}
}
function Pop-VolumenJuego {
    if ($script:juegoVolAntes -lt 0) { return }
    try { [void][AX]::PonerVolumenApp($script:juegoVolPid, $script:juegoVolAntes) } catch {}
    $script:juegoVolAntes = -1
    $script:juegoVolPid = 0
    $script:juegoBajadoHasta = 0
}

# SOLTAR SITIO EN EL DISCO (23/09, funcion 6 de la tanda de funciones nuevas).
# Nova ya le avisa pero no sabe actuar, y encima promete algo que no tiene: cuatro veces le ha
# dicho "te quedan X gigas, preguntame que ocupa mas" -20/09 con 14,5 GB, 21/09 con 14,9,
# 22/09 con 11,1, 23/09 con 13,8- y "que ocupa mas" NO EXISTE: el unico parser de tamaño es
# "cuanto ocupa {juego}", y el "lo que mas ocupa" de mas arriba mide RAM, no disco. El 18/09
# le quedaban 115 GB; hoy 13,7 de 475.
#
# LISTA CERRADA Y ESCRITA AQUI, nunca una ruta dicha por voz. Y solo se borra lo que el
# sistema REGENERA solo: caches de video y ficheros temporales viejos. Nada de Descargas,
# nada de Documentos, nada que braya haya puesto. Medido hoy en su consola: TEMP 2.494 MB,
# Packages 606, AMD 37, D3DSCache 2,4.
#
# Y SE BORRA DE VERDAD (Remove-Item), no a la papelera: mandarlo a la papelera lo mueve pero
# NO libera el disco, asi que Nova diria "te he soltado 900 MB" y DriveInfo seguiria marcando
# lo mismo. Eso es mentir con un numero delante, que es peor que no hacer nada.
$CachesLimpiables = @(
    @{ nombre = 'la cache de video de AMD'; ruta = "$env:LOCALAPPDATA\AMD\DxCache" }
    @{ nombre = 'la cache de shaders';      ruta = "$env:LOCALAPPDATA\D3DSCache" }
    @{ nombre = 'la cache de AMD GL';       ruta = "$env:LOCALAPPDATA\AMD\GLCache" }
    @{ nombre = 'los temporales viejos';    ruta = $env:TEMP; dias = 7 }
)
function Get-TamanoMB([string]$ruta, [int]$dias = 0) {
    if (-not $ruta -or -not (Test-Path -LiteralPath $ruta)) { return 0.0 }
    try {
        $fich = Get-ChildItem -LiteralPath $ruta -Recurse -File -Force -ErrorAction SilentlyContinue
        if ($dias -gt 0) {
            $corte = (Get-Date).AddDays(-$dias)
            $fich = @($fich | Where-Object { $_.LastWriteTime -lt $corte })
        }
        $b = ($fich | Measure-Object -Property Length -Sum).Sum
        return [Math]::Round(([double]$b) / 1MB, 1)
    } catch { return 0.0 }
}
function Get-FacturaDisco {
    $filas = @()
    foreach ($c in $CachesLimpiables) {
        $mb = Get-TamanoMB $c.ruta ([int]$c.dias)
        if ($mb -ge 1) { $filas += @{ nombre = $c.nombre; mb = $mb; ruta = $c.ruta; dias = [int]$c.dias } }
    }
    return @($filas | Sort-Object -Property { -$_.mb })
}
# LO QUE SE SOLTO DE VERDAD SE MIDE CON EL DISCO, no sumando lo que se borro: un fichero
# bloqueado no se va, y el numero tiene que ser el que ve Windows.
function Clear-CachesDisco {
    $antes = 0.0
    try { $antes = [Math]::Round((New-Object System.IO.DriveInfo('C')).AvailableFreeSpace / 1GB, 2) } catch {}
    $tocadas = 0
    foreach ($c in $CachesLimpiables) {
        if (-not $c.ruta -or -not (Test-Path -LiteralPath $c.ruta)) { continue }
        try {
            # SE BORRA EXACTAMENTE LO QUE SE CONTO (revision del 23/09). Get-TamanoMB cuenta
            # FICHEROS, recursivamente, y por la fecha DEL FICHERO; esto listaba solo el
            # primer nivel, miraba la fecha de la ENTRADA -carpetas incluidas- y borraba con
            # -Recurse. Medido en su %TEMP%: se anunciaban 193 ficheros viejos = 12,3 MB y se
            # borraban 22 entradas = 0,44 MB. Pedir permiso para doce megas y soltar medio es
            # exactamente lo que la casa no tolera. Y de paso se iba la punta peligrosa: una
            # carpeta vieja se llevaba por delante los ficheros de ayer que tuviera dentro.
            $items = Get-ChildItem -LiteralPath $c.ruta -Recurse -File -Force -ErrorAction SilentlyContinue
            if ([int]$c.dias -gt 0) {
                $corte = (Get-Date).AddDays(-[int]$c.dias)
                $items = @($items | Where-Object { $_.LastWriteTime -lt $corte })
            }
            foreach ($it in $items) {
                # y NUNCA la carpeta de Nova: ahi viven sus propias copias y medidas
                if ($it.FullName -like "*voice-ctrl*" -or $it.FullName -like "*claude*") { continue }
                try { Remove-Item -LiteralPath $it.FullName -Force -ErrorAction SilentlyContinue; $tocadas++ } catch {}
            }
            # y despues, las carpetas que se hayan quedado vacias. De dentro hacia fuera, y
            # solo si no queda NADA: una carpeta con un fichero de hoy no se toca.
            $dirs = @(Get-ChildItem -LiteralPath $c.ruta -Recurse -Directory -Force -ErrorAction SilentlyContinue |
                      Sort-Object -Property { $_.FullName.Length } -Descending)
            foreach ($dd in $dirs) {
                if ($dd.FullName -like "*voice-ctrl*" -or $dd.FullName -like "*claude*") { continue }
                try {
                    if (-not (Get-ChildItem -LiteralPath $dd.FullName -Force -ErrorAction SilentlyContinue)) {
                        Remove-Item -LiteralPath $dd.FullName -Force -ErrorAction SilentlyContinue
                    }
                } catch {}
            }
        } catch {}
    }
    $despues = $antes
    try { $despues = [Math]::Round((New-Object System.IO.DriveInfo('C')).AvailableFreeSpace / 1GB, 2) } catch {}
    return @{ antes = $antes; despues = $despues; soltado = [Math]::Round($despues - $antes, 2); tocadas = $tocadas }
}

# LIMPIAR LO QUE CREE SABER DE BRAYA (23/09, funcion 5 de la tanda de funciones nuevas).
# perfil.md tiene 59 datos y el tope son 60: esta a un dato de llenarse, y a partir de ahi
# cada dato nuevo expulsa a otro. Y solo las 15 ultimas lineas viajan en cada prompt de la
# charla, o sea que lo que este ahi arriba le vuelve hablado. Hoy, OCHO de esos 59 se los
# comen dos nombres MAL OIDOS: cuatro lineas de "Meramiau"/"Mira mio"/"Meramian" -que
# acabaron inventando un gato que no existe- y cuatro de un juego llamado "Amin"/"Amino".
# (Contado hoy sobre el fichero: 59 lineas que empiezan por "- "; Amino en las 16, 18, 19 y
#  20, y los Meramiau en las 24, 25, 27 y 34.)
# El caso que lo prueba es del 20/09 a las 23:09-23:11: sus DOS correcciones seguidas del
# nombre del juego se guardaron como dos datos NUEVOS encima del malo, en vez de corregirlo.
#
# COMO SE LIMPIA SIN INVENTAR: no se decide solo. Se buscan los dos datos que mas se parecen
# entre si -los que casi seguro son el mismo con dos redacciones- y se le PREGUNTA con las dos
# opciones delante. Una pregunta, dos opciones, y el que sobra se va. Nada de borrar a ciegas
# lo que el escribio.
$script:perfilPar = $null
# Resuelve el par: 1 = me quedo con la primera, 2 = con la segunda, 0 = las dejo las dos.
# La usan las DOS vias -la voz y el mando-, asi que el borrado esta escrito una sola vez.
function Resolve-PerfilPar([int]$cual) {
    $p = $script:perfilPar
    $script:perfilPar = $null
    if (-not $p) { return 'ya no tengo esa pregunta abierta' }
    if ($cual -ne 1 -and $cual -ne 2) { return 'vale, las dejo las dos' }
    $fuera = if ($cual -eq 1) { [string]$p.b } else { [string]$p.a }
    $dp = @(Get-DatosPerfil)
    Save-DatosPerfil (@($dp | Where-Object { $_ -ne $fuera }))
    Log "PERFIL: braya eligio la $cual; fuera '$fuera'"
    Add-Estadistica 'perfil-limpia' $fuera
    return 'hecho, me quedo con la otra'
}

function Get-ParParecidoPerfil {
    $datos = @(Get-DatosPerfil)
    if ($datos.Count -lt 8) { return $null }
    # las palabras que salen en medio perfil no distinguen nada (ver Add-DatoPerfil): el mismo
    # calculo, para no medir el parecido por "braya" y "tiene".
    $cuenta = @{}
    foreach ($y in $datos) {
        $cy = (((ConvertTo-Suave $y) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim()
        foreach ($w in @($cy -split '\s+' | Where-Object { $_.Length -ge 4 } | Select-Object -Unique)) {
            $cuenta[$w] = [int]$cuenta[$w] + 1
        }
    }
    # MAS ESTRICTO QUE EN Add-DatoPerfil, y a proposito: alli se compara un dato NUEVO
    # contra los viejos, y aqui se comparan los 59 ENTRE SI. Con el liston de un tercio,
    # "tiene" (15 de 59) no contaba como vacia y emparejaba "tiene dificultad con
    # Meramiau" con "braya tiene algo que se le acaba", que no tienen nada que ver.
    $topeV = [Math]::Max(3, [int][Math]::Ceiling($datos.Count / 6.0))
    # UN NOMBRE PROPIO NUNCA ES UNA PALABRA VACIA, por pocas lineas que haya. Con diez datos
    # el tope sale 3, y "Amino" -que esta en tres lineas- se marcaba como comun y desaparecia
    # justo el caso que se venia a cazar. Los nombres propios se calculan abajo, asi que aqui
    # se dejan fuera del filtro por su forma: empiezan por mayuscula dentro de la frase.
    $conMayus = @{}
    foreach ($y in $datos) {
        $pal0 = @($y -split '\s+')
        for ($k0 = 1; $k0 -lt $pal0.Count; $k0++) {
            $w0 = $pal0[$k0] -replace '[^\wáéíóúñÁÉÍÓÚÑ]', ''
            if ($w0.Length -ge 4 -and $w0.Substring(0, 1) -cmatch '[A-ZÁÉÍÓÚÑ]') { $conMayus[(ConvertTo-Suave $w0)] = $true }
        }
    }
    $vacias = @($cuenta.Keys | Where-Object { $cuenta[$_] -ge $topeV -and -not $conMayus[$_] })
    # Y LOS NOMBRES PROPIOS, que es donde esta la basura de verdad. Su perfil tiene hoy tres
    # lineas de un juego llamado "Amino" -"se llama Amino", "usa Amino", "juega en Amino"- y
    # dos de un "Meramiau" que el oido se invento. Son frases de dos o tres palabras: por
    # proporcion no se emparejan nunca, porque casi no tienen palabras que comparar.
    # La señal es otra: comparten un nombre PROPIO (con mayuscula y no al principio de la
    # linea) que sale en pocas lineas, y las dos frases son cortas. Medido sobre sus 59 datos,
    # eso encuentra las tres de "Amino" y el "Steam" repetido, y ni un falso: los verbos
    # comunes -"prefiere", "quiere"- se caen solos porque van en minuscula.
    $propios = @{}
    foreach ($y in $datos) {
        $pal = @($y -split '\s+')
        for ($k = 1; $k -lt $pal.Count; $k++) {
            $w = $pal[$k] -replace '[^\wáéíóúñÁÉÍÓÚÑ]', ''
            if ($w.Length -ge 4 -and $w.Substring(0, 1) -cmatch '[A-ZÁÉÍÓÚÑ]') {
                $propios[(ConvertTo-Suave $w)] = $true
            }
        }
    }
    $mejorA = ''; $mejorB = ''; $mejorP = 0.0
    for ($i = 0; $i -lt $datos.Count; $i++) {
        $pa = @(((((ConvertTo-Suave $datos[$i]) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim() -split '\s+') |
                Where-Object { $_.Length -ge 4 -and $vacias -notcontains $_ } | Select-Object -Unique)
        if ($pa.Count -lt 1) { continue }
        for ($j = $i + 1; $j -lt $datos.Count; $j++) {
            $pb = @(((((ConvertTo-Suave $datos[$j]) -replace '[^a-z0-9 ]', ' ') -replace '\s+', ' ').Trim() -split '\s+') |
                    Where-Object { $_.Length -ge 4 -and $vacias -notcontains $_ } | Select-Object -Unique)
            if ($pb.Count -lt 1) { continue }
            $comunes = @($pa | Where-Object { $pb -contains $_ })
            # el caso del nombre propio: dos frases cortas que hablan de lo mismo
            # EL TOPE ES 6 Y NO 4 (revision del 23/09): su perfil tiene CUATRO lineas de
            # "Amino", asi que con "-le 4" entraba por los pelos y una quinta -que llega
            # sola, porque el oido sigue inventandoselo- sacaba del rango justo el caso que
            # se viene a cazar.
            $raras = @($comunes | Where-Object { $propios[$_] -and [int]$cuenta[$_] -ge 2 -and [int]$cuenta[$_] -le 6 })
            $cortaA = (@($datos[$i] -split '\s+').Count -le 8)
            $cortaB = (@($datos[$j] -split '\s+').Count -le 8)
            if ($raras.Count -gt 0 -and $cortaA -and $cortaB) {
                # GANA EL NOMBRE QUE MAS LINEAS ENSUCIA (revision del 23/09). Antes se fijaba
                # un 0,9 plano y se comparaba con "-gt" estricto, asi que ganaba el PRIMER par
                # de 0,9 que apareciera y todos los empates posteriores se tiraban. Medido
                # sobre su perfil de verdad: salia el par "tiene 14 juegos instalados en
                # Steam" / "Braya usa Steam" -que son dos datos DISTINTOS, o sea que Nova
                # proponia borrar informacion buena- y las cuatro lineas de "Amino" no se
                # ofrecian jamas. Con la cuenta, "Amino" (4 lineas) gana a "Steam" (2).
                $sc = 0.9 + 0.001 * [int]$cuenta[$raras[0]]
                if ($sc -gt $mejorP) { $mejorP = $sc; $mejorA = $datos[$i]; $mejorB = $datos[$j] }
                continue
            }
            if ($comunes.Count -lt 2) { continue }
            $p = [Math]::Max($comunes.Count / [double]$pa.Count, $comunes.Count / [double]$pb.Count)
            if ($p -gt $mejorP) { $mejorP = $p; $mejorA = $datos[$i]; $mejorB = $datos[$j] }
        }
    }
    # 0,6 es el mismo liston con el que Add-DatoPerfil decide que dos frases son el mismo tema
    if ($mejorP -lt 0.6) { return $null }
    return @{ a = $mejorA; b = $mejorB; parecido = [Math]::Round([Math]::Min(1.0, $mejorP), 2) }
}

# MONTAJES CON NOMBRE (23/09, funcion 3 de la tanda de funciones nuevas).
# Es lo que mas ha pedido braya y lo unico que nunca consiguio: el propio codigo lo tiene
# contado -en catorce dias la pantalla dividida no se ejecuto bien ni una vez por voz, cero de
# once intentos-. Y no es un capricho suelto: YouTube en una mitad y Pinterest en la otra sale
# en ocho momentos distintos, y el 18/09 a las 20:04 se quejo por voz ("solo abriste Pinterest,
# nunca abriste YouTube ni dividiste la pantalla"). Su perfil dice para que le sirve: quiere
# recrear una foto con su pareja -las referencias en Pinterest, el tutorial en YouTube-.
# Hoy hay cinco patrones peleandose por adivinar como lo dice. Con un nombre no hay nada que
# adivinar: "guarda esto como el tablero" y luego "pon el tablero".
#
# EL MONTAJE NO SE SACA DE MIRAR LA PANTALLA: se guarda de los destinos YA RESUELTOS de un
# "dividir" que Nova acaba de ejecutar bien. Asi guarda "https://www.pinterest.com a la
# izquierda" y no "dos ventanas de Edge", y no le hace falta saber leer la barra del navegador.
$MontajesPath = Join-Path $MemoriaDir 'montajes.json'
$script:montajes = $null
function Get-Montajes {
    if ($null -ne $script:montajes) { return $script:montajes }
    $script:montajes = @{}
    try {
        if (Test-Path -LiteralPath $MontajesPath) {
            $crudoM = Get-Content -LiteralPath $MontajesPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($pm in $crudoM.PSObject.Properties) {
                $script:montajes[$pm.Name] = @{
                    izq = [string]$pm.Value.izq; der = [string]$pm.Value.der
                    izqTipo = [string]$pm.Value.izqTipo; derTipo = [string]$pm.Value.derTipo
                    cuando = [string]$pm.Value.cuando
                }
            }
        }
    } catch { Log ('montajes: no pude leerlos: ' + $_.Exception.Message) }
    return $script:montajes
}
function Save-Montajes {
    # MODO INVITADO: lo que diga otro no se queda (17/09). Un invitado puede MONTAR los que
    # ya hay -eso no escribe nada-, pero no crear ni borrar montajes en la consola de braya.
    if ($script:invitado) { Log 'montajes: modo invitado, no guardo nada'; return }
    try {
        [System.IO.File]::WriteAllText($MontajesPath, (ConvertTo-Json -InputObject (Get-Montajes) -Depth 4),
                                       (New-Object System.Text.UTF8Encoding($false)))
    } catch { Log ('montajes: no pude guardarlos: ' + $_.Exception.Message) }
}
# ABRIR O ENFOCAR, que no es lo mismo: 'dividir' siempre hace Start-Process, asi que si el
# navegador ya estaba abierto te abre OTRO. Aqui se mira primero si ya hay una ventana suya.
function Show-OAbrir([string]$tipo, [string]$destino) {
    if ($tipo -ne 'url') {
        $nom = [System.IO.Path]::GetFileNameWithoutExtension($destino)
        $pv = $null
        try { $pv = @(Get-Process -Name $nom -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 })[0] } catch {}
        if ($pv) {
            try {
                [void][AX]::ShowWindow($pv.MainWindowHandle, 9)
                [void][AX]::ForceForeground($pv.MainWindowHandle)
                return $true
            } catch {}
        }
    }
    try {
        if ($tipo -eq 'url') { Start-Process $destino -ErrorAction Stop }
        else { $null = Start-Process $destino -PassThru -ErrorAction Stop }
        return $true
    } catch { Log ("montaje: no pude abrir $destino"); return $false }
}

# AJEDREZ A CIEGAS (23/09, lo pidio braya). Las reglas las lleva python-chess y juega
# Stockfish: aqui solo esta el puente. Un turno = un proceso que arranca y se muere (medido:
# 1,2 s, de los que 0,15 son pensar); un worker vivo ahorraria medio segundo y le quitaria
# memoria al juego durante horas, que es justo lo que no se quiere.
#
# LA TRIPLE LLAVE para que una frase cuente como jugada, y las tres hacen falta:
#   (a) hay partida abierta -si no, ni se mira-;
#   (b) la frase tiene FORMA de jugada, con patron anclado en ^...$, no un -match suelto;
#   (c) y python-chess la valida contra las jugadas legales de ESE tablero.
# Si falla cualquiera, la frase sigue su camino de siempre y aqui no ha pasado nada. Por eso
# esto va en Process-Texto y NO dentro de Invoke-FastCommand: a esa la llaman las reglas, los
# perfiles de juego y las traducciones, y ninguna es braya hablando.
# Se puede apagar entero desde config.json (juego.ajedrez = false), como todo lo demas.
$AjedrezOn = [bool](Get-Cfg 'juego' 'ajedrez' $true)
$script:recuerdoPide = ''        # de que se le pidio acordarse (ver funcion 4)
$script:ultimoDividir = $null     # el ultimo 'dividir' que salio bien, para poder guardarlo
$script:ajedrezActiva = $null      # $null = aun no se ha mirado el disco en este arranque
$script:ajedrezPreguntaHasta = 0   # hasta cuando vale contestar "la primera" / "la segunda"
$AjedrezPy = Join-Path $LogDir 'ajedrez_turno.py'
function Test-AjedrezAbierta {
    if ($null -eq $script:ajedrezActiva) {
        $script:ajedrezActiva = Test-Path -LiteralPath (Join-Path $MemoriaDir 'ajedrez.json')
    }
    return [bool]$script:ajedrezActiva
}
function Invoke-AjedrezPy([string[]]$args2) {
    try {
        $salida = & $PyExe $AjedrezPy @args2 2>$null
        if (-not $salida) { return $null }
        return ([string]($salida -join '')) | ConvertFrom-Json
    } catch { Log ("ajedrez: " + $_.Exception.Message); return $null }
}
function Invoke-Ajedrez([string]$texto) {
    if (-not $AjedrezOn) { return $null }
    $pl = ConvertTo-Plain $texto
    if (-not $pl) { return $null }
    # EMPEZAR. Se reconoce siempre, haya partida o no.
    if ($pl -match '^(?:(?:juguemos|jugamos|juega|jugar|echamos|echemos)\s+(?:una\s+partida\s+de\s+|al\s+|a\s+)?ajedrez(?:\s+conmigo)?|(?:una\s+)?partida\s+de\s+ajedrez|ajedrez\s+(?:a\s+ciegas|mental))$') {
        $r = Invoke-AjedrezPy @('--empezar')
        if ($r) { $script:ajedrezActiva = $true; return [string]$r.decir }
        return 'No puedo con el ajedrez ahora mismo.'
    }
    if (-not (Test-AjedrezAbierta)) { return $null }
    # SALIR. Siempre con salida clara: braya rechaza los modos de los que no se sabe salir.
    if ($pl -match '^(?:dejamos?\s+(?:la\s+)?partida|deja\s+(?:el\s+)?ajedrez|abandono|me\s+rindo|borra\s+la\s+partida|cierra\s+la\s+partida|ya\s+no\s+juego)$') {
        $r = Invoke-AjedrezPy @('--cerrar')
        $script:ajedrezActiva = $false
        return $(if ($r) { [string]$r.decir } else { 'Partida cerrada.' })
    }
    if ($pl -match '^(?:por\s+donde\s+(?:vamos|ibamos)|como\s+va\s+la\s+partida|a\s+quien\s+le\s+toca|que\s+jugada\s+vamos)$') {
        $r = Invoke-AjedrezPy @('--estado')
        return $(if ($r) { [string]$r.decir } else { $null })
    }
    # DESHACER, que es la salvaguarda de esto: no se confirma con un "si" -al 70,4 % de oido,
    # un si mal oido no es una confirmacion-, se deshace.
    if ($pl -match '^(?:retira\s+esa|retira\s+la\s+jugada|deshaz(?:\s+eso)?|no\s+era\s+esa|vuelve\s+atras)$') {
        $r = Invoke-AjedrezPy @('--deshacer')
        return $(if ($r) { [string]$r.decir } else { $null })
    }
    # CONTESTANDO A "¿foxtrot tres o charlie tres?" -- con la voz de siempre. El mando
    # (funcion 10) es la OTRA manera, no la unica: aqui se cierra el selector si estaba.
    #
    # SOLO SI HAY UNA PREGUNTA VIVA (revision del 23/09). Antes bastaba con que hubiera
    # partida abierta, y la partida vive DIAS: un "dos" suelto tres dias despues hacia la
    # jugada que quedo pendiente. Ademas cada una de estas dos lineas arranca Python (~1,2 s
    # con el bucle parado) aunque no hubiera nada que elegir. El lado de Python tiene su
    # propia caducidad de 60 s; esta es la de aca, y ahorra el arranque.
    if ($script:ajedrezPreguntaHasta -gt 0 -and $sw.ElapsedMilliseconds -ge $script:ajedrezPreguntaHasta) { $script:ajedrezPreguntaHasta = 0 }
    if ($script:ajedrezPreguntaHasta -gt 0 -and $pl -match '^(?:la\s+)?(?:primera|primero|el\s+primero|uno)$') { $script:ajedrezPreguntaHasta = 0; Close-Eleccion $false; $r = Invoke-AjedrezPy @('--elegir', '1'); return $(if ($r) { [string]$r.decir } else { $null }) }
    if ($script:ajedrezPreguntaHasta -gt 0 -and $pl -match '^(?:la\s+)?(?:segunda|segundo|el\s+segundo|dos)$')  { $script:ajedrezPreguntaHasta = 0; Close-Eleccion $false; $r = Invoke-AjedrezPy @('--elegir', '2'); return $(if ($r) { [string]$r.decir } else { $null }) }
    # UNA JUGADA. El patron es la llave (b): pieza o columna, y una fila. Anclado en ^...$ y
    # escrito contra lo que LLEGA (ConvertTo-Plain ya lo paso a minusculas y quito la coma).
    $piezas = 'rey|dama|reina|torre|alfil|caballo|peon'
    $cols = 'alfa|bravo|charlie|delta|echo|foxtrot|golf|hotel|be|ce|de|efe|ge|hache'
    $filas = 'uno|dos|tres|cuatro|cinco|seis|siete|ocho|[1-8]'
    # Y LA CORONACION (revision del 23/09). formas_de() ya generaba " corono dama" desde el
    # principio, pero el patron de aqui estaba anclado justo detras de la fila, asi que
    # "peon echo ocho corono dama" no llegaba nunca: era codigo muerto desde este lado.
    $corona = '(?:\s+corono\s+(?:dama|reina|torre|alfil|caballo))?'
    if ($pl -match '^(?:enroque|enroco)\b' -or
        $pl -match ("^(?:$piezas)\s+(?:a\s+|come\s+en\s+)?(?:$cols|[a-h])\s+(?:$filas)$corona$") -or
        $pl -match ("^(?:$cols)\s+(?:$filas)$corona$")) {
        $r = Invoke-AjedrezPy @('--dicho', $texto)
        if ($r -and $r.decir) {
            # SI PREGUNTA ENTRE DOS, EL MANDO LAS RESUELVE (23/09, funcion 10). Es el caso
            # con mas motivo de todos: las dos opciones se parecen un 70 % al oido -por eso
            # se pregunta-, asi que contestar hablando es pedirle al oido justo lo que no
            # sabe hacer. Con la cruceta no hay nada que entender.
            if ($r.opciones -and @($r.opciones).Count -ge 2) {
                $script:ajedrezPreguntaHasta = $sw.ElapsedMilliseconds + 60000
                [void](Open-Eleccion @($r.opciones) 'ajedrez')
            }
            return [string]$r.decir
        }
        return $null      # tenia forma pero no era legal: que siga su camino
    }
    return $null
}

# LO QUE DICE AL HACER UNA ORDEN, CONJUGADO (23/09, idea 1 de la cuarta tanda, y lo pidio
# braya: "que lo diga conjugado en todas las frases que se pueda").
# Invoke-FastCommand devuelve el nombre interno de la accion -"abrir steam", "cerrar
# navegador", "volumen al 50 por ciento"- y esa misma cadena se decia en voz alta. Medido en
# assistant.log: 139 respuestas locales en infinitivo, 77 formas distintas, y "abrir steam" es
# la frase mas repetida de toda Nova (23 veces). Sonaba a fichero de log.
#
# TRES REGLAS, y las tres importan:
#  1. LISTA CERRADA y anclada al principio. Lo que no reconoce se devuelve TAL CUAL: mas vale
#     un infinitivo suelto que una frase inventada. Aqui no hay modelo ni adivinanza.
#  2. NO se toca el dato interno. $a.desc sigue siendo "abrir steam" en el log, en la memoria
#     de la charla y en los bancos: lo que cambia es solo lo que sale por el altavoz y por la
#     capsula. Si se tocara el dato, se romperian 22 comprobaciones que lo afirman, la
#     respuesta de "repite" y lo que la charla recuerda de la ultima orden.
#  3. NI la rama de confirmacion. La pregunta "¿Abro SILENT BREATH?" ya esta conjugada por su
#     lado, y deformarla seria tocar justo la frase con la que braya dice si o no.
# Los planes se dicen ENTEROS, cambiando el ';' por ' y ': la capsula no conserva la lista
# -Show-Popup escribe y Say la pisa milisegundos despues-, asi que recortar ahi quitaria los
# pasos de la voz Y de la pantalla.
function Get-FraseAccion([string]$txt) {
    if (-not $txt) { return $txt }
    $trozos = @()
    foreach ($t in ($txt -split ';')) {
        $u = $t.Trim()
        if (-not $u) { continue }
        # el orden importa: lo mas especifico primero, y todo anclado en ^
        $v = switch -Regex ($u) {
            '^abrir\s+(?:la\s+carpeta\s+)?(.+)$'            { "Abro $($Matches[1])"; break }
            '^cerrar\s+todo$'                               { 'Cierro todo'; break }
            '^cerrar\s+(.+)$'                               { "Cierro $($Matches[1])"; break }
            '^mostrar\s+el\s+escritorio$'                   { 'Muestro el escritorio'; break }
            '^mostrar\s+(.+)$'                              { "Muestro $($Matches[1])"; break }
            '^volumen\s+al\s+(.+)$'                         { "Pongo el volumen al $($Matches[1])"; break }
            '^brillo\s+al\s+(.+)$'                          { "Pongo el brillo al $($Matches[1])"; break }
            '^subir\s+(?:el\s+)?(volumen|brillo)(.*)$'      { "Subo el $($Matches[1])$($Matches[2])"; break }
            '^bajar\s+(?:el\s+)?(volumen|brillo)(.*)$'      { "Bajo el $($Matches[1])$($Matches[2])"; break }
            "^buscar\s+'(.+)'\s+en\s+(.+)$"                 { "Busco $($Matches[1]) en $($Matches[2])"; break }
            "^escribir\s+'(.+)'$"                           { "Escribo $($Matches[1])"; break }
            '^dividir\s+pantalla\s+con\s+(.+)$'             { "Divido la pantalla con $($Matches[1])"; break }
            '^dividir\s+pantalla\s+(.+?)\s+con\s+(.+)$'     { "Divido la pantalla entre $($Matches[1]) y $($Matches[2])"; break }
            '^reproducir\s+(.+)$'                           { "Reproduzco $($Matches[1])"; break }
            '^silenciar$'                                   { 'Silencio el sonido'; break }
            '^pausar$'                                      { 'Pauso'; break }
            '^bloquear$'                                    { 'Bloqueo la consola'; break }
            '^minimizar\s*(.*)$'                            { "Minimizo $($Matches[1])".Trim(); break }
            '^maximizar\s*(.*)$'                            { "Maximizo $($Matches[1])".Trim(); break }
            '^apagar\s+(.+)$'                               { "Apago $($Matches[1])"; break }
            '^encender\s+(.+)$'                             { "Enciendo $($Matches[1])"; break }
            '^activar\s+(.+)$'                              { "Activo $($Matches[1])"; break }
            '^desactivar\s+(.+)$'                           { "Desactivo $($Matches[1])"; break }
            '^enfocar\s+(.+)$'                              { "Voy a $($Matches[1])"; break }
            '^copiar$'                                      { 'Copio'; break }
            '^pegar$'                                       { 'Pego'; break }
            '^poner\s+(.+)$'                                { "Pongo $($Matches[1])"; break }
            '^crear\s+(.+)$'                                { "Creo $($Matches[1])"; break }
            '^borrar\s+(.+)$'                               { "Borro $($Matches[1])"; break }
            '^mover\s+(.+)$'                                { "Muevo $($Matches[1])"; break }
            '^instalar\s+(.+)$'                             { "Instalo $($Matches[1])"; break }
            '^leer\s+(.+)$'                                 { "Leo $($Matches[1])"; break }
            '^enviar\s+(.+)$'                               { "Envio $($Matches[1])"; break }
            '^grabar\s*(.*)$'                               { "Grabo $($Matches[1])".Trim(); break }
            default                                          { $u }
        }
        $trozos += [string]$v
    }
    if ($trozos.Count -eq 0) { return $txt }
    # el primero con mayuscula; los demas pegados con ' y ' y en minuscula, que es como se
    # dice una lista hablada ("Abro Steam y pongo el volumen al 50 por ciento")
    $out = [string]$trozos[0]
    if ($out.Length -gt 1) { $out = $out.Substring(0, 1).ToUpper() + $out.Substring(1) }
    for ($i = 1; $i -lt $trozos.Count; $i++) {
        $sig = [string]$trozos[$i]
        if ($sig.Length -gt 1) { $sig = $sig.Substring(0, 1).ToLower() + $sig.Substring(1) }
        $out += ' y ' + $sig
    }
    return $out
}

function Add-TildesVoz([string]$s) {
    if (-not $s) { return $s }
    if (-not $script:TildesVoz) {
        $a = [char]0xE1; $e = [char]0xE9; $i = [char]0xED; $o = [char]0xF3; $u = [char]0xFA; $n = [char]0xF1
        $script:TildesVoz = [ordered]@{
            'entendi' = "entend$i"; 'aqui' = "aqu$i"; 'ahi' = "ah$i"; 'alli' = "all$i"; 'asi' = "as$i"
            'todavia' = "todav$i" + 'a'; 'despues' = "despu$e" + 's'; 'tambien' = "tambi$e" + 'n'; 'ademas' = "adem$a" + 's'
            'musica' = "m$u" + 'sica'; 'bateria' = "bater$i" + 'a'; 'cancion' = "canci$o" + 'n'; 'ultimo' = "$u" + 'ltimo'
            'ultima' = "$u" + 'ltima'; 'ultimos' = "$u" + 'ltimos'; 'rapido' = "r$a" + 'pido'; 'numero' = "n$u" + 'mero'
            'pagina' = "p$a" + 'gina'; 'dia' = "d$i" + 'a'; 'dias' = "d$i" + 'as'; 'podria' = "podr$i" + 'a'; 'habia' = "hab$i" + 'a'
            'tenia' = "ten$i" + 'a'; 'queria' = "quer$i" + 'a'; 'minimo' = "m$i" + 'nimo'; 'maximo' = "m$a" + 'ximo'
            'manana' = "ma$n" + 'ana'; 'segun' = "seg$u" + 'n'; 'algun' = "alg$u" + 'n'; 'ningun' = "ning$u" + 'n'
            'volvera' = "volver$a"; 'sera' = "ser$a"; 'estare' = "estar$e"; 'avisare' = "avisar$e"; 'recordare' = "recordar$e"
            'boton' = "bot$o" + 'n'; 'microfono' = "micr$o" + 'fono'; 'conexion' = "conexi$o" + 'n'; 'configuracion' = "configuraci$o" + 'n'
            'telefono' = "tel$e" + 'fono'; 'dificil' = "dif$i" + 'cil'; 'facil' = "f$a" + 'cil'
            'sabado' = "s$a" + 'bado'; 'miercoles' = "mi$e" + 'rcoles'; 'dificiles' = "dif$i" + 'ciles'; 'rapida' = "r$a" + 'pida'
        }
    }
    if (-not $script:TildesVozRe) {
        # UNA sola expresion para todas: se llama en cada frase y en cada tarjeta
        $script:TildesVozRe = New-Object System.Text.RegularExpressions.Regex(
            ('\b(?:' + (@($script:TildesVoz.Keys) -join '|') + ')\b'),
            ([System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::Compiled))
    }
    # conserva la mayuscula inicial ("Ultimo" -> "Último")
    return $script:TildesVozRe.Replace($s, {
        param($m)
        $r = $script:TildesVoz[$m.Value.ToLowerInvariant()]
        if ($m.Value -ceq $m.Value.ToUpperInvariant()) { $r = $r.ToUpperInvariant() }
        elseif ([char]::IsUpper($m.Value[0])) { $r = $r.Substring(0, 1).ToUpperInvariant() + $r.Substring(1) }
        $r
    })
}

# El texto TAL CUAL llega a la voz: espacios, tildes y el corte a 300 letras. Aparte
# porque la voz preparada (Send-PrepVoz) tiene que pedir exactamente el mismo, o no
# acierta en la cache.
# LAS PALABRAS QUE BRAYA NO AGUANTA (23/09, funcion 2 de la tanda de funciones nuevas).
# Se lo ha pedido TRES veces y seguia pasando: 20/09 23:05 "deja de decirme man, no me digas
# asi", 20/09 23:19 "deja de llamarme tio", 21/09 00:03 "deja de decir tio, no me gusta esa
# palabra, guardalo en memoria". Nova prometio dos veces que no, y el 22/09 a las 21:48:35:
# "No te sigo, tio".
# Y lo peor no es que siguiera diciendolo: es lo que APRENDIO de la queja. En memoria\perfil.md
# quedo escrito "braya habla con acento español (usa 'tio')" -el dato del reves: la muletilla
# es de ella, no de el- y esa linea viaja en el prompt de todas sus charlas, o sea que la
# queja realimentaba justo lo que molestaba.
#
# EL FILTRO VA AQUI DENTRO, NO EN Say, Y ESO IMPORTA: la charla pre-sintetiza la voz con
# Get-TextoVoz y la cachea por md5 del texto. Filtrando despues, en Say, el md5 no cuadraria y
# cada frase tocada perderia la voz ya preparada: casi un segundo por frase. Aqui, los tres
# caminos de la voz comparten el mismo texto y la capsula enseña lo mismo que se oye.
# Y SOLO LO QUE NOVA REDACTA. El correo, el OCR, los nombres de juegos o lo que ella repite de
# un dictado no se tocan: censurar un correo que dice "man" no es obedecerle, es mentirle
# sobre lo que pone en la pantalla.
$PalabrasNoPath = Join-Path $MemoriaDir 'palabras-no.json'
$script:palabrasNo = $null
function Get-PalabrasNo {
    if ($null -ne $script:palabrasNo) { return $script:palabrasNo }
    $script:palabrasNo = @()
    try {
        if (Test-Path -LiteralPath $PalabrasNoPath) {
            $script:palabrasNo = @((Get-Content -LiteralPath $PalabrasNoPath -Raw -Encoding UTF8 | ConvertFrom-Json) |
                                   Where-Object { $_ } | ForEach-Object { [string]$_ })
        }
    } catch { Log ('palabras-no: no pude leerlas: ' + $_.Exception.Message) }
    return $script:palabrasNo
}
function Save-PalabrasNo([string[]]$lista) {
    # MODO INVITADO: lo que diga otro no se queda (17/09). Esta lista son SUS palabras, las
    # que a el le molestan; un invitado no se las cambia.
    if ($script:invitado) { Log 'palabras-no: modo invitado, no guardo nada'; return }
    $script:palabrasNo = @($lista | Where-Object { $_ } | Select-Object -Unique)
    try {
        [System.IO.File]::WriteAllText($PalabrasNoPath, (ConvertTo-Json -InputObject @($script:palabrasNo) -Depth 2),
                                       (New-Object System.Text.UTF8Encoding($false)))
    } catch { Log ('palabras-no: no pude guardarlas: ' + $_.Exception.Message) }
}
function Remove-PalabrasNo([string]$texto) {
    $lista = @(Get-PalabrasNo)
    if ($lista.Count -eq 0 -or -not $texto) { return $texto }
    $t = $texto
    foreach ($p in $lista) {
        $pl = [regex]::Escape((ConvertTo-Plain $p))
        if (-not $pl) { continue }
        # PALABRA ENTERA Y SIN TILDES: "man" a secas se come mando, manda, semana y comando
        # -y Nova le lee los cuatro mandos-; y "tio" con tilde no caza el "tio" que escupe el
        # modelo la mitad de las veces. Ademas se lleva la coma del vocativo, para que
        # "No te sigo, tio." no quede como "No te sigo, .".
        $t = [regex]::Replace($t, '(?i)\s*,\s*' + $pl + '(?=[\s.,;!?]|$)', '')
        $t = [regex]::Replace($t, '(?i)\b' + $pl + '\b[\s]*', ' ')
    }
    # y la coma huerfana que queda cuando el vocativo iba al PRINCIPIO ("Tio, eso no lo se"
    # se quedaba en ", eso no lo se")
    $t = ($t -replace '\s+', ' ') -replace '\s+([.,;!?])', '$1'
    $t = $t -replace '^[\s,;:]+', ''
    if ($t.Length -gt 1) { $t = $t.Substring(0, 1).ToUpper() + $t.Substring(1) }
    return $t.Trim()
}
function Get-TextoVoz([string]$texto) {
    $t = Add-TildesVoz (Remove-PalabrasNo (($texto -replace '\s+', ' ').Trim()))
    # RESPUESTAS LARGAS ENTERAS (15/09): con el tope en 300 letras la voz se callaba a
    # mitad de una respuesta del agente ("se corta y deja de hablar") mientras la tarjeta
    # ensenaba el resto. Ahora el tope es 1.200 letras, y la voz tiene mas plazo.
    if ($t.Length -gt 1200) {
        # POR EL FINAL DE UNA FRASE (14/09): cortar a secas dejaba la voz a mitad de
        # palabra. Se busca el ultimo punto; si no, el ultimo espacio.
        $corteV = $t.Substring(0, 1200).LastIndexOfAny([char[]]'.!?;')
        if ($corteV -lt 400) { $corteV = $t.Substring(0, 1200).LastIndexOf(' ') }
        $t = if ($corteV -gt 0) { $t.Substring(0, $corteV + 1).Trim() } else { $t.Substring(0, 1200) }
    }
    return $t
}

# VOZ PREPARADA (14/09). Una frase nueva tarda ~1 s en sintetizarse (medido: 0,99 s
# de media) y una ya hecha 2 ms. La charla llega frase a frase, pero cada una se
# sintetizaba al tocarle, con ~1 s de hueco entre frase y frase. Un segundo worker
# de voz, igual que el de siempre y con la misma cache, las va preparando en cuanto
# llegan; al decirlas ya estan hechas. Escribe con .part y renombra, asi que los
# dos pueden pedir la misma sin pisarse. Su salida no se lee: no hace falta.
$script:prepVozProc = $null
function Send-PrepVoz([string]$texto, [string]$emo = '') {
    if (-not $texto -or -not $script:ttsProc -or $script:ttsProc.HasExited) { return }
    try {
        if (-not $script:prepVozProc -or $script:prepVozProc.HasExited) {
            $psiP = New-Object System.Diagnostics.ProcessStartInfo
            $psiP.FileName = $PyWorker
            $psiP.Arguments = "-u `"$TtsWorker`" $VozOnlineNombre `"$VozCache`""
            $psiP.UseShellExecute = $false
            $psiP.RedirectStandardInput = $true
            $psiP.CreateNoWindow = $true
            $psiP.WorkingDirectory = $LogDir
            $script:prepVozProc = [System.Diagnostics.Process]::Start($psiP)
            try { $script:prepVozProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
            Log "voz preparada: worker PID=$($script:prepVozProc.Id)"
        }
        $script:prepVozUltima = $sw.ElapsedMilliseconds
        $envioP = if ($emo) { "{emo:$emo} $texto" } else { $texto }
        $bytesP = [System.Text.Encoding]::UTF8.GetBytes($envioP + "`n")
        $script:prepVozProc.StandardInput.BaseStream.Write($bytesP, 0, $bytesP.Length)
        $script:prepVozProc.StandardInput.BaseStream.Flush()
    } catch { Log ("voz preparada: " + $_.Exception.Message) }
}

# EL MP3 ABIERTO ANTES DE HABLAR (22/09). Play-Audio hacia Open() y Play() pegados, y eso
# cuesta: desde el Open hasta que sale sonido pasan 464 ms de media (120 medidas en esta
# maquina; el rango 453-547 ya estaba apuntado en Play-Audio, en EL CUARTO DE SEGUNDO QUE
# SE PAGABA EN CADA FRASE). Con el mismo mp3 YA abierto en otro MediaPlayer, ese Play()
# suena en 31 ms. Son 433 ms menos por frase, y en el log de braya hay 599 frases de voz:
# 259 segundos de Nova callada esperando a que cargue un audio que ya tenia hecho.
#
# DONDE SE PUEDE PAGAR POR ADELANTADO: en la charla. Las frases llegan en cola
# (charlaFrases) y la siguiente no se dice hasta que acaba la que suena, o sea que hay
# SEGUNDOS de margen, y durante ese rato la voz preparada ya le esta haciendo el mp3. La
# ruta no hay que adivinarla: tts_worker.py (~226) la saca de md5(VOZ|[ritmo|][tono|]texto),
# asi que se calcula igual aqui y se abre en cuanto el archivo aparece.
# De las 599 frases del log, 309 llegaron "ya preparadas": esas son las que esto gana. Las
# otras 290 se sintetizan al momento, y de un mp3 que aun no existe no hay nada que abrir.
#
# SI LAS DOS CUENTAS SE SEPARAN, NO PASA NADA: Play-Audio compara con la ruta que DEVUELVE
# el worker. Un md5 que no cuadre solo significa no ganar los 433 ms.
#
# LO QUE NO SE TOCA, A PROPOSITO:
#   - el "+450" de Say-Online ($dur = $n * 50 + 450) NO es margen de cola: es esta misma
#     latencia de Open, y con ella se fija pausaHasta, que es la VENTANA DE SORDINA. Si se
#     bajara a la vez que la latencia, el instante en que Nova vuelve a escuchar se
#     adelantaria y podria oirse a si misma: eso es una orden equivocada, que es lo peor
#     que le puede pasar. Dejandolo en 450 la sordina se abre EXACTAMENTE en el mismo
#     instante de reloj que hoy (Refresh-UI no se ha movido); lo unico que cambia es que la
#     voz empieza y acaba 433 ms antes, o sea que la sordina sobra un poco al final, que es
#     el lado seguro. Y la charla encadena en el mismo instante que hoy, ni antes ni despues.
#   - el "-300" del reloj de la envolvente en nova_ui.cs (~2976) tampoco se toca, pero NO
#     por el motivo que puse aqui primero. Escribi que era "lo mismo por el lado de la
#     capsula", o sea que compensaba este Open, y es falso: el -300 entro el 11/09 en el
#     commit 866db98, seis dias ANTES de que nadie midiera Open. Nunca compenso nada de
#     esto. Y tampoco hay "boca" que se desincronice: el ecualizador de cuatro bandas se
#     quito el 12/09 porque "parecia una boca de palitos y se veia mal" (nova_ui.cs:1053),
#     y lo que queda solo mueve el resplandor y el tamano del punto entero.
#     Lo que hay de verdad, medido: desde el 11/09 ese punto late ~170 ms POR DELANTE de la
#     voz, en 599 frases y ocho dias de log, y braya no lo ha mencionado ni una vez. Esa es
#     la unica medida real de lo que se nota, y es >= 170 ms. Con el adelanto puesto pasa a
#     ir ~270 ms por detras: mas, pero del mismo orden, en un brillo y no en unos labios.
#     Asi que NO queda apuntado como paso pendiente: no hay dato que diga que molesta, y
#     cero casos en el log todavia. Si algun dia lo dice el, entonces se mide y se arregla.
function Get-RutaVozCache([string]$texto, [string]$emo = '') {
    if (-not $texto -or -not $VozCache) { return '' }
    try {
        # la misma cuenta que velocidad() en tts_worker.py (~166): el numero de
        # velocidad.txt, recortado a -50..100
        $vv = 0
        $fVel = Join-Path $VozCache 'velocidad.txt'
        if (Test-Path -LiteralPath $fVel) {
            try { $vv = [int](([System.IO.File]::ReadAllText($fVel)).Trim()) } catch { $vv = 0 }
        }
        $vv = [Math]::Max(-50, [Math]::Min(100, $vv))
        # y AJUSTE_EMOCION (~179): alegre suma 6 y sube a +6Hz; suave resta 8 y baja a -5Hz
        $tonoV = '+0Hz'
        if ($emo -eq 'alegre') { $vv = $vv + 6; $tonoV = '+6Hz' }
        elseif ($emo -eq 'suave') { $vv = $vv - 8; $tonoV = '-5Hz' }
        $vv = [Math]::Max(-50, [Math]::Min(100, $vv))
        $ritmoV = $(if ($vv -ge 0) { '+' + [string]$vv + '%' } else { [string]$vv + '%' })
        # el ritmo y el tono solo entran en la clave cuando NO son los de siempre
        $trozoR = $(if ($ritmoV -eq '+0%') { '' } else { $ritmoV + '|' })
        $trozoT = $(if ($tonoV -eq '+0Hz') { '' } else { $tonoV + '|' })
        $clave = $VozOnlineNombre + '|' + $trozoR + $trozoT + $texto
        if (-not $script:preVozMd5) { $script:preVozMd5 = [System.Security.Cryptography.MD5]::Create() }
        $hV = $script:preVozMd5.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($clave))
        return (Join-Path $VozCache ([System.BitConverter]::ToString($hV).Replace('-', '').ToLowerInvariant() + '.mp3'))
    } catch { return '' }
}

function Open-VozAdelantada {
    if ($script:charlaFrases.Count -eq 0) { return }
    try {
        $cabezaV = $script:charlaFrases.Peek()
        $crudoV = [string]$cabezaV.t
        if ($crudoV -ne $script:preVozTexto) {
            # la cabeza de la cola cambio: se calcula la ruta UNA vez y se guarda, que esto
            # corre en cada vuelta del bucle. El texto y la emocion se sacan igual que al
            # decirla de verdad (Get-TextoVoz dentro de Say, Get-EmocionFrase al sacarla de
            # la cola); si no fueran los mismos, el md5 no coincidiria y no se ganaria nada.
            $script:preVozTexto = $crudoV
            $script:preVozCalc = Get-RutaVozCache (Get-TextoVoz $crudoV) (Get-EmocionFrase $crudoV)
        }
        if (-not $script:preVozCalc) { return }
        if ($script:preVozRuta -eq $script:preVozCalc) { return }           # ya esta abierto
        if (-not (Test-Path -LiteralPath $script:preVozCalc)) { return }    # el worker aun lo esta haciendo
        if (-not $script:reproductorPrevio) {
            Add-Type -AssemblyName PresentationCore -ErrorAction Stop
            $script:reproductorPrevio = New-Object System.Windows.Media.MediaPlayer
        }
        $script:reproductorPrevio.Open([Uri]$script:preVozCalc)
        $script:preVozRuta = $script:preVozCalc
        $script:preVozDesde = $sw.ElapsedMilliseconds
    } catch { $script:preVozRuta = '' }
}

# Habla sin bloquear el bucle: la sintesis tarda ~60 ms y Play() es asincrono.
function Say([string]$texto, [string]$emo = '') {
    if (-not $texto) { return }
    $script:vozFinReal = 0
    $t = Get-TextoVoz $texto
    if ($t.Length -eq 0) { return }
    # en una llamada no se habla: la capsula lo ensena y late (ver SILENCIO EN LLAMADAS)
    if (Test-EnLlamada) {
        try { Set-UI 'hablando' $t 5000; Send-UIEvento 'pulso:llamada' } catch {}
        return
    }
    # Silenciar la escucha mientras hablamos. La reproduccion es asincrona, asi
    # que se estima la duracion por longitud del texto (~70 ms por caracter) y
    # el bucle principal reanuda al vencer el plazo.
    try {
        $script:finVoz = $sw.ElapsedMilliseconds
        $estimado = [Math]::Min(90000, ($t.Length * 70) + 1200)
        $previaV = $script:pausaHasta
        Pausar-Escucha $estimado $t
        # si fue ESTA estimacion la que alargo la pausa, Say-Online la puede acortar
        # a la duracion real del audio (ver LA PAUSA REAL)
        $script:pausaEstimadaVoz = if ($script:pausaHasta -gt $previaV) { $script:pausaHasta } else { -1 }
        # la capsula muestra lo que se dice y vuelve al reposo al callar. El
        # audio se anade despues, cuando se sabe cual es (Say-Online).
        $script:uiAudio = ''
        Set-UI 'hablando' $t ([Math]::Max($estimado, 2500))
    } catch {}
    # cadena de respaldo: si la red falla, sigue habiendo voz
    if ($script:ttsProc) { if (Say-Online $t $emo) { return } }
    # PIPER NO ARRANCABA NUNCA, Y ESTE RESPALDO NO EXISTIA (21/09). $script:piperProc
    # solo se llena en Initialize-Piper, y a Initialize-Piper no se llegaba jamas: la
    # linea de arriba de Initialize-Voz -'if ($VozMotor -eq online -and
    # (Initialize-Online)) { return }'- hace return en cuanto arranca el worker en
    # linea, y config.json tiene voz.motor = online. Asi que piperProc era $null para
    # siempre, esta linea no se cumplia nunca y Say-Piper era codigo muerto. Los 73 MB
    # de piper.exe y el modelo es-MX llevan sin usarse desde el 10/09.
    #
    # LO QUE COSTO: 20/09 23:39:12, en mitad de una charla y con braya delante.
    #   charla dice: Te esta enganchando o aun estas viendo como va la cosa?
    #   voz online: ERR [WinError 32] ... mp3.part -> mp3
    #   voz: no hay ninguna voz disponible
    # Dijo media respuesta y se callo. Ni Piper, ni Windows. Igual el 19/09 a las
    # 09:24:46 y a las 09:25:08.
    #
    # Say-Piper ya arranca Piper sola cuando piperProc esta vacio, e Initialize-Piper
    # devuelve $false en seco si faltan el .exe o el modelo: cuando la red va bien esto
    # no cuesta nada, porque Say-Online ya devolvio antes.
    if ($VozOn -and $VozMotor -ne 'windows') { if (Say-Piper $t) { return } }
    # MUDA Y SORDA HASTA 90 SEGUNDOS (17/09). La pausa se fija ARRIBA, por cuenta de
    # letras y antes de saber si va a sonar algo: con el tope de 1.200 letras de
    # Get-TextoVoz son 85 s. Solo Say-Online la corrige. Si no hay voz ninguna se salia
    # por aqui dejando el plazo entero: el worker ignorando el microfono, la capsula en
    # 'hablando' moviendo la boca en silencio (Tic33 simula silabas si no hay envolvente)
    # y "callate" sin servir, porque tambien pasa por el microfono pausado. Un modo
    # pegado de los peores.
    #
    # Se reanuda SIN -Forzar a proposito: si braya dijo "no me escuches media hora", eso
    # manda y Reanudar-Escucha lo respeta. Aqui solo se deshace lo que puso esta frase.
    if (-not $script:vozSyn) {
        Log "voz: no hay ninguna voz disponible; no me quedo sorda esperando a un audio que no va a sonar"
        $script:pausaEstimadaVoz = -1
        Reanudar-Escucha
        $script:uiHasta = 0
        Set-UI 'reposo'
        return
    }
    try {
        $st = Await-Voz ($script:vozSyn.SynthesizeTextToStreamAsync($t)) ([Windows.Media.SpeechSynthesis.SpeechSynthesisStream])
        if (-not $st) { return }
        $dr = New-Object Windows.Storage.Streams.DataReader($st.GetInputStreamAt(0))
        [void](Await-Voz ($dr.LoadAsync([uint32]$st.Size)) ([uint32]))
        $bytes = New-Object byte[] $st.Size
        $dr.ReadBytes($bytes)
        $wav = Join-Path $TmpDir "voz.wav"
        [System.IO.File]::WriteAllBytes($wav, $bytes)
        $script:vozPlayer.SoundLocation = $wav
        $script:vozPlayer.Load()
        $script:vozPlayer.Play()
    } catch {
        Log ("voz error: " + $_.Exception.Message)
    }
}

# =====================================================================
# ESCUCHA CONTINUA (palabra de activacion)
# Motor SAPI en es-ES, offline. La gramatica es CERRADA: solo el nombre y sus
# variantes. Cuanto mas cerrada, menos falsos disparos, porque el motor no
# tiene otra cosa con la que confundirse. Verificado que rechaza "abre steam",
# "que hora es" y hasta "no va a llover", que foneticamente se le parece.
# =====================================================================
$EscuchaOn = [bool](Get-Cfg 'escucha' 'activada' $true)
$EscuchaNombre = [string](Get-Cfg 'escucha' 'nombre' 'nova')
$EscuchaConf = [double](Get-Cfg 'escucha' 'confianzaMinima' 0.65)
$EscuchaMotor = [string](Get-Cfg 'escucha' 'motor' 'vosk')
# ganancia por software: 'auto' mide el pico real y se ajusta sola
$EscuchaGanancia = [string](Get-Cfg 'escucha' 'ganancia' 'auto')
$script:wakeProc = $null
$script:vozWinProc = $null
$script:vozWinCheck = 0
$script:vozWinIntentos = 0
$script:finVoz = 0
$MarcaWake = Join-Path $TmpDir "despierta.flag"
# Mientras exista esta marca, el worker ignora el microfono. Se crea al hablar
# y al dictar: la voz del propio asistente volvia al microfono con pico 0.99 y
# hundia su ganancia automatica, dejandolo sordo.
$MarcaPausa = Join-Path $TmpDir "escucha-pausa.flag"
# --- DICTADO POR VOSK (sustituye a Win+H) ---
# Win+H era el origen de casi todos los fallos: robaba el foco -y si fallaba,
# el texto se escribia en OTRA ventana-, deformaba palabras ("steamidos",
# "little nighters 3") y obligaba a esperar el silencio desde fuera. El worker
# ya tiene el microfono abierto: dicta el tambien.
$MotorDictado = [string](Get-Cfg 'input' 'dictado' 'vosk')
# MODO DE SEGUIMIENTO: tras responder, se vuelve a escuchar durante este
# tiempo SIN palabra de activacion. Si hablas, es otra orden; si no, se cierra
# en silencio. Permite encadenar: "nova, abre steam" ... "y sube el volumen"
# ... "y avisame en veinte minutos". 0 = desactivado. Solo con el dictado del
# worker (whisper/vosk): Win+H no puede esperar sin robar el foco.
$SeguimientoMs = [int](Get-Cfg 'input' 'seguimientoMs' 2500)
# CORTAR LA CADENA (20/09). En seguimiento no hace falta decir 'nova', asi que el
# umbral de rafaga (escucha.rafagaMinima = 0.030) no filtra nada ahi: anoche 5
# activaciones falsas dieron 14 grabaciones de una conversacion privada. Con esto en
# false (lo normal) el microfono no se reabre solo detras de un final en nada. En true
# vuelve la segunda oportunidad que pidio braya el 15/09, pero UNA sola vez y nunca
# encadenando seguimiento sobre seguimiento.
$SeguimientoTrasSeco = [bool](Get-Cfg 'escucha' 'seguimientoTrasSeco' $false)
# 'vosk' y 'whisper' comparten el camino: el worker de escucha graba la orden
# y la transcribe (Whisper es mucho mas preciso; Vosk pequeno se queda para
# la palabra de activacion). 'windows' es Win+H.
$DictadoWorker = ($MotorDictado -in @('vosk', 'whisper'))
$WhisperModelo = [string](Get-Cfg 'input' 'whisperModelo' 'small')
# Modelo de repaso: el rapido dicta, y solo cuando la orden no se reconoce se
# repasa el MISMO audio con este (mas lento, bastante mas preciso con los
# nombres propios). Vacio = desactivado, se dicta solo con el rapido.
$WhisperPreciso = [string](Get-Cfg 'input' 'whisperModeloPreciso' '')
# ULTIMO RECURSO (15/09): si ni el rapido ni el preciso entienden la orden, se repasa con
# este (~12 s). Vacio = desactivado. Ver Request-UltimoRecurso.
# EL TURBO, APAGADO DESDE EL 15/09 Y CON SU CUENTA AL LADO (24/09, idea 17 de la tanda nueva).
#
# El commit 446acb1 lo apago poniendo whisperModeloUltimo a vacio, y lleva nueve dias sin
# usarse. NO se borra el codigo: esta apagado por CONFIG, asi que braya puede volver a
# encenderlo hablando, y borrarlo le quitaria esa opcion.
#
# PERO SI SE DEJA AQUI LO QUE CUESTA, porque el que lo encienda dentro de un mes no va a ir a
# buscarlo al registro. Las 29 peticiones que hubo, todas del 15/09:
#     de que entra a que sale:  25 s de mediana, 61 s el peor, 721 s (12 min) en 29 frases
#     cargas del modelo grande: 17, de las que QUINCE se soltaron sin usarse, con la VRAM a 4 GB
#
# Y la otra cara, que tambien conviene que este: no era "1 de 29". De los 27 'turbo-nada',
# solo UNO murio de verdad; en CATORCE el turbo impuso su transcripcion porque era mejor
# ("Coladojara y abre Steam" -> "Calculadora, y abre Steam"). O sea 15 de 29 (52 %).
# Es caro, no inutil.
$WhisperUltimo = [string](Get-Cfg 'input' 'whisperModeloUltimo' 'large-v3-turbo')
# OJO (15/09): vacio se le pasa a la escucha como '-'. Con un argumento vacio Start-Process
# falla y la escucha NO arranca (paso al apagar turbo en uso real).
# LO QUE DECIDIO SOLA Y AUN SE PUEDE DESHACER HABLANDO (ver Undo-DecisionPropia). Aqui si
# vale Get-Cfg: $cfg acaba de cargarse del archivo.
try {
    $dGuardada = [string](Get-Cfg 'auto' 'ultimaDecision' '')
    if ($dGuardada) {
        $pD = $dGuardada -split '\|', 4
        if ($pD.Count -eq 4) { $script:autoDecision = @{ seccion = $pD[0]; clave = $pD[1]; antes = $pD[2]; que = $pD[3] } }
    }
    # Y LO QUE BRAYA LE DEVOLVIO (23/09, idea 13). Sin esto, el "deshaz" duraba lo que durara
    # la sesion, o sea 5,8 minutos de mediana, y al siguiente arranque Nova lo volvia a apagar.
    $devG = [string](Get-Cfg 'auto' 'devueltas' '')
    if ($devG) {
        foreach ($parG in ($devG -split ';')) {
            $kvG = $parG -split '=', 2
            if ($kvG.Count -eq 2 -and $kvG[0]) { $script:decisionDevueltas[$kvG[0]] = $kvG[1] }
        }
    }
} catch {}
$MarcaDictar = Join-Path $TmpDir "dictar.flag"
# confirmacion por voz de coincidencias dudosas: el worker escucha si/no
$MarcaConfirmar = Join-Path $TmpDir "confirmar.flag"
# PARAR LIMPIO (18/09): tools\parar-nova.ps1 deja esta marca y el bucle sale por exit, que
# es lo unico que dispara PowerShell.Exiting (un Stop-Process no lo hace). Antes la unica
# forma de parar a Nova era matarla, y la linea "VoiceAssistant cerrado" no salia nunca.
$MarcaSalir = Join-Path $TmpDir "salir.flag"
$RutaConfirmacion = Join-Path $TmpDir "confirmacion.txt"
# NO ES "para que Whisper acierte los nombres" (22/09): eso es lo que ponia aqui, y hace
# once dias que no es verdad. Whisper no lee este fichero desde el 11/09 (su initial_prompt
# es PROMPT_ORDENES, sin nombres propios) y la escucha dejo de abrirlo el 19/09, cuando se
# quito leer_vocabulario(). Se sigue pasando en argv[13] y se sigue escribiendo, y el unico
# que lo lee hoy es tools\probar-audio.py, que es justo la herramienta que compara Whisper
# CON y SIN estas pistas. Por eso no se borra: borrarlo dejaria esa medicion sin la mitad
# que compara. Ver LA FIRMA DE LA ALUCINACION DE WHISPER para por que se quitaron.
$RutaVocabulario = Join-Path $TmpDir "vocabulario.txt"
$RutaDictado = Join-Path $TmpDir "dictado.txt"
$RutaParcial = Join-Path $TmpDir "dictado-parcial.txt"
# LO QUE OYO CADA MOTOR DE LA MISMA FRASE (25/09, idea de braya: "lo que entienden todos los
# modelos deberia enviarse y una IA como Claude debe armar la frase entera de ser necesario").
#
# POR QUE SALE CASI GRATIS: cuando el reconocedor local no entiende una orden, Nova YA llama a
# Claude para traducirla -SUBMIT (traducir), 1,5 s medidos el 25/09-. Hoy le manda UNA frase, y
# a veces es la peor que tenia. Darle las tres candidatas es la MISMA llamada con mas
# informacion: ni una peticion mas, ni un segundo mas.
#
# EL CASO QUE LO PIDE, del 25/09 a la 01:25: Parakeet oyo bien el nombre de un amigo de braya y
# la cobertura descarto esa transcripcion por DOS DECIMAS (3,8 letras por segundo contra un
# liston de 4,0, porque braya hablaba algo mas despacio de lo normal). Viajo la de Whisper, que
# habia convertido ese nombre en "base". Con "base" dentro, Claude no podia adivinar nada y
# Nova contesto que no sabia. Con las dos delante, si puede.
$RutaOidos = Join-Path $TmpDir "dictado-oidos.txt"
function Get-OtrosOidos([string]$principal, [string]$ruta = $RutaOidos) {
    if (-not $ruta -or -not (Test-Path -LiteralPath $ruta)) { return '' }
    $lineas = @()
    try {
        $lineas = @(Get-Content -LiteralPath $ruta -Encoding UTF8 | Where-Object { $_.Trim() })
    } catch { return '' }
    # SE CONSUME AL LEERLA. Unas candidatas de hace tres ordenes no ayudan: harian que Nova
    # contestara a lo de antes. El oido las reescribe en cada dictado, pero si por lo que sea
    # no llegara a hacerlo, aqui se cierra la puerta igual.
    try { Remove-Item -LiteralPath $ruta -Force -ErrorAction SilentlyContinue } catch {}
    $plano = (ConvertTo-Plain $principal).ToLower().Trim()
    $utiles = @()
    foreach ($l in $lineas) {
        $t = ($l -replace '^[a-z-]+:\s*', '').Trim()
        if (-not $t) { continue }
        # la que ya se probo no es una segunda opinion
        if ((ConvertTo-Plain $t).ToLower().Trim() -eq $plano) { continue }
        if ($utiles -contains $l) { continue }
        $utiles += $l
    }
    if ($utiles.Count -eq 0) { return '' }
    return ("LO QUE OYERON LOS OTROS MOTORES de esa misma frase (el microfono es imperfecto y" +
            " cada motor se equivoca en cosas distintas):`n" + ($utiles -join "`n") +
            "`nSi la frase de arriba no tiene sentido y alguna de estas si, o si juntandolas se" +
            " entiende lo que pedia, usa eso. Son la MISMA frase oida de varias maneras: no las" +
            " trates como peticiones distintas ni contestes a varias. Si la de arriba ya se" +
            " entiende sola, IGNORA esta lista entera.")
}
# YA NO TE OYE, AUNQUE LA ONDA SIGA MOVIENDOSE (22/09). La escucha crea esta marca en
# el instante en que cierra el microfono y la borra justo antes de dejar el texto:
# mientras existe, esta transcribiendo y esta sorda. Sin ella la capsula se quedaba en
# 'escuchando' -onda verde animada y ojos atentos- una media de 3,48 s por orden
# (mediana 2,0 s, p90 7,0 s, maximo 37 s; 229 de 412 por encima de dos segundos): 1.434
# segundos en total diciendo "sigue, te escucho" a alguien que ya habia terminado.
$RutaTranscribiendo = Join-Path $TmpDir "transcribiendo.flag"
# $true en cuanto se ha visto esa marca en el dictado de ahora; Start-Dictado lo baja
$script:dictaSordo = $false
# la orden ya se entiende entera: la escucha cierra la frase antes (ver SILENCIO_FIN_LOTENGO)
$RutaLoTengo = Join-Path $TmpDir "lotengo.txt"
$RutaEstado = Join-Path $TmpDir "escucha-estado.txt"
# EL FICHERO DEL LATIDO (24/09, idea 19): lo escribe el oido con anota_latido, y desde la idea
# 7 tambien la serie de la bateria. El nombre se calcula igual que alli -el del log con
# "-pulso" detras- para que los dos escriban en el mismo sitio sin ponerse de acuerdo.
$PulsoPath = [System.IO.Path]::ChangeExtension($EventLog, $null).TrimEnd('.') + '-pulso.log'
# --- DICTADO CON EL MOTOR DE WINDOWS (el de Win+H, sin su ventana) ---
# Convive con Whisper en vez de sustituirlo: los dos oyen la misma orden y
# se prefiere lo que diga Windows SI dice algo. Esa API escucha el microfono
# ella misma y no acepta audio amplificado, asi que puede no oir este micro,
# que entra a 0.02-0.05; por eso viene apagado y por eso hay respaldo.
$VozWindowsOn = [bool](Get-Cfg 'input' 'vozWindows' $false)
$RutaDictadoWin = Join-Path $TmpDir "dictado-winrt.txt"
# Mientras hay un juego delante, la palabra de activacion se apaga y solo vale
# el boton. Es cuando mas molesta equivocarse -el 11/09 abrio un juego solo en
# mitad de una partida- y cuando el boton del mando esta mas a mano.
$MarcaSoloBoton = Join-Path $TmpDir "solo-boton.flag"
$SoloBotonEnJuego = [bool](Get-Cfg 'escucha' 'soloBotonEnJuego' $true)
# QUE SOLO TE OBEDEZCA A TI. El tono de cada orden dictada ya se estimaba y se
# guardaba (tmp\voces.json); nadie lo usaba para nada. Si la orden viene de una
# voz que no se parece a la tuya, no se ejecuta: se pregunta. Es la defensa que
# faltaba contra el audio de un video CON VOZ HUMANA, que es el unico ruido que
# los filtros de hoy no distinguen (no es voz sintetica ni ruido: es una voz de
# verdad diciendo palabras de verdad).
# El margen es ancho a proposito: tu propia voz se mueve al susurrar, al gritar
# o resfriado, y preguntar de mas es peor que no preguntar. Con 35 Hz, una voz
# de video a 230 Hz salta y tu mismo hablando algo mas agudo no.
$SoloYoOn = [bool](Get-Cfg 'escucha' 'soloYo' $true)
$InterrumpirOn = [bool](Get-Cfg 'escucha' 'interrumpir' $true)   # ver INTERRUMPIR A NOVA
$SoloYoMargen = [double](Get-Cfg 'escucha' 'soloYoMargenHz' 35)
$SoloYoMinimo = [int](Get-Cfg 'escucha' 'soloYoMinimo' 12)
$MarcaReintento = Join-Path $TmpDir "reintentar.flag"
# una orden ESCRITA en vez de dicha (tools\decir.ps1): para probar sin hablar
$RutaOrdenEscrita = Join-Path $TmpDir "orden-escrita.txt"
$RutaReintento = Join-Path $TmpDir "reintento.txt"
# nivel de voz 0..1 que el worker escribe mientras dictas; lo lee la interfaz
# directamente (nova_ui.exe busca ui-nivel.txt junto a ui-estado.json)
$RutaNivel = Join-Path $TmpDir "ui-nivel.txt"

# MARCAS HUERFANAS. Si el asistente murio de golpe -taskkill, cierre de sesion,
# un cuelgue- sus marcas se quedan puestas y el worker nuevo las obedece como si
# fueran de ahora. La peor con diferencia es escucha-pausa.flag: el worker nace
# SORDO, tirando todo el audio, y no hay forma de sacarlo de ahi hablando,
# porque justamente no oye. Reanudar-Escucha solo la borra si pausaHasta > 0, y
# en un proceso recien arrancado vale 0, asi que se quedaba puesta para siempre.
# Una dictar.flag huerfana es mas leve pero tambien molesta: el worker se pone a
# grabar una orden que nadie esta dictando. Se limpian todas al arrancar.
# Restos de peticiones al agente que se cancelaron a mitad (manteniendo el
# boton): el runner muere antes de borrar sus in-/out-/err-/raw- y se quedan
# ahi para siempre. Se barren los de hace mas de un dia, nunca los recientes,
# que pueden estar en uso ahora mismo.
# UNA SOLA NOVA, Y ANTES DE TOCAR tmp\ (auditoria del 13/09): el candado estaba
# mas abajo, asi que una segunda copia (la clave Run mas un arranque a mano)
# borraba las marcas de la que ya funcionaba -le quitaba la pausa mientras
# hablaba- y solo despues se daba cuenta de que sobraba.
$mutex = $null
if (-not $Probar) {
    $mutex = New-Object System.Threading.Mutex($false, "Local\VoiceAssistant")
    if (-not $mutex.WaitOne(0)) {
        Write-Output "VoiceAssistant ya esta ejecutandose."
        exit 0
    }
    # workers de una sesion anterior que se quedaron huerfanos (su asistente ya
    # no existe): siguen con el microfono y al arrancar habria dos escuchando
    try {
        # OJO CON EL NOMBRE DEL PROCESO (17/09): esto filtraba Name='python.exe', pero
        # los workers se lanzan con pythonw.exe desde el 14/09 (ver $PyWorker), asi que
        # este barrido llevaba tres dias sin encontrar NI UNO. El log acumulaba 30
        # relanzamientos y 31 marcas huerfanas, y cada worker vivo se queda con el
        # microfono y con su RAM en una maquina de 8 GB. Faltaba ademas charla_worker.py,
        # que es el que mas memoria gasta de los tres.
        # Y FALTABA voz_windows.py (24/09): la lista se escribio el 17/09 a las 16:34 y el
        # worker del dictado de Windows existe desde el 11/09 a las 23:00, asi que no fue
        # un desfase sino un olvido. Es una lista cerrada que el diseno amplio: cada vez
        # que se anada un worker residente hay que anadirlo aqui Y al parar limpio.
        foreach ($wo in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
                          Where-Object { $_.Name -in @('python.exe', 'pythonw.exe') -and $_.CommandLine -and
                                         ($_.CommandLine -match 'wake_vosk\.py' -or $_.CommandLine -match 'tts_worker\.py' -or
                                          $_.CommandLine -match 'charla_worker\.py' -or $_.CommandLine -match 'voz_windows\.py') })) {
            if (-not (Get-Process -Id $wo.ProcessId -ErrorAction SilentlyContinue)) { continue }
            if (-not (Get-Process -Id $wo.ParentProcessId -ErrorAction SilentlyContinue)) {
                Stop-Process -Id $wo.ProcessId -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
}
try {
    $limite = (Get-Date).AddDays(-1)
    $restos = @(Get-ChildItem -LiteralPath $TmpDir -File -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -match '^(?:in|out|err|raw)-[0-9a-f]{16,}' -and $_.LastWriteTime -lt $limite })
    # tampoco en el banco: podrian ser los de una orden VIVA del asistente
    if ($restos.Count -gt 0 -and -not $Probar) {
        $restos | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
        Log "limpieza: $($restos.Count) restos de ordenes canceladas"
    }
} catch {}

# NO en el banco (-Probar): tmp\ es el MISMO que usa el asistente encendido, y
# borrarle las marcas le quitaba la pausa mientras hablaba (se oia a si mismo,
# 12/09 22:20) o le cancelaba un dictado o una confirmacion en curso.
foreach ($m in $(if ($Probar) { @() } else { @($MarcaPausa, $MarcaSoloBoton, $MarcaDictar, $MarcaConfirmar, $MarcaReintento, $MarcaWake, $MarcaSalir) })) {
    if (Test-Path -LiteralPath $m) {
        Log "marca huerfana de la sesion anterior: $(Split-Path -Leaf $m)"
        try { Remove-Item -LiteralPath $m -Force -ErrorAction SilentlyContinue } catch {}
    }
}
$script:pausaHasta = 0

function Pausar-Escucha([int]$ms, [string]$voz = '') {
    try {
        # INTERRUMPIR A NOVA (M5): si la pausa es porque habla, la marca lleva lo que
        # dice. El worker escucha solo "espera", "para", "calla"... y descarta la
        # palabra si esta en la propia frase (sin eso se cortaria con su eco)
        # Y NO EN SORDINA (21/09). La sordina pone la pausa larga SIN texto -marca 'x'-,
        # pero justo despues Say dice 'me callo media hora, si me necesitas antes manten
        # el boton' y vuelve a pasar por aqui CON texto: la marca se reescribia como
        # 'voz:...' y ahi se quedaba los treinta minutos enteros, porque $pausaHasta no
        # cambia (la sordina es mas larga).
        # Con la marca en 'voz:', vigilar_corte sigue corriendo un reconocedor sobre CADA
        # bloque de audio media hora, y acepta 'nova', 'para', 'calla'... o sea que decir
        # 'nova' abria el microfono y sonaba el tic mientras escucha-pausa.flag seguia en
        # disco: la sordina rota y Nova a medio despertar. Justo lo que braya pidio que
        # NO pasara al decir 'no me escuches media hora'.
        # Lo unico que se pierde es cortar con la voz la frase 'me callo media hora', que
        # dura dos segundos y para la que esta el boton.
        # Y EN SORDINA, 'nombre:' (22/09). La marca decia 'x', que en el worker significa
        # "no escuches nada": ni siquiera su nombre la sacaba de ahi, solo el boton. braya
        # pidio lo contrario -"hasta que la vuelva a llamar"-, asi que mientras esta callada
        # la marca lleva su nombre y el worker corre un reconocedor que SOLO conoce esa
        # palabra. Las de corte ('para', 'calla') siguen fuera: son para interrumpirla
        # mientras habla, no para despertarla.
        $marcaTxt = if ($voz -and $InterrumpirOn -and $script:sordinaHasta -le $sw.ElapsedMilliseconds) { 'voz:' + (ConvertTo-Plain $voz) }
                    elseif ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { 'nombre:' + (ConvertTo-Plain $EscuchaNombre) }
                    else { 'x' }
        [System.IO.File]::WriteAllText($MarcaPausa, $marcaTxt)
        $fin = $sw.ElapsedMilliseconds + $ms
        if ($fin -gt $script:pausaHasta) { $script:pausaHasta = $fin }
    } catch {}
}

# QUE SIGNIFICA UN CORTE (24/09, idea 2 de la tanda nueva). Pura y aparte para que el
# banco pueda recorrer las seis combinaciones en un milisegundo, y sobre todo para que
# NINGUNA se quede sin rama: el fallo de los quince dias fue justo que habia dos ramas y
# tres situaciones posibles.
# LAS CINCO SALIDAS Y NINGUNA MAS:
#   en sordina + su nombre        -> vuelve entera (lo de siempre)
#   en sordina + otra palabra     -> tarde: en sordina no esta hablando
#   dictado abierto               -> se cancela el dictado   <- LO QUE FALTABA
#   hablando + su nombre          -> se calla y abre el microfono
#   hablando + otra palabra       -> se calla y NO abre el microfono
#   ni hablando ni dictando       -> tarde
function Resolve-Corte([string]$palabra, [string]$nombre, [bool]$armado, [bool]$enPausa, [bool]$enSordina) {
    $esNombre = ((ConvertTo-Plain $palabra) -eq (ConvertTo-Plain $nombre))
    if ($enSordina) {
        if ($esNombre) { return @{ accion = 'sordina-vuelve'; abreMicro = $true; estadistica = 'sordina-nombre' } }
        return @{ accion = 'tarde'; abreMicro = $false; estadistica = 'corte-tarde' }
    }
    # EL DICTADO MANDA SOBRE LA PAUSA: si hay uno abierto, lo que se pide es cancelarlo,
    # y da igual que ademas estuviera hablando.
    if ($armado) { return @{ accion = 'cancela-dictado'; abreMicro = $false; estadistica = 'corte-dictado' } }
    if ($enPausa) {
        if ($esNombre) { return @{ accion = 'corta-y-escucha'; abreMicro = $true; estadistica = 'corte-nombre' } }
        return @{ accion = 'corta-y-calla'; abreMicro = $false; estadistica = 'corte-callar' }
    }
    return @{ accion = 'tarde'; abreMicro = $false; estadistica = 'corte-tarde' }
}

function Reanudar-Escucha([switch]$Forzar) {
    # CON LA SORDINA PUESTA NO SE REANUDA (auditoria del 13/09): "no me escuches
    # media hora" se levantaba en cuanto Nova terminaba de decir "vale". Solo la
    # levanta quien lo pide a proposito (-Forzar: el dictado con el boton).
    if (-not $Forzar -and $script:sordinaHasta -gt $sw.ElapsedMilliseconds) { $script:pausaHasta = 0; return }
    try { Remove-Item -LiteralPath $MarcaPausa -Force -ErrorAction SilentlyContinue } catch {}
    $script:pausaHasta = 0
}

function Initialize-Escucha {
    if (-not $EscuchaOn) { Log "escucha continua desactivada por configuracion"; return }
    # DOS MOTORES POSIBLES:
    #  vosk (por defecto): lee el microfono en Python y AMPLIFICA por software.
    #    En esta maquina el microfono entra muy bajo (prueba de Windows: 7 %) y
    #    SAPI lo tomaba por silencio. Vosk da acceso al audio crudo, asi que la
    #    ganancia se puede corregir; SAPI no lo permitia.
    #  sapi: worker en C# (wake_worker.exe). Se conserva como alternativa.
    #    OJO: NO puede ser un script de PowerShell. PowerShell no soporta los
    #    eventos asincronos de SAPI: el manejador corre en el hilo del
    #    reconocedor y mata el proceso en silencio. Comprobado dos veces.
    try {
        Remove-Item -LiteralPath $MarcaWake -Force -ErrorAction SilentlyContinue
        if ($EscuchaMotor -eq 'vosk') {
            # el worker vigila que este proceso siga vivo: si muere, sale y suelta
            # el microfono en vez de quedarse escuchando huerfano (auditoria 13/09)
            $env:NOVA_PID_PADRE = "$PID"
            $worker = Join-Path $LogDir "wake_vosk.py"
            if (-not (Test-Path -LiteralPath $worker)) { Log "WARN: falta wake_vosk.py"; Add-FalloArranque 'no puedo oirte por la palabra, solo con el boton'; return }
            # La confianza minima va TAMBIEN aqui: hasta ahora solo la recibia el
            # wake_worker.exe viejo, asi que el ajuste del config no hacia nada.
            $conf = $EscuchaConf.ToString([System.Globalization.CultureInfo]::InvariantCulture)
            # LA RAFAGA MINIMA PARA LA PALABRA DE DESPERTAR (20/09). Ver LA RAFAGA QUE DE
            # VERDAD TE DELATA en wake_vosk.py: con 0.008 Nova se activaba sola oyendo una
            # conversacion de fondo. Se pasa como argumento 21 para poder bajarlo desde
            # config.json (escucha.rafagaMinima) si alguna vez no le oye al llamarla flojo.
            $rafagaMin = ([double](Get-Cfg 'escucha' 'rafagaMinima' 0.03)).ToString([System.Globalization.CultureInfo]::InvariantCulture)
            # EL JUEZ DE SEGUNDA ETAPA (20/09/2026). Ver EL JUEZ DEL NOMBRE en wake_vosk.py:
            # la gramatica de Vosk es CERRADA y esta OBLIGADA a devolver algo de su lista ante
            # cualquier ruido, y por eso la madrugada del 20/09 Nova grabo 70 s de una
            # conversacion privada sin que braya dijera su nombre. El juez es el mismo modelo
            # sin gramatica, escuchando en paralelo: no carga nada ni anade espera al llamarla.
            # Argumento 22. Se estrena en 'mirar' porque todavia no hay medida: la rafaga del
            # nombre no se guarda en pruebas\audio\uso, asi que el unico sitio donde se puede
            # medir es el log de un dia de uso real. Valores: 'si', 'mirar', 'no'.
            $juezNombre = [string](Get-Cfg 'escucha' 'juezNombre' 'mirar')
            if ([string]::IsNullOrWhiteSpace($juezNombre)) { $juezNombre = 'mirar' }
            # EL STDERR DEL WORKER, A UN ARCHIVO. El 12/09 murio tres veces sin
            # dejar ni una linea (se lanzaba sin redirigir nada). Y lo que dejo
            # la vez anterior se pasa al log ANTES de relanzar, porque la
            # redireccion vacia el archivo justo cuando mas falta hace.
            $rutaErrWorker = Join-Path $TmpDir 'wake-err.log'
            try {
                if ((Test-Path -LiteralPath $rutaErrWorker) -and (Get-Item -LiteralPath $rutaErrWorker).Length -gt 0) {
                    $errViejo = ([System.IO.File]::ReadAllText($rutaErrWorker)).Trim()
                    if ($errViejo) { Log ("worker de escucha, su salida de error la vez anterior: " + $errViejo.Substring([Math]::Max(0, $errViejo.Length - 2000))) }
                }
            } catch {}
            $script:wakeProc = Start-Process -FilePath $PyWorker `
                -ArgumentList @('-u', $worker, $EscuchaNombre, $MarcaWake, $EventLog, $EscuchaGanancia,
                                $MarcaPausa, $MarcaDictar, $RutaDictado, $RutaParcial, $RutaNivel,
                                $MarcaConfirmar, $RutaConfirmacion, "$MotorDictado`:$WhisperModelo", $RutaVocabulario,
                                $conf, $MarcaReintento, $RutaReintento, $(if ($WhisperPreciso) { $WhisperPreciso } else { '-' }), $(if ($WhisperUltimo) { $WhisperUltimo } else { '-' }), $rafagaMin, $juezNombre) `
                -WorkingDirectory $LogDir -WindowStyle Hidden -PassThru `
                -RedirectStandardError $rutaErrWorker
        } else {
            $worker = Join-Path $LogDir "wake_worker.exe"
            if (-not (Test-Path -LiteralPath $worker)) { Log "WARN: falta wake_worker.exe"; return }
            $conf = $EscuchaConf.ToString([System.Globalization.CultureInfo]::InvariantCulture)
            $script:wakeProc = Start-Process -FilePath $worker `
                -ArgumentList @($EscuchaNombre, $conf, $MarcaWake, $EventLog) `
                -WindowStyle Hidden -PassThru
        }
        $null = $script:wakeProc.Handle
        # el oido de Windows, si esta activado: otro proceso aparte, que mira
        # la MISMA marca de dictado y escribe en su propio archivo
        if ($VozWindowsOn) {
            $wv = Join-Path $LogDir "voz_windows.py"
            if (Test-Path -LiteralPath $wv) {
                try {
                    # DE QUIEN ES HIJO (24/09). Sin esto el worker no puede saber que se ha
                    # quedado solo: el 24/09 Nova murio a las 21:53 y media hora despues habia
                    # 44 de estos vivos comiendo 1,3 GB mientras braya jugaba.
                    # SE PONE AQUI Y NO SOLO ARRIBA A PROPOSITO: la linea de mas arriba esta
                    # dentro de "if (EscuchaMotor -eq 'vosk')", y este bloque esta fuera de esa
                    # rama. Hoy el motor es vosk y por eso la variable llegaba de casualidad;
                    # con cualquier otro motor el dictado se quedaba sin proteger.
                    $env:NOVA_PID_PADRE = "$PID"
                    $script:vozWinProc = Start-Process -FilePath $PyWorker `
                        -ArgumentList @('-u', $wv, $MarcaDictar, $RutaDictadoWin, $EventLog, 'es-ES') `
                        -WorkingDirectory $LogDir -WindowStyle Hidden -PassThru
                    $null = $script:vozWinProc.Handle
                    try { $script:vozWinProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
                    Log "dictado de Windows ACTIVO (worker PID=$($script:vozWinProc.Id))"
                } catch { Log ("WARN: no arranco el dictado de Windows: " + $_.Exception.Message) }
            } else { Log "WARN: falta voz_windows.py" }
        }
        # Es un portatil de JUEGOS: la escucha nunca debe competir por CPU con
        # el juego en primer plano.
        try { $script:wakeProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
        $script:wakeDesde = $sw.ElapsedMilliseconds
        # PARA MEDIR CUANTO TARDA EN OIR (23/09, idea 12): sin esto no hay forma de saber si
        # mover la carga a un hilo arreglaria algo o pagaria la primera orden por nada.
        $script:oidoMarcaPuesta = $sw.ElapsedMilliseconds
        $script:oidoApuntado = $false
        $script:oidoListoEn = 0
        $script:oidoProntoDicho = $false
        # LA MARCA LA PONE QUIEN LLEGA PRIMERO (20/09, H5m4). La escribia el worker justo
        # antes de cargar Whisper, y en el arranque de las 13:28 llego DOS SEGUNDOS tarde:
        # el saludo ya habia salido. Aqui no hay carrera posible, porque esto pasa antes
        # de lanzar nada que tarde. La borra el worker cuando ya oye de verdad.
        try { [System.IO.File]::WriteAllText((Join-Path $TmpDir 'oido-cargando.txt'), $EscuchaMotor) } catch {}
        Log "escucha continua ACTIVA [$EscuchaMotor] (worker PID=$($script:wakeProc.Id)): di '$EscuchaNombre'"
    } catch {
        Log ("WARN: escucha continua no arranco: " + $_.Exception.Message)
        $script:wakeProc = $null
    }
}

# =====================================================================
# INTERFAZ (nova_ui.exe): la cara visible del asistente
# Una capsula de cristal en la esquina inferior izquierda que vive en su
# propio proceso WPF. Aqui NO se dibuja nada: solo se escribe un JSON con el
# estado y la interfaz lo lee cada 80 ms. Mismo patron de archivos que los
# workers de voz y escucha; cero hilos compartidos con este bucle.
#
# La barra antigua de WinForms sigue existiendo porque el dictado de Windows
# necesita una ventana con foco donde escribir, pero se vuelve invisible
# (opacidad minima) cuando la interfaz nueva esta activa.
# =====================================================================
$UiNuevaOn = [bool](Get-Cfg 'ui' 'nueva' $true)
# EL MICROFONO NO SE ABRE EN SILENCIO (20/09/2026). Esa madrugada Nova se
# activo sola 5 veces en 12 minutos y grabo 70 s de una conversacion privada;
# las 5 activaciones se volvieron 14 grabaciones porque el seguimiento reabre
# la escucha solo y lo hacia SIN sonido (9 de las 14 entraron por esa puerta).
# La regla de Alexa es que el indicador suena CADA vez que se abre el micro,
# sin excepcion: si suena, se oye que esta grabando y se puede cortar. El tono
# es el sonTic que la capsula ya tiene (1320 Hz, 25 ms): corto para no pisar
# la frase. Si molesta, ui.ticMicro = false y vuelve a callar.
$TicMicroOn = [bool](Get-Cfg 'ui' 'ticMicro' $true)
$RutaUiEstado = Join-Path $TmpDir "ui-estado.json"
$script:uiProc = $null
$script:uiUltimo = ''
$script:uiHasta = 0     # cuando vence, la capsula vuelve al reposo
$script:uiCheck = 0
$script:uiIntentos = 0

# Estados: reposo | escuchando | pensando | hablando | error.
# $ms > 0: volver al reposo pasado ese tiempo (si no hay nada mas en marcha).
# Ademas del estado, el JSON lleva:
#   evento/n : animacion puntual (despierta, hecho, aviso). La interfaz la
#              dispara cuando cambia n, asi que el mismo evento puede repetirse.
#   juego    : ejecutable del juego en primer plano; su icono pasa a ser el
#              avatar de la capsula y el punto se vuelve insignia de estado.
$script:uiEstado = 'reposo'
$script:uiTexto = ''
$script:uiEvento = ''
$script:uiEventoN = 0
$script:juegoExe = ''
$script:uiAudio = ''        # mp3 que suena; la capsula busca <mp3>.env para mover la boca
$script:uiBateria = 100
$script:uiCargando = 0
$script:uiPerfil = ''       # ultimo perfil aplicado ("noche" cambia la paleta)
$script:uiCarga = 0         # % de CPU: la capsula se agita por encima del 85
$script:uiProgreso = 0      # 0..1 mientras opencode trabaja (linea del borde)
# Cuando vence el si/no, en reloj de pared: la capsula dibuja la barra que se
# vacia con su propio reloj, sin reescribir el estado en cada tic. Se declara
# AQUI y no junto a $pendiente porque Set-UI se usa mucho antes: alli valdrian
# $null y el JSON saldria roto.
$script:confirmaFin = 0
$script:confirmaTotal = 0
$script:uiVoz = 0           # indice de la voz que dicto (por tono), 0 = la habitual
$script:ultimaF0 = 0        # tono de la ultima orden dictada, en Hz (0 = no se pudo medir)
$script:ambienteUltimo = ''   # lo que sonaba antes de llamarla (solo con escucha.ambiente)
$script:uiClima = ''        # emoji del tiempo: solo unos segundos cuando se pregunta
$script:uiClimaHasta = 0
$script:uiAnimo = 0         # -1..1 segun aciertos y errores de las ultimas 24 h
$script:uiHaciendo = ''     # QUE se esta ejecutando ahora mismo (glifo en la capsula)
$script:uiRemoto = $false   # "pensando" lo lleva la IA (violeta) y no Nova sola (ambar)
$script:sinTarjeta = $false # la proxima respuesta es para oirla: sin tarjeta grande (ver Show-Popup)
$script:sinTarjetaEn = 0
$script:respuestaSinTarjeta = $false   # la respuesta del cerebro que viene es para oirla
$script:notaJuegoPendiente = $null     # la respuesta que viene es donde te quedaste en este juego
$script:notaPorGrabar = $null          # el proximo seguimiento se guarda como nota de voz
$script:grabandoNota = $null           # ...y esta en marcha (ruta del WAV)
$script:traducirPorOir = $null         # el proximo seguimiento se oye en este idioma
$script:traduciendoVoz = $null         # ...y esta en marcha
$script:huecoPendiente = $null         # a una receta le falta un valor y se ha preguntado
$script:avisosAplazados = New-Object System.Collections.ArrayList   # avisos que llegaron mientras dictabas
$script:notifCheck = 0      # ultima vez que se miraron las notificaciones
$script:uiCola = ''         # "3/2" = tres cosas en esta orden, va por la segunda; "3/2!" = esa fallo
$script:uiDescarga = 0      # 0..1 de la descarga de Steam mas avanzada (anillo)

function ConvertTo-JsonTexto([string]$s) {
    $t = (($s -replace '[\r\n\t]+', ' ') -replace '\s+', ' ').Trim()
    return $t.Replace('\', '\\').Replace('"', '\"')
}

# EL TEXTO DE LA CAPSULA, CORTADO POR DONDE SE PUEDE LEER (17/09). Cortaba a 137 letras a
# pelo, o sea a mitad de palabra: "no he podido abrir la carpeta de desc..." se quedaba en
# "desc". La VOZ ya lo hacia bien desde el 14/09 -Get-TextoVoz busca el final de una frase y
# si no el ultimo espacio-; esto es lo mismo para lo que se LEE, que es por donde pasa TODO
# el texto que ensena la capsula.
#
# Si la ultima palabra no cabe entera, se corta por el espacio anterior. Una palabra
# larguisima sin espacios utiles (una ruta, una URL) se corta a pelo a proposito: es mejor
# que ensenar tres palabras y kilometro y medio de nada.
# Aparte de Set-UI para que una prueba pueda ejecutarla sin montar media capsula.
function Get-TextoCapsula([string]$texto, [int]$tope = 140) {
    $t = (($texto -replace '[\r\n\t]+', ' ') -replace '\s+', ' ').Trim()
    if ($t.Length -le $tope) { return $t }
    $cabe = $t.Substring(0, $tope - 3).TrimEnd()
    $esp = $cabe.LastIndexOf(' ')
    if ($esp -ge [int]($tope * 0.4)) { $cabe = $cabe.Substring(0, $esp) }
    return $cabe.TrimEnd([char[]]@(' ', ',', ';', ':', '.')) + '...'
}

function Set-UI([string]$estado, [string]$texto = '', [int]$ms = 0) {
    if (-not $UiNuevaOn) { return }
    # ESCONDIDA: volver al reposo es volver a esconderse. Sin esto, la propia
    # respuesta ("me quito...") la sacaba y al callar se quedaba a la vista
    # (13/09). Hablar o escuchar si la ensenan un momento.
    if ($estado -eq 'reposo' -and $script:uiRetirada) { $estado = 'retirada' }
    $t = Get-TextoCapsula $texto
    $script:uiEstado = $estado
    $script:uiTexto = $t
    # la marca de "lo lleva la IA" dura lo que dura el pensar: cualquier otro
    # estado (respuesta, error, reposo) la quita
    if ($estado -ne 'pensando') { $script:uiRemoto = $false }
    # temporizador mas proximo, en tiempo de reloj (ms Unix) para que la
    # capsula dibuje el anillo con su propio reloj sin que haya que reescribir
    $tFin = 0; $tTotal = 0; $tTipo = ''
    if ($script:temporizadores -and $script:temporizadores.Count -gt 0) {
        $prox = $null
        # los que estan en pausa no dibujan el anillo (su vence es infinito)
        foreach ($tp in $script:temporizadores) { if ($tp.pausado) { continue }; if ($null -eq $prox -or $tp.vence -lt $prox.vence) { $prox = $tp } }
        if ($prox) {
            $tFin = [DateTimeOffset]::Now.ToUnixTimeMilliseconds() + ($prox.vence - $sw.ElapsedMilliseconds)
            $tTotal = $prox.total
            if ($prox.tipo) { $tTipo = [string]$prox.tipo }
        }
    }
    # EN QUE ESTADO ESTA EL OIDO. La capsula lo dibuja: sin esto, estar sorda y
    # estar escuchando se ven exactamente igual.
    $oido = 'palabra'
    if ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { $oido = 'sorda' }
    # "solo boton": la palabra esta apagada pero el boton sigue valiendo.
    # Pasa con un juego delante (marca solo-boton) o si el worker murio.
    elseif (Test-Path -LiteralPath $MarcaSoloBoton) { $oido = 'boton' }
    elseif ($EscuchaOn -and (-not $script:wakeProc -or $script:wakeProc.HasExited)) { $oido = 'boton' }
    $json = '{"estado":"' + $estado + '","texto":"' + (ConvertTo-JsonTexto $t) + '","nivel":0' +
            ',"evento":"' + $script:uiEvento + '","n":' + $script:uiEventoN +
            ',"juego":"' + (ConvertTo-JsonTexto $script:juegoExe) + '"' +
            # Y SI NO SE LA VE (25/09, idea 1): la propia capsula lo sabe, para poder dejar de
            # gastar en animaciones que nadie mira.
            ',"capsulaCiega":' + $(if ($script:capsulaCiega) { '1' } else { '0' }) +
            ',"audio":"' + (ConvertTo-JsonTexto $script:uiAudio) + '"' +
            ',"bateria":' + $script:uiBateria + ',"cargando":' + $script:uiCargando +
            ',"tempoFin":' + $tFin + ',"tempoTotal":' + $tTotal +
            ',"perfil":"' + $script:uiPerfil + '"' +
            ',"carga":' + $script:uiCarga + ',"clima":"' + (ConvertTo-JsonTexto $script:uiClima) + '"' +
            ',"animo":' + ([double]$script:uiAnimo).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"progreso":' + ([double]$script:uiProgreso).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"oido":"' + $oido + '","tempoTipo":"' + $tTipo + '"' +
            ',"haciendo":"' + $script:uiHaciendo + '"' +
            ',"remoto":"' + $(if ($script:uiRemoto -or $script:busy) { '1' } else { '0' }) + '"' +
            ',"musica":"' + $script:uiMusica + '"' +
            ',"peligrosa":"' + $(if ($script:pendiente -and $script:pendiente.tipo -eq 'peligrosa') { '1' } else { '0' }) + '"' +
            ',"madurez":"' + $script:uiMadurez + '"' +
            ',"tiempo":"' + $script:uiTiempo + '"' +
            ',"vol":"' + $script:uiVolumen + '"' +
            ',"cola":"' + $script:uiCola + '"' +
            ',"descarga":' + ([double]$script:uiDescarga).ToString('0.000', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"escala":' + ([double]$script:uiEscala * $(if ($script:uiDock -eq 1) { 1.25 } else { 1.0 })).ToString('0.00', [System.Globalization.CultureInfo]::InvariantCulture) +
            ',"origen":"' + $script:uiOrigen + '"' +
            ',"color":"' + $script:uiColor + '"' +
            ',"confirmaFin":' + ([long]$script:confirmaFin) + ',"confirmaTotal":' + ([long]$script:confirmaTotal) +
            ',"esquina":"' + $script:esquina + '"' +
            ',"voz":' + $script:uiVoz + '}'
    if ($json -ne $script:uiUltimo) {
        # UTF-8 SIN BOM: la interfaz lo lee tal cual y el BOM colaria un caracter
        try { [System.IO.File]::WriteAllText($RutaUiEstado, $json, (New-Object System.Text.UTF8Encoding $false)) } catch {}
        $script:uiUltimo = $json
    }
    $script:uiHasta = if ($ms -gt 0) { $sw.ElapsedMilliseconds + $ms } else { 0 }
    # si se pregunto el tiempo, que el emoji dure al menos lo que la respuesta
    if ($script:uiClimaHasta -gt 0 -and $script:uiHasta -gt $script:uiClimaHasta) { $script:uiClimaHasta = $script:uiHasta + 1500 }
}

# Dispara una animacion sin cambiar el estado (el estado se reescribe igual).
function Send-UIEvento([string]$evento) {
    # ACABA DE APRENDER ALGO: el "hecho" de siempre se convierte en la
    # celebracion. Hace falta porque la capsula lee UN evento por vuelta, y el
    # "hecho" que llega justo despues de aprender pisaria el gesto. La marca
    # caduca a los 10 s, para no celebrar a destiempo algo que no toca.
    if ($script:acabaDeAprender -and ($sw.ElapsedMilliseconds - $script:acabaDeAprenderEn) -gt 10000) { $script:acabaDeAprender = $false }
    if ($evento -eq 'hecho' -and $script:acabaDeAprender) { $evento = 'gesto:aprendido' }
    if ($evento -eq 'gesto:aprendido') { $script:acabaDeAprender = $false }
    # eco en el mando: lo que la capsula celebra, el mando lo hace sentir
    switch ($evento) {
        'hecho' { Start-Vibracion @(50, 60, 50) 18000 }
        'logro' { Start-Vibracion @(80, 60, 80, 60, 160) 26000 }
        'aviso' { Start-Vibracion @(120, 80, 120) 22000 }
        'gesto:aprendido' { Start-Vibracion @(40, 50, 40, 50, 110) 22000 }
        'gesto:sinia' { Start-Vibracion @(50, 60, 50) 18000 }
    }
    if (-not $UiNuevaOn) { return }
    $script:uiEvento = $evento
    $script:uiEventoN++
    Refresh-UI
}

# Reescribe el estado actual (tras cambiar el juego o lanzar un evento) sin
# tocar el plazo de vuelta al reposo.
function Refresh-UI {
    $resta = 0
    if ($script:uiHasta -gt 0) { $resta = [Math]::Max(1, $script:uiHasta - $sw.ElapsedMilliseconds) }
    Set-UI $script:uiEstado $script:uiTexto $resta
}

# QUE VA A HACER, ANTES DE HACERLO
# Cada accion que toca el sistema enciende un glifo en la capsula JUSTO ANTES de
# ejecutarse: la app, el altavoz, la ventana. Una forma se reconoce de un
# vistazo; leer el texto tarda mas que la accion en pasar, y para entonces ya no
# hay nada que cancelar. NO anade ninguna espera: el glifo se ve durante lo que
# tarde la accion y el respiro de 250 ms que la sigue. Las ordenes que solo
# CONSULTAN (la hora, a que juegas, que modos hay) no llevan glifo: no hay nada
# que cancelar y el parpadeo solo seria ruido.
$GlifosAccion = @{
    'app' = 'app'; 'url' = 'web'; 'buscarEquipo' = 'web'
    'volumenPct' = 'sonido'; 'volumenRel' = 'sonido'; 'volumenApp' = 'sonido'
    'silencio' = 'mudo'
    'brillo' = 'brillo'
    'key' = 'tecla'; 'atajo' = 'tecla'; 'winkey' = 'tecla'; 'winaltg' = 'tecla'; 'alttab' = 'tecla'
    'escribir' = 'escribir'
    'winprt' = 'captura'
    'otroMonitor' = 'ventana'; 'siempreEncima' = 'ventana'; 'esconder' = 'ventana'
    'enfocar' = 'ventana'; 'enfocarJuego' = 'ventana'
    'cerrarApp' = 'cerrar'; 'cerrarJuego' = 'cerrar'; 'cerrarTodo' = 'cerrar'; 'zombis' = 'cerrar'
    'lock' = 'bloqueo'
    'memoria' = 'nota'; 'ocrMemoria' = 'nota'; 'apuntarCopiado' = 'nota'
    'temporizador' = 'tiempo'; 'quitarTempo' = 'tiempo'
    'copiar' = 'copia'; 'pegar' = 'copia'; 'copiarRespuesta' = 'copia'
    'ocr' = 'pantalla'; 'seguirLeyendo' = 'pantalla'
    'deshacer' = 'deshacer'; 'deshacerDesde' = 'deshacer'; 'noEraEso' = 'deshacer'; 'deshacerAuto' = 'deshacer'
}
# CUANTAS COSAS SON Y POR CUAL VA. "abre steam y pon modo juego" son dos; si
# falla la segunda, hasta ahora no habia forma de saber cual fue. Solo se manda
# cuando hay MAS DE UNA: para una sola, un punto suelto no dice nada.
function Set-UICola([int]$total, [int]$indice, [bool]$fallo = $false) {
    if (-not $UiNuevaOn) { return }
    $v = ''
    if ($total -gt 1) { $v = "$total/$indice" + $(if ($fallo) { '!' } else { '' }) }
    if ($v -eq $script:uiCola) { return }
    $script:uiCola = $v
    Refresh-UI
}

function Set-UIHaciendo([string]$kind) {
    if (-not $UiNuevaOn) { return }
    $g = ''
    if ($kind) { $g = [string]$GlifosAccion[$kind] }
    # solo se reescribe el estado si CAMBIA: dos teclas seguidas no valen dos
    # escrituras del JSON ni dos animaciones de entrada
    if ($g -eq $script:uiHaciendo) { return }
    $script:uiHaciendo = $g
    Refresh-UI
}

# AVISOS SIN VOZ
# Hasta ahora un aviso o te hablaba encima o no existia. Con un juego delante,
# que te hable es justo lo que no quieres; en sordina, le acabas de pedir
# silencio. Pero callar del todo es no enterarte. Asi que en esos casos el
# aviso se ve -tres pulsos de color en el borde de la capsula, con el texto
# puesto- y no suena.
# El aviso SIEMPRE aparece; lo unico que cambia es si ademas habla.
$AvisosSinVoz = [bool](Get-Cfg 'avisos' 'sinVoz' $true)
$AvisosSinVozEnJuego = [bool](Get-Cfg 'avisos' 'sinVozEnJuego' $true)
# SILENCIO EN LLAMADAS (13/09): si OTRA app esta usando el microfono (Discord,
# una llamada, una grabacion), Nova no habla: su voz se colaria en la llamada.
# Lo dice el registro de privacidad de Windows (LastUsedTimeStop = 0 mientras se
# usa). No cuentan el worker de escucha de Nova (python) ni el dictado de
# Windows. Se mira como mucho cada 3 s.
$script:llamadaVista = 0
$script:llamadaActiva = $false
function Test-EnLlamada {
    if (($sw.ElapsedMilliseconds - $script:llamadaVista) -lt 3000 -and $script:llamadaVista -gt 0) { return $script:llamadaActiva }
    $script:llamadaVista = $sw.ElapsedMilliseconds
    $activa = $false
    try {
        $raizM = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone'
        $claves = @(Get-ChildItem -LiteralPath $raizM -ErrorAction SilentlyContinue) + @(Get-ChildItem -LiteralPath (Join-Path $raizM 'NonPackaged') -ErrorAction SilentlyContinue)
        foreach ($cl in $claves) {
            if ($cl.PSChildName -match '(?i)python|TextInputHost|MicrosoftWindows\.Client|voice-ctrl|^NonPackaged$') { continue }
            $pr = Get-ItemProperty -LiteralPath $cl.PSPath -ErrorAction SilentlyContinue
            if ($pr -and $null -ne $pr.LastUsedTimeStart -and [long]$pr.LastUsedTimeStop -eq 0) { $activa = $true; break }
        }
    } catch {}
    if ($activa -ne $script:llamadaActiva) { Log ("LLAMADA: " + $(if ($activa) { 'otra app usa el microfono; Nova se calla' } else { 'microfono libre; Nova vuelve a hablar' })) }
    $script:llamadaActiva = $activa
    return $activa
}
# LA CAPSULA CIEGA (25/09, idea 1).
#
# LO QUE PASO la noche del 24 con braya jugando: la capsula estaba en z=0 -por delante del
# juego-, visible, colocada y del tamano correcto, y NO SE PINTABA NI UN PIXEL. A Way Out
# estaba en pantalla completa EXCLUSIVA, y ahi ningun overlay de ventana se dibuja. Nova estuvo
# media hora ensenandole cosas a nadie, y eso choca con la regla 2 de la casa: ningun modo
# puede tener una sola salida.
#
# COMO SE SABE, y es limpio: el modo exclusivo CAMBIA LA RESOLUCION DEL ESCRITORIO. Medido esa
# noche: el panel de la Ally es 1920x1080 nativo y el escritorio estaba a 1280x720. El modo
# "ventana sin bordes" no la cambia nunca, asi que la diferencia lo delata sin preguntarle nada
# a DirectX ni inyectar nada en el juego.
#
# LA NATIVA SE PREGUNTA UNA VEZ: el panel de una consola no cambia de tamano, y la consulta WMI
# cuesta cientos de milisegundos. La actual si se mira cada vez, porque es lo que cambia.
$script:resNativa = $null
$script:resNativaMirada = $false
function Get-ResolucionNativa {
    if ($script:resNativaMirada) { return $script:resNativa }
    $script:resNativaMirada = $true
    try {
        $m = @(Get-CimInstance -Namespace 'root\wmi' -ClassName WmiMonitorListedSupportedSourceModes -ErrorAction SilentlyContinue)
        foreach ($x in $m) {
            $p = $x.MonitorSourceModes[$x.PreferredMonitorSourceModeIndex]
            if ($p.HorizontalActivePixels -gt 0) {
                $script:resNativa = @([int]$p.HorizontalActivePixels, [int]$p.VerticalActivePixels)
                break
            }
        }
    } catch { $script:resNativa = $null }
    return $script:resNativa
}
function Get-ResolucionActual {
    try {
        $v = @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue |
               Where-Object { $_.CurrentHorizontalResolution -gt 0 })
        if ($v.Count -gt 0) { return @([int]$v[0].CurrentHorizontalResolution, [int]$v[0].CurrentVerticalResolution) }
    } catch {}
    return $null
}
function Test-CapsulaCiega {
    # ANTE LA DUDA, SE VE: si no se sabe alguna de las dos resoluciones, no se inventa un
    # problema. Dar por ciega una capsula que si se ve haria hablar a Nova encima del juego,
    # que es peor que el fallo que esto arregla.
    if (-not $script:juegoActivo) { return $false }
    $nat = Get-ResolucionNativa
    $act = Get-ResolucionActual
    if (-not $nat -or -not $act) { return $false }
    return (($nat[0] -ne $act[0]) -or ($nat[1] -ne $act[1]))
}

function Test-AvisoSinVoz {
    if (Test-EnLlamada) { return $true }
    if (-not $AvisosSinVoz) { return $false }
    # te callaste tu: no te hablo yo
    if ($script:sordinaHasta -gt $sw.ElapsedMilliseconds) { return $true }
    # con un juego delante, hablarte encima te saca de la partida
    if ($AvisosSinVozEnJuego -and $script:juegoActivo) { return $true }
    # y el modo silencio es exactamente esto
    if ($script:uiPerfil -eq 'silencio') { return $true }
    return $false
}

# SI NO SE LA VE, QUE AL MENOS SE NOTE (25/09, idea 1). Con un juego en pantalla completa
# exclusiva la capsula no se pinta: un aviso que se calla por respeto a la partida y ademas no
# se ve no ha llegado a ninguna parte, y eso es la regla 2 rota. Se vibra, que no interrumpe
# la partida como si lo haria hablar encima.
function Send-AvisoVibrado {
    if (-not $script:capsulaCiega) { return $false }
    try { Start-Vibracion @(90, 60, 90) 16000; return $true } catch { return $false }
}

# Un aviso, por la puerta que toque. $tipo da el color del pulso: bateria,
# tiempo, descarga, recordatorio.
function Send-Aviso([string]$texto, [string]$tipo = '') {
    # MIENTRAS DICTAS, ESPERA (auditoria del 13/09): hablar encima de un dictado
    # pone la pausa y el worker tira tu audio. Se guarda y suena al terminar.
    if ($script:armed) {
        [void]$script:avisosAplazados.Add(@{ texto = $texto; tipo = $tipo })
        Log "aviso aplazado hasta que termines de dictar: $texto"
        return
    }
    Show-Popup $texto
    if (Test-AvisoSinVoz) {
        Send-UIEvento ("pulso:" + $tipo)
        # Y SI LA CAPSULA NO SE VE, QUE AL MENOS SE NOTE (25/09, idea 1): con el juego en
        # pantalla completa exclusiva ese pulso no lo pinta nadie. Vibrar no saca a braya de la
        # partida, que es lo que se evitaba callandose.
        $vib = Send-AvisoVibrado
        Log ("aviso SIN VOZ ($tipo)" + $(if ($vib) { ', vibrado: no se ve la capsula' }) + ": $texto")
    } else {
        Say $texto
        # una descarga terminada tiene su propio gesto: el salto con chispas (13/09)
        Send-UIEvento $(if ($tipo -eq 'descarga') { 'gesto:descargado' } else { 'aviso' })
    }
}

function Initialize-UI {
    if (-not $UiNuevaOn) { Log "interfaz nueva desactivada por configuracion"; return }
    $exe = Join-Path $LogDir "nova_ui.exe"
    if (-not (Test-Path -LiteralPath $exe)) { Log "WARN: falta nova_ui.exe (compilar con tools\compilar-ui.ps1); sigue la barra antigua"; Add-FalloArranque 'me falta la capsula'; $script:UiNuevaOn = $false; return }
    try {
        # arrancar siempre en reposo: un JSON viejo de otra sesion dejaria la
        # capsula abierta con un texto rancio
        $script:uiUltimo = ''
        Set-UI 'reposo'
        # se le pasa nuestro PID: si este proceso muere, la capsula se cierra sola
        $script:uiProc = Start-Process -FilePath $exe -ArgumentList @((ConvertTo-CmdArg $RutaUiEstado), "$PID") `
            -WorkingDirectory $LogDir -PassThru
        $null = $script:uiProc.Handle
        try { $script:uiProc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } catch {}
        Log "interfaz ACTIVA (PID=$($script:uiProc.Id))"
    } catch {
        Log ("WARN: la interfaz no arranco: " + $_.Exception.Message)
        $script:uiProc = $null
    }
}

# Win + Alt + <tecla>: atajos de la barra de juego (grabar, captura)
function Send-WinAlt([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    [AX]::keybd_event([byte]$VK_MENU, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_MENU, 0, $KEYUP, [UIntPtr]::Zero)
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

# --- QUE ESTA EN PRIMER PLANO ---
# Saber a que juegas desbloquea frases naturales ("cuanto llevo jugando",
# "busca una guia de esto") sin tener que nombrarlo cada vez.
$script:juegoActivo = $null
# Si el juego esta en pantalla completa exclusiva, la capsula no se pinta (ver LA CAPSULA
# CIEGA). Se recalcula junto al juego, no en cada aviso: la consulta cuesta milisegundos.
$script:capsulaCiega = $false
$script:juegoDesde = 0
$script:juegoPid = 0             # PID del proceso que tiene la ventana del juego (C4, 19/09)
$script:juegoPidCandidato = 0
$script:juegoSalida = $null      # salida EN DUDA: @{nombre; exe; proc; desdeMs} (C4, 19/09)
$script:juegoSesionMin = 0       # minutos de primer plano de la partida de ahora (C4, 19/09)

# EL PID DE LA VENTANA, NO SU MainWindowHandle (24/09, idea 8 de la tanda nueva).
#
# Esto recorria los ~200 procesos buscando uno cuyo MainWindowHandle fuera EXACTAMENTE la
# ventana de delante. Con un juego en pantalla completa exclusiva eso no casa, y devolvia
# $null: Nova se quedaba ciega con el juego delante.
#
# ESTA MEDIDO Y CON SUS PALABRAS. El 20/09 el registro de Steam dice que ELDEN RING corrio de
# 18:59:53 a 19:07:57; Nova lo vio ONCE SEGUNDOS y a las 19:01:22 contesto "ELDEN RING no esta
# abierto". A las 19:02:27 braya le dijo al microfono -y esta en el registro-: "Elden Ring si
# esta abierto... el juego sigue abierto". Se quedo ciega los 7 min 49 s restantes, unas 47
# vueltas del bucle. Lo mismo el 19/09 (13 s de 272) y el 18/09 (11 s de 185). En total, el
# 5,5 % de lo que jugo a ese juego con Nova viva.
#
# (El otro 90 % de lo que se pierde no es esto: es que Nova no estaba encendida. Eso no se
# arregla aqui, y no se finge que si.)
#
# LA SOLUCION YA ESTABA ESCRITA TREINTA LINEAS MAS ABAJO, en el comentario del 23/09: "se pide
# el handle de delante, su PID, y UN solo Get-Process -Id", con su medicion -de 500 a 740 ms
# recorriendo los 200 procesos, frente a 20 ms-. Mas barato y mas certero, y Get-PidDeVentana
# ya se usa en la primera linea de Get-JuegoEnPrimerPlano.
#
# Y NO LA VUELVE PERMISIVA: esto solo devuelve el PROCESO. Quien decide si eso es un juego es
# Get-JuegoEnPrimerPlano con sus $CARPETAS_JUEGO, $EXES_JUEGO, $CARPETA_NO_JUEGO y el filtro
# de instaladores, y eso no se toca.
function Get-ProcesoEnPrimerPlano {
    try {
        $h = [AX]::GetForegroundWindow()
        if ($h -eq [IntPtr]::Zero) { return $null }
        $pidFg = Get-PidDeVentana $h
        if ($pidFg -gt 0) {
            $pr = Get-Process -Id $pidFg -ErrorAction SilentlyContinue
            if ($pr) { return $pr }
        }
        # DE RESPALDO, lo de siempre: si el PID no se puede resolver o el proceso ya murio
        # entre una linea y otra, se busca por ventana principal como hasta hoy.
        foreach ($p in (Get-Process -ErrorAction SilentlyContinue)) {
            if ($p.MainWindowHandle -eq $h) { return $p }
        }
    } catch {}
    return $null
}

# QUE VENTANA TENGO DELANTE, BARATO (23/09, idea 2). Hace falta para resolver "esto", y el
# coste manda: el comentario de Get-RamResumen, medido el 21/09, dice que leer
# MainWindowTitle de los 200 y pico procesos cuesta de 500 a 740 ms frente a 20 ms. Por eso
# aqui NO se usa Get-ProcesoEnPrimerPlano, que recorre todos: se pide el handle de delante,
# su PID, y UN solo Get-Process -Id.
# No corre en el bucle: solo cuando llega una frase con deictico. Y cachea 800 ms, que es
# menos de lo que tarda braya en decir dos frases seguidas.
$script:ventanaDelante = $null
$script:ventanaDelanteMs = 0
function Get-VentanaDelante {
    if ($script:ventanaDelanteMs -gt 0 -and ($sw.ElapsedMilliseconds - $script:ventanaDelanteMs) -lt 800) {
        return $script:ventanaDelante
    }
    $script:ventanaDelanteMs = $sw.ElapsedMilliseconds
    $script:ventanaDelante = $null
    try {
        $h = [AX]::GetForegroundWindow()
        if ($h -eq [IntPtr]::Zero) { return $null }
        $duenoV = Get-PidDeVentana $h
        if ($duenoV -le 0) { return $null }
        # MI PROPIA VENTANA NO CUENTA, la misma guarda que Get-JuegoEnPrimerPlano: ni esta
        # consola ni la capsula. Con la capsula delante no se sabe que hay detras, y
        # adivinarlo seria inventarse el referente.
        if ($duenoV -eq $PID) { return $null }
        if ($script:uiProc -and -not $script:uiProc.HasExited -and $duenoV -eq $script:uiProc.Id) { return $null }
        $p = Get-Process -Id $duenoV -ErrorAction SilentlyContinue
        if (-not $p) { return $null }
        $nomP = [string]$p.ProcessName
        if ($PROCESOS_INTOCABLES -contains $nomP) { return $null }
        $tit = ''
        try { $tit = [string]$p.MainWindowTitle } catch { $tit = '' }
        $script:ventanaDelante = @{ titulo = $tit; proceso = $nomP; nombre = (Get-NombreDeTitulo $tit $nomP) }
    } catch { $script:ventanaDelante = $null }
    return $script:ventanaDelante
}

# EL NOMBRE QUE SE DICE EN VOZ ALTA, sacado del titulo. Pura: no llama a Windows, asi que una
# prueba puede ejecutarla con titulos de verdad.
# El tope de 40 es el mismo criterio que ya usa el listado de "cierra todo": un titulo largo
# es una frase ("Documento1 - Word - 3 paginas sin guardar"), no un nombre, y decirlo entero
# en mitad de una pregunta no ayuda a nadie. La lista de contenedores es CERRADA: quitar "lo
# que va detras del ultimo guion" se llevaria por delante los nombres con guion.
function Get-NombreDeTitulo([string]$titulo, [string]$proceso) {
    $t = ([string]$titulo).Trim()
    if (-not $t) { return $proceso }
    $t = $t -replace '^\(\d+\)\s*', ''          # el "(3) " de los contadores de mensajes
    foreach ($suf in @(' - google chrome', ' - mozilla firefox', ' - microsoft edge', ' - brave',
                       ' - opera', ' - visual studio code', ' - bloc de notas', ' and 1 more page - personal')) {
        if ($t.ToLowerInvariant().EndsWith($suf)) { $t = $t.Substring(0, $t.Length - $suf.Length).Trim(); break }
    }
    if (-not $t -or $t.Length -gt 40) { return $proceso }
    return $t
}

# Devuelve el juego de Steam que esta en primer plano, o $null.
# DE DONDE SALE ESTA LISTA (21/09): la noche del 20 al 21 braya jugo DOS HORAS a
# Roblox y para Nova no estaba jugando. Aqui solo valia steamapps\\common, asi que
# $script:juegoActivo se quedo en $null las dos horas y con el se quedaron fuera: el
# tiempo de juego, el avatar de la capsula, el freno de los avisos, el limite de
# tiempo, la nota semanal y -lo que mas se noto- el 'braya esta jugando a X' que va
# en el prompt del cerebro y le pide contestar en UNA frase. Sin el, se enrollaba.
# Su Roblox es el de Game Pass: C:\\XboxGames\\Roblox\\Content\\RobloxPlayerBeta.exe.
#
# CADA PATRON EXIGE UNA BARRA DETRAS DEL NOMBRE a proposito: es lo que distingue la
# carpeta de un juego del ejecutable de la tienda. Sin ella, Epic Games\\algo.exe o el
# propio GalaxyClient.exe entrarian como si fueran juegos.
# EL NOMBRE QUE SE DICE EN VOZ ALTA. Las carpetas se llaman como les da la gana:
# '.minecraft' es la de datos y 'Minecraft Launcher' la del lanzador. Lo usan
# Get-JuegoEnPrimerPlano y Get-JuegosXbox, y tiene que ser LA MISMA limpieza en las
# dos: si no, el tiempo de juego se apunta a nombre de una y se lee a nombre de otra.
function Get-NombreJuegoLimpio([string]$n) {
    if (-not $n) { return $n }
    $n = $n.TrimStart('.')
    $n = ($n -replace '\s+(?:Launcher|Game Preview Edition)$', '')
    return $n.Trim()
}

$CARPETAS_JUEGO = @(
    '(?i)steamapps\\common\\([^\\]+)\\'   # Steam
    '(?i)\\XboxGames\\([^\\]+)\\'   # Xbox / Game Pass
    '(?i)\\Epic Games\\([^\\]+)\\'   # Epic
    '(?i)\\GOG Galaxy\\Games\\([^\\]+)\\'   # GOG
    '(?i)\\Ubisoft Game Launcher\\games\\([^\\]+)\\'   # Ubisoft
    '(?i)\\(?:Origin|EA) Games\\([^\\]+)\\'   # EA
    '(?i)\\Riot Games\\([^\\]+)\\'   # Riot
    '(?i)\\itch\\apps\\([^\\]+)\\'   # itch.io
    '(?i)\\(Roblox)\\Versions\\'   # Roblox de la web
    '(?i)\\\.(minecraft)\\'   # Minecraft
)
# lo que vive en esas carpetas y no es un juego
$CARPETA_NO_JUEGO = @('launcher', 'epic games launcher', 'gamesave', 'directxredist',
                      'redistributables', '_commonredist', 'support', 'epic online services')
# SI NO SE PUEDE LEER LA RUTA, POR EL NOMBRE DEL PROCESO. Las apps de la Store corren
# protegidas y $p.Path puede saltar por permisos; antes eso era un 'no hay juego'.
$EXES_JUEGO = @{ 'robloxplayerbeta' = 'Roblox'; 'minecraft' = 'Minecraft'
                 'minecraftlauncher' = 'Minecraft'; 'fortniteclient-win64-shipping' = 'Fortnite' }
function Get-JuegoEnPrimerPlano {
    # MI PROPIA VENTANA DELANTE NO ES SALIR DEL JUEGO (21/09). Esto solo miraba si la
    # ventana de delante era de un juego; si no, devolvia $null y el bucle daba la
    # partida por terminada: Exit-Juego, las reglas de 'juegoCierra', el brillo
    # restaurado, vuelve la palabra de activacion y a cero el tiempo jugado. Y al dictar,
    # la capsula se pone delante un momento.
    # ESTA EN EL LOG DESDE EL 11/09, siempre igual y siempre con un dictado por medio:
    #   15:43:46  dictado: escuchando la orden
    #   15:43:49  JUEGO: brillo restaurado a 100 al salir de Little Nightmares III
    #   15:44:0x  juego en primer plano: Little Nightmares III   (volvia una vuelta despues)
    # Start-Dictado ya lo tenia resuelto para lo suyo, y lo dice: 'NINGUNA ventana del
    # asistente cuenta como tuya: ni la de captura ni la CAPSULA'. Aqui faltaba.
    # Se devuelve el juego que YA habia, no $null: con la capsula delante no se sabe que
    # hay detras, y lo ultimo que se supo sigue siendo lo mas probable.
    try {
        $hFg = [AX]::GetForegroundWindow()
        if ($hFg -ne [IntPtr]::Zero) {
            $duenoFg = Get-PidDeVentana $hFg
            $mio = ($duenoFg -eq $PID)
            if (-not $mio -and $script:uiProc -and -not $script:uiProc.HasExited -and $duenoFg -eq $script:uiProc.Id) { $mio = $true }
            if ($mio) { return $script:juegoActivo }
        }
    } catch {}
    $p = Get-ProcesoEnPrimerPlano
    if (-not $p) { return $null }
    $ruta = ''
    try { $ruta = $p.Path } catch { $ruta = '' }
    $carpeta = ''
    if ($ruta) {
        foreach ($reJ in $CARPETAS_JUEGO) {
            if ($ruta -match $reJ) { $carpeta = $Matches[1]; break }
        }
    }
    if (-not $carpeta) {
        $nomP = ''
        try { $nomP = ([string]$p.Name).ToLowerInvariant() } catch {}
        if ($nomP -and $EXES_JUEGO.ContainsKey($nomP)) { $carpeta = [string]$EXES_JUEGO[$nomP] }
    }
    if (-not $carpeta) { return $null }
    if ($CARPETA_NO_JUEGO -contains $carpeta.ToLowerInvariant()) { return $null }
    # UN INSTALADOR DENTRO DE LA CARPETA DEL JUEGO NO ES JUGAR. Al instalar,
    # .../Fortnite/Engine/Extras/Redist/_CommonRedist/vcredist.exe pasa por delante
    # un momento y capturaba 'Fortnite': Nova diria que estas jugando mientras
    # esperas la descarga, y con eso se callaria los avisos que si querias.
    if ($ruta -match '(?i)\\(?:_CommonRedist|Redist|DirectX|vcredist|DotNetFX|Installers?)\\') { return $null }
    $carpeta = Get-NombreJuegoLimpio $carpeta
    # el ejecutable se guarda aparte: la capsula saca de el el icono del juego
    $script:juegoExeCandidato = $ruta
    # C4 (19/09): y el PID, para poder preguntar luego si ese proceso sigue vivo sin
    # tener que enumerar todos los procesos de la maquina (4 nucleos)
    $script:juegoPidCandidato = [int]$p.Id
    # la carpeta de instalacion suele parecerse al titulo
    $j = Find-Juego $carpeta
    if ($j) { return $j.nombre }
    return $carpeta
}

# --- RUTINAS DE JUEGO (config.json -> juego) ---
# Al entrar en un juego se aplica un perfil (por defecto "juego"); al salir se
# restaura el brillo que habia. El volumen no se puede leer sin librerias
# externas, asi que no se restaura: se avisa en vez de fingir.
$JuegoPerfilEntrar = [string](Get-Cfg 'juego' 'perfilAlEntrar' 'juego')
$JuegoRestaurar = [bool](Get-Cfg 'juego' 'restaurarAlSalir' $true)
$JuegoAvisoMin = [int](Get-Cfg 'juego' 'avisoMinutos' 120)
# C4 (19/09): CUANTO TIENE QUE DURAR UNA PARTIDA PARA QUE CONTESTE AL CERRARLA.
# Sale del log del 10 al 19/09, de las 11 salidas con rastro completo:
#   falsas (alt-tab o juego recien lanzado): 4 s, 10 s, 11 s, 83 s y 100 s
#   partidas de verdad: 3 min 31 s, 4 min 10 s, 12 min 50 s, 33 min 55 s, 59 min 39 s, 6 h 14 min
# El hueco esta entre 1 min 40 s y 3 min 31 s, asi que el corte va en 3 minutos: deja
# fuera las cinco falsas con casi el doble de margen y no se come ninguna partida real.
# OJO AL NOMBRE (20/09). Esto se llamaba $JuegoSesionMin, y PowerShell NO distingue
# mayusculas en los nombres de variable: era LA MISMA que $script:juegoSesionMin, el
# acumulador de minutos de tres lineas mas arriba. Se pisaban. El umbral de 3 minutos
# que se puso el 19/09 -justo para no cantar cierres falsos de ELDEN RING- no ha
# funcionado NUNCA: nacio roto en el commit c714970 y la linea 'sin aviso' no aparece
# ni una vez en todo el log. El 20/09 a las 19:00:08 anuncio 'cerraste ELDEN RING' con
# 0 minutos de partida, once segundos despues de abrirlo, y de ahi salio media hora de
# lio con braya. El nombre nuevo no colisiona con nada.
$JuegoMinimoPartida = [int](Get-Cfg 'juego' 'sesionMinima' 3)
$script:juegoBrilloAntes = $null
# EL ESTADO DEL AVISO VIVE EN habitos.json (23/09), no en memoria. Con 16,3 arranques al
# dia, un aviso que solo se acuerda en RAM se repetiria en el primer chequeo despues de
# cada reinicio: dieciseis veces al dia, que es peor que no avisar.
$script:juegoAvisoDia = ''     # el dia del ultimo aviso
$script:juegoAvisoUlt = 0      # minutos de hoy cuando se aviso
$script:juegoAvisoCada = 0     # 0 = una vez al dia; >0 = cada N minutos
$script:ultimaRegla = $null    # la ultima regla creada, para que 'siempre' sepa cual es
$script:juegoAvisoNo = ''      # el dia en que dijo hoy no me avises

$script:juegoHoras = 0

# --- EL TIEMPO (config.json -> clima) ---
# Una consulta por hora a Open-Meteo (sin clave). Si no hay coordenadas en la
# configuracion se piden UNA vez a ip-api.com por la IP publica: eso manda la
# IP a un tercero; con clima.lat/lon en config.json no hace falta.
$ClimaOn = [bool](Get-Cfg 'clima' 'activada' $true)
$ClimaLat = Get-Cfg 'clima' 'lat' $null
$ClimaLon = Get-Cfg 'clima' 'lon' $null
$script:clima = $null
$script:climaCheck = -3600000

# lluvia / nieve / tormenta / '' : lo dibuja la capsula, muy de vez en cuando
$script:uiTiempo = ''
# el volumen que Nova acaba de poner: la capsula ensancha el halo al cambiar (13/09)
$script:uiVolumen = -1
function Update-Clima {
    if (-not $ClimaOn) { return }
    try {
        if ($null -eq $ClimaLat -or $null -eq $ClimaLon) {
            # LA UBICACION, UNA VEZ AL DIA (18/09). Se pedia por IP en CADA arranque: 126
            # llamadas en el registro, siempre el mismo resultado. Es red repetida para nada.
            # OJO, y esto corrige a quien escribio la idea: NO son "20 s del arranque".
            # Update-Clima se llama desde el bucle con "una vez por hora, la primera a los 20 s
            # de arrancar", asi que esos 20 s son la espera de diseño, no lo que tarda esto.
            # Lo que se gana es la red y no quedarse sin clima el dia que ip-api no conteste.
            $rutaU = Join-Path $MemoriaDir 'ubicacion.json'
            $hoyU = (Get-Date).ToString('yyyy-MM-dd')
            $cacheU = $null
            if (Test-Path -LiteralPath $rutaU) {
                try { $cacheU = Get-Content -LiteralPath $rutaU -Raw -Encoding UTF8 | ConvertFrom-Json } catch {}
            }
            if ($cacheU -and $cacheU.lat -and [string]$cacheU.dia -eq $hoyU) {
                $script:ClimaLat = [double]$cacheU.lat; $script:ClimaLon = [double]$cacheU.lon
            } else {
                $g = $null
                try { $g = Invoke-RestMethod -Uri 'http://ip-api.com/json/?fields=lat,lon,city' -TimeoutSec 4 } catch { $g = $null }
                if ($g -and $g.lat) {
                    $script:ClimaLat = [double]$g.lat; $script:ClimaLon = [double]$g.lon
                    Log "clima: ubicacion por IP ($($g.city))"
                    try {
                        Write-Atomico $rutaU (ConvertTo-Json -InputObject ([ordered]@{ lat = [double]$g.lat; lon = [double]$g.lon; ciudad = [string]$g.city; dia = $hoyU }) -Depth 3)
                    } catch {}
                } elseif ($cacheU -and $cacheU.lat) {
                    # sin red: mejor el sitio de ayer que quedarse sin tiempo
                    $script:ClimaLat = [double]$cacheU.lat; $script:ClimaLon = [double]$cacheU.lon
                    Log "clima: sin respuesta de ip-api; uso la ubicacion guardada ($([string]$cacheU.ciudad))"
                } else { return }
            }
        }
        $cul = [System.Globalization.CultureInfo]::InvariantCulture
        $u = 'https://api.open-meteo.com/v1/forecast?latitude=' + ([double]$ClimaLat).ToString($cul) + '&longitude=' + ([double]$ClimaLon).ToString($cul) + '&current_weather=true'
        $r = Invoke-RestMethod -Uri $u -TimeoutSec 4
        $cw = $r.current_weather
        if (-not $cw) { return }
        $codigo = [int]$cw.weathercode
        $noche = ($cw.is_day -eq 0)
        # codigos WMO -> emoji + descripcion hablada
        $emoji = '☀️'; $desc = 'esta despejado'
        if ($codigo -ge 1 -and $codigo -le 2) { $emoji = '⛅'; $desc = 'hay algunas nubes' }
        elseif ($codigo -eq 3) { $emoji = '☁️'; $desc = 'esta nublado' }
        elseif ($codigo -ge 45 -and $codigo -le 48) { $emoji = '🌫️'; $desc = 'hay niebla' }
        elseif ($codigo -ge 51 -and $codigo -le 67) { $emoji = '🌧️'; $desc = 'esta lloviendo' }
        # 85 Y 86 SON CHUBASCOS DE NIEVE, Y FALTABAN (21/09). Esta cadena saltaba de 77 a
        # 80, asi que un codigo 85 u 86 no encajaba en ninguna rama y se quedaba con el
        # valor de arriba: 'esta despejado'. Y la linea de la capsula, doce lineas mas
        # abajo, SI los cuenta como nieve: Nova decia que estaba despejado mientras su
        # propia cara dejaba caer copos.
        elseif (($codigo -ge 71 -and $codigo -le 77) -or ($codigo -ge 85 -and $codigo -le 86)) { $emoji = '🌨️'; $desc = 'esta nevando' }
        elseif ($codigo -ge 80 -and $codigo -le 82) { $emoji = '🌦️'; $desc = 'hay chubascos' }
        elseif ($codigo -ge 95) { $emoji = '⛈️'; $desc = 'hay tormenta' }
        elseif ($noche) { $emoji = '🌙'; $desc = 'esta despejado' }
        $temp = [int][Math]::Round([double]$cw.temperature)
        $script:clima = @{ emoji = $emoji; desc = $desc; temp = $temp }
        # EL CLIMA VIVO: la capsula deja caer una gota (o un copo) de vez en cuando
        $tiempoAntes = $script:uiTiempo
        $script:uiTiempo = if (($codigo -ge 51 -and $codigo -le 67) -or ($codigo -ge 80 -and $codigo -le 82)) { 'lluvia' }
                           elseif (($codigo -ge 71 -and $codigo -le 77) -or ($codigo -ge 85 -and $codigo -le 86)) { 'nieve' }
                           elseif ($codigo -ge 95) { 'tormenta' }
                           elseif ($codigo -le 1 -and -not $noche) { 'sol' } else { '' }
        if ($script:uiTiempo -ne $tiempoAntes) { Refresh-UI }
        # el avatar NO cambia solo: la carita manda. El tiempo se ensena solo
        # cuando se pregunta (Resolve-Fragment) y unos segundos.
        Log "clima: $desc, $temp grados (codigo $codigo)"
    } catch { Log ("clima: no disponible (" + $_.Exception.Message + ")") }
}

# =====================================================================
# REGLAS POR VOZ: "cuando abra elden ring pon modo noche", "cuando la bateria
# baje del 20 bloquea", "todos los dias a las 9 pon el brillo al 60", "cada
# 45 minutos avisame en 0 minutos que descanse". Se guardan en reglas.json y
# se evaluan desde el bucle principal. La accion es una orden LOCAL (se
# valida con Test-FastCommand al crearla): nada de texto libre al modelo.
# =====================================================================
# --- COPIA DE SEGURIDAD DE LO APRENDIDO (idea 8) ---
# Traducciones, reglas, modos, alias, rechazos, listas, fechas, recordatorios,
# el diario y la voz del dueno: meses de ajustes repartidos en una docena de
# JSON que se reescriben enteros cada vez. Uno que se corte a medias (un
# apagon, la bateria a cero en mitad de un Set-Content) se lleva todo lo suyo
# sin avisar. Una copia al dia, sola, y otra cuando se pida; se guardan las 14
# ultimas, que con ~40 KB cada una no ocupan nada.
$CopiasDir = Join-Path $LogDir 'copias'
$CopiasMax = 14
function New-CopiaSeguridad([string]$motivo = 'a mano') {
    try {
        $origen = @($TraduccionesPath, (Join-Path $LogDir 'reglas.json'), $cmdsPath, $cfgPath, $MemoriaDir,
                    (Join-Path $TmpDir 'mi-voz.json')) | Where-Object { $_ -and (Test-Path -LiteralPath $_) }
        if ($origen.Count -eq 0) { Log "COPIA: no hay nada que copiar"; return $null }
        if (-not (Test-Path -LiteralPath $CopiasDir)) { New-Item -ItemType Directory -Path $CopiasDir -Force | Out-Null }
        $zip = Join-Path $CopiasDir ('lo-aprendido_' + (Get-Date -Format 'yyyy-MM-dd_HHmm') + '.zip')
        Compress-Archive -LiteralPath $origen -DestinationPath $zip -Force -ErrorAction Stop
        # las viejas fuera: el nombre lleva la fecha, asi que ordenar por nombre es ordenar por fecha
        Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' | Sort-Object Name -Descending |
            Select-Object -Skip $CopiasMax | Remove-Item -Force -ErrorAction SilentlyContinue
        $n = @($origen | ForEach-Object { if (Test-Path -LiteralPath $_ -PathType Container) { Get-ChildItem -LiteralPath $_ -Recurse -File } else { Get-Item -LiteralPath $_ } }).Count
        $kb = [int][Math]::Ceiling((Get-Item -LiteralPath $zip).Length / 1KB)
        Log "COPIA ($motivo): $n archivos, $kb KB -> $zip"
        # TAMBIEN EN ONEDRIVE (13/09): si el equipo tiene OneDrive, la misma copia
        # se deja en OneDrive\Nova\copias (las 14 ultimas), para no perderla si se
        # pierde la Ally. Si no hay OneDrive, no pasa nada.
        try {
            $odN = $env:OneDrive
            if ($odN -and (Test-Path -LiteralPath $odN)) {
                $destOD = Join-Path $odN 'Nova\copias'
                if (-not (Test-Path -LiteralPath $destOD)) { New-Item -ItemType Directory -Force -Path $destOD | Out-Null }
                Copy-Item -LiteralPath $zip -Destination $destOD -Force
                @(Get-ChildItem -LiteralPath $destOD -Filter 'lo-aprendido_*.zip' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -Skip 14) |
                    ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
                Log "COPIA: tambien en OneDrive ($destOD)"
            }
        } catch { Log ("COPIA: no pude dejarla en OneDrive: " + $_.Exception.Message) }
        return @{ ruta = $zip; archivos = $n; kb = $kb }
    } catch {
        Log ("COPIA fallida ($motivo): " + $_.Exception.Message)
        return $null
    }
}
# ¿Hace falta la copia del dia? Solo si la ultima tiene mas de 20 horas: asi
# reiniciar el asistente cinco veces no deja cinco copias iguales.
function Test-CopiaPendiente {
    if (-not (Test-Path -LiteralPath $CopiasDir)) { return $true }
    $ultima = Get-ChildItem -LiteralPath $CopiasDir -Filter 'lo-aprendido_*.zip' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if (-not $ultima) { return $true }
    return (((Get-Date) - $ultima.LastWriteTime).TotalHours -ge 20)
}

$ReglasPath = Join-Path $LogDir 'reglas.json'
$script:reglas = $null
$HORAS_PALABRA = @{ 'una' = 1; 'dos' = 2; 'tres' = 3; 'cuatro' = 4; 'cinco' = 5; 'seis' = 6; 'siete' = 7; 'ocho' = 8; 'nueve' = 9; 'diez' = 10; 'once' = 11; 'doce' = 12 }

function Get-Reglas {
    if ($null -ne $script:reglas) { return ,$script:reglas }
    $script:reglas = New-Object System.Collections.ArrayList
    if (Test-Path -LiteralPath $ReglasPath) {
        try {
            # sin @(): ver el comentario de Get-Recordatorios
            $crudoReglas = Get-Content -LiteralPath $ReglasPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($r in $crudoReglas) {
                if ($null -eq $r -or -not [string]$r.tipo) { continue }
                # 'hasta' (23/09, idea 4): dia en que caduca la regla, 'yyyy-MM-dd'. Vacio = sin
                # plazo, que es como se leen las reglas de antes: se portan igual que siempre.
                [void]$script:reglas.Add(@{ id = [int]$r.id; tipo = [string]$r.tipo; valor = [string]$r.valor; accion = [string]$r.accion; ultima = [string]$r.ultima; cond = [string]$r.cond; hasta = [string]$r.hasta })
            }
        } catch { Save-Corrupto $ReglasPath 'reglas' }
    }
    # la coma evita que PowerShell "desenrolle" la lista vacia en $null
    return ,$script:reglas
}

function Save-Reglas {
    try {
        # foreach sobre la variable, no por tuberia: la lista llega como UN
        # objeto (por la coma de Get-Reglas) y la tuberia no la desenrollaria
        $g = Get-Reglas
        $lista = @()
        foreach ($x in $g) {
            $o = New-Object PSObject
            foreach ($k in 'id', 'tipo', 'valor', 'accion', 'ultima', 'cond', 'hasta') { $o | Add-Member -NotePropertyName $k -NotePropertyValue $x[$k] }
            $lista += $o
        }
        $json = if ($lista.Count -eq 0) { '[]' } else { ConvertTo-Json -InputObject @($lista) -Depth 4 }
        Write-Atomico $ReglasPath $json
    } catch { Log ("reglas: no pude guardar: " + $_.Exception.Message) }
}

# --- REGLAS SOBRE CUALQUIER APP (idea 5) ---
# Antes "cuando abra X" solo entendia juegos de Steam: "cuando abra Spotify,
# baja el juego al 40" contestaba "no conozco el juego". Ahora X puede ser
# cualquier app de commands.json. Si el nombre es EXACTAMENTE una app, gana la
# app (Spotify no debe acabar emparejado por parecido con un juego); si no, se
# prueba como juego y, por ultimo, como app por parecido.
function Resolve-SujetoRegla([string]$obj) {
    if ($cmds -and (Test-Prop $cmds.apps $obj)) { return @{ app = $true; nombre = $obj } }
    $j = Find-Juego $obj
    if ($j) { return @{ app = $false; nombre = $j.nombre } }
    $pr = Resolve-Proceso $obj
    if ($pr -and $pr.proceso -ne '*juego*') { return @{ app = $true; nombre = $pr.nombre } }
    return $null
}

# Vigila las apps que salen en alguna regla y dispara al CAMBIAR: de cerrada a
# abierta (appAbre) y al reves (appCierra). La primera mirada solo toma nota:
# si al arrancar el asistente Spotify ya estaba abierto, eso no es "abrirlo".
# Lo mismo con una regla recien creada: su app se apunta y dispara a la
# siguiente vez que cambie.
$script:appsCheck = 0
$script:appsVivas = @{}
function Watch-AppsReglas {
    $g = Get-Reglas
    $nombres = @($g | Where-Object { $_.tipo -eq 'appAbre' -or $_.tipo -eq 'appCierra' } | ForEach-Object { $_.valor } | Select-Object -Unique)
    if ($nombres.Count -eq 0) { $script:appsVivas = @{}; return }
    foreach ($n in $nombres) {
        $pr = Resolve-Proceso $n
        if (-not $pr -or $pr.proceso -eq '*juego*') { continue }
        $viva = [bool](Get-Process -Name $pr.proceso -ErrorAction SilentlyContinue)
        $antes = $script:appsVivas[$n]
        $script:appsVivas[$n] = $viva
        if ($null -eq $antes) { continue }
        if ($viva -and -not $antes) { Log "APP abierta: $n"; Invoke-Reglas 'appAbre' $n }
        elseif ($antes -and -not $viva) { Log "APP cerrada: $n"; Invoke-Reglas 'appCierra' $n }
    }
}

function Describe-Regla($r) {
    $cuando = switch ($r.tipo) {
        'juegoAbre' { if ($r.valor) { "cuando abras $($r.valor)" } else { 'cuando abras un juego' } }
        'juegoCierra' { if ($r.valor) { "cuando cierres $($r.valor)" } else { 'cuando cierres el juego' } }
        'appAbre' { "cuando abras $($r.valor)" }
        'appCierra' { "cuando cierres $($r.valor)" }
        'bateria' { "cuando la bateria baje del $($r.valor) por ciento" }
        'cargadorQuita' { 'cuando quites el cargador' }
        'cargadorPone' { 'cuando enchufes el cargador' }
        'dockPone' { 'cuando conectes el dock o una pantalla' }
        'cascosPone' { 'cuando te pongas los cascos' }
        'dockQuita' { 'cuando quites la pantalla' }
        'cascosQuita' { 'cuando te quites los cascos' }
        'bateriaLlena' { 'cuando termine de cargar' }
        'discoJuegos' { if ($r.valor -eq 'quita') { 'cuando quites el disco de los juegos' } else { 'cuando conectes el disco de los juegos' } }
        'mandoCoge' { 'cuando cojas el mando' }
        # el nombre, no el steamid: la regla se lee en voz alta y un 76561198... no se entiende
        'amigoConecta' { $nomD = ([string]$r.valor).Split('|'); if ($nomD.Count -ge 2 -and $nomD[1]) { "cuando se conecte $($nomD[1])" } else { 'cuando se conecte' } }
        'disco' { "cuando queden menos de $($r.valor) gigas" }
        'descarga' { if ($r.valor) { "cuando termine de descargarse $($r.valor)" } else { 'cuando termine una descarga' } }
        'hora' { "todos los dias a las $($r.valor)" }
        'cada' { "cada $($r.valor) minutos" }
        default { $r.tipo }
    }
    return "$cuando" + $(if ($r.cond -eq 'noche') { ' y sea de noche' } elseif ($r.cond -eq 'dia') { ' y sea de dia' } else { '' }) + ", $($r.accion)" + $(if ($r.ultima -eq 'unavez') { ' (una sola vez)' } else { '' }) + $(if ($r.hasta) { ' (solo por hoy)' } else { '' })
}

# CADA CUANTO TOCA, CONTADO CON EL RELOJ DE PARED (23/09, idea 4).
# Antes esto se contaba con $sw.ElapsedMilliseconds, que es el cronometro DEL PROCESO, y se
# persistia en reglas.json. Dos fallos en uno:
#  - al reiniciar, $sw vuelve a cero y $r.ultima sigue valiendo, por ejemplo, 7200000: la
#    resta sale NEGATIVA y la regla no vuelve a hablar NUNCA. Con 244 arranques en 15 dias
#    -16,3 al dia- eso le pasa el primer dia;
#  - y aunque estuviera a cero, la cuenta empezaba de cero en cada arranque, asi que "cada
#    dos horas" casi nunca llegaba a las dos horas: la sesion media no llega a hora y media.
# El $ahora es parametro para que una prueba pueda mover el reloj en vez de esperar dos horas.
# NADA DE AVISOS ATRASADOS (regla 1): tras nueve horas apagado con periodo de dos, se dispara
# UNA vez y se rearma; no se sueltan de golpe las cuatro que "tocaban".
function Test-CadaDispara($r, [datetime]$ahora = (Get-Date)) {
    $per = [int]$r.valor
    if ($per -lt 1) { return $false }
    # MIGRACION DEL FORMATO VIEJO, sin fichero nuevo ni una linea de mas: un 'ultima' que son
    # TODO digitos son los milisegundos del cronometro de otra sesion, y un [datetime] de
    # "7200000" NUNCA parsea (comprobado, tambien con "20260923" y "1200"). Asi que el catch
    # ya hace la migracion entera: lo viejo se lee como "no ha disparado nunca" y la cuenta
    # arranca hoy. Se probo poner ademas un -notmatch de digitos y no cambiaba nada: rompiendo
    # esa linea a proposito, el banco seguia en verde.
    $ult = $null
    if ($r.ultima) { try { $ult = [datetime]$r.ultima } catch { $ult = $null } }
    if (-not $ult) { $r.ultima = $ahora.ToString('s'); return $false }
    if (($ahora - $ult).TotalMinutes -lt $per) { return $false }
    $r.ultima = $ahora.ToString('s')
    return $true
}

# SE ACABO EL PLAZO? (23/09, idea 4). Una regla que habla sola cada dos horas y sobrevive
# semanas es justo la fabrica de las 101 frases (de 232) que Nova arranco sola y cayeron en
# el vacio. Por eso una regla 'cada' nace con plazo de hoy, salvo que braya diga 'siempre'.
function Test-ReglaCaducada($r, [datetime]$ahora = (Get-Date)) {
    if (-not $r.hasta) { return $false }
    try { return ($ahora.Date -gt [datetime]::ParseExact([string]$r.hasta, 'yyyy-MM-dd', $null)) } catch { return $false }
}

# Intenta interpretar la frase como regla. Devuelve la respuesta hablada, o
# $null si no es una regla.
function Invoke-ReglaVoz([string]$text) {
    $p = ConvertTo-Plain $text
    $g = Get-Reglas
    # REGLAS COMBINADAS (13/09): "cuando abra hades y sea de noche, pon modo noche".
    # La condicion se quita de la frase (el resto se entiende como siempre) y se
    # guarda aparte; al dispararse, se mira la hora (noche = de 20:00 a 7:00).
    $condR = ''
    if ($p -match '^cuando\s' -and $p -match '\s+(?:y\s+)?(?:solo\s+)?(?:(?:sea|es|este|estemos)\s+)?(?:de|por la|en la)\s+(noche|dia)\b') {
        $condR = $Matches[1]
        $p = ($p -replace '\s+(?:y\s+)?(?:solo\s+)?(?:(?:sea|es|este|estemos)\s+)?(?:de|por la|en la)\s+(?:noche|dia)\b', '').Trim()
    }
    # "SIEMPRE", QUE NOVA OFRECIA Y NO EXISTIA (24/09, repaso). Al crear una regla 'cada' Nova
    # dice literalmente "Di 'siempre' si quieres que se quede", y NO habia ni un patron que
    # entendiera esa palabra: la frase se iba al modelo y la regla se moria a medianoche
    # creyendo braya que la habia dejado fija. Anunciar una salida que no existe es peor que
    # no anunciarla.
    # La ventana es la misma que la de las otras respuestas cortas de la casa: si no se dice
    # en dos minutos, "siempre" vuelve a ser una palabra cualquiera.
    if ($p -match '^(?:siempre|que se quede|dejala|dejalo|todos los dias|cada dia|para siempre)$' -and
        $script:ultimaRegla -and ($sw.ElapsedMilliseconds - [double]$script:ultimaRegla.en) -lt 120000) {
        $idS = [int]$script:ultimaRegla.id
        $script:ultimaRegla = $null
        $qS = @(); foreach ($xS in @($g)) { if ($xS.id -eq $idS) { $qS += $xS } }
        if ($qS.Count -eq 0) { return "Esa regla ya no esta." }
        if (-not $qS[0].hasta) { return "La regla $idS ya se queda puesta." }
        $qS[0].hasta = ''
        Save-Reglas
        Log "REGLA ${idS}: se queda sin plazo (lo pediste diciendo 'siempre')"
        return ("Vale, la regla $idS se queda. Di 'borra la regla $idS' cuando te canse.")
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+(?:todas\s+)?(?:las\s+)?reglas$') {
        $g.Clear(); Save-Reglas; return "Listo, sin reglas."
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+la\s+regla\s+(\d+)$') {
        $id = [int]$Matches[1]
        $q = @($g | Where-Object { $_.id -eq $id })
        if ($q.Count -eq 0) { return "No hay ninguna regla $id" }
        foreach ($x in $q) { $g.Remove($x) }
        Save-Reglas; return "Regla $id borrada."
    }
    # LA SEGUNDA SALIDA, POR TEXTO (23/09, idea 4). La de numero -"borra la regla 3"- es lista
    # cerrada y aguanta el 70,4 % del oido, pero exige acordarse del numero que Nova canto
    # hace horas. Las dos NO SE PISAN, y no por el orden: esta exige la palabra "recordatorio",
    # "aviso" o "recordarme", que la de numero no lleva. Se probo cambiandolas de sitio a
    # proposito y no pasaba nada, asi que el orden aqui no es lo que las separa.
    # SI HAY MAS DE UNA QUE ENCAJE NO SE BORRA NINGUNA: se leen con su numero y se pregunta.
    # Borrar la que no era es exactamente la regla 1 al reves.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UN RECORDATORIO (23/09). "quita el aviso de cada
    # hora" es de Resolve-Fragment, y esta funcion se mira ANTES, asi que sin esta salvedad
    # aquel patron se quedaba en codigo muerto. Lo canto probar-tiempo-juego, que es justo
    # para lo que esta. La lista es cerrada y es LA MISMA que la de alli.
    if ($p -match '^(?:deja\s+de\s+(?:recordarme|avisarme|decirme)|quita(?:me)?\s+(?:el\s+)?(?:recordatorio|aviso)|borra\s+(?:el\s+)?(?:recordatorio|aviso))\s+(?!(?:de\s+|del\s+)?(?:cada\s+)?(?:hora|rato|tiempo|tiempo de juego|juego)$)(?:lo\s+)?(?:de\s+|del\s+|que\s+|sobre\s+)?(.+)$') {
        $busca = (ConvertTo-Suave ($Matches[1].Trim()))
        $cand = @($g | Where-Object { $_.tipo -in @('cada', 'hora') -and (ConvertTo-Suave ([string]$_.accion)).Contains($busca) })
        if ($cand.Count -eq 0) { return "No tengo ningun recordatorio de eso." }
        if ($cand.Count -gt 1) {
            return ("Tengo " + $cand.Count + " que encajan: " + (($cand | ForEach-Object { "regla $($_.id), " + (Describe-Regla $_) }) -join '. ') + ". Dime cual borro.")
        }
        $qR = $cand[0]
        [void]$g.Remove($qR); Save-Reglas
        Log ("REGLA $($qR.id) borrada por texto: " + (Describe-Regla $qR))
        return "Listo, ya no te lo recuerdo. Era la regla $($qR.id)."
    }
    if ($p -match '^(?:que reglas hay|que reglas tengo|mis reglas|cuales son las reglas|lista las reglas|dime las reglas)$') {
        if ($g.Count -eq 0) { return "No tienes reglas. Puedes decir: cuando abra un juego, pon modo juego." }
        return ("Tienes " + $g.Count + ": " + (($g | ForEach-Object { "regla $($_.id), " + (Describe-Regla $_) }) -join '. '))
    }
    # RECORDATORIO DE UN SOLO USO LIGADO A UNA APP (13/09): "recuerdame comprar la
    # expansion cuando abra hades" o "cuando abra hades recuerdame...". Es una regla
    # que lo dice la primera vez que abres eso, y se borra sola.
    # y el recordatorio de un solo uso al conectar el dock o ponerse los cascos (F8)
    $recDisp = $null; $recTxtD = $null
    $RE_DISP = '((?:conecte|conectes|enchufe|ponga)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)|(?:me\s+)?(?:conecte|ponga)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos))'
    if ($p -match ('^(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+?)\s+cuando\s+' + $RE_DISP + '$')) { $recTxtD = $Matches[1]; $recDisp = $Matches[2] }
    elseif ($p -match ('^cuando\s+' + $RE_DISP + '\s*,?\s*(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+)$')) { $recDisp = $Matches[1]; $recTxtD = $Matches[2] }
    if ($recDisp -and $recTxtD) {
        $esCascos = ($recDisp -match 'cascos|auriculares|audifonos')
        $idD = 1; foreach ($x in $g) { if ($x.id -ge $idD) { $idD = $x.id + 1 } }
        $rDisp = @{ id = $idD; tipo = $(if ($esCascos) { 'cascosPone' } else { 'dockPone' }); valor = ''; accion = "di " + $recTxtD.Trim(); ultima = 'unavez' }
        [void]$g.Add($rDisp); Save-Reglas
        Log ("REGLA $idD guardada: " + (Describe-Regla $rDisp))
        return "Vale, te lo recuerdo cuando " + $(if ($esCascos) { 'te pongas los cascos.' } else { 'conectes el dock.' })
    }
    $recApp = $null; $recTexto = $null
    if ($p -match '^(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+?)\s+cuando\s+(?:abra|abras|abro|inicie|arranque|entre en|entre a|juegue a|juegue al|juegue)\s+(?:el\s+|la\s+|al\s+|a\s+)?(.+)$') {
        $recTexto = $Matches[1]; $recApp = $Matches[2]
    } elseif ($p -match '^cuando\s+(?:abra|abras|abro|inicie|arranque|entre en|entre a|juegue a|juegue al|juegue)\s+(?:el\s+|la\s+|al\s+|a\s+)?(.+?)\s*,?\s*(?:recuerdame|avisame)\s+(?:que\s+|de\s+)?(.+)$') {
        $recApp = $Matches[1]; $recTexto = $Matches[2]
    }
    if ($recApp -and $recTexto) {
        $sujR = Resolve-SujetoRegla $recApp.Trim()
        if (-not $sujR) { return "No conozco '$($recApp.Trim())': no es un juego instalado ni una app de las que se abrir." }
        $idR = 1; foreach ($x in $g) { if ($x.id -ge $idR) { $idR = $x.id + 1 } }
        $rR = @{ id = $idR; tipo = $(if ($sujR.app) { 'appAbre' } else { 'juegoAbre' }); valor = $sujR.nombre; accion = "di " + $recTexto.Trim(); ultima = 'unavez' }
        [void]$g.Add($rR); Save-Reglas
        Log ("REGLA $idR guardada: " + (Describe-Regla $rR))
        return "Vale, te lo recuerdo cuando abras $($sujR.nombre)."
    }
    $tipo = $null; $valor = ''; $accion = ''
    # LAS PALABRAS TAMBIEN SON NUMEROS (23/09, idea 4). El patron de 'cada' pide digitos y
    # ConvertTo-Plain no los convierte, asi que "cada DOS horas di que estire la espalda" no
    # casaba con nada y se iba al modelo. ConvertTo-Digitos ya existia y no la llamaba nadie
    # desde aqui. Se guarda APARTE y solo la usan los dos patrones de 'cada': los doce de
    # arriba dependen de las palabras tal cual ("cuando abra hades" tiene que seguir entrando).
    $pCada = ConvertTo-Digitos $p
    if ($p -match '^cuando\s+(?:se\s+)?(?:abra|abras|abro|inicie|arranque|empiece|entre a|entre en)\s+(?:el\s+|un\s+|cualquier\s+)?(.+?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'juegoAbre'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        if ($obj -notmatch '^(?:juego|videojuego|algo|cualquier cosa)$') {
            $sujeto = Resolve-SujetoRegla $obj
            if (-not $sujeto) { return "No conozco '$obj': no es un juego instalado ni una app de las que se abrir." }
            if ($sujeto.app) { $tipo = 'appAbre' }
            $valor = $sujeto.nombre
        }
    }
    # "AVISAME CUANDO LA DESCARGA DE STEAM TERMINE" (21/09 noche, del uso real). braya lo
    # dijo asi y le costo 46 SEGUNDOS para acabar oyendo que no se podia: parakeet ->
    # canary -> omni -> whisper -> la nube -> la API, y la API contesto 'No puedo completar
    # esta orden porque falta especificar que accion quieres'. La orden era perfecta; lo que
    # faltaba era el patron. El de abajo solo entiende el orden inverso -'cuando termine de
    # descargarse X, avisame'-, que nadie dice asi.
    # AQUI LA ACCION ES AVISAR, y por eso no hace falta que diga que hacer: 'avisame' YA es
    # lo que quiere. Va DELANTE del patron de abajo porque es mas especifico (pide el verbo
    # de avisar al principio) y no le quita ninguna frase.
    # LA VOCAL FINAL SE LA COME EL OIDO (22/09, minando los descartes). En la lista de
    # frases tiradas estaba 'avisame cuando la descarga de Steam TERMINO' dos veces, con
    # 'termino' donde braya dijo 'termine'. No es que lo dijera mal: es que Whisper y
    # Parakeet fallan la vocal atona del final constantemente, que es de lo mas dificil
    # de oir. Aceptar termine/termino/termina -y acabe/acabo/acaba, etc.- no abre la
    # puerta a nada: 'la descarga termino' y 'cuando la descarga termine' piden lo mismo,
    # y el patron ya exige el 'avisame cuando' delante.
    if ($p -match '^(?:avisa|avisame|avisas|dime|me dices|me avisas)\s+(?:cuando|en cuanto)\s+(?:(?:se\s+)?(?:termin[eoa]|acab[eoa]|complet[eoa]|descargue|baj[eoa]|instal[eoa])\s+(?:de\s+)?(?:descargar|bajar|instalar)?(?:se)?\s*(?:el\s+|la\s+|un\s+)?(?:descarga\s+de\s+)?(.*?)|(?:la\s+)?descarga(?:\s+de\s+(.*?))?\s+(?:termin[eoa]|acab[eoa]|se\s+complet[eoa]))\s*$') {
        # los dos grupos se copian YA: el -match de Find-Juego pisaria $Matches
        $objA = ([string]$Matches[1]).Trim()
        if (-not $objA) { $objA = ([string]$Matches[2]).Trim() }
        $tipo = 'descarga'; $accion = 'avisame'
        $valor = ''
        # 'avisame cuando termine la descarga' sin decir cual: vale cualquiera, que es lo que
        # hace el patron de abajo con 'algo'. Y 'de steam' no es un juego: es de donde baja.
        if ($objA -and $objA -notmatch '^(?:algo|cualquier cosa|lo que sea|juego|videojuego|el juego|descarga|la descarga|steam|de steam|el steam)$') {
            $jA = Find-Juego $objA
            if ($jA) { $valor = $jA.nombre } else { return "No conozco el juego '$objA'" }
        }
    }
    # DESCARGAS: "cuando termine de descargarse elden ring, abrelo"
    # Ojo con el orden: esta va ANTES que la de "cuando termine X" (cerrar un
    # juego), porque "cuando termine de descargarse X" tambien encaja alli y
    # se quedaria con ella.
    elseif ($p -match '^cuando\s+(?:se\s+)?(?:termine|acabe|complete)\s+(?:de\s+)?(?:descargar|bajar|instalar)(?:se)?\s*(?:el\s+|la\s+|un\s+)?(.*?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame|abrelo|abrela|ejecutalo|lanzalo|inicialo|arrancalo|juegalo)\b.*)$') {
        $tipo = 'descarga'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        $valor = ''
        if ($obj -and $obj -notmatch '^(?:algo|cualquier cosa|lo que sea|juego|videojuego|el juego|descarga|la descarga)$') {
            $j = Find-Juego $obj
            if ($j) { $valor = $j.nombre } else { return "No conozco el juego '$obj'" }
        }
        # "abrelo" es la forma NATURAL aqui y no vale en ninguna otra regla, porque
        # en las demas no hay un "lo" evidente. Aqui si lo hay: el juego que acaba
        # de bajarse. Se traduce ya, que la accion se guarda como texto y luego la
        # ejecuta Invoke-FastCommand sin saber de que regla vino.
        if ($accion -match '^(?:abrelo|abrela|ejecutalo|lanzalo|inicialo|arrancalo|juegalo)$') {
            if (-not $valor) { return "Dime que juego: 'abrelo' no se a que se refiere si no nombras uno." }
            $accion = "abre $valor"
        }
    }
    # LA BATERIA LLENA: "cuando termine de cargar, avisame" (16/09).
    # OJO CON EL ORDEN, y esto lo cazo el banco: tiene que ir ANTES que la de cerrar un
    # juego ("cuando termine X"), porque esa se comia "cuando termine DE CARGAR" tomando
    # "de cargar" como nombre de juego, y contestaba "no conozco 'de cargar'". Es la
    # misma trampa que ya obligo a subir la de las descargas, unas lineas mas arriba.
    elseif ($p -match '^cuando\s+(?:(?:se\s+)?(?:termine|acabe)\s+de\s+cargar(?:se)?|(?:la\s+)?(?:bateria|pila)\s+(?:este|se\s+ponga)\s+(?:llena|cargada|al\s+(?:cien|100)(?:\s*(?:por ciento|%))?))\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'bateriaLlena'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:se\s+)?(?:cierre|cierres|cierro|termine|acabe|salga de|salga del)\s+(?:el\s+|un\s+|cualquier\s+)?(.+?)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'juegoCierra'; $obj = $Matches[1].Trim(); $accion = $Matches[2].Trim()
        if ($obj -notmatch '^(?:juego|videojuego|algo|cualquier cosa)$') {
            $sujeto = Resolve-SujetoRegla $obj
            if (-not $sujeto) { return "No conozco '$obj': no es un juego instalado ni una app de las que se abrir." }
            if ($sujeto.app) { $tipo = 'appCierra' }
            $valor = $sujeto.nombre
        }
    }
    elseif ($p -match '^cuando\s+la\s+(?:bateria|pila)\s+(?:baje|este|llegue|caiga)\s+(?:del|al|a|por debajo del|por debajo de|de|menos del)\s+(\d{1,3})\s*(?:por ciento|%)?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'bateria'; $valor = [string][int]$Matches[1]; $accion = $Matches[2].Trim()
    }
    # CARGADOR: "cuando quite el cargador pon el brillo al 30"
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:quite|quites|desenchufe|desenchufes|saque|saques|desconecte|desconectes)\s+(?:el\s+)?(?:cargador|cable|corriente|enchufe)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cargadorQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:enchufe|enchufes|conecte|conectes|ponga|pongas)\s+(?:el\s+)?(?:cargador|cable|corriente|enchufe|a cargar)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cargadorPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # DOCK Y CASCOS (F8): "cuando conecte el dock pon modo tele", "cuando me ponga los cascos sube el volumen"
    elseif ($p -match '^cuando\s+(?:conecte|conectes|enchufe|enchufes|ponga|pongas)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'dockPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    elseif ($p -match '^cuando\s+(?:me\s+)?(?:conecte|conectes|ponga|pongas)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cascosPone'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # LOS SENSORES DE LAS 31 IDEAS, YA ENGANCHABLES (16/09). Hasta ahora Nova se
    # enteraba de todo esto y solo lo decia; no se podia colgar nada de ello.
    # "cuando quite el dock, pon el modo bateria"
    elseif ($p -match '^cuando\s+(?:lo\s+|la\s+)?(?:quite|quites|desconecte|desconectes|saque|saques|desenchufe|desenchufes)\s+(?:el\s+|la\s+)?(?:dock|base|tele|television|monitor|pantalla)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'dockQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # "cuando me quite los cascos, pausa"
    elseif ($p -match '^cuando\s+(?:me\s+)?(?:quite|quites|saque|saques)\s+(?:los\s+|mis\s+)?(?:cascos|auriculares|audifonos)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'cascosQuita'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # "cuando conecte el disco de los juegos, di ya estan" (y al quitarlo).
    # El verbo decide: el mismo patron sirve para las dos, y el valor guarda cual.
    elseif ($p -match '^cuando\s+(conecte|conectes|enchufe|enchufes|ponga|pongas|quite|quites|desconecte|desconectes|saque|saques)\s+(?:el\s+)?disco(?:\s+(?:de\s+(?:los\s+)?juegos|externo|duro|de\s+fuera))?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'discoJuegos'; $accion = $Matches[2].Trim()
        $valor = if ($Matches[1] -match '^(?:quite|quites|desconecte|desconectes|saque|saques)$') { 'quita' } else { 'pone' }
    }
    # "cuando coja el mando, pon el modo juego"
    elseif ($p -match '^cuando\s+(?:coja|cojas|agarre|agarres|use|uses|toque|toques|encienda|enciendas)\s+(?:el\s+)?(?:mando|control|joystick|gamepad|mandito)\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'mandoCoge'; $valor = ''; $accion = $Matches[1].Trim()
    }
    # DISCO: "cuando queden menos de 20 gigas avisame"
    elseif ($p -match '^cuando\s+(?:queden|quede|haya|tenga)\s+menos\s+de\s+(\d{1,4})\s*(?:gigas?|gb|g)\b\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        $tipo = 'disco'; $valor = [string][int]$Matches[1]; $accion = $Matches[2].Trim()
    }
    elseif ($p -match '^(?:todos los dias|cada dia|diariamente|siempre)?\s*a\s+las?\s+(\d{1,2}|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce)(?::(\d{2})|\s+y\s+media|\s+y\s+cuarto)?\s*(de la manana|de la tarde|de la noche|de la madrugada|am|pm)?\s*,?\s*(?:entonces\s+)?((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        # Los grupos, COPIADOS antes de nada: el primer -match de las lineas de
        # abajo (la franja) reescribe $Matches entero y $Matches[4] desaparecia.
        # 'a las 10 de la noche pon modo noche' reventaba con una excepcion que
        # se tragaba el catch de Invoke-FastCommand, asi que la regla no se
        # creaba y nadie se enteraba. Lo mismo con 'y media' y 'y cuarto': el
        # ejemplo de la documentacion llevaba roto desde que se escribio.
        $g0 = $Matches[0]; $g1 = $Matches[1]; $g2 = $Matches[2]; $g3 = $Matches[3]; $g4 = $Matches[4]
        $h = $g1; if ($HORAS_PALABRA.ContainsKey($h)) { $h = $HORAS_PALABRA[$h] }; $h = [int]$h
        $m = 0
        if ($g2) { $m = [int]$g2 } elseif ($g0 -match 'y media') { $m = 30 } elseif ($g0 -match 'y cuarto') { $m = 15 }
        $franja = $g3
        if ($franja -match 'tarde|noche|pm' -and $h -lt 12) { $h += 12 }
        # LAS DOCE ES EL UNICO NUMERO QUE NO SIGUE LA REGLA (21/09). La linea de arriba
        # suma 12 solo si la hora es MENOR que 12, asi que el 12 no lo tocaba; y esta
        # miraba 'manana|am', que es justo al reves de como se dice en espanol:
        #   las doce de la NOCHE son las 00:00   (se guardaba 12:00, el mediodia)
        #   las doce de la MANANA son las 12:00  (se guardaba 00:00, la medianoche)
        # Error de doce horas exactas, y no solo en un aviso: 'a las doce de la noche pon
        # modo noche' le bajaba el brillo al MEDIODIA, jugando.
        # 'manana' y 'madrugada' no contienen 'am' (comprobado), asi que la alternancia
        # no se pisa a si misma.
        if ($franja -match 'noche|madrugada|am' -and $h -eq 12) { $h = 0 }
        $tipo = 'hora'; $valor = ('{0:00}:{1:00}' -f $h, $m); $accion = $g4.Trim()
    }
    # COMO LO DICE EL DE VERDAD (23/09, idea 4): "recuerdame cada dos horas que estire la
    # espalda". Va DELANTE del de '^cada' de abajo, que ancla al principio de la frase, asi
    # que no le quita ni una. Y no le roba nada al aviso del tiempo de juego, que exige que la
    # frase ACABE ahi ("avisame cada hora"): este pide una accion detras.
    # 'media', 'un' y 'una' se admiten a mano porque ConvertTo-Digitos los deja fuera a
    # proposito -son articulos muchas mas veces que numeros-.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UN RECORDATORIO (24/09, repaso). "avisame cada 2 horas
    # que llevo jugando" caia aqui -esta funcion se mira antes que Resolve-Fragment- y creaba
    # una regla cuya accion era "di llevo jugando": Nova decia literalmente eso cada dos horas.
    # La cola es la MISMA lista que la del patron de alla, y por eso esta escrita igual.
    elseif ($pCada -match '^(?:recuerdame|avisame|recuerda|dime)\s+cada\s+(?:\d{1,4}|media|un|una)\s*(?:minutos?|horas?)\b\s*(?:que\s+)?(?:llevo\s+)?(?:jugando|de juego|del juego|con el juego)$') {
        return $null
    }
    elseif ($pCada -match '^(?:recuerdame|avisame|recuerda|dime)\s+cada\s+(\d{1,4}|media|un|una)\s*(minutos?|horas?)\b\s*(?:,\s*)?(?:que\s+|de\s+que\s+)?(.+)$') {
        $nR = [string]$Matches[1]; $unidadR = [string]$Matches[2]; $accionR = [string]$Matches[3]
        $n = if ($nR -eq 'media') { 1 } elseif ($nR -in @('un', 'una')) { 1 } else { [int]$nR }
        if ($unidadR -match '^hora') { $n *= 60 }
        if ($nR -eq 'media') { $n = [int]($n / 2) }
        if ($n -lt 1) { return "Cada cuanto tiempo? Necesito al menos un minuto." }
        $tipo = 'cada'; $valor = [string]$n
        # "recuerdame cada dos horas que estire la espalda" -> la accion es hablar
        $accion = $accionR.Trim()
        if ($accion -notmatch '(?i)^(?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b') { $accion = 'di ' + $accion }
    }
    # 'media', 'un' y 'una' entran aqui tambien (23/09, idea 4): ConvertTo-Digitos los deja
    # fuera a proposito -son articulos muchas mas veces que numeros- y sin esto "cada media
    # hora avisame" se iba al modelo.
    elseif ($pCada -match '^cada\s+(\d+|media|un|una)\s*(minutos?|horas?)\b\s*,?\s*((?:' + $VERBOS + '|modo|activa|desactiva|bloquea|di|avisa|avisame)\b.*)$') {
        # los grupos se copian ANTES del -match de la unidad, que pisa $Matches:
        # con "horas" la accion salia $null y la regla no se creaba (auditoria 13/09)
        $crudoC = [string]$Matches[1]; $unidadC = [string]$Matches[2]; $accionC = [string]$Matches[3]
        $n = if ($crudoC -match '^\d+$') { [int]$crudoC } else { 1 }
        if ($unidadC -match '^hora') { $n *= 60 }
        if ($crudoC -eq 'media') { $n = [int]($n / 2) }
        if ($n -lt 1) { return "Cada cuanto tiempo? Necesito al menos un minuto." }
        $tipo = 'cada'; $valor = [string]$n; $accion = $accionC.Trim()
    }
    if (-not $tipo) { return $null }
    # "avisame" a secas no es una accion ejecutable, pero es lo que se dice.
    # Se convierte en un aviso hablado con el texto del propio disparador.
    if ($accion -match '^(?:avisa|avisame)$') {
        $queDecir = switch ($tipo) {
            'disco' { "queda poco espacio en el disco, menos de $valor gigas" }
            'descarga' { if ($valor) { "$valor ha terminado de descargarse" } else { 'ha terminado una descarga' } }
            'bateria' { "te queda poca bateria, menos del $valor por ciento" }
            'cargadorQuita' { 'has quitado el cargador' }
            'cargadorPone' { 'ya esta cargando' }
            'dockPone' { 'has conectado una pantalla' }
            'cascosPone' { 'te has puesto los cascos' }
            'dockQuita' { 'has quitado la pantalla' }
            'cascosQuita' { 'te has quitado los cascos' }
            'bateriaLlena' { 'ya esta cargada del todo' }
            'discoJuegos' { if ($valor -eq 'quita') { 'has quitado el disco de los juegos' } else { 'ya esta el disco de los juegos' } }
            'mandoCoge' { 'has cogido el mando' }
            'juegoAbre' { 'ya abriste el juego' }
            'juegoCierra' { 'ya cerraste el juego' }
            'appAbre' { "se abrio $valor" }
            'appCierra' { "se cerro $valor" }
            default { 'aviso' }
        }
        $accion = "di $queDecir"
    }
    if (-not (Test-FastCommand $accion)) { return "Entendi la condicion, pero no reconozco la accion '$accion'. Tiene que ser una orden que yo sepa hacer." }
    # NADA DESTRUCTIVO EN ALGO QUE SE VA A EJECUTAR SOLO (17/09). Este mismo filtro ya
    # existia para las propuestas de costumbres ("que no se cuele nada destructivo en una
    # regla que corre sola"), pero el camino HABLADO se lo habia saltado: se podia decir
    # "cuando abra steam cierra todos los programas" y quedaba guardado. Es el MISMO
    # criterio a proposito; dos listas distintas acabarian separandose.
    # OJO CON LO QUE SOLO HABLA: "di ..." nunca es destructivo. Sin esta excepcion el
    # banco cazo -bien cazado- que "cuando termine de cargar avisame", que se convierte
    # en "di ya esta cargada del TODO", quedaba rechazada por la palabra "todo". El
    # filtro es para lo que HACE, no para lo que dice.
    if ((ConvertTo-Plain $accion) -notmatch '^di\s' -and
        (ConvertTo-Plain $accion) -match '^(?:cierra|apaga|reinicia|bloquea|borra|elimina)\b|\b(?:todo|todos|todas)\b') {
        Log "REGLA rechazada: '$accion' es demasiado gorda para dispararse sola"
        Add-Estadistica 'regla-peligrosa' $accion
        return "Eso prefiero que me lo pidas tu en el momento: no lo dejo en una regla que se dispara sola."
    }
    $id = 1; foreach ($x in $g) { if ($x.id -ge $id) { $id = $x.id + 1 } }
    # TODA REGLA QUE HABLA SOLA NACE CON PLAZO (23/09, idea 4; regla 2: ningun modo sin
    # salida). De 232 frases que Nova arranco sola, 101 -el 43,5 %- cayeron en el vacio: una
    # regla que habla cada dos horas y sobrevive semanas es la fabrica de esas 101. Asi que
    # una 'cada' dura hasta el final del dia salvo que braya diga 'siempre' o 'todos los
    # dias'. Solo las 'cada': las demas cuelgan de un suceso suyo -abrir un juego, quitar el
    # cargador- y no hablan por su cuenta.
    $hastaR = ''
    if ($tipo -eq 'cada' -and $p -notmatch '\b(?:siempre|todos los dias|cada dia|para siempre)\b') {
        $hastaR = (Get-Date).ToString('yyyy-MM-dd')
    }
    $r = @{ id = $id; tipo = $tipo; valor = $valor; accion = $accion; ultima = ''; cond = $condR; hasta = $hastaR }
    [void]$g.Add($r); Save-Reglas
    # LA QUE ACABA DE NACER, para que "siempre" sepa a cual se refiere (24/09, repaso)
    $script:ultimaRegla = @{ id = $id; en = $sw.ElapsedMilliseconds }
    Log ("REGLA $id guardada: " + (Describe-Regla $r))
    Add-Estadistica 'local' "regla: $text"
    # LAS DOS SALIDAS SE DICEN EN VOZ ALTA, que es lo unico que las hace salidas de verdad.
    $colaR = if ($hastaR) { " Di 'siempre' si quieres que se quede, o 'borra la regla $id'." } else { " Di 'borra la regla $id' cuando te canse." }
    return ("Regla $id guardada: " + (Describe-Regla $r) + "." + $colaR)
}

# Ejecuta las reglas de un tipo cuyo valor encaje.
function Invoke-Reglas([string]$tipo, [string]$dato = '') {
    # CUANTAS DISPARARON EN ESTA LLAMADA (21/09). No se devuelve con 'return' a
    # proposito: esta funcion se llama desde treinta sitios sin [void], y cualquier
    # cosa que devuelva se colaria en la salida de la funcion que la llama. Con un
    # $script: lo lee quien lo necesite y nadie mas se entera.
    $script:reglasDisparadas = 0
    $script:reglasCaducadas = 0
    $g = Get-Reglas
    if ($g.Count -eq 0) { return }
    $hoy = Get-Date -Format 'yyyy-MM-dd'
    foreach ($r in @($g)) {
        if ($r.tipo -ne $tipo) { continue }
        $dispara = $false
        switch ($tipo) {
            'juegoAbre' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'juegoCierra' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'appAbre' { $dispara = ($r.valor -eq $dato) }
            'appCierra' { $dispara = ($r.valor -eq $dato) }
            'bateria' {
                $pct = [int]$dato
                if ($pct -le [int]$r.valor) { if ($r.ultima -ne 'baja') { $dispara = $true; $r.ultima = 'baja' } }
                elseif ($pct -gt ([int]$r.valor + 10)) { $r.ultima = '' }
            }
            'cargadorQuita' { $dispara = ($dato -eq 'quita') }
            'cargadorPone' { $dispara = ($dato -eq 'pone') }
            'dockPone' { $dispara = ($dato -eq 'pone') }
            'cascosPone' { $dispara = ($dato -eq 'pone') }
            'dockQuita' { $dispara = ($dato -eq 'quita') }
            'cascosQuita' { $dispara = ($dato -eq 'quita') }
            'bateriaLlena' { $dispara = ($dato -eq 'llena') }
            # sin valor vale cualquiera de las dos, por si alguien dice solo "el disco"
            'discoJuegos' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'mandoCoge' { $dispara = ($dato -eq 'coge') }
            # el dato que llega es el steamid, que es lo unico que no cambia: el nick se puede
            # cambiar en Steam en cualquier momento
            'amigoConecta' { $dispara = (([string]$r.valor).Split('|')[0] -eq $dato) }
            'disco' {
                # igual que la bateria: solo al cruzar el umbral, y se rearma
                # cuando vuelve a haber holgura (5 gigas de margen)
                $gb = [double]$dato
                if ($gb -le [double]$r.valor) { if ($r.ultima -ne 'poco') { $dispara = $true; $r.ultima = 'poco' } }
                elseif ($gb -gt ([double]$r.valor + 5)) { $r.ultima = '' }
            }
            'descarga' { $dispara = (-not $r.valor -or $r.valor -eq $dato) }
            'hora' { if ($dato -eq $r.valor -and $r.ultima -ne $hoy) { $dispara = $true; $r.ultima = $hoy } }
            'cada' {
                # ver Test-CadaDispara: el reloj de pared, no el cronometro del proceso
                # NI 'continue' NI 'break' AQUI DENTRO: dentro de un switch los dos salen del
                # switch, no del foreach, y eso se lee como si saltara la regla cuando en
                # realidad hace otra cosa. Se apaga $dispara y lo recoge el if de abajo.
                if (Test-ReglaCaducada $r) {
                    Log "REGLA $($r.id): se acabo el plazo de hoy, la quito"
                    [void]$g.Remove($r); $script:reglasCaducadas++
                    $dispara = $false
                } else {
                    $dispara = Test-CadaDispara $r
                }
            }
        }
        if (-not $dispara) { continue }
        # la condicion de una regla combinada (ver REGLAS COMBINADAS)
        if ($r.cond) {
            $horaC = (Get-Date).Hour
            $esNocheC = ($horaC -ge 20 -or $horaC -lt 7)
            if (($r.cond -eq 'noche' -and -not $esNocheC) -or ($r.cond -eq 'dia' -and $esNocheC)) { continue }
        }
        # LA SEGUNDA PUERTA (17/09). Al crear ya no se admite nada destructivo, pero una
        # regla guardada ANTES de ese filtro -o escrita a mano en reglas.json- llegaba
        # aqui igual, y $script:confirmado = $true le daba carta blanca: "cierra todos
        # los programas" se ejecutaba sin preguntar y sin que nadie pudiera pararlo.
        # Mismo criterio que al crearla, a proposito.
        # misma excepcion que al crearla: "di ..." solo habla, y "di ya esta cargada del
        # TODO" no puede quedarse sin dispararse por llevar esa palabra
        if ((ConvertTo-Plain $r.accion) -notmatch '^di\s' -and
            (ConvertTo-Plain $r.accion) -match '^(?:cierra|apaga|reinicia|bloquea|borra|elimina)\b|\b(?:todo|todos|todas)\b') {
            Log "REGLA $($r.id) NO se dispara: '$($r.accion)' es demasiado gorda para hacerla sola"
            Add-Estadistica 'regla-peligrosa' $r.accion
            continue
        }
        Log ("REGLA $($r.id) dispara: " + (Describe-Regla $r))
        $script:reglasDisparadas++
        $script:confirmado = $true
        $res = $null
        try { $res = Invoke-FastCommand $r.accion } catch { $res = $null } finally { $script:confirmado = $false }
        # 'amigoConecta' entra aqui (23/09, idea 10): la vigilancia se borra sola en cuanto
        # avisa una vez. Es la primera de sus tres salidas y no cuesta una linea de codigo
        # nueva, solo estar en esta lista.
        $unaVez = ($r.ultima -eq 'unavez' -and $tipo -in @('appAbre', 'juegoAbre', 'dockPone', 'cascosPone', 'amigoConecta'))
        # POR LA PUERTA DE LOS AVISOS, NO POR Say (24/09). Esto llamaba a Say directamente, y
        # Say no pasa por NINGUNA de las cuatro guardas que Nova tiene para no hablar cuando
        # no debe: ni la llamada, ni la sordina -que braya puede pedir para media hora-, ni el
        # juego delante (avisos.sinVozEnJuego esta a true en config.json), ni el modo silencio.
        # O sea que una regla que venciera dentro de la sordina que el mismo pidio se la
        # saltaba, y jugando le hablaba encima de la partida.
        #
        # Send-Aviso es la misma puerta que usa el aviso de descarga terminada, cinco lineas
        # mas arriba en este bucle: jugando deja capsula y pulso y se calla; sin juego lo dice
        # igual que antes. Y ademas APLAZA si braya esta dictando, que es otra cosa que Say no
        # hacia: "hablar encima de un dictado pone la pausa y el worker tira tu audio"
        # (auditoria del 13/09). Una regla que venciera en mitad de una orden se la comia.
        #
        # EN QUINCE DIAS NO HA DISPARADO NI UNA REGLA, asi que el dano hasta hoy es cero; pero
        # el ciclo entero se probo hoy de punta a punta, y en cuanto haya una regla viva pasa.
        if ($res) {
            Send-UIEvento 'hecho'
            Send-Aviso ($(if ($unaVez) { 'Recuerda' } else { "Regla $($r.id)" }) + ": $res") 'regla'
        } else { Log "REGLA $($r.id): la accion no se pudo ejecutar" }
        # un recordatorio de un solo uso se borra al cumplirse (ver Invoke-ReglaVoz)
        if ($unaVez) { [void]$g.Remove($r); Save-Reglas; Log "REGLA $($r.id): era de un solo uso, borrada" }
    }
    if ($tipo -in @('bateria', 'hora', 'cada', 'disco') -or $script:reglasCaducadas -gt 0) { Save-Reglas }
}

# =====================================================================
# FECHAS: "recuerda que el 3 de octubre es el cumple de Ana" -> ademas del
# diario, se guarda en memoria\fechas.json y ese dia lo celebra al arrancar.
# =====================================================================
$FechasPath = Join-Path $MemoriaDir 'fechas.json'
$MESES = @{ 'enero' = 1; 'febrero' = 2; 'marzo' = 3; 'abril' = 4; 'mayo' = 5; 'junio' = 6; 'julio' = 7; 'agosto' = 8; 'septiembre' = 9; 'setiembre' = 9; 'octubre' = 10; 'noviembre' = 11; 'diciembre' = 12 }

function Get-Fechas {
    $lista = @()
    if (Test-Path -LiteralPath $FechasPath) {
        # mismo fantasma que en los recordatorios: ver Get-Recordatorios
        try {
            $crudo = Get-Content -LiteralPath $FechasPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($x in $crudo) { if ($null -ne $x -and [string]$x.texto) { $lista += $x } }
        } catch { $lista = @(); Save-Corrupto $FechasPath 'fechas' }
    }
    return $lista
}

function Add-Fecha([string]$frase) {
    if ($script:invitado) { return $null }   # MODO INVITADO: lo que diga otro no se queda (17/09)
    $p = ConvertTo-Plain $frase
    if ($p -notmatch '\b(?:el\s+)?(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\b') { return $null }
    $d = [int]$Matches[1]; $m = $MESES[$Matches[2]]
    if ($d -lt 1 -or $d -gt 31) { return $null }
    $md = '{0:00}-{1:00}' -f $m, $d
    $lista = @(Get-Fechas | Where-Object { -not ($_.md -eq $md -and $_.texto -eq $frase) })
    $lista += New-Object PSObject -Property @{ md = $md; texto = $frase }
    try {
        Write-Atomico $FechasPath (ConvertTo-Json -InputObject @($lista) -Depth 3)
        Log "FECHA guardada ($md): $frase"
    } catch {}
    return $md
}

function Test-FechasHoy {
    $hoy = Get-Date -Format 'MM-dd'
    $de = @(Get-Fechas | Where-Object { $_.md -eq $hoy })
    if ($de.Count -eq 0) { return }
    foreach ($f in $de) {
        Log "FECHA de hoy: $($f.texto)"
        Say ("Hoy es un dia especial: " + $f.texto)
        Send-UIEvento 'logro'
    }
}

# =====================================================================
# RECORDATORIOS CON FECHA Y HORA: "recuerdame manana a las 10 que llame al
# medico", "avisame el viernes a las cinco de la tarde que...", "recuerdame
# a las 3 revisar el horno" (hoy si aun no ha pasado; si no, manana). Se
# guardan en memoria\recordatorios.json y sobreviven a los reinicios.
# =====================================================================
$RecordatoriosPath = Join-Path $MemoriaDir 'recordatorios.json'
$DIAS_SEMANA = @{ 'lunes' = 1; 'martes' = 2; 'miercoles' = 3; 'jueves' = 4; 'viernes' = 5; 'sabado' = 6; 'domingo' = 0 }

function Get-Recordatorios {
    $lista = @()
    if (Test-Path -LiteralPath $RecordatoriosPath) {
        # OJO con @(...) alrededor de ConvertFrom-Json: con un "[]" en el
        # archivo, PowerShell 5.1 no devuelve una lista vacia sino una lista de
        # UN elemento que contiene la lista vacia. Ese fantasma se guardaba
        # luego como {"value":[],"Count":0} dentro del json y contaba como un
        # recordatorio de verdad. El foreach sobre el resultado crudo si da 0.
        try {
            $crudo = Get-Content -LiteralPath $RecordatoriosPath -Raw -Encoding UTF8 | ConvertFrom-Json
            foreach ($x in $crudo) { if ($null -ne $x -and [string]$x.texto) { $lista += $x } }
        } catch { $lista = @(); Save-Corrupto $RecordatoriosPath 'recordatorios' }
    }
    return $lista
}

function Save-Recordatorios($lista) {
    $json = if (@($lista).Count -eq 0) { '[]' } else { ConvertTo-Json -InputObject @($lista) -Depth 3 }
    Write-Atomico $RecordatoriosPath $json
}

function Invoke-RecordatorioVoz([string]$text) {
    $p = ConvertTo-Plain $text
    # LA MULETILLA DE DELANTE COSTO 49 SEGUNDOS (21/09). 'Mira, recuerdame manana
    # instalarme el juego el que esta guardado en mi lista' (20/09 23:08:04): sin el
    # 'Mira,' se resuelve aqui al momento; con el, el log dice 'LOCAL descarta: no
    # reconozco mira recuerdame manana...' (23:08:14) y la frase se fue a traducir
    # (haiku, 4277 c.), a plan (haiku, 4734 c.) y AL AGENTE ENTERO (sonnet, 28,4 s,
    # 3 pasos, 19534 B) para contestar a las 23:08:53, con Roblox delante.
    # Remove-Filler ya quita estas palabras, pero se llama DESPUES: los recordatorios
    # y las reglas se resuelven sobre la frase entera, antes de partirla en
    # fragmentos. Por eso hay que quitarlas tambien aqui.
    # EL LOOKAHEAD ES LA GUARDA: solo se borra si detras viene de verdad un verbo de
    # recordatorio. 'mira que tengo apuntado' o 'bueno, pues nada' no se tocan.
    $p = [regex]::Replace($p, '^(?:(?:oye|mira|escucha|hey|ey|hola|nova|ok|okey|okay|vale|bueno|pues|luego|despues|ahora|entonces)\s+)+(?=(?:recuerdame|avisame|recordatorio|ponme|pon)\b)', '')
    # "REVISA MI CALENDARIO PARA MAÑANA" (18/09). braya lo pidio tres veces y acabo en el agente
    # (23 s) o en la charla. Nova no tiene calendario -el correo va por IMAP y por ahi no se
    # llega a Google Calendar-, pero tiene SUS recordatorios, que es justo lo que el agente
    # acabo contestando. Aqui se contesta en local, filtrando por dia si lo dice. Lo que
    # empieza por recuerdame/avisame/pon es CREAR uno y sigue su camino.
    if ($p -notmatch '^(?:recuerdame|avisame|recordatorio|ponme|pon)\b' -and
        # SU FRASE NO ENTRABA (23/09). El dijo "dime si tengo algo anotado para manana" y el
        # patron del tema exige que la frase EMPIECE por "tengo algo anotado": la suya empieza
        # por "dime si". La otra mitad de la condicion -la del verbo de cabeza- si la aceptaba,
        # asi que faltaba media puerta. La alternativa sin ancla pide las DOS palabras juntas
        # ('tengo algo anotado'), que no aparecen por casualidad en otra orden.
        ($p -match '\b(?:calendario|agenda)\b' -or $p -match '\btengo\s+algo\s+(?:apuntado|anotado|programado|pendiente)\b' -or $p -match '^que\s+tengo\s+(?:apuntado|anotado|programado)\b') -and
        $p -match '^(?:(?:puedes?\s+|podrias\s+)?(?:revisa|revisar|mira|mirar|consulta|consultar|dime|decirme|ver|que)\b.*|(?:que\s+)?tengo\s+algo\b.*)$') {
        # EL RANGO, Y EL ORDEN IMPORTA (23/09, idea 5): 'pasado manana' antes que 'manana', y
        # 'fin de semana' antes que 'semana', porque "este fin de semana" lleva 'semana'
        # dentro y se lo comeria.
        $hoyC = (Get-Date).Date
        $desdeC = $hoyC; $hastaC = $hoyC.AddDays(30); $cuandoC = ''
        if ($p -match '\bpasado\s+manana\b') { $desdeC = $hoyC.AddDays(2); $hastaC = $desdeC; $cuandoC = ' para pasado manana' }
        elseif ($p -match '\bmanana\b') { $desdeC = $hoyC.AddDays(1); $hastaC = $desdeC; $cuandoC = ' para manana' }
        elseif ($p -match '\bhoy\b') { $hastaC = $hoyC; $cuandoC = ' para hoy' }
        # 'el fin de LA semana' tambien se dice, y ESA si choca con la rama de abajo: lleva
        # 'la semana' dentro. Por eso esta va primero. (Con solo 'fin de semana' el orden no
        # cambiaba nada: se probo cambiandolas de sitio y el banco seguia en verde.)
        elseif ($p -match '\b(?:este\s+|el\s+)?fin\s+de\s+(?:la\s+)?semana\b') {
            $aSab = (6 - [int]$hoyC.DayOfWeek + 7) % 7
            $desdeC = $hoyC.AddDays($aSab); $hastaC = $desdeC.AddDays(1); $cuandoC = ' para el fin de semana'
        }
        elseif ($p -match '\b(?:esta|la)\s+semana\b') { $hastaC = $hoyC.AddDays(6); $cuandoC = ' de hoy a siete dias' }
        elseif ($p -match '\bel\s+(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b') {
            # el mismo calculo que al crear un recordatorio: "el viernes" dicho un viernes es
            # el que viene, no hoy
            $dC = $DIAS_SEMANA[$Matches[1]]
            $deltaC = ($dC - [int]$hoyC.DayOfWeek + 7) % 7
            if ($deltaC -eq 0) { $deltaC = 7 }
            $desdeC = $hoyC.AddDays($deltaC); $hastaC = $desdeC; $cuandoC = " para el $($Matches[1])"
        }
        # SUS CITAS NO VAN AL REGISTRO (24/09, repaso): esta funcion devuelve la frase ya
        # montada, y la linea de "LOCAL: ... -> ..." la escribia entera.
        $script:respuestaPrivada = $true
        $rsC = @(Get-AgendaDe $desdeC $hastaC)
        if ($rsC.Count -eq 0) { return "No tienes nada apuntado$cuandoC. Si quieres, di: recuerdame manana a las diez que llame al medico." }
        $culC = New-Object System.Globalization.CultureInfo('es-MX')
        $listaC = @($rsC | ForEach-Object {
            if ($_.origen -eq 'fecha') { ([datetime]$_.cuando).ToString('dddd d', $culC) + ', ' + $_.texto }
            else { ([datetime]$_.cuando).ToString('dddd d "a las" H:mm', $culC) + ', ' + $_.texto }
        })
        return ("Tienes " + $(if ($rsC.Count -eq 1) { 'una cosa' } else { "$($rsC.Count) cosas" }) + "$cuandoC`: " + ($listaC -join '. ') + '.')
    }
    if ($p -match '^(?:que recordatorios (?:tengo|hay)|mis recordatorios|que tengo pendiente|que me tienes que recordar)$') {
        $rs = @(Get-Recordatorios | Sort-Object cuando)
        if ($rs.Count -eq 0) { return "No tienes recordatorios. Di, por ejemplo: recuerdame manana a las diez que llame al medico." }
        $cul = New-Object System.Globalization.CultureInfo('es-MX')
        return ("Tienes " + $rs.Count + ": " + (($rs | ForEach-Object { ([DateTime]$_.cuando).ToString('dddd d "a las" H:mm', $cul) + ", " + $_.texto }) -join '. '))
    }
    if ($p -match '^(?:borra|elimina|quita|olvida)\s+(?:todos\s+)?(?:los\s+)?recordatorios$') { Save-Recordatorios @(); return "Listo, sin recordatorios." }
    # BORRAR UNA CITA HABLANDO (23/09, idea 5). Va DETRAS del 'todos', que es mas especifico y
    # sigue ganando, y EXIGE el sustantivo delante ('recordatorio', 'aviso' o 'cita'): sin eso
    # se comeria "borra la carpeta descargas", que es otra cosa y ademas destructiva de verdad.
    # EL AVISO DEL TIEMPO DE JUEGO NO ES UNA CITA. Es la tercera vez hoy con la misma
    # familia de frases: "quita el aviso de cada hora" es de Resolve-Fragment, y esta
    # funcion se mira ANTES, asi que sin la salvedad aquel patron se queda en codigo
    # muerto. La lista de palabras es la MISMA que alli y que en los recordatorios
    # repetidos: tres sitios, una lista.
    if ($p -match '^(?!(?:borra|elimina|quita|olvida|cancela)\s+(?:el\s+|la\s+|mi\s+)?(?:aviso|avisos)\s+(?:de\s+|del\s+)?(?:cada\s+)?(?:hora|rato|tiempo|tiempo de juego|juego)$)(?:borra|elimina|quita|olvida|cancela)\s+(?:el\s+|la\s+|mi\s+)?(?:recordatorio|aviso|cita)\s*(?:de\s+|del\s+|sobre\s+|que\s+)?(.+)$') {
        $qR = [string]$Matches[1]
        # LA SEGUNDA VIA, POR NUMERO (regla 7, oido al 70,4 %): Nova acaba de leer la lista
        # numerada, asi que "borra el recordatorio dos" es una lista cerrada de una palabra.
        $nR = switch -Regex ($qR.Trim()) { '^(?:uno|1)$' { 1 } '^(?:dos|2)$' { 2 } '^(?:tres|3)$' { 3 } '^(?:cuatro|4)$' { 4 } '^(?:cinco|5)$' { 5 } default { 0 } }
        if ($nR -gt 0) {
            $todosR = @(Get-Recordatorios | Sort-Object cuando)
            if ($nR -gt $todosR.Count) { return "Solo tienes $($todosR.Count)." }
            $elR = $todosR[$nR - 1]
            # SE FILTRA LA LISTA QUE YA SE LEYO, no otra lectura: leer dos veces crea objetos
            # nuevos y "-ne" compara por referencia, asi que no se iba ninguno y Nova decia
            # "Listo, quitado" sin quitar nada.
            $quedanR = @()
            for ($iR = 0; $iR -lt $todosR.Count; $iR++) { if ($iR -ne ($nR - 1)) { $quedanR += $todosR[$iR] } }
            Save-Recordatorios $quedanR
            Log ("RECORDATORIO borrado por numero: " + ([string]$elR.texto).Length + " caracteres")
            return "Listo, quitado: $($elR.texto)."
        }
        $rq = Remove-RecordatorioTexto $qR
        if ($rq.estado -eq 'ninguno') { return "No tengo nada apuntado de eso." }
        if ($rq.estado -eq 'varios') {
            $nn = 0
            $lR = @($rq.lista | ForEach-Object { $nn++; "$nn, $($_.texto)" })
            return ("Tengo " + $rq.lista.Count + " que hablan de eso: " + ($lR -join '. ') + ". Cual borro? Di: borra el recordatorio uno.")
        }
        return "Listo, quitado: $($rq.borrado.texto)."
    }
    if ($p -notmatch '^(?:recuerdame|avisame|recordatorio|ponme un recordatorio|pon un recordatorio)\s+(?!que\b)(.+)$') { return $null }
    $resto = $Matches[1]
    $hoy = (Get-Date).Date
    $fecha = $null; $hora = -1; $min = 0
    # dia
    if ($resto -match '^(?:para\s+)?hoy\b\s*(.*)$') { $fecha = $hoy; $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?pasado manana\b\s*(.*)$') { $fecha = $hoy.AddDays(2); $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?manana\b\s*(.*)$') { $fecha = $hoy.AddDays(1); $resto = $Matches[1] }
    elseif ($resto -match '^(?:para\s+)?el\s+(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b\s*(.*)$') {
        $d = $DIAS_SEMANA[$Matches[1]]; $resto = $Matches[2]
        $delta = ($d - [int]$hoy.DayOfWeek + 7) % 7
        if ($delta -eq 0) { $delta = 7 }   # "el viernes" dicho un viernes = el que viene
        $fecha = $hoy.AddDays($delta)
    }
    elseif ($resto -match '^(?:para\s+)?el\s+(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\b\s*(.*)$') {
        $dd = [int]$Matches[1]; $mm = $MESES[$Matches[2]]; $resto = $Matches[3]
        try { $fecha = Get-Date -Year $hoy.Year -Month $mm -Day $dd -Hour 0 -Minute 0 -Second 0 } catch { return "Esa fecha no existe." }
        if ($fecha.Date -lt $hoy) { $fecha = $fecha.AddYears(1) }
    }
    # AVISO ANTES DE UNA HORA (idea 6): "avisame diez minutos antes de las
    # diez", "recuerdame media hora antes de las ocho que empieza la partida".
    # Habia "a las diez" y habia "en veinte minutos", pero no lo que de verdad
    # se pide antes de una partida. Va DESPUES del dia ("manana diez minutos
    # antes de las diez") y ANTES de la hora, que se lee igual que siempre.
    $antesMin = 0
    if ($resto -match '^(.+?)\s+(minutos?|horas?)(\s+y\s+media)?\s+antes(?:\s+(?:de\s+)?(.+))?$') {
        $cantA = $Matches[1].Trim(); $unidadA = $Matches[2]; $yMediaA = [bool]$Matches[3]; $trasA = $Matches[4]
        if ($cantA -match '^(?:un\s+)?cuarto\s+de$') { $antesMin = 15 }
        elseif ($cantA -match '^medi[ao]$') { if ($unidadA -like 'hora*') { $antesMin = 30 } }
        elseif ($cantA -match '^(?:un|una)$') { $antesMin = if ($unidadA -like 'hora*') { 60 } else { 1 } }
        else {
            $cantA = (ConvertTo-Digitos $cantA).Trim()
            if ($cantA -match '^\d{1,3}$') { $antesMin = if ($unidadA -like 'hora*') { [int]$cantA * 60 } else { [int]$cantA } }
        }
        # "una hora y media antes", "dos horas y media antes"
        if ($antesMin -gt 0 -and $yMediaA -and $unidadA -like 'hora*') { $antesMin += 30 }
        if ($antesMin -gt 0) {
            $resto = $trasA
            # "antes de las diez": el patron de la hora espera "a las"
            if ($resto -match '^las?\s') { $resto = 'a ' + $resto }
        }
    }
    # hora
    # "11:30" llega como "11 30": ConvertTo-Plain cambia los dos puntos por un
    # espacio, y con solo ':' el patron se quedaba con las 11 y guardaba "30 de
    # la noche que apague el horno" como texto del recordatorio (12/09).
    if ($resto -match '^(?:a\s+las?\s+)(\d{1,2}|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce)(?:(?::|\s+)(\d{2})\b|\s+y\s+media|\s+y\s+cuarto|\s+menos\s+cuarto)?\s*(de la manana|de la tarde|de la noche|de la madrugada|am|pm)?\s*(.*)$') {
        # mismos cuidados que en las reglas: copiar ANTES de volver a usar
        # -match. Aqui el fallo era mudo: $resto quedaba vacio y contestaba
        # '¿Que te recuerdo?', asi que creias haber puesto el recordatorio y no
        # existia. Pasaba con 'y media', 'y cuarto' y 'menos cuarto'.
        $g0 = $Matches[0]; $g1 = $Matches[1]; $g2 = $Matches[2]; $g3 = $Matches[3]; $g4 = $Matches[4]
        $h = $g1; if ($HORAS_PALABRA.ContainsKey($h)) { $h = $HORAS_PALABRA[$h] }; $hora = [int]$h
        if ($g2) { $min = [int]$g2 } elseif ($g0 -match 'y media') { $min = 30 } elseif ($g0 -match 'y cuarto') { $min = 15 } elseif ($g0 -match 'menos cuarto') { $min = 45; $hora-- }
        $franja = $g3; $resto = $g4
        if ($franja -match 'tarde|noche|pm' -and $hora -lt 12) { $hora += 12 }
        # LAS DOCE ES EL UNICO NUMERO QUE NO SIGUE LA REGLA (21/09). La linea de arriba
        # suma 12 solo si la hora es MENOR que 12, asi que el 12 no lo tocaba; y esta
        # miraba 'manana|am', que es justo al reves de como se dice en espanol:
        #   las doce de la NOCHE son las 00:00   (se guardaba 12:00, el mediodia)
        #   las doce de la MANANA son las 12:00  (se guardaba 00:00, la medianoche)
        # Error de doce horas exactas, y no solo en un aviso: 'a las doce de la noche pon
        # modo noche' le bajaba el brillo al MEDIODIA, jugando.
        # 'manana' y 'madrugada' no contienen 'am' (comprobado), asi que la alternancia
        # no se pisa a si misma.
        if ($franja -match 'noche|madrugada|am' -and $hora -eq 12) { $hora = 0 }
        # sin franja y hora "pequena": si ya paso, sera de tarde.
        # PERO DE MADRUGADA NO (21/09). Esto sumaba 12 SIEMPRE que la hora fuera de 1 a 7
        # y no se dijera la franja, y a las tres de la madrugada eso es justo al reves de
        # lo que quiere decir: 'recuerdame a las siete que desayune', dicho a las 3:00, se
        # guardaba para las 19:00 -cuando lo que queda son cuatro horas para las 7 de la
        # manana-. Y braya juega de madrugada, que es cuando mas lo dice.
        # La razon de sumar 12 es 'esa hora ya paso hoy', asi que se mira eso y no un
        # numero fijo: si la hora pedida AUN NO HA LLEGADO, se toma tal cual.
        $horaAhora = (Get-Date).Hour
        if (-not $franja -and $hora -le 7 -and $hora -ge 1 -and $null -eq $fecha -and
            $horaAhora -ge $hora) { $hora += 12 }
    }
    # no es un recordatorio con fecha... salvo que haya antelacion sin hora, que
    # se pregunta justo debajo
    if ($null -eq $fecha -and $hora -lt 0 -and $antesMin -le 0) { return $null }
    # "avisame veinte minutos antes" sin decir de que: mejor preguntar que
    # dejar que la frase se vaya al agente
    if ($antesMin -gt 0 -and $hora -lt 0) { return "¿Antes de que hora? Di, por ejemplo: avisame diez minutos antes de las nueve." }
    $texto = ($resto -replace '^(?:que|de que|de|para|a)\s+', '').Trim()
    # con antelacion no hace falta decir que: el aviso ya dice cuanto falta
    if (-not $texto -and $antesMin -le 0) { return "¿Que te recuerdo?" }
    if ($hora -lt 0) { $hora = 9 }   # solo dia: a las 9 de la manana
    if ($null -eq $fecha) {
        $fecha = $hoy
        if ($hoy.AddHours($hora).AddMinutes($min) -le (Get-Date)) { $fecha = $hoy.AddDays(1) }
    }
    $cuando = $fecha.Date.AddHours($hora).AddMinutes($min)
    if ($cuando -le (Get-Date)) { return "Esa hora ya paso." }
    $antesDicho = ''
    if ($antesMin -gt 0) {
        $evento = $cuando
        $cuando = $evento.AddMinutes(-$antesMin)
        $cul0 = New-Object System.Globalization.CultureInfo('es-MX')
        $margen = if ($antesMin % 60 -eq 0) { $hh = $antesMin / 60; if ($hh -eq 1) { 'una hora' } else { "$hh horas" } } elseif ($antesMin -eq 30) { 'media hora' } elseif ($antesMin -eq 90) { 'una hora y media' } elseif ($antesMin % 60 -eq 30) { "$([int][Math]::Floor($antesMin / 60)) horas y media" } elseif ($antesMin -eq 1) { 'un minuto' } else { "$antesMin minutos" }
        # "falta una hora", "faltan diez minutos": se lee en voz alta
        $falta = if ($margen -match '^(?:una hora|media hora|una hora y media|un minuto)$') { 'falta' } else { 'faltan' }
        if ($cuando -le (Get-Date)) { return "Ya $falta menos de $margen para las " + $evento.ToString('H:mm', $cul0) + "." }
        $texto = if ($texto) { "$texto. Es a las " + $evento.ToString('H:mm', $cul0) } else { "$falta $margen para las " + $evento.ToString('H:mm', $cul0) }
        $antesDicho = ", $margen antes"
    }
    $lista = @(Get-Recordatorios) + @(New-Object PSObject -Property @{ cuando = $cuando.ToString('s'); texto = $texto })
    Save-Recordatorios $lista
    $cul = New-Object System.Globalization.CultureInfo('es-MX')
    $dicho = if ($cuando.Date -eq $hoy) { "hoy a las " + $cuando.ToString('H:mm', $cul) } elseif ($cuando.Date -eq $hoy.AddDays(1)) { "manana a las " + $cuando.ToString('H:mm', $cul) } else { $cuando.ToString('dddd d "de" MMMM "a las" H:mm', $cul) }
    Log "RECORDATORIO ($cuando): $texto"
    Add-Estadistica 'local' "recordatorio: $text"
    return "Listo, te lo recuerdo $dicho$antesDicho."
}

# LA AGENDA MIRA LOS TRES SITIOS (23/09, idea 5). Nova apunta cosas con fecha en TRES sitios
# y el alias del calendario solo leia uno:
#   - recordatorios.json, con fecha y hora exactas;
#   - fechas.json, lo anual ("el 15 de septiembre es el cumple de Ana"), que hoy tiene una
#     entrada de verdad en el disco y que Test-FechasHoy solo mira EL MISMO DIA;
#   - las reglas de tipo 'hora', que es donde vive "todos los dias a las ocho di que me tome
#     la pastilla".
# NO se crea un cuarto fichero: eso es exactamente la leccion que ya esta escrita en el
# codigo ("dos listas distintas acabarian separandose"). Cero migracion, cero formato nuevo.
# De las reglas solo entran las que HABLAN ('di ...'): un modo nocturno no es una cita.
function Get-AgendaDe([datetime]$desde, [datetime]$hasta) {
    $out = @()
    foreach ($r in @(Get-Recordatorios)) {
        $c = $null
        try { $c = [datetime]$r.cuando } catch { $c = $null }
        if ($c -and $c.Date -ge $desde.Date -and $c.Date -le $hasta.Date) {
            $out += @{ cuando = $c; texto = [string]$r.texto; origen = 'recordatorio' }
        }
    }
    $fechas = @(Get-Fechas)
    # SE ASIGNA PRIMERO Y LUEGO foreach, que es como lo hace Invoke-Reglas, y no por tuberia.
    # Get-Reglas devuelve ",$script:reglas" para que una lista vacia no se vuelva $null, y eso
    # hace que @(Get-Reglas) sea un array de UN elemento que ES la lista. Con Where-Object
    # pasaba lo peor: $_.tipo sobre una coleccion devuelve la lista de tipos, comparada con
    # 'hora' da algo no vacio -o sea verdadero- y la lista ENTERA se colaba como si fuera una
    # regla; despues [string]$g.valor salia "08:00 23:00" y se descartaba sola, en silencio.
    # Con una sola regla el fallo no se ve: hacen falta dos para que aparezca.
    $reglas = @()
    try {
        $todasR = Get-Reglas
        foreach ($rr in @($todasR)) {
            if ([string]$rr.tipo -eq 'hora' -and (ConvertTo-Plain ([string]$rr.accion)) -match '^di\s') { $reglas += $rr }
        }
    } catch { $reglas = @() }
    if ($fechas.Count -gt 0 -or $reglas.Count -gt 0) {
        for ($d = $desde.Date; $d -le $hasta.Date; $d = $d.AddDays(1)) {
            $md = $d.ToString('MM-dd')
            foreach ($f in $fechas) {
                # UN CUMPLEANOS NO TIENE HORA: se le pone una para poder ordenar, y al leerlo
                # se dice sin ella.
                if ([string]$f.md -eq $md) { $out += @{ cuando = $d.AddHours(9); texto = [string]$f.texto; origen = 'fecha' } }
            }
            foreach ($g in $reglas) {
                $hh = 0; $mm = 0
                if ([string]$g.valor -match '^(\d{1,2}):(\d{2})$') { $hh = [int]$Matches[1]; $mm = [int]$Matches[2] } else { continue }
                $out += @{ cuando = $d.AddHours($hh).AddMinutes($mm)
                           texto = (([string]$g.accion) -replace '(?i)^\s*di\s+', '')
                           origen = 'regla' }
            }
        }
    }
    return @($out | Sort-Object { $_.cuando })
}

# BORRAR UNA CITA HABLANDO (23/09, idea 5). Antes solo existia "borra todos los
# recordatorios", que es todo o nada.
# CON MAS DE UNA COINCIDENCIA NO BORRA NINGUNA: borrar la que no era es la regla 1 al reves,
# y encima sobre algo que no se puede recuperar. Se leen numeradas y decide el.
function Remove-RecordatorioTexto([string]$q) {
    # borrar un recordatorio de braya no tiene vuelta atras.
    if ($script:invitado) { return $null }   # MODO INVITADO: lo que borre otro tampoco se queda (24/09)
    $todos = @(Get-Recordatorios)
    $qs = ConvertTo-Plain ([string]$q).Trim()
    # SUELO DE TRES LETRAS (regla 7, oido al 70,4 %). Con menos, un trozo mal oido borra lo
    # que pille: "borra el recordatorio de la" se llevaba "sacar la basura" porque 'la' esta
    # dentro, y un recordatorio borrado no se recupera. Tres letras es lo mismo que ya pide
    # Remove-DatoPerfil para no emparejar por una palabra vacia.
    if ($qs.Length -lt 3) { return @{ estado = 'ninguno' } }
    $hit = @($todos | Where-Object { (ConvertTo-Plain ([string]$_.texto)).Contains($qs) })
    if ($hit.Count -eq 0) { return @{ estado = 'ninguno' } }
    if ($hit.Count -gt 1) { return @{ estado = 'varios'; lista = $hit } }
    Save-Recordatorios @($todos | Where-Object { $_ -ne $hit[0] })
    Log ("RECORDATORIO borrado a mano: " + ([string]$hit[0].texto).Length + " caracteres")
    return @{ estado = 'uno'; borrado = $hit[0] }
}

# Los que ya se apuntaron como ilegibles en ESTE arranque, para no repetir la linea en cada
# vuelta del bucle. En memoria y no en disco a proposito: si al reiniciar sigue rota, merece
# una linea nueva -es informacion de que el problema no se ha arreglado solo-.
$script:recordatorioIlegible = New-Object System.Collections.ArrayList
function Test-Recordatorios {
    $lista = @(Get-Recordatorios)
    if ($lista.Count -eq 0) { return }
    $ahora = Get-Date
    $quedan = @()
    foreach ($r in $lista) {
        $c = $null
        try { $c = [DateTime]$r.cuando } catch {
            # UNA FECHA ILEGIBLE NO BORRA EL RECORDATORIO (24/09). Aqui habia un 'continue'
            # que saltaba el 'else { $quedan += $r }' de abajo, y el Save de dos lineas mas
            # alla guardaba la lista SIN esta entrada: la fecha rota no aplazaba nada, borraba
            # el recordatorio del disco y sin escribir una linea.
            # Se apunta UNA vez por arranque y no en cada vuelta: el bucle pasa por aqui
            # constantemente, y repetirlo seria el fallo de los 25 avisos identicos del 22/09.
            # Y no se adivina la fecha: se conserva para que braya pueda preguntar por el.
            if (-not $script:recordatorioIlegible.Contains([string]$r.texto)) {
                [void]$script:recordatorioIlegible.Add([string]$r.texto)
                Log "RECORDATORIO con fecha ilegible ('$($r.cuando)'): lo dejo donde esta, no lo borro"
                Add-Estadistica 'recordatorio-ilegible' ([string]$r.texto)
            }
            $quedan += $r
            continue
        }
        if ($c -le $ahora) {
            # el despertador no es un aviso: suena (ver DESPERTADOR)
            if ($r.texto -eq 'despertador') { try { Invoke-Despertador } catch { Log ("despertador: " + $_.Exception.Message) }; continue }
            Log "RECORDATORIO vence: $($r.texto)"
            Send-Aviso ("Te recuerdo: " + $r.texto) 'recordatorio'
            Start-Vibracion @(120, 80, 120)
        } else { $quedan += $r }
    }
    if ($quedan.Count -ne $lista.Count) { Save-Recordatorios $quedan }
}

# =====================================================================
# MICRO-CHARLA: un comentario espontaneo al dia, y solo si viene a cuento.
# =====================================================================
$CharlaOn = [bool](Get-Cfg 'charla' 'activada' $true)
$script:charlaAgua = ''
$script:charlaTarde = ''

# =====================================================================
# LOGROS DE STEAM: Steam reescribe appcache\stats\UserGameStats_<usuario>_<app>.bin
# cuando cambian los logros del juego que esta corriendo. Se vigila la fecha
# del archivo del juego activo: si cambia, medalla. (Tambien cambia con otras
# estadisticas: puede haber algun falso positivo; una medalla de mas no duele.)
# =====================================================================
$script:logroArchivo = ''
$script:logroStamp = [DateTime]::MinValue
$script:logroUltimo = 0

function Watch-LogrosSteam {
    if (-not $script:juegoActivo) { $script:logroArchivo = ''; return }
    try {
        if (-not $script:logroArchivo) {
            $j = @($script:Juegos | Where-Object { $_.nombre -eq $script:juegoActivo }) | Select-Object -First 1
            if (-not $j) { return }
            $sp = (Get-ItemProperty 'HKCU:\Software\Valve\Steam' -ErrorAction SilentlyContinue).SteamPath -replace '/', '\'
            $f = Get-ChildItem -LiteralPath (Join-Path $sp 'appcache\stats') -Filter "UserGameStats_*_$($j.id).bin" -ErrorAction SilentlyContinue | Select-Object -First 1
            if (-not $f) { $script:logroArchivo = '-'; return }
            $script:logroArchivo = $f.FullName
            $script:logroStamp = $f.LastWriteTimeUtc
            return
        }
        if ($script:logroArchivo -eq '-') { return }
        $st = [System.IO.File]::GetLastWriteTimeUtc($script:logroArchivo)
        if ($st -ne $script:logroStamp) {
            $script:logroStamp = $st
            if (($sw.ElapsedMilliseconds - $script:logroUltimo) -ge 120000) {
                $script:logroUltimo = $sw.ElapsedMilliseconds
                Log "LOGRO (stats de Steam cambiaron) en $($script:juegoActivo)"
                Send-UIEvento 'logro'
            }
        }
    } catch {}
}

# =====================================================================
# ACELEROMETRO (WinRT): un golpe o sacudida de la consola sobresalta a la
# capsula. Si el sensor no existe, no se hace nada.
# =====================================================================
$script:acelerometro = $null
$script:acelCheck = 0
$script:acelUltimo = 0
# Apagado por defecto: en la ROG Ally GetDefault() devuelve un sensor pero
# GetCurrentReading() tarda 5 s y devuelve null SIEMPRE (probado con
# ReportInterval fijado). Con sensores.acelerometro = true se intenta, con la
# guarda de Watch-Acelerometro por si cambia el hardware.
if ([bool](Get-Cfg 'sensores' 'acelerometro' $false)) {
    try {
        $null = [Windows.Devices.Sensors.Accelerometer, Windows.Devices.Sensors, ContentType = WindowsRuntime]
        $script:acelerometro = [Windows.Devices.Sensors.Accelerometer]::GetDefault()
        if ($script:acelerometro) { Log "acelerometro: disponible (se probara la primera lectura)" } else { Log "acelerometro: no hay sensor" }
    } catch { $script:acelerometro = $null; Log "acelerometro: no disponible" }
}

$script:acelProbado = $false
function Watch-Acelerometro {
    if (-not $script:acelerometro) { return }
    try {
        # GUARDA: en la Ally el sensor "existe" pero GetCurrentReading tarda
        # 5 s y devuelve null. Llamado cada 250 ms bloqueaba el asistente
        # entero (se descubrio porque las ordenes tardaban 30 s en leerse).
        # Si la primera lectura es lenta o vacia, se apaga para siempre.
        if (-not $script:acelProbado) {
            $script:acelProbado = $true
            try { $script:acelerometro.ReportInterval = [Math]::Max(100, $script:acelerometro.MinimumReportInterval) } catch {}
            $t = [System.Diagnostics.Stopwatch]::StartNew()
            $r0 = $script:acelerometro.GetCurrentReading()
            if ($t.ElapsedMilliseconds -gt 150 -or -not $r0) {
                Log ("acelerometro: sin lecturas utiles (" + $t.ElapsedMilliseconds + " ms, nulo=" + ($null -eq $r0) + "); desactivado")
                $script:acelerometro = $null
                return
            }
            Log "acelerometro: lecturas OK"
        }
        $r = $script:acelerometro.GetCurrentReading()
        if (-not $r) { return }
        $mag = [Math]::Sqrt($r.AccelerationX * $r.AccelerationX + $r.AccelerationY * $r.AccelerationY + $r.AccelerationZ * $r.AccelerationZ)
        if ([Math]::Abs($mag - 1.0) -gt 0.7 -and ($sw.ElapsedMilliseconds - $script:acelUltimo) -ge 5000) {
            $script:acelUltimo = $sw.ElapsedMilliseconds
            Log ("SACUDIDA: {0:0.00} g" -f $mag)
            Send-UIEvento 'gesto:sobresalto'
        }
    } catch { $script:acelerometro = $null }
}

# =====================================================================
# NOTA SEMANAL: memoria\semanas\AAAA-Www.md, escrita en lenguaje hablado a
# partir de las estadisticas y del diario de gestos. Una por semana vencida.
# =====================================================================
# LO QUE DECIDI YO SOLA, en el parte semanal (17/09). La nota ya contaba cuantas cosas
# pediste, cuantas se resolvieron al instante y que no entendi... pero hablaba solo de ti.
# Desde esta tanda Nova toma decisiones propias (apagar la nube, el oido fino o el ultimo
# recurso, avisar de que su idea de tu voz se movio), y no estaban en ninguna parte que
# leyeras: solo en el log.
#
# La regla de la lista: si no puede explicar una decision con un numero, es que no deberia
# haberla tomado. Aqui se cumple sola, porque el detalle que se guarda YA trae el numero
# ("ultimo recurso off: 1 de 29").
#
# Si esa semana no decidio nada, no escribe ninguna linea: un parte que dice "no hice nada
# especial" cansa mas de lo que informa.
function Get-ParrafoDecisiones($stats, [datetime]$ini, [datetime]$fin) {
    $hechas = @(); $deshechas = 0; $medias = 0
    try {
        # DE "decisiones", QUE PARA ESO SE HIZO (22/09). Esto leia "recientes", que tiene 40
        # filas y se las lleva cualquier racha: medido hoy, 28 de esas 40 eran aviso-entorno
        # y las decisiones dentro de la ventana eran CERO, asi que este parrafo -que es
        # SEMANAL- salia vacio siempre. Se sigue mirando "recientes" si la lista nueva esta
        # vacia, que es lo que pasa con un estadisticas.json de antes de hoy: asi el primer
        # resumen despues del cambio no se queda sin lo que ya habia.
        # EL Where-Object NO SOBRA, y me costo ocho rojos de un banco que ya existia: si
        # $stats no trae la clave 'decisiones' -un objeto de antes de hoy-, $stats.decisiones
        # es $null, y en PowerShell @($null).Count es UNO, no cero. O sea que el respaldo no
        # entraba nunca y el foreach corria sobre un $null: el parrafo seguia saliendo vacio,
        # que es justo lo que se venia a arreglar. Filtrando, una lista ausente y una vacia
        # se parecen por fin.
        $deDonde = @($stats.decisiones | Where-Object { $_ })
        if ($deDonde.Count -eq 0) { $deDonde = @($stats.recientes | Where-Object { $_ }) }
        foreach ($r in $deDonde) {
            if ($r -notmatch '^(\d{4}-\d{2}-\d{2})\s+\S+\s+\[([a-z-]+)\]\s+(.*)$') { continue }
            $f = $null
            try { $f = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) } catch { continue }
            if ($f -lt $ini -or $f -gt $fin) { continue }
            switch ($Matches[2]) {
                'auto-ajuste'     { $hechas += [string]$Matches[3] }
                'auto-deshecho'   { $deshechas++ }
                'arranque-medias' { $medias++ }
            }
        }
    } catch { return '' }
    if ($hechas.Count -eq 0 -and $deshechas -eq 0 -and $medias -eq 0) { return '' }
    $lineas = @()
    if ($hechas.Count -gt 0) {
        $lineas += "Esta semana decidi " + $(if ($hechas.Count -eq 1) { 'una cosa' } else { "$($hechas.Count) cosas" }) + " por mi cuenta: " + (($hechas | Select-Object -First 4) -join '; ') + "."
    }
    if ($deshechas -gt 0) {
        $lineas += "Me pediste deshacer " + $(if ($deshechas -eq 1) { 'una de ellas' } else { "$deshechas de ellas" }) + ", asi que ahi me equivoque."
    }
    if ($medias -gt 0) {
        $lineas += "Y arranque a medias " + $(if ($medias -eq 1) { 'una vez' } else { "$medias veces" }) + "."
    }
    return ($lineas -join ' ')
}

function Write-NotaSemanal {
    try {
        $hoy = (Get-Date).Date
        # lunes de ESTA semana; la semana a resumir es la anterior
        $lunes = $hoy.AddDays(-(([int]$hoy.DayOfWeek + 6) % 7))
        $ini = $lunes.AddDays(-7); $fin = $lunes.AddDays(-1)
        $cal = [System.Globalization.CultureInfo]::InvariantCulture.Calendar
        $semana = $cal.GetWeekOfYear($ini, [System.Globalization.CalendarWeekRule]::FirstFourDayWeek, [DayOfWeek]::Monday)
        $dir = Join-Path $MemoriaDir 'semanas'
        $ruta = Join-Path $dir ('{0}-W{1:00}.md' -f $ini.Year, $semana)
        if (Test-Path -LiteralPath $ruta) { return }
        $s = Get-Estadisticas
        $tot = @{}; $dias = 0
        for ($d = $ini; $d -le $fin; $d = $d.AddDays(1)) {
            $k = $d.ToString('yyyy-MM-dd')
            if (-not $s.dias.ContainsKey($k)) { continue }
            $dias++
            foreach ($r in $s.dias[$k].Keys) { if (-not $tot.ContainsKey($r)) { $tot[$r] = 0 }; $tot[$r] += $s.dias[$k][$r] }
        }
        if ($dias -eq 0) { return }   # semana sin uso: no hay nada que contar
        $gestos = @{}
        $gl = Join-Path $TmpDir 'gestos.log'
        if (Test-Path -LiteralPath $gl) {
            foreach ($l in [System.IO.File]::ReadAllLines($gl, [System.Text.Encoding]::UTF8)) {
                if ($l -match '^(\d{4}-\d{2}-\d{2}) \S+ (\S+)$') {
                    $dd = [DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null)
                    if ($dd -lt $ini -or $dd -gt $fin) { continue }
                    if ($Matches[2] -in @('escucho', 'lotengo', 'atencion')) { continue }
                    if (-not $gestos.ContainsKey($Matches[2])) { $gestos[$Matches[2]] = 0 }
                    $gestos[$Matches[2]]++
                }
            }
        }
        $cul = New-Object System.Globalization.CultureInfo('es-MX')
        $n = 0; foreach ($k in 'local', 'aprendida', 'memoria', 'pregunta', 'traducida', 'accion', 'charla') { if ($tot.ContainsKey($k)) { $n += $tot[$k] } }
        $rapidas = 0; foreach ($k in 'local', 'aprendida', 'memoria') { if ($rapidas -ne $null -and $tot.ContainsKey($k)) { $rapidas += $tot[$k] } }
        $errores = if ($tot.ContainsKey('error')) { $tot['error'] } else { 0 }
        $desc = @($s.descartes | Where-Object { $_ -match '^(\d{4}-\d{2}-\d{2})' -and ([DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) -ge $ini) -and ([DateTime]::ParseExact($Matches[1], 'yyyy-MM-dd', $null) -le $fin) } | ForEach-Object { $_ -replace '^\S+\s+', '' } | Select-Object -First 5)
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine("# Semana del " + $ini.ToString('d "de" MMMM', $cul) + " al " + $fin.ToString('d "de" MMMM "de" yyyy', $cul))
        [void]$sb.AppendLine("")
        [void]$sb.AppendLine("Esta semana hablamos $dias " + $(if ($dias -eq 1) { 'día' } else { 'días' }) + ". Me pediste $n " + $(if ($n -eq 1) { 'cosa' } else { 'cosas' }) + $(if ($n -gt 0) { ", y $rapidas de ellas las resolví al instante sin pasar por el modelo" } else { '' }) + ".")
        if ($errores -gt 0) { [void]$sb.AppendLine("Hubo $errores " + $(if ($errores -eq 1) { 'tropiezo' } else { 'tropiezos' }) + " (cancelaciones, dictados vacíos o esperas que se pasaron de tiempo).") }
        if ($desc.Count -gt 0) { [void]$sb.AppendLine(""); [void]$sb.AppendLine("Cosas que no entendí a la primera y que podrías enseñarme en commands.json: " + (($desc | ForEach-Object { "«$_»" }) -join ', ') + ".") }
        $parrafoYo = Get-ParrafoDecisiones $s $ini $fin
        if ($parrafoYo) { [void]$sb.AppendLine(""); [void]$sb.AppendLine($parrafoYo) }
        if ($gestos.Count -gt 0) {
            $top = @($gestos.GetEnumerator() | Sort-Object -Property Value -Descending | Select-Object -First 4 | ForEach-Object { "$($_.Key) ×$($_.Value)" })
            [void]$sb.AppendLine(""); [void]$sb.AppendLine("Lo que más me dijiste, según mis gestos: " + ($top -join ', ') + ".")
            if ($gestos.ContainsKey('carino') -and $gestos['carino'] -ge 3) { [void]$sb.AppendLine("Gracias por los cariños, se notaron.") }
            if ($gestos.ContainsKey('negar') -and $gestos['negar'] -gt ($n / 3)) { [void]$sb.AppendLine("Hubo bastantes «no»: si algo hago mal a menudo, apúntamelo en la lista de descartes y lo aprendo.") }
        }
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
        [System.IO.File]::WriteAllText($ruta, $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))
        Log "nota semanal escrita: $ruta"
    } catch { Log ("nota semanal: " + $_.Exception.Message) }
}

function Enter-Juego([string]$nombre) {
    # IDEA 11: el juego tiene algo pendiente. En los manifiestos de Steam, StateFlags 4
    # es "instalado y listo"; cualquier otra cosa (6, 550, 1026...) es actualizacion o
    # descarga a medias. Mejor saberlo AHORA que cuando el juego no arranca.
    try {
        $jE = @($script:Juegos | Where-Object { $_.nombre -eq $nombre }) | Select-Object -First 1
        if ($jE -and [int]$jE.estado -ne 4) {
            [void](Send-AvisoEntorno "juego-pendiente-$nombre" "Ojo, $nombre tiene una actualizacion o descarga pendiente en Steam." 'medio' 120)
        }
    } catch {}
    # (el aviso de las dos horas ya NO se rearma aqui: era lo que lo mataba en cada
    #  alt-tab. Ahora se cuenta por dia, en Get-MinutosJuegoHoy.)
    $script:juegoHoras = 0
    # C4 (19/09): los minutos de la partida SIGUEN contando si es el mismo juego al que
    # se acaba de volver (un alt-tab de 10 s parte la sesion en dos, y el log del 18/09
    # tiene tres de esos); con otro juego delante, la cuenta empieza de cero.
    if (-not ($script:juegoSalida -and $script:juegoSalida.nombre -eq $nombre)) { $script:juegoSesionMin = 0 }
    $script:juegoBrilloAntes = $null
    $script:logroArchivo = ''
    try { Show-RecuerdoJuego $nombre } catch { Log ("juegos: " + $_.Exception.Message) }
    Invoke-Reglas 'juegoAbre' $nombre
    if (-not $JuegoPerfilEntrar) { return }
    if (-not (Test-Prop $cmds.perfiles $JuegoPerfilEntrar)) { return }
    # EL BRILLO DE ANTES SOBREVIVE A UN REINICIO DE NOVA (23/09, idea 2 de la cuarta tanda).
    # Este numero vivia solo en RAM. Si Nova muere con el juego delante -y muere mucho: 235
    # arranques en 14 dias-, la instancia nueva vuelve a aplicar el perfil y lee como "brillo
    # de antes" el 100 que dejo puesto la muerta; al salir del juego escribe "brillo
    # restaurado a 100" y no restaura nada. Medido: 33 perfiles aplicados contra 21
    # restauraciones, 12 sin deshacer, y de las 16 restauraciones desde que su brillo es 70,
    # las 12 con la cadena limpia devolvieron 70 y las 4 con un reinicio en medio devolvieron
    # 100. Cuatro de cuatro: el fallo es exactamente ese y no otro.
    # DOS LLAVES para que el fichero no se use rancio: el MISMO juego tiene que seguir vivo
    # (Test-JuegoVivo, con PID y ruta) y no puede pasar de doce horas. Sin eso, el caso real
    # del 20/09 -It Takes Two a las 15:44, Nova reinicia a las 18:53, y a las 18:59 entra
    # ELDEN RING- le habria movido la pantalla sola a un numero de otro juego.
    $brilloGuardado = Join-Path $TmpDir 'juego-brillo.json'
    $script:juegoBrilloAntes = $null
    try {
        if (Test-Path -LiteralPath $brilloGuardado) {
            $gB = $null
            try { $gB = Get-Content -LiteralPath $brilloGuardado -Raw -Encoding UTF8 | ConvertFrom-Json } catch {}
            $frescoB = $false
            if ($gB -and $gB.cuando) {
                $cB = [datetime]::MinValue
                if ([datetime]::TryParse([string]$gB.cuando, [ref]$cB)) { $frescoB = ((Get-Date) - $cB).TotalHours -lt 12 }
            }
            if ($gB -and $frescoB -and (Test-JuegoVivo $gB)) {
                $script:juegoBrilloAntes = [int]$gB.brillo
                Log "JUEGO: recupero el brillo de antes ($($gB.brillo)) del disco; Nova reinicio con el juego delante"
            } else {
                Remove-Item -LiteralPath $brilloGuardado -Force -ErrorAction SilentlyContinue
            }
        }
    } catch {}
    if ($null -eq $script:juegoBrilloAntes) {
        try { $script:juegoBrilloAntes = (Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction Stop).CurrentBrightness } catch {}
        # y se guarda UNA vez por partida, no en cada alt-tab: Enter-Juego se dispara cada vez
        # que el juego vuelve al primer plano (diez veces la noche del 22).
        if ($null -ne $script:juegoBrilloAntes) {
            try {
                $oB = [ordered]@{ brillo = [int]$script:juegoBrilloAntes; proc = [int]$script:juegoPid
                                  exe = [string]$script:juegoExe; juego = [string]$nombre
                                  cuando = (Get-Date).ToString('s') }
                [System.IO.File]::WriteAllText($brilloGuardado, (ConvertTo-Json -InputObject $oB -Depth 3), (New-Object System.Text.UTF8Encoding($false)))
            } catch {}
        }
    }
    # NO se abren apps del perfil al entrar solo en un juego (abrir Discord
    # encima de un juego recien lanzado seria un estorbo): solo niveles
    $ordenes = @($cmds.perfiles.$JuegoPerfilEntrar) | Where-Object { (ConvertTo-Plain $_) -notmatch '^(?:abre|abrir|lanza|ejecuta)\b' }
    $hechas = @()
    foreach ($o in $ordenes) {
        $r = $null
        try { $r = Invoke-FastCommand $o } catch { $r = $null }
        if ($r) { $hechas += $r }
    }
    if ($hechas.Count -gt 0) {
        Log "JUEGO: perfil '$JuegoPerfilEntrar' aplicado al entrar en $nombre"
        Say "Modo $JuegoPerfilEntrar."
        Send-UIEvento 'hecho'
    }
}

function Exit-Juego([string]$nombre) {
    try { Save-TiempoJuego } catch {}
    # "me quede en..." dicho justo despues de salir sigue siendo de este juego
    $script:ultimoJuego = $nombre
    $script:ultimoJuegoEn = $sw.ElapsedMilliseconds
    # C4 (19/09): PERDER EL PRIMER PLANO NO ES CERRAR EL JUEGO. Esta funcion la llama el
    # bucle en cuanto cambia la ventana de delante: de las 11 salidas del log (10-19/09)
    # CINCO duraron menos de 2 minutos (ELDEN RING 4 s, 10 s, 11 s y 100 s; Little
    # Nightmares III 83 s) y en tres de ellas se vuelve al MISMO juego en 20 s, 10 s y
    # 3 min 51 s: el juego nunca se habia cerrado, era un alt-tab. Por eso aqui ya no
    # sale ningun aviso de cierre: se suman los minutos jugados y se apunta una salida
    # EN DUDA que Test-SalidaJuego confirma cuando el PROCESO ha muerto de verdad.
    # [int] REDONDEA en PowerShell: 40 s daban 1 minuto entero, y tres alt-tabs de 40 s
    # sumaban 3 minutos sin haber jugado ni dos. Con Floor, un minuto es un minuto.
    $minsFg = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 60000)
    if ($minsFg -gt 0 -and $minsFg -le 720) { $script:juegoSesionMin += $minsFg }
    # IDEAS 19 y 20: cuanto se juega cada dia. Se apunta AL CERRAR, que es cuando se
    # sabe lo que duro la partida; asi "cuanto llevo hoy" no se lo inventa nadie.
    # UNA SOLA FUENTE DE VERDAD: juegos.json (23/09). Aqui se escribia ADEMAS en
    # habitos.json, y esa copia solo se escribia si Nova estaba viva cuando cambiaba la
    # ventana: si se reiniciaba con el juego delante, esos minutos no se apuntaban NUNCA.
    # Se nota en el fichero: falta entero el 15/09 (5 h 38), falta el 16/09, y el 20/09
    # apunta 2 minutos donde juegos.json apunta 2 h 45. Encima los dos usaban un "dia"
    # distinto -aqui se restaban 5 horas y alli era el dia natural-, asi que no podian
    # cuadrar jamas. juegos.json sobrevive porque se vuelca cada 300 s desde el bucle.
    try {
        $minJ = [int][Math]::Floor(($sw.ElapsedMilliseconds - $script:juegoDesde) / 60000)
        if ($minJ -ge 2 -and $minJ -le 720) {
            $totJ = Get-MinutosJuegoHoy $nombre
            Log "JUEGO: $minJ min con $nombre (hoy van $totJ)"
            # el "hoy llevas N horas" se ha mudado a Test-SalidaJuego (C4, 19/09): aqui
            # nunca llegaba a decirse, porque $script:juegoActivo todavia vale el juego
            # que se acaba de dejar y Test-PuedoAvisar tira todo lo que no sea 'alto'
            # con un juego delante. Alli se dice al cerrarlo, que es cuando se escucha.
        }
    } catch {}
    Invoke-Reglas 'juegoCierra' $nombre
    # C4 (19/09): la salida queda EN DUDA hasta que se sepa que el proceso murio. El
    # "Cerraste X, dime donde te quedaste" lo suelta Test-SalidaJuego desde el bucle.
    if ($nombre) {
        $script:juegoSalida = @{
            nombre  = $nombre
            exe     = [string]$script:juegoExe
            proc    = [int]$script:juegoPid
            desdeMs = $sw.ElapsedMilliseconds
        }
    }
    if (-not $JuegoRestaurar -or $null -eq $script:juegoBrilloAntes) { return }
    try {
        Set-Brillo ([int]$script:juegoBrilloAntes)
        Log "JUEGO: brillo restaurado a $($script:juegoBrilloAntes) al salir de $nombre"
        # restaurado: el respaldo ya no vale para nada y no debe sobrevivir a la partida
        try { Remove-Item -LiteralPath (Join-Path $TmpDir 'juego-brillo.json') -Force -ErrorAction SilentlyContinue } catch {}
    } catch {}
    $script:juegoBrilloAntes = $null
}

# --- C4 (19/09): SE CERRO EL JUEGO, O SOLO CAMBIASTE DE VENTANA ---
# Vivo = el proceso que tenia la ventana del juego sigue ahi. Se mira por PID, que es
# una consulta barata; enumerar todos los procesos cada 10 s en una maquina de 4 nucleos
# no lo es, y solo se hace si no hubo PID. Windows reutiliza los PID, asi que se
# comprueba ademas la ruta; si la ruta no se puede leer se da por VIVO, que como mucho
# retrasa un aviso (decir "cerraste ELDEN RING" jugando es mucho peor).
function Test-JuegoVivo($s) {
    if (-not $s) { return $false }
    $idJ = 0
    try { $idJ = [int]$s.proc } catch {}
    if ($idJ -gt 0) {
        $pJ = $null
        try { $pJ = Get-Process -Id $idJ -ErrorAction SilentlyContinue } catch {}
        if (-not $pJ) { return $false }
        $rutaJ = ''
        try { $rutaJ = [string]$pJ.Path } catch {}
        if (-not $s.exe -or -not $rutaJ -or $rutaJ -eq [string]$s.exe) { return $true }
        return $false
    }
    if ($s.exe) {
        try { return (@(Get-Process -ErrorAction SilentlyContinue | Where-Object { try { $_.Path -eq $s.exe } catch { $false } }).Count -gt 0) } catch {}
    }
    return $false
}

# Lo llama el bucle cada 10 s, justo despues de mirar que hay en primer plano. Aqui es
# donde salen los dos avisos del cierre, y no en Exit-Juego, por dos motivos:
#  (a) el proceso: hasta que no muere, lo que hubo fue un alt-tab, no una salida;
#  (b) $script:juegoActivo: el bucle ya lo ha puesto al dia cuando se llega aqui, asi
#      que Test-PuedoAvisar deja pasar el aviso en vez de tirarlo por "esta jugando",
#      que es lo que le pasaba a los dos desde que existen los frenos (16/09).
function Test-SalidaJuego {
    $s = $script:juegoSalida
    if (-not $s) { return }
    # ha vuelto al mismo juego: no era una salida
    if ($script:juegoActivo -and $script:juegoActivo -eq $s.nombre) { $script:juegoSalida = $null; return }
    if (Test-JuegoVivo $s) {
        # dos horas con el juego abierto detras sin mirarlo: si se cierra ahora ya no
        # viene a cuento preguntar donde te quedaste, asi que se deja de vigilar
        if (($sw.ElapsedMilliseconds - [double]$s.desdeMs) -ge 7200000) {
            Log "JUEGO: $($s.nombre) sigue abierto 2 h despues de dejarlo; se olvida la salida"
            $script:juegoSalida = $null
            $script:juegoSesionMin = 0
        }
        return
    }
    $script:juegoSalida = $null
    $minsS = [int]$script:juegoSesionMin
    $script:juegoSesionMin = 0
    if ($minsS -lt $JuegoMinimoPartida) {
        Log "JUEGO: $($s.nombre) cerrado con $minsS min de partida (minimo $JuegoMinimoPartida): sin aviso"
        return
    }
    Log "JUEGO: cerrado de verdad $($s.nombre) ($minsS min de partida)"
    # Y SI TE DEJO LA PANTALLA CAMBIADA (25/09, idea 6). Medido el 24/09: braya cerro A Way Out
    # a las 00:01:13 y VEINTE MINUTOS despues el escritorio seguia a 1280x720 con un panel de
    # 1920x1080. El juego no le devolvio su resolucion y nadie se lo dijo.
    # NO SE LA CAMBIA SOLA, a proposito: en una consola portatil bajar la resolucion a veces es
    # deliberado, para que dure la bateria. Se dice y decide braya.
    try {
        $script:capsulaCiega = $false
        $nat = Get-ResolucionNativa
        $act = Get-ResolucionActual
        if ($nat -and $act -and (($nat[0] -ne $act[0]) -or ($nat[1] -ne $act[1]))) {
            [void](Send-AvisoEntorno 'pantalla-cambiada' (
                "El juego te ha dejado la pantalla en $($act[0]) por $($act[1]); la tuya es $($nat[0]) por $($nat[1])."
            ) 'medio' 120)
        }
    } catch {}
    # idea 9: es el momento en que te acuerdas; media hora despues, ya no
    [void](Send-AvisoEntorno 'juego-cierra' "Cerraste $($s.nombre). Si quieres, dime donde te quedaste." 'medio' 120)
    # IDEA 20: y de paso, lo que llevas hoy (se lee de habitos, que lo acaba de sumar
    # Exit-Juego; si el ultimo tramo no llego a 2 min, el total del dia sigue valiendo)
    try {
        $hbS = Get-Habitos
        $totS = Get-MinutosJuegoHoy    # la fuente buena: juegos.json, que sobrevive a los reinicios
        if ($totS -ge 240) {
            [void](Send-AvisoEntorno 'horas-hoy' "Hoy llevas $([Math]::Round($totS / 60.0, 1)) horas de juego." 'bajo' 480)
        }
    } catch { Log ("horas de hoy: " + $_.Exception.Message) }
}

# =====================================================================
# VER LA PANTALLA: captura de la ventana activa (o de toda la pantalla) y
# OCR con el motor integrado de Windows (WinRT, sin instalar nada).
# =====================================================================
$script:winrtAsTask = $null
function Await-WinRT($op, $tipo, [int]$esperaMs = 8000) {
    if (-not $script:winrtAsTask) {
        Add-Type -AssemblyName System.Runtime.WindowsRuntime
        $script:winrtAsTask = ([System.WindowsRuntimeSystemExtensions].GetMethods() |
            Where-Object { $_.Name -eq 'AsTask' -and $_.GetParameters().Count -eq 1 -and
                           $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' })[0]
    }
    $t = $script:winrtAsTask.MakeGenericMethod($tipo).Invoke($null, @($op))
    if (-not $t.Wait($esperaMs)) { throw "WinRT: sin respuesta en $esperaMs ms" }
    return $t.Result
}

# QUÉ TROZO DE LA PANTALLA (C15, 20/09). Devuelve el rectángulo de "arriba",
# "abajo-derecha", "centro"... en FRACCIONES y no en píxeles, para que valga igual
# en la pantalla de 7 pulgadas de la consola y en un monitor de casa.
# El SOLAPE del 6 % no es un capricho: un renglón que cruce justo por la mitad se
# partiría en dos y el OCR leería medias palabras, que es peor que no leer nada.
# Así cada mitad se lleva un pellizco de la de al lado.
# El centro es el 20-80 % de cada lado: el cartel que sale en medio de un juego cabe
# de sobra ahí, y se queda fuera todo el HUD de los bordes, que es justo el ruido que
# hacía inútil leer la pantalla entera mientras juegas.
function Get-ZonaRect([int]$x, [int]$y, [int]$w, [int]$h, [string]$zona) {
    if (-not $zona) { return @{ x = $x; y = $y; w = $w; h = $h } }
    $sol = 0.06
    $x0 = 0.0; $x1 = 1.0; $y0 = 0.0; $y1 = 1.0
    if ($zona -eq 'centro') {
        $x0 = 0.2; $x1 = 0.8; $y0 = 0.2; $y1 = 0.8
    } else {
        if     ($zona -like '*arriba*')    { $y1 = 0.5 + $sol }
        elseif ($zona -like '*abajo*')     { $y0 = 0.5 - $sol }
        if     ($zona -like '*izquierda*') { $x1 = 0.5 + $sol }
        elseif ($zona -like '*derecha*')   { $x0 = 0.5 - $sol }
    }
    $nx = $x + [int][Math]::Round($w * $x0)
    $ny = $y + [int][Math]::Round($h * $y0)
    $nw = [int][Math]::Round($w * ($x1 - $x0))
    $nh = [int][Math]::Round($h * ($y1 - $y0))
    # un recorte ridículo no lo lee nadie: si la ventana ya era diminuta, entera.
    if ($nw -lt 80 -or $nh -lt 40) { return @{ x = $x; y = $y; w = $w; h = $h } }
    return @{ x = $nx; y = $ny; w = $nw; h = $nh }
}

# Guarda un PNG de la ventana en primer plano (o de toda la pantalla si no
# hay ventana util). Esconde la capsula un instante para que no salga.
# Con $zona guarda SOLO ese trozo (ver Get-ZonaRect). El recorte se hace aquí, al
# copiar de la pantalla, y no después sobre el PNG: así se copian menos píxeles y el
# OCR mira menos área, que es lo que hace que leer una esquina salga más rápido que
# leer la pantalla entera, y no al revés.
function Save-Captura([string]$ruta, [string]$zona = '') {
    if ($UiNuevaOn) { Send-UIEvento 'oculta'; Start-Sleep -Milliseconds 180 }
    # Y LA LUPA TAMBIEN SE APARTA (revision del 23/09). La lupa es una ventana siempre
    # encima, y CopyFromScreen copia lo que hay encima: con la lupa puesta, el OCR leia el
    # trozo YA ampliado y la vision de la nube describia la lupa en vez de la pantalla. Se
    # esconde y se vuelve a poner -no se cierra- porque braya la estaba mirando.
    $lupaTapa = $null
    if ($script:lupaForm) {
        try { $lupaTapa = $script:lupaForm.Handle; [void][AX]::ShowWindow($lupaTapa, 0); Start-Sleep -Milliseconds 60 } catch { $lupaTapa = $null }
    }
    try {
        $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
        $x = $b.Left; $y = $b.Top; $w = $b.Width; $h = $b.Height
        try {
            $hw = [AX]::GetForegroundWindow()
            if ($hw -ne [IntPtr]::Zero -and $hw -ne $capture.Handle) {
                $r = New-Object AX+RECT
                if ([AX]::GetWindowRect($hw, [ref]$r) -and ($r.Right - $r.Left) -gt 80 -and ($r.Bottom - $r.Top) -gt 60) {
                    $x = [Math]::Max($b.Left, $r.Left); $y = [Math]::Max($b.Top, $r.Top)
                    $w = [Math]::Min($b.Right, $r.Right) - $x; $h = [Math]::Min($b.Bottom, $r.Bottom) - $y
                }
            }
        } catch {}
        if ($zona) {
            $zR = Get-ZonaRect $x $y $w $h $zona
            $x = $zR.x; $y = $zR.y; $w = $zR.w; $h = $zR.h
        }
        $bmp = New-Object System.Drawing.Bitmap($w, $h)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.CopyFromScreen($x, $y, 0, 0, (New-Object System.Drawing.Size($w, $h)))
            $bmp.Save($ruta, [System.Drawing.Imaging.ImageFormat]::Png)
        } finally { $g.Dispose(); $bmp.Dispose() }
        return $ruta
    } finally {
        if ($lupaTapa) { try { [void][AX]::ShowWindow($lupaTapa, 8) } catch {} }   # SW_SHOWNA
    }
}

# Un trozo de texto para decir en voz alta, desde $desde. Se corta en un PUNTO
# y, si no hay, en un espacio: partir una palabra por la mitad suena a fallo,
# no a pausa. Devuelve el texto y DONDE se quedo, para poder seguir.
function Get-Trozo([string]$todo, [int]$desde, [int]$largo = 320) {
    if ($desde -lt 0) { $desde = 0 }
    if ($desde -ge $todo.Length) { return @{ texto = ''; fin = $todo.Length } }
    $resto = $todo.Substring($desde)
    if ($resto.Length -le $largo) { return @{ texto = $resto.Trim(); fin = $todo.Length } }
    $cacho = $resto.Substring(0, $largo)
    # el ultimo punto que deje al menos media frase; si no, el ultimo espacio
    $corte = $cacho.LastIndexOf('. ')
    if ($corte -lt [int]($largo / 2)) { $corte = $cacho.LastIndexOf(' ') }
    if ($corte -lt [int]($largo / 2)) { $corte = $largo - 1 }
    $fin = $desde + $corte + 1
    return @{ texto = $resto.Substring(0, $corte + 1).Trim(); fin = $fin }
}

function Invoke-OCR([string]$png) {
    $null = [Windows.Media.Ocr.OcrEngine, Windows.Foundation, ContentType = WindowsRuntime]
    $null = [Windows.Storage.StorageFile, Windows.Storage, ContentType = WindowsRuntime]
    $null = [Windows.Graphics.Imaging.BitmapDecoder, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
    $null = [Windows.Globalization.Language, Windows.Globalization, ContentType = WindowsRuntime]
    $null = [Windows.Storage.Streams.IRandomAccessStream, Windows.Storage.Streams, ContentType = WindowsRuntime]
    $null = [Windows.Storage.FileAccessMode, Windows.Storage, ContentType = WindowsRuntime]
    $null = [Windows.Graphics.Imaging.SoftwareBitmap, Windows.Graphics.Imaging, ContentType = WindowsRuntime]
    $null = [Windows.Media.Ocr.OcrResult, Windows.Foundation, ContentType = WindowsRuntime]
    $motor = $null
    try { $motor = [Windows.Media.Ocr.OcrEngine]::TryCreateFromLanguage((New-Object Windows.Globalization.Language 'es')) } catch { $motor = $null }
    if (-not $motor) { $motor = [Windows.Media.Ocr.OcrEngine]::TryCreateFromUserProfileLanguages() }
    if (-not $motor) { throw "no hay motor de OCR (instala el idioma en Windows)" }
    $archivo = Await-WinRT ([Windows.Storage.StorageFile]::GetFileFromPathAsync($png)) ([Windows.Storage.StorageFile])
    $flujo = Await-WinRT ($archivo.OpenAsync([Windows.Storage.FileAccessMode]::Read)) ([Windows.Storage.Streams.IRandomAccessStream])
    $dec = Await-WinRT ([Windows.Graphics.Imaging.BitmapDecoder]::CreateAsync($flujo)) ([Windows.Graphics.Imaging.BitmapDecoder])
    $bmp = Await-WinRT ($dec.GetSoftwareBitmapAsync()) ([Windows.Graphics.Imaging.SoftwareBitmap])
    $res = Await-WinRT ($motor.RecognizeAsync($bmp)) ([Windows.Media.Ocr.OcrResult])
    try { $flujo.Dispose() } catch {}
    # una linea por renglon, para que se lea con pausas naturales
    $lineas = @($res.Lines | ForEach-Object { $_.Text })
    return (($lineas -join '. ') -replace '\s+', ' ').Trim()
}

# =====================================================================
# VIBRACION DEL MANDO: patron de [on, off, on, ...] en ms, sin bloquear; el
# bucle principal lo va ejecutando. Un eco tactil de lo que hace la capsula.
# =====================================================================
$MandoVibracion = [bool](Get-Cfg 'mando' 'vibracion' $true)
$script:vibraCola = @()
$script:vibraHasta = 0
$script:vibraEncendida = $false
$script:vibraFuerza = 0

$script:vibraSiguienteOn = $true
$script:vibraAvisado = $false

function Start-Vibracion([int[]]$patron, [int]$fuerza = 22000) {
    if (-not $MandoVibracion -or -not $patron -or $patron.Count -eq 0) { return }
    # el patron alterna encendido/apagado empezando por encendido
    $script:vibraCola = @($patron)
    $script:vibraFuerza = $fuerza
    $script:vibraHasta = 0
    $script:vibraSiguienteOn = $true
}

function Tick-Vibracion {
    if ($script:vibraHasta -gt 0) {
        if ($sw.ElapsedMilliseconds -lt $script:vibraHasta) { return }
        $script:vibraHasta = 0
        if ($script:vibraEncendida) { try { [void][AX]::Vibrar(0, 0, 0) } catch {}; $script:vibraEncendida = $false }
    }
    if ($script:vibraCola.Count -eq 0) { return }
    $ms = [int]$script:vibraCola[0]
    $script:vibraCola = @($script:vibraCola | Select-Object -Skip 1)
    if ($script:vibraSiguienteOn) {
        $ok = $false
        try { $ok = [AX]::Vibrar(0, [uint16]$script:vibraFuerza, [uint16]($script:vibraFuerza / 2)) } catch { $ok = $false }
        if (-not $script:vibraAvisado) { $script:vibraAvisado = $true; Log ("mando: vibracion " + $(if ($ok) { 'disponible' } else { 'no disponible (sin mando XInput)' })) }
        if (-not $ok) { $script:vibraCola = @(); return }   # sin mando: fuera
        $script:vibraEncendida = $true
    }
    $script:vibraSiguienteOn = -not $script:vibraSiguienteOn
    $script:vibraHasta = $sw.ElapsedMilliseconds + $ms
}

# Win + <tecla>: usado para colocar ventanas (Win+flechas)
# Win+Shift+<tecla>: mover la ventana entre monitores. Es Send-WinKey con el
# Shift por fuera; separadas para no meterle un parametro opcional a la que ya
# usan quince sitios.
function Send-WinShiftKey([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]0x10, 0, 0, [UIntPtr]::Zero)      # Shift
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]0x10, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

function Send-WinKey([int]$vk) {
    [AX]::keybd_event([byte]$VK_LWIN, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$vk, 0, 0, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 40
    [AX]::keybd_event([byte]$vk, 0, $KEYUP, [UIntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [AX]::keybd_event([byte]$VK_LWIN, 0, $KEYUP, [UIntPtr]::Zero)
}

if ($Probar) {
    if (-not (Test-Path -LiteralPath $Probar)) { Write-Output "no existe: $Probar"; exit 1 }
    # Reconocer una orden NO es gratis: "recuerdame manana a las diez que llame
    # al medico" crea el recordatorio de verdad nada mas detectarlo, y "cuando
    # abras elden ring..." guarda la regla. La primera version de este banco
    # llego a escribir ambas cosas en la memoria real. Aqui se desvia a una
    # carpeta de usar y tirar todo lo que persiste: probar no toca nada tuyo.
    $pruebaDir = Join-Path ([System.IO.Path]::GetTempPath()) ("nova-prueba-" + [guid]::NewGuid().ToString("N").Substring(0, 8))
    New-Item -ItemType Directory -Path $pruebaDir -Force | Out-Null
    New-Item -ItemType Directory -Path (Join-Path $pruebaDir 'diario') -Force | Out-Null
    $MemoriaDir = $pruebaDir
    # el banco escribia RECORDATORIO/REGLA de mentira en el assistant.log real
    $EventLog = Join-Path $pruebaDir 'probar.log'
    # el perfil y las recetas se calculan al cargar, ANTES de este bloque: sin
    # esto, "aprende que mi..." pasado por el banco escribiria en el perfil real
    $PerfilPath = Join-Path $pruebaDir 'perfil.md'
    $RecetasPath = Join-Path $pruebaDir 'recetas.json'
    $DiarioDir = Join-Path $pruebaDir 'diario'
    $ReglasPath = Join-Path $pruebaDir 'reglas.json'
    $RecordatoriosPath = Join-Path $pruebaDir 'recordatorios.json'
    $FechasPath = Join-Path $pruebaDir 'fechas.json'
    $TraduccionesPath = Join-Path $pruebaDir 'traducciones.json'
    $EstadisticasJson = Join-Path $pruebaDir 'estadisticas.json'
    $EstadisticasMd = Join-Path $pruebaDir 'estadisticas.md'
    $ok = 0; $no = 0; $salt = 0
    foreach ($linea in (Get-Content -LiteralPath $Probar -Encoding UTF8)) {
        $t = $linea.Trim()
        if (-not $t -or $t.StartsWith('#')) { continue }
        # LO QUE DEPENDE DE UN JUEGO QUE YA NO TIENES (19/09): el banco bajo de 88 a 85 y de
        # 183 a 181 sin que nadie tocara el codigo; los cinco "fallos" eran Little Nightmares
        # III, SILENT BREATH y REANIMAL, desinstalados de Steam esa semana. Un banco que se
        # pone rojo solo porque cambio la biblioteca no sirve para ver una regresion de
        # verdad. Con '@si-tienes:<juego>' la linea solo cuenta si ese juego esta instalado
        # AHORA, con el nombre exacto: parecido no vale, que "Little Nightmares III" casa de
        # sobra con "Little Nightmares Enhanced Edition" y eso taparia justo lo que se mira.
        $exige = ''
        $mJ = [regex]::Match($t, '\s*@si-tienes:\s*(.+)$')
        if ($mJ.Success) { $exige = $mJ.Groups[1].Value.Trim(); $t = $t.Substring(0, $mJ.Index).Trim() }
        if ($exige) {
            [void](Update-Juegos)
            $pe = (ConvertTo-Plain $exige).ToLowerInvariant()
            $hayJ = @($script:Juegos | Where-Object { (ConvertTo-Plain ([string]$_.nombre)).ToLowerInvariant() -eq $pe }).Count -gt 0
            if (-not $hayJ) {
                $salt++
                Write-Output ("  SALTO " + $t.PadRight(38) + "  (ya no tienes '$exige' instalado)")
                continue
            }
        }
        # mismo orden que Process-Texto: reglas y recordatorios se resuelven
        # antes que las ordenes sueltas, o el banco mentiria
        $r = $false; $via = ''
        try { if (Invoke-ReglaVoz $t) { $r = $true; $via = 'regla' } } catch { $via = 'REGLA ROTA' ; $r = $false }
        if (-not $r) { try { if (Invoke-RecordatorioVoz $t) { $r = $true; $via = 'recordatorio' } } catch { $via = 'RECORDATORIO ROTO' } }
        if (-not $r) { try { $r = Test-FastCommand $t } catch { $r = $false } }
        if ($r) {
            $ok++
            # QUE haria, no solo si lo reconoce. Sin esto, el banco decia 'OK'
            # a 'pesa' sin contar que eso era un Ctrl+V en lo que tuvieras
            # delante, ni a 'abre el speaker' que lanzaba PEAK.
            $comoQue = ''
            # si lo cogio una regla o un recordatorio, decirlo: la descripcion
            # de Resolve-Fragment seria otra cosa y despistaria
            if ($via) { $comoQue = "  ->  [$via]" }
            elseif ($true) { try {
                $descs = @()
                foreach ($fr in @(Split-Ordenes $t)) {
                    $acc = Resolve-Fragment $fr
                    if ($acc) { $descs += @($acc | ForEach-Object { $_.desc }) }
                }
                $descs = @($descs | Where-Object { $_ })
                if ($descs.Count -gt 0) { $comoQue = '  ->  ' + ($descs -join ' + ') }
            } catch {} }
            Write-Output ("  OK    " + $t.PadRight(38) + $comoQue)
        }
        else    { $no++; Write-Output ("  ->IA  " + $t) }
    }
    Write-Output ""
    Write-Output ("reconocidas en local: $ok de " + ($ok + $no))
    # el listero de probar-todo.ps1 suma las dos: asi el minimo sigue siendo el mismo
    # aunque hoy falte un juego, y baja de verdad solo si se rompe algo
    Write-Output ("saltadas por juegos que ya no tienes: $salt")
    try { Remove-Item -LiteralPath $pruebaDir -Recurse -Force -ErrorAction SilentlyContinue } catch {}
    exit 0
}

